import { NextRequest, NextResponse } from 'next/server';
import { runSimulator } from '@/lib/simulator-runner';

type RunPayload = {
  name?: string;
  format?: 'json' | 'csv';
};

export async function POST(request: NextRequest) {
  if (process.env.NODE_ENV === 'production' && process.env['ENABLE_SIMULATOR'] !== 'true') {
    return NextResponse.json(
      { ok: false, error: 'Simulator endpoints are disabled in production.' },
      { status: 501 }
    );
  }
  let payload: RunPayload;
  try {
    payload = await request.json();
  } catch (error) {
    return NextResponse.json({ ok: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  if (!payload?.name || typeof payload.name !== 'string') {
    return NextResponse.json({ ok: false, error: 'Name is required.' }, { status: 400 });
  }

  const args = ['--json', '--run-saved', payload.name];
  if (payload.format === 'csv') {
    args.push('--out', 'csv');
  }

  try {
    const result = await runSimulator(args);
    const status = result?.ok === false ? 400 : 200;
    return NextResponse.json(result, { status });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Simulator invocation failed';
    return NextResponse.json({ ok: false, error: message }, { status: 500 });
  }
}

import { NextRequest } from 'next/server';
import { runSimulator } from '@/lib/simulator-runner';
import {
  withErrorTracking,
  ApiError,
  apiSuccess,
  apiError,
  validateBody
} from '@/lib/error-tracking';

type SavePayload = {
  name: string;
  question: string;
};

export const POST = withErrorTracking(
  async (request: NextRequest) => {
    // Check if simulator is enabled in production
    if (process.env.NODE_ENV === 'production' && process.env['ENABLE_SIMULATOR'] !== 'true') {
      throw new ApiError('Simulator endpoints are disabled in production', 501, 'SIMULATOR_DISABLED');
    }

    // Parse and validate request body
    let payload: unknown;
    try {
      payload = await request.json();
    } catch (error) {
      throw new ApiError('Invalid JSON body', 400, 'INVALID_JSON');
    }

    // Validate required fields
    const validatedPayload = validateBody<SavePayload>(payload, {
      name: {
        required: true,
        type: 'string',
        validate: (v) => v.length > 0 && v.length <= 100
      },
      question: {
        required: true,
        type: 'string',
        validate: (v) => v.length > 0 && v.length <= 1000
      }
    });

    // Run the simulator
    try {
      const result = await runSimulator([
        '--json',
        '--save',
        validatedPayload.name,
        '-q',
        validatedPayload.question
      ]);

      if (result?.ok === false) {
        throw new ApiError(
          result.error || 'Simulator execution failed',
          400,
          'SIMULATOR_ERROR'
        );
      }

      return apiSuccess(result);
    } catch (error) {
      // Re-throw ApiErrors as-is
      if (error instanceof ApiError) {
        throw error;
      }

      // Wrap other errors
      throw new ApiError(
        'Simulator invocation failed',
        500,
        'SIMULATOR_INVOCATION_FAILED'
      );
    }
  },
  { endpoint: '/api/sim-save' }
);

