                  moduleId: moduleId || "",
                });
                const base = process.env.NEXT_PUBLIC_BASE_PATH || "";
                window.location.href = `${base}/assessments?${params.toString()}`;
              }}
            />
          )}

          {mode === "review" && sessionId && (
