/**
 * Module Detail Page - Fixed Server Component with MDX
 * Properly handles server-side MDX rendering without client/server conflicts
 */

import { notFound } from "next/navigation";
import fs from "fs/promises";
import path from "path";
import matter from "gray-matter";
import { serialize } from "next-mdx-remote/serialize";
import ModuleRenderer from "@/components/modules/ModuleRenderer";
import { validateModuleFrontmatter } from "@/lib/mdx/module-schema";

interface ModulePageProps {
  params: Promise<{ slug: string }>;
}

// Map slug variations to canonical filenames
const SLUG_TO_FILENAME: Record<string, string> = {
  "tanium-platform-foundation": "00-tanium-platform-foundation.mdx",
  "platform-foundation": "00-tanium-platform-foundation.mdx",
  "asking-questions": "01-asking-questions.mdx",
  "refining-questions-targeting": "02-refining-questions-targeting.mdx",
  "refining-questions": "02-refining-questions-targeting.mdx",
  "taking-action-packages-actions": "03-taking-action-packages-actions.mdx",
  "taking-action": "03-taking-action-packages-actions.mdx",
  "navigation-basic-modules": "04-navigation-basic-modules.mdx",
  "navigation": "04-navigation-basic-modules.mdx",
  "reporting-data-export": "05-reporting-data-export.mdx",
  "reporting": "05-reporting-data-export.mdx",
};

async function getModuleContent(slug: string) {
  try {
    // Get the filename from slug mapping
    const filename = SLUG_TO_FILENAME[slug];
    if (!filename) {
      return null;
    }

    // Construct the full path
    const modulePath = path.join(process.cwd(), "src", "content", "modules", filename);

    // Check if file exists
    try {
      await fs.access(modulePath);
    } catch {
      return null;
    }

    // Read the file
    const fileContent = await fs.readFile(modulePath, "utf8");

    // Parse frontmatter and content
    const { data: frontmatter, content } = matter(fileContent);

    // Validate frontmatter
    const validation = validateModuleFrontmatter(frontmatter, modulePath);
    if (!validation.success || !validation.data) {
      console.error(`Invalid frontmatter in ${filename}:`, validation.errors);
      return null;
    }

    // Serialize the MDX content for client-side hydration
    const mdxSource = await serialize(content, {
      mdxOptions: {
        remarkPlugins: [],
        rehypePlugins: [],
      },
    });

    return {
      frontmatter: validation.data,
      content: mdxSource,
      slug,
      filePath: modulePath,
    };
  } catch (error) {
    console.error(`Error loading module ${slug}:`, error);
    return null;
  }
}

export default async function ModulePage({ params }: ModulePageProps) {
  const { slug } = await params;

  // Get module content
  const moduleData = await getModuleContent(slug);

  if (!moduleData) {
    notFound();
  }

  // Use the existing ModuleRenderer component which handles client-side MDX
  return <ModuleRenderer moduleData={moduleData} />;
}

// Generate static params for all modules
export async function generateStaticParams() {
  return Object.keys(SLUG_TO_FILENAME).map((slug) => ({
    slug,
  }));
}

// Metadata generation
export async function generateMetadata({ params }: ModulePageProps) {
  const { slug } = await params;
  const moduleData = await getModuleContent(slug);

  if (!moduleData) {
    return {
      title: "Module Not Found",
    };
  }

  return {
    title: `${moduleData.frontmatter.title} | Tanium TCO Study`,
    description: moduleData.frontmatter.description || `Study module for ${moduleData.frontmatter.title}`,
  };
}

/**
 * Modules Page - MDX-backed module index
 * Lists modules discovered in src/content/modules using the MDX loader.
 * Falls back to dynamic MDX imports on production if fs discovery is empty.
 */

import { getAllModuleMetadata } from "@/lib/mdx/module-loader";
import { ModulesBrowser } from "@/components/modules/ModulesBrowser";
import Link from "next/link";
import { AVAILABLE_DOMAINS, getMDXMetadata, loadMDXContent } from "@/lib/mdx-loader";

export default async function Modules() {
  let modules = await getAllModuleMetadata();

  if (!modules || (Array.isArray(modules) && modules.length === 0)) {
    // Fallback: build metadata via dynamic imports
    const dyn: any[] = [];
    for (const slug of AVAILABLE_DOMAINS) {
      const mod = await loadMDXContent(slug);
      if (!mod) continue;
      const meta = getMDXMetadata(mod);
      dyn.push({
        slug,
        frontmatter: {
          id: meta.id,
          title: meta.title,
          description: '',
          difficulty: meta.difficulty || 'Intermediate',
          estimatedTime: meta.estimatedTime || '45 min',
          domainEnum: (meta.domainSlug || slug).toUpperCase().replace(/-/g, '_'),
          learningObjectives: meta.objectives || [],
        },
      });
    }
    modules = dyn as any;
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8 text-center">
        <h1 className="mb-3 text-4xl font-bold text-white">TCO Study Center</h1>
        <p className="mx-auto max-w-3xl text-blue-200">
          Explore interactive study modules powered by MDX content.
        </p>
        <div className="mt-4">
          <a
            href="/study/review"
            className="inline-flex items-center rounded-md border border-yellow-500/40 bg-yellow-900/30 px-3 py-1 text-sm text-yellow-200 hover:bg-yellow-900/50"
          >
            Go to Review Center →
          </a>
        </div>
      </div>
      {/* Lightweight resume banner using localStorage (client-side only). */}
      <div className="mb-6 text-center text-sm text-gray-300">
        <noscript />
        <span id="resume-banner" />
      </div>
      {(() => {
        const idToSlug = Object.fromEntries((modules as any[]).map((m) => [m.frontmatter.id, m.slug]));
        const mapping = JSON.stringify(idToSlug).replace(/</g, '\u003c');
        return (
          <script
            dangerouslySetInnerHTML={{
              __html: `(() => { try { const map = ${mapping}; const keys = Object.keys(localStorage).filter(k => k.startsWith('tco-study-progress:')); for (const k of keys) { const v = JSON.parse(localStorage.getItem(k) || 'null'); if (v && v.lastViewed) { const moduleId = k.split(':')[1]; const slug = map[moduleId] || ''; if (slug) { const el = document.getElementById('resume-banner'); if (el) { el.innerHTML = '<a class="text-cyan-300 hover:underline" href="/modules/' + slug + '#' + encodeURIComponent(v.lastViewed) + '">Continue where you left off →</a>'; } break; } } } } catch {} })();`,
            }}
          />
        );
      })()}
      <ModulesBrowser modules={modules as any} />
    </div>
  );
}

