"use client";

import { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { teamService, type TeamSeat } from "@/lib/team";
import { useAuth } from "@/contexts/AuthContext";
import { analytics } from "@/lib/analytics";

export default function TeamPage() {
  const { user } = useAuth();
  const [seats, setSeats] = useState<TeamSeat[]>([]);
  const [email, setEmail] = useState("");
  const [error, setError] = useState<string | null>(null);
  const limit = teamService.getLimit();

  useEffect(() => {
    let active = true;
    (async () => {
      const list = await teamService.list(user);
      if (active) setSeats(list);
    })();
    return () => { active = false; };
  }, [user?.id]);

  const used = seats.filter((s) => s.status !== "revoked").length;
  const remaining = Math.max(0, limit - used);

  function validEmail(e: string) {
    return /.+@.+\..+/.test(e);
  }

  async function handleInvite() {
    setError(null);
    const e = email.trim().toLowerCase();
    if (!validEmail(e)) {
      setError("Enter a valid email address");
      return;
    }
    if (remaining <= 0) {
      setError("Seat limit reached");
      return;
    }
    if (seats.some((s) => s.email === e && s.status !== "revoked")) {
      setError("This email already has a seat");
      return;
    }
    const seat = await teamService.invite(e, user);
    analytics.capture("team_invite", { email: e });
    setSeats((prev) => [seat, ...prev]);
    setEmail("");
  }

  async function handleRevoke(id: string) {
    await teamService.revoke(id, user);
    analytics.capture("team_revoke", { id });
    setSeats((prev) => prev.map((s) => (s.id === id ? { ...s, status: "revoked" } : s)));
  }

  async function handleActivate(id: string) {
    await teamService.activate(id, user);
    analytics.capture("team_activate", { id });
    setSeats((prev) => prev.map((s) => (s.id === id ? { ...s, status: "active", acceptedAt: new Date().toISOString() } : s)));
  }

  const sorted = useMemo(() => {
    return [...seats].sort((a, b) => (a.invitedAt < b.invitedAt ? 1 : -1));
  }, [seats]);

  return (
    <div className="mx-auto max-w-5xl p-6">
      <h1 className="mb-4 text-3xl font-bold text-white">Team Seats (Beta)</h1>
      <p className="mb-6 text-gray-300">Invite teammates to use your Team plan. This MVP stores seats in your account with Supabase when available, with a local fallback for development.</p>

      <Card className="glass border-white/10">
        <CardHeader>
          <CardTitle className="text-white">Seat Summary</CardTitle>
        </CardHeader>
        <CardContent className="flex items-center justify-between text-sm text-gray-200">
          <div>
            <div><span className="font-medium">Limit:</span> {limit}</div>
            <div><span className="font-medium">Used:</span> {used}</div>
          </div>
          <Badge variant={remaining > 0 ? "secondary" : "outline"}>
            {remaining} seats remaining
          </Badge>
        </CardContent>
      </Card>

      <Card className="mt-6 glass border-white/10">
        <CardHeader>
          <CardTitle className="text-white">Invite a teammate</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="grid gap-2 sm:grid-cols-[1fr_auto] sm:items-end">
            <div>
              <Label htmlFor="invite-email" className="text-gray-300">Email</Label>
              <Input id="invite-email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="teammate@company.com" disabled={!user} />
            </div>
            <Button onClick={handleInvite} disabled={!email.trim() || !user} className="sm:ml-2">Invite</Button>
          </div>
          {!user && <div className="text-sm text-yellow-300">Sign in to invite and manage seats.</div>}
          {error && <div className="text-sm text-red-400">{error}</div>}
        </CardContent>
      </Card>

      <Card className="mt-6 glass border-white/10">
        <CardHeader>
          <CardTitle className="text-white">Seats</CardTitle>
        </CardHeader>
        <CardContent>
          {sorted.length === 0 ? (
            <div className="text-sm text-gray-300">No seats yet. Invite your first teammate above.</div>
          ) : (
            <ul className="divide-y divide-white/10">
              {sorted.map((s) => (
                <li key={s.id} className="flex items-center justify-between py-3">
                  <div>
                    <div className="text-white">{s.email}</div>
                    <div className="text-xs text-gray-400">
                      Invited {new Date(s.invitedAt).toLocaleString()} • Status: {s.status}
                      {s.acceptedAt ? ` • Activated ${new Date(s.acceptedAt).toLocaleString()}` : ""}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    {s.status === "invited" && (
                      <Button size="sm" variant="outline" onClick={() => handleActivate(s.id)}>Mark Active</Button>
                    )}
                    {s.status !== "revoked" && (
                      <Button size="sm" variant="destructive" onClick={() => handleRevoke(s.id)}>Revoke</Button>
                    )}
                  </div>
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { useDatabase } from "@/contexts/DatabaseContext";
import { useIncorrectAnswers } from "@/contexts/IncorrectAnswersContext";
import { useModule } from "@/contexts/ModuleContext";
import { useProgress } from "@/contexts/ProgressContext";
import { useQuestions } from "@/contexts/QuestionsContext";
import { useSearch } from "@/contexts/SearchContext";
import { useSettings } from "@/contexts/SettingsContext";
import { cn } from "@/lib/utils";
import type { TCODomain } from "@/types/exam";
import {
  AlertCircle,
  CheckCircle2,
  Database,
  Loader2,
  RefreshCw,
  User,
  XCircle,
} from "lucide-react";
import { useState } from "react";

interface TestResult {
  name: string;
  status: "pending" | "testing" | "success" | "error";
  message?: string;
  details?: any;
}

export default function TestDatabasePage() {
  const { user, signIn, signOut } = useAuth();
  const db = useDatabase();
  const { state: settingsState, updateSetting, resetSettings } = useSettings();
  const { state: progressState, updateSessionStats } = useProgress();
  const {
    state: incorrectAnswersState,
    addIncorrectAnswer,
    clearAllAnswers,
    getRecentIncorrectAnswers,
  } = useIncorrectAnswers();
  const { state: moduleState, updateModuleProgress, resetProgress } = useModule();
  const { questions: questionsData, loading: questionsLoading } = useQuestions();
  const { performSearch } = useSearch();

  const [testResults, setTestResults] = useState<TestResult[]>([
    { name: "Authentication", status: "pending" },
    { name: "Database Connection", status: "pending" },
    { name: "Settings Context", status: "pending" },
    { name: "Progress Context", status: "pending" },
    { name: "Incorrect Answers Context", status: "pending" },
    { name: "Module Context", status: "pending" },
    { name: "Questions Context", status: "pending" },
    { name: "Search Context", status: "pending" },
  ]);

  const [isRunning, setIsRunning] = useState(false);

  const updateTestResult = (
    name: string,
    status: TestResult["status"],
    message?: string,
    details?: any
  ) => {
    setTestResults((prev) =>
      prev.map((test) => (test.name === name ? { ...test, status, message, details } : test))
    );
  };

  const testAuthentication = async () => {
    updateTestResult("Authentication", "testing");
    try {
      if (!user) {
        updateTestResult("Authentication", "error", "Not authenticated. Please sign in first.");
        return false;
      }
      updateTestResult("Authentication", "success", `Authenticated as ${user.email}`);
      return true;
    } catch (error) {
      updateTestResult("Authentication", "error", String(error));
      return false;
    }
  };

  const testDatabaseConnection = async () => {
    updateTestResult("Database Connection", "testing");
    try {
      if (!db?.supabase) {
        updateTestResult("Database Connection", "error", "Database not initialized");
        return false;
      }

      // Test with a simple query
      const { data, error } = await db.supabase
        .from("user_study_progress")
        .select("count")
        .single();

      if (error && error.code !== "PGRST116") {
        throw error;
      }

      updateTestResult("Database Connection", "success", "Connected to Supabase");
      return true;
    } catch (error) {
      updateTestResult("Database Connection", "error", String(error));
      return false;
    }
  };

  const testSettingsContext = async () => {
    updateTestResult("Settings Context", "testing");
    try {
      // Test updating a setting
      const originalTheme = settingsState.settings.theme;
      updateSetting("theme", originalTheme === "dark" ? "light" : "dark");

      // Wait for save
      await new Promise((resolve) => setTimeout(resolve, 1000));

      // Verify it was saved by checking the state
      if (settingsState.settings.theme === originalTheme) {
        throw new Error("Setting was not updated");
      }

      // Restore original
      updateSetting("theme", originalTheme);

      updateTestResult("Settings Context", "success", "Settings sync working", {
        theme: settingsState.settings.theme,
        soundEnabled: settingsState.settings.soundEnabled,
      });
      return true;
    } catch (error) {
      updateTestResult("Settings Context", "error", String(error));
      return false;
    }
  };

  const testProgressContext = async () => {
    updateTestResult("Progress Context", "testing");
    try {
      // Test updating progress
      const testProgress = {
        questionsAnswered: 10,
        correctAnswers: 8,
        totalTimeSpent: 600,
        lastUpdated: new Date().toISOString(),
      };

      await updateSessionStats(
        testProgress.questionsAnswered,
        testProgress.correctAnswers,
        testProgress.totalTimeSpent
      );

      // Wait for save
      await new Promise((resolve) => setTimeout(resolve, 1000));

      updateTestResult("Progress Context", "success", "Progress sync working", {
        questionsAnswered: progressState.progress.totalQuestions,
        correctAnswers: progressState.progress.correctAnswers,
      });
      return true;
    } catch (error) {
      updateTestResult("Progress Context", "error", String(error));
      return false;
    }
  };

  const testIncorrectAnswersContext = async () => {
    updateTestResult("Incorrect Answers Context", "testing");
    try {
      // Test adding an incorrect answer
      const testAnswer = {
        questionId: `test-q-${Date.now()}`,
        questionText: "Test Question",
        userAnswer: "A",
        correctAnswer: "B",
        explanation: "Test explanation",
        domain: "asking-questions" as TCODomain,
        sessionId: `test-session-${Date.now()}`,
      };

      await addIncorrectAnswer(testAnswer);

      // Wait for save
      await new Promise((resolve) => setTimeout(resolve, 1000));

      // Check if it was added
      const found = incorrectAnswersState.answers.some(
        (a: any) => a.questionId === testAnswer.questionId
      );

      if (!found) {
        throw new Error("Incorrect answer was not added");
      }

      updateTestResult("Incorrect Answers Context", "success", "Incorrect answers sync working", {
        count: incorrectAnswersState.answers.length,
      });
      return true;
    } catch (error) {
      updateTestResult("Incorrect Answers Context", "error", String(error));
      return false;
    }
  };

  const testModuleContext = async () => {
    updateTestResult("Module Context", "testing");
    try {
      // Test updating module progress
      const testModuleId = "test-module-1";
      await updateModuleProgress(testModuleId, {
        completedAt: undefined,
        sectionsCompleted: ["obj-1"],
        currentSection: "section-1",
        totalTimeSpent: 300,
        lastAccessedAt: new Date(),
      });

      // Wait for save
      await new Promise((resolve) => setTimeout(resolve, 1000));

      updateTestResult("Module Context", "success", "Module progress sync working", {
        modulesCount:
          moduleState && (moduleState as any).moduleProgress
            ? Object.keys((moduleState as any).moduleProgress).length
            : 0,
      });
      return true;
    } catch (error) {
      updateTestResult("Module Context", "error", String(error));
      return false;
    }
  };

  const testQuestionsContext = async () => {
    updateTestResult("Questions Context", "testing");
    try {
      // Questions are loaded from Supabase automatically
      if (!questionsData || questionsData.length === 0) {
        throw new Error("No questions loaded from database");
      }

      updateTestResult("Questions Context", "success", `Loaded ${questionsData.length} questions`, {
        totalQuestions: questionsData.length,
        isLoading: questionsLoading,
      });
      return true;
    } catch (error) {
      updateTestResult("Questions Context", "error", String(error));
      return false;
    }
  };

  const testSearchContext = async () => {
    updateTestResult("Search Context", "testing");
    try {
      // Test search functionality
      const results = await performSearch();

      const resultCount = Array.isArray(results) ? results.length : 0;
      updateTestResult("Search Context", "success", `Search returned ${resultCount} results`, {
        resultsCount: resultCount,
      });
      return true;
    } catch (error) {
      updateTestResult("Search Context", "error", String(error));
      return false;
    }
  };

  const runAllTests = async () => {
    setIsRunning(true);

    // Reset all test results
    setTestResults((prev) =>
      prev.map((test) => ({ ...test, status: "pending", message: undefined, details: undefined }))
    );

    // Run tests in sequence
    const authOk = await testAuthentication();
    if (!authOk) {
      setIsRunning(false);
      return;
    }

    const dbOk = await testDatabaseConnection();
    if (!dbOk) {
      setIsRunning(false);
      return;
    }

    // Run remaining tests
    await testSettingsContext();
    await testProgressContext();
    await testIncorrectAnswersContext();
    await testModuleContext();
    await testQuestionsContext();
    await testSearchContext();

    setIsRunning(false);
  };

  const getStatusIcon = (status: TestResult["status"]) => {
    switch (status) {
      case "success":
        return <CheckCircle2 className="h-5 w-5 text-green-400" />;
      case "error":
        return <XCircle className="h-5 w-5 text-red-400" />;
      case "testing":
        return <Loader2 className="h-5 w-5 animate-spin text-blue-400" />;
      default:
        return <AlertCircle className="h-5 w-5 text-gray-400" />;
    }
  };

  const getStatusBadge = (status: TestResult["status"]) => {
    const variants = {
      success: "bg-green-500/20 text-green-300",
      error: "bg-red-500/20 text-red-300",
      testing: "bg-blue-500/20 text-blue-300",
      pending: "bg-gray-500/20 text-gray-300",
    };

    return <Badge className={cn("ml-auto", variants[status])}>{status}</Badge>;
  };

  return (

      <div className="container mx-auto max-w-6xl px-4 py-8">
        <div className="mb-8">
          <h1 className="mb-4 text-4xl font-bold text-white">Database Integration Test</h1>
          <p className="text-white/70">Verify all database connections and context integrations</p>
        </div>

        {/* Authentication Status */}
        <Card className="glass mb-6 border-white/10">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-white">
              <User className="h-5 w-5" />
              Authentication Status
            </CardTitle>
          </CardHeader>
          <CardContent>
            {user ? (
              <div className="space-y-2">
                <Alert className="border-green-500/30 bg-green-500/10">
                  <CheckCircle2 className="h-4 w-4 text-green-400" />
                  <AlertDescription className="text-white">
                    Signed in as <strong>{user.email}</strong>
                  </AlertDescription>
                </Alert>
                <Button
                  onClick={signOut}
                  variant="outline"
                  className="border-white/20 text-white hover:bg-white/10"
                >
                  Sign Out
                </Button>
              </div>
            ) : (
              <div className="space-y-2">
                <Alert className="border-yellow-500/30 bg-yellow-500/10">
                  <AlertCircle className="h-4 w-4 text-yellow-400" />
                  <AlertDescription className="text-white">
                    Not authenticated. Sign in to test database features.
                  </AlertDescription>
                </Alert>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Test Controls */}
        <Card className="glass mb-6 border-white/10">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-white">
              <Database className="h-5 w-5" />
              Test Controls
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex gap-4">
              <Button
                onClick={runAllTests}
                disabled={!user || isRunning}
                className="bg-tanium-accent hover:bg-tanium-accent/80"
              >
                {isRunning ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Running Tests...
                  </>
                ) : (
                  <>
                    <RefreshCw className="mr-2 h-4 w-4" />
                    Run All Tests
                  </>
                )}
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Test Results */}
        <Card className="glass border-white/10">
          <CardHeader>
            <CardTitle className="text-white">Test Results</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {testResults.map((test) => (
                <div key={test.name} className="flex items-start gap-3 rounded-lg bg-white/5 p-3">
                  {getStatusIcon(test.status)}
                  <div className="flex-1">
                    <div className="flex items-center">
                      <h3 className="font-medium text-white">{test.name}</h3>
                      {getStatusBadge(test.status)}
                    </div>
                    {test.message && <p className="mt-1 text-sm text-white/70">{test.message}</p>}
                    {test.details && (
                      <pre className="mt-2 rounded bg-black/20 p-2 text-xs text-white/50">
                        {JSON.stringify(test.details, null, 2)}
                      </pre>
                    )}
