                  )}
                </div>
              </motion.button>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile Navigation Menu */}
      <AnimatePresence>
        {isMenuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -20, scale: 0.95 }}
            className="lg:hidden mt-2 bg-black/80 backdrop-blur-xl border border-cyan-500/20 rounded-2xl shadow-[0_0_50px_rgba(34,211,238,0.1)]"
          >
            <div className="relative p-4">
              <div className="relative space-y-2">
                {navItems.map((item) => (
                  <motion.button
                    key={item.name}
                    onClick={() => {
                      handleTabChange(item.name, item.href)
                      setIsMenuOpen(false)
                    }}
                    className={`w-full text-left px-4 py-3 rounded-lg transition-all duration-300 flex items-center space-x-3 ${
                      activeTab === item.name
                        ? 'text-cyan-400 bg-cyan-500/10'
                        : 'text-cyan-100/80 hover:text-cyan-400 hover:bg-cyan-500/5'
                    }`}
                    whileHover={{ x: 5 }}
                  >
                    {item.icon}
                    <span className="font-medium">{item.name}</span>
                  </motion.button>
                ))}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  )
}

