    optimalStudyTime: string;
    suggestedFrequency: string;
    weeklyTarget: number;
    predictedGrowth: number;
  };
  examSimulation: {
    passLikelihood: number;
    expectedScore: number;
    strengthAreas: string[];
    focusAreas: string[];
  };
}

export function PerformancePredictions() {
  const { getDomainStats, getOverallStats, state } = useProgress();

  // Memoize expensive function calls to prevent infinite re-renders
  const domainStats = useMemo(() => getDomainStats(), [getDomainStats]);
  const overallStats = useMemo(() => getOverallStats(), [getOverallStats]);

  // AI-powered prediction model
  const generatePredictions = (): PredictionModel => {
    const { totalQuestions } = overallStats;
    const avgScore = overallStats.averageScore;
    const { studyStreak } = overallStats;
    const { sessionCount } = state.progress;

    // Calculate exam readiness
    const readinessFactors = {
      avgScore: Math.min(avgScore / 85, 1), // 85% is target for exam readiness
      consistency: Math.min(studyStreak / 14, 1), // 2 weeks streak is ideal
      practice: Math.min(totalQuestions / 500, 1), // 500 questions is comprehensive
      coverage: Math.min(sessionCount / 20, 1), // 20 sessions shows commitment
    };

    const readinessScore = Math.round(
      (readinessFactors.avgScore * 0.4 +
        readinessFactors.consistency * 0.2 +
        readinessFactors.practice * 0.3 +
        readinessFactors.coverage * 0.1) *
        100
    );

    let readinessLevel: PredictionModel["examReadiness"]["level"] = "Poor";
    let timeToReady = "8-12 weeks";
    let requiredSessions = 30;

    if (readinessScore >= 90) {
      readinessLevel = "Exam Ready";
      timeToReady = "Ready now";
      requiredSessions = 0;
    } else if (readinessScore >= 75) {
      readinessLevel = "Excellent";
      timeToReady = "1-2 weeks";
      requiredSessions = 3;
    } else if (readinessScore >= 60) {
      readinessLevel = "Good";
      timeToReady = "2-4 weeks";
      requiredSessions = 8;
    } else if (readinessScore >= 40) {
      readinessLevel = "Fair";
      timeToReady = "4-6 weeks";
      requiredSessions = 15;
    }

    // Domain predictions
    const domainPredictions = domainStats.map((domain) => {
      const currentScore = domain.score;
      const { questionsAnswered } = domain;

      // Predict improvement based on current trajectory
      const growthRate =
        questionsAnswered > 10
          ? Math.min((currentScore - 50) / 10, 5) // Assume 50% baseline
          : 2; // Default growth rate

      const predictedScore = Math.min(currentScore + growthRate * 2, 100);
      const confidence = Math.min(questionsAnswered * 5, 95); // Confidence based on data points

      let recommendation = "Continue current pace";
      if (currentScore < 60) {
        recommendation = "Intensive study needed - focus on fundamentals";
      } else if (currentScore < 75) {
        recommendation = "Regular practice with targeted improvement";
      } else if (currentScore >= 85) {
        recommendation = "Maintain proficiency with light practice";
      }

      return {
        domain: domain.domain,
        currentScore,
        predictedScore,
        confidence,
        recommendation,
      };
    });

    // Study insights
    const studyInsights = {
      optimalStudyTime:
        avgScore < 60 ? "45-60 minutes" : avgScore < 80 ? "30-45 minutes" : "20-30 minutes",
      suggestedFrequency:
        studyStreak < 7 ? "Daily" : studyStreak < 14 ? "5-6 times per week" : "4-5 times per week",
      weeklyTarget: avgScore < 60 ? 100 : avgScore < 80 ? 75 : 50,
      predictedGrowth: Math.round(Math.min(15 - avgScore / 10, 8)),
    };

    // Exam simulation
    const strongDomains = domainStats.filter((d) => d.score >= 75).map((d) => d.domain);
    const weakDomains = domainStats.filter((d) => d.score < 65).map((d) => d.domain);

    const examSimulation = {
      passLikelihood: Math.min(Math.max((avgScore - 50) * 2, 0), 100),
      expectedScore: Math.round(avgScore + studyStreak * 0.5),
      strengthAreas: strongDomains,
      focusAreas: weakDomains,
    };

    return {
      examReadiness: {
        score: readinessScore,
        level: readinessLevel,
        confidence: Math.min(totalQuestions * 2, 95),
        timeToReady,
        requiredSessions,
      },
      domainPredictions,
      studyInsights,
      examSimulation,
    };
  };

  const predictions = generatePredictions();

  const getReadinessColor = (level: string) => {
    switch (level) {
      case "Exam Ready":
        return "text-green-400 border-green-400 bg-green-400/10";
      case "Excellent":
        return "text-blue-400 border-blue-400 bg-blue-400/10";
      case "Good":
        return "text-yellow-400 border-yellow-400 bg-yellow-400/10";
      case "Fair":
        return "text-orange-400 border-orange-400 bg-orange-400/10";
      default:
        return "text-red-400 border-red-400 bg-red-400/10";
    }
  };

  const getReadinessIcon = (level: string) => {
    switch (level) {
      case "Exam Ready":
        return Trophy;
      case "Excellent":
        return CheckCircle;
      case "Good":
        return Target;
      case "Fair":
        return Clock;
      default:
        return AlertTriangle;
    }
  };

  return (
    <Card className="glass border-white/10">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-white">
          <Brain className="h-5 w-5 text-tanium-accent" />
          Performance Predictions & Exam Readiness
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Exam Readiness Overview */}
        <div className="grid gap-6 lg:grid-cols-3">
          <div className="lg:col-span-2">
            <div
              className={`rounded-lg border p-6 ${getReadinessColor(predictions.examReadiness.level)}`}
            >
              <div className="mb-4 flex items-start justify-between">
                <div>
                  <h3 className="mb-1 text-xl font-bold text-white">
                    Exam Readiness: {predictions.examReadiness.score}%
                  </h3>
                  <Badge className={getReadinessColor(predictions.examReadiness.level)}>
                    {predictions.examReadiness.level}
                  </Badge>
                </div>
                {(() => {
                  const Icon = getReadinessIcon(predictions.examReadiness.level);
                  return <Icon className="h-8 w-8 text-current" />;
                })()}
              </div>

              <Progress value={predictions.examReadiness.score} className="mb-4 h-3" />

              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <div className="mb-2 flex items-center gap-2 text-gray-300">
                    <Clock className="h-4 w-4" />
                    <span className="text-sm">Time to Ready</span>
                  </div>
                  <p className="font-medium text-white">{predictions.examReadiness.timeToReady}</p>
                </div>
                <div>
                  <div className="mb-2 flex items-center gap-2 text-gray-300">
                    <BookOpen className="h-4 w-4" />
                    <span className="text-sm">Sessions Needed</span>
                  </div>
                  <p className="font-medium text-white">
                    {predictions.examReadiness.requiredSessions} sessions
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-4">
            <div className="glass rounded-lg border border-white/10 p-4">
              <h4 className="mb-3 flex items-center gap-2 font-medium text-white">
                <Target className="h-4 w-4 text-tanium-accent" />
                Pass Likelihood
              </h4>
              <div className="text-center">
                <div className="mb-1 text-2xl font-bold text-tanium-accent">
                  {predictions.examSimulation.passLikelihood}%
                </div>
                <Progress value={predictions.examSimulation.passLikelihood} className="h-2" />
              </div>
            </div>

            <div className="glass rounded-lg border border-white/10 p-4">
              <h4 className="mb-3 flex items-center gap-2 font-medium text-white">
                <BarChart3 className="h-4 w-4 text-tanium-accent" />
                Expected Score
              </h4>
              <div className="text-center">
                <div className="text-2xl font-bold text-tanium-accent">
                  {predictions.examSimulation.expectedScore}%
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Domain Predictions */}
        <div className="space-y-4">
          <h4 className="flex items-center gap-2 font-medium text-white">
            <TrendingUp className="h-4 w-4 text-tanium-accent" />
            Domain Performance Predictions
          </h4>
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {predictions.domainPredictions.map((prediction) => (
              <div key={prediction.domain} className="glass rounded-lg border border-white/10 p-4">
                <div className="mb-3 flex items-center justify-between">
                  <h5 className="text-sm font-medium text-white">{prediction.domain}</h5>
                  <Badge
                    variant="outline"
                    className="text-xs"
                    style={{
                      borderColor:
                        prediction.confidence > 70
                          ? "#10B981"
                          : prediction.confidence > 50
                            ? "#F59E0B"
                            : "#EF4444",
                      color:
                        prediction.confidence > 70
                          ? "#10B981"
                          : prediction.confidence > 50
                            ? "#F59E0B"
                            : "#EF4444",
                    }}
                  >
                    {prediction.confidence}% confidence
                  </Badge>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-300">Current</span>
                    <span className="font-medium text-white">{prediction.currentScore}%</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-300">Predicted</span>
                    <span className="font-medium text-tanium-accent">
                      {prediction.predictedScore}%
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    {prediction.predictedScore > prediction.currentScore ? (
                      <TrendingUp className="h-3 w-3 text-green-400" />
                    ) : (
                      <Activity className="h-3 w-3 text-gray-400" />
                    )}
                    <span className="text-xs text-gray-400">
                      {prediction.predictedScore > prediction.currentScore ? "+" : ""}
                      {Math.round(prediction.predictedScore - prediction.currentScore)} points
                    </span>
                  </div>
                </div>

                <div className="mt-3 border-t border-white/10 pt-3">
                  <p className="text-xs text-gray-400">{prediction.recommendation}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Study Insights */}
        <div className="grid gap-4 md:grid-cols-2">
          <div className="glass rounded-lg border border-white/10 p-4">
            <h4 className="mb-4 flex items-center gap-2 font-medium text-white">
              <Calendar className="h-4 w-4 text-tanium-accent" />
              Optimized Study Plan
            </h4>
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-300">Session Length</span>
                <span className="font-medium text-white">
                  {predictions.studyInsights.optimalStudyTime}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-300">Frequency</span>
                <span className="font-medium text-white">
                  {predictions.studyInsights.suggestedFrequency}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-300">Weekly Target</span>
                <span className="font-medium text-white">
                  {predictions.studyInsights.weeklyTarget} questions
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-300">Expected Growth</span>
                <span className="font-medium text-tanium-accent">
                  +{predictions.studyInsights.predictedGrowth}% per month
                </span>
              </div>
            </div>
          </div>

          <div className="glass rounded-lg border border-white/10 p-4">
            <h4 className="mb-4 flex items-center gap-2 font-medium text-white">
              <Zap className="h-4 w-4 text-tanium-accent" />
              Focus Areas
            </h4>
            <div className="space-y-3">
              <div>
                <span className="mb-2 block text-sm text-gray-300">Strengths to Maintain</span>
                <div className="flex flex-wrap gap-2">
                  {predictions.examSimulation.strengthAreas.length > 0 ? (
                    predictions.examSimulation.strengthAreas.map((area) => (
                      <Badge key={area} className="border-green-400 bg-green-400/10 text-green-400">
                        {area}
                      </Badge>
                    ))
                  ) : (
                    <span className="text-xs text-gray-500">Continue building strengths</span>
                  )}
                </div>
              </div>

              <div>
                <span className="mb-2 block text-sm text-gray-300">Priority Focus</span>
                <div className="flex flex-wrap gap-2">
                  {predictions.examSimulation.focusAreas.length > 0 ? (
                    predictions.examSimulation.focusAreas.map((area) => (
                      <Badge key={area} className="border-red-400 bg-red-400/10 text-red-400">
                        {area}
                      </Badge>
                    ))
                  ) : (
                    <span className="text-xs text-green-400">All domains performing well!</span>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Disclaimer */}
        <div className="glass rounded-lg border border-yellow-400/20 bg-yellow-400/5 p-4">
          <div className="flex items-start gap-3">
            <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-yellow-400" />
            <div>
              <h4 className="mb-1 font-medium text-yellow-400">Prediction Methodology</h4>
              <p className="text-sm text-gray-300">
                These predictions are based on your current performance patterns, study consistency,
                and practice volume. Results may vary based on individual learning pace and study
                quality. Use as guidance alongside your personal assessment of readiness.
              </p>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
} from "recharts";
import { TrendingUp, BarChart3 } from "lucide-react";

interface ScoreDataPoint {
  period: string;
  score: number;
  questions: number;
}

interface ScoreChartProps {
  data: ScoreDataPoint[];
  title: string;
  type?: "line" | "bar";
  showTrend?: boolean;
}

export function ScoreChart({ data, title, type = "line", showTrend = true }: ScoreChartProps) {
  const averageScore = Math.round(data.reduce((sum, point) => sum + point.score, 0) / data.length);
  const trend = data.length > 1 ? data[data.length - 1].score - data[0].score : 0;

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload?.length) {
      return (
        <div className="rounded-lg border border-white/10 bg-gray-900/95 p-3 text-white">
          <p className="font-medium">{label}</p>
          <p className="text-tanium-accent">Score: {payload[0].value}%</p>
          {payload[0].payload.questions && (
            <p className="text-sm text-gray-300">Questions: {payload[0].payload.questions}</p>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <Card className="glass border-white/10">
      <CardHeader>
        <CardTitle className="flex items-center justify-between text-white">
          <div className="flex items-center gap-2">
            {type === "line" ? (
              <TrendingUp className="h-5 w-5 text-tanium-accent" />
            ) : (
              <BarChart3 className="h-5 w-5 text-tanium-accent" />
            )}
            {title}
          </div>
          {showTrend && (
            <div className="flex items-center gap-2 text-sm">
              <span className="text-gray-300">Avg: {averageScore}%</span>
              {trend !== 0 && (
                <span className={trend > 0 ? "text-green-400" : "text-red-400"}>
                  {trend > 0 ? "+" : ""}
                  {trend}%
                </span>
              )}
            </div>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={300}>
          {type === "line" ? (
            <LineChart data={data}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" opacity={0.3} />
              <XAxis dataKey="period" stroke="#9CA3AF" fontSize={12} />
              <YAxis stroke="#9CA3AF" fontSize={12} domain={[0, 100]} />
              <Tooltip content={<CustomTooltip />} />
              <Line
                type="monotone"
                dataKey="score"
                stroke="#3B82F6"
                strokeWidth={3}
                dot={{ fill: "#3B82F6", strokeWidth: 2, r: 4 }}
                activeDot={{ r: 6, stroke: "#3B82F6", strokeWidth: 2 }}
              />
            </LineChart>
          ) : (
            <BarChart data={data}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" opacity={0.3} />
              <XAxis dataKey="period" stroke="#9CA3AF" fontSize={12} />
              <YAxis stroke="#9CA3AF" fontSize={12} domain={[0, 100]} />
              <Tooltip content={<CustomTooltip />} />
              <Bar dataKey="score" fill="#3B82F6" radius={[4, 4, 0, 0]} opacity={0.8} />
            </BarChart>
          )}
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { useProgress } from "@/contexts/ProgressContext";
import { TCODomain } from "@/types/exam";
import { cn } from "@/lib/utils";
import { useMemo } from "react";
import {
  Brain,
  Target,
  Clock,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
  Zap,
  BookOpen,
  Shield,
  Server,
  FileText,
  Layers,
  Wrench,
  Trophy,
  MessageSquare,
  Play,
  Navigation,
  BarChart3,
} from "lucide-react";

interface Recommendation {
  type: "focus" | "practice" | "review" | "exam" | "achievement";
  priority: "high" | "medium" | "low";
  title: string;
  description: string;
  action: string;
  link: string;
  icon: any;
  color: string;
}

export function StudyRecommendations() {
  const router = useRouter();
  const { getOverallStats, getDomainStats, state } = useProgress();

  // Memoize expensive function calls to prevent infinite re-renders
  const overallStats = useMemo(() => getOverallStats(), [getOverallStats]);
  const domainStats = useMemo(() => getDomainStats(), [getDomainStats]);

  const generateRecommendations = (): Recommendation[] => {
    const recommendations: Recommendation[] = [];

    // Find weakest domain
    const weakestDomain = domainStats.reduce((min, domain) =>
      domain.score < min.score ? domain : min
    );

    // Find strongest domain
    const strongestDomain = domainStats.reduce((max, domain) =>
      domain.score > max.score ? domain : max
    );

    // Domain-specific recommendations
    if (weakestDomain && weakestDomain.score < 70) {
      const domainIcons = {
        [TCODomain.ASKING_QUESTIONS]: BookOpen,
        [TCODomain.REFINING_QUESTIONS]: Target,
        [TCODomain.REFINING_TARGETING]: Target,
        [TCODomain.TAKING_ACTION]: Zap,
        [TCODomain.NAVIGATION_MODULES]: Layers,
        [TCODomain.REPORTING_EXPORT]: FileText,
        [TCODomain.SECURITY]: Shield,
        [TCODomain.FUNDAMENTALS]: BookOpen,
        [TCODomain.TROUBLESHOOTING]: AlertTriangle,
      };

      const domainUrls: Record<TCODomain, string> = {
        [TCODomain.ASKING_QUESTIONS]: "asking-questions",
        [TCODomain.REFINING_QUESTIONS]: "refining-questions",
        [TCODomain.REFINING_TARGETING]: "refining-questions-targeting",
        [TCODomain.TAKING_ACTION]: "taking-action",
        [TCODomain.NAVIGATION_MODULES]: "navigation-modules",
        [TCODomain.REPORTING_EXPORT]: "reporting-export",
        [TCODomain.SECURITY]: "security",
        [TCODomain.FUNDAMENTALS]: "fundamentals",
        [TCODomain.TROUBLESHOOTING]: "troubleshooting",
      };

      recommendations.push({
        type: "focus",
        priority: "high",
        title: `Focus on ${weakestDomain.domain}`,
        description: `Your weakest area with ${weakestDomain.score}% average. Targeted practice will improve overall readiness.`,
        action: `Study ${weakestDomain.domain}`,
        link: `/domains/${domainUrls[weakestDomain.domain]}`,
        icon: domainIcons[weakestDomain.domain] || Target,
        color: "text-red-400 border-red-400",
      });
    }

    // Study streak recommendations
    if (overallStats.studyStreak === 0) {
      recommendations.push({
        type: "practice",
        priority: "high",
        title: "Start Your Study Streak",
        description: "Begin building momentum with daily practice sessions to improve retention.",
        action: "Start Practice",
        link: "/practice",
        icon: Zap,
        color: "text-orange-400 border-orange-400",
      });
    } else if (overallStats.studyStreak < 7) {
      recommendations.push({
        type: "practice",
        priority: "medium",
        title: "Build Study Consistency",
        description: `You're on a ${overallStats.studyStreak}-day streak. Keep going to reach the 7-day milestone!`,
        action: "Continue Streak",
        link: "/practice",
        icon: Clock,
        color: "text-yellow-400 border-yellow-400",
      });
    }

    // Overall score recommendations
    if (overallStats.averageScore < 70) {
      recommendations.push({
        type: "review",
        priority: "high",
        title: "Review Fundamentals",
        description:
          "Your overall score suggests focusing on core concepts before attempting mock exams.",
        action: "Review Basics",
        link: "/domains/fundamentals",
        icon: BookOpen,
        color: "text-blue-400 border-blue-400",
      });
    } else if (overallStats.averageScore >= 80) {
      recommendations.push({
        type: "exam",
        priority: "medium",
        title: "Ready for Mock Exams",
        description: "Your strong performance indicates readiness for timed practice exams.",
        action: "Take Mock Exam",
        link: "/mock",
        icon: CheckCircle,
        color: "text-green-400 border-green-400",
      });
    }

    // Session count recommendations
    if (state.progress.sessionCount < 5) {
      recommendations.push({
        type: "practice",
        priority: "medium",
        title: "Build Practice Momentum",
        description:
          "Complete more practice sessions to establish patterns and identify knowledge gaps.",
        action: "Start Practice",
        link: "/practice",
        icon: Target,
        color: "text-blue-400 border-blue-400",
      });
    }

    // Readiness-based recommendations
    if (overallStats.readinessLevel === "Poor" || overallStats.readinessLevel === "Fair") {
      recommendations.push({
        type: "focus",
        priority: "high",
        title: "Intensive Study Needed",
        description: "Current readiness level requires focused study across multiple domains.",
        action: "Study Plan",
        link: "/domains/fundamentals",
        icon: Brain,
        color: "text-red-400 border-red-400",
      });
    }

    // Achievement recommendations
    const possibleAchievements = [
      {
        name: "Perfect Score",
        condition: () => !state.progress.achievements.includes("Perfect Score"),
      },
      {
        name: "Week Warrior",
        condition: () =>
          overallStats.studyStreak < 7 && !state.progress.achievements.includes("Week Warrior"),
      },
      {
        name: "Centurion",
        condition: () =>
          overallStats.totalQuestions < 100 && !state.progress.achievements.includes("Centurion"),
      },
    ];

    const nextAchievement = possibleAchievements.find((achievement) => achievement.condition());
    if (nextAchievement) {
      recommendations.push({
        type: "achievement",
        priority: "low",
        title: `Unlock "${nextAchievement.name}"`,
        description: getAchievementDescription(nextAchievement.name),
        action: "Work Toward Goal",
        link: "/practice",
        icon: Trophy,
        color: "text-cyan-400 border-cyan-400",
      });
    }

    // Sort by priority
    const priorityOrder = { high: 3, medium: 2, low: 1 };
    return recommendations
      .sort((a, b) => priorityOrder[b.priority] - priorityOrder[a.priority])
      .slice(0, 6);
  };

  const getAchievementDescription = (achievement: string): string => {
    switch (achievement) {
      case "Perfect Score":
        return "Score 100% on any practice session to unlock this achievement.";
      case "Week Warrior":
        return `Study for ${7 - overallStats.studyStreak} more consecutive days to earn this badge.`;
      case "Centurion":
        return `Answer ${100 - overallStats.totalQuestions} more questions to reach 100 total.`;
      default:
        return "Complete the requirements to unlock this achievement.";
    }
  };

  const recommendations = generateRecommendations();

  if (recommendations.length === 0) {
    return (
      <Card className="glass border-white/10">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-white">
            <CheckCircle className="h-5 w-5 text-green-400" />
            Excellent Progress!
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="py-8 text-center">
            <CheckCircle className="mx-auto mb-4 h-12 w-12 text-green-400" />
            <h3 className="mb-2 font-medium text-white">You&rsquo;re on track!</h3>
            <p className="mb-4 text-gray-400">
              Your performance is strong across all areas. Continue with regular practice to
              maintain your readiness.
            </p>
            <Button
              onClick={() => router.push("/mock")}
              className="bg-tanium-accent hover:bg-blue-600"
            >
              Take a Mock Exam
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="glass border-white/10">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-white">
          <Brain className="h-5 w-5 text-tanium-accent" />
          Personalized Study Recommendations
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {recommendations.map((rec, index) => {
            const Icon = rec.icon;
            return (
              <div
                key={index}
                className="glass flex items-start gap-4 rounded-lg border border-white/10 p-4 transition-colors hover:border-white/20"
              >
                <div className={`rounded-lg p-2 bg-${rec.color.split("-")[1]}-500/20`}>
                  <Icon className={`h-5 w-5 ${rec.color}`} />
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <h4 className="mb-1 font-medium text-white">{rec.title}</h4>
                      <p className="mb-3 text-sm text-gray-400">{rec.description}</p>
                    </div>
                    <Badge
                      variant="outline"
                      className={cn(
                        "shrink-0",
                        rec.priority === "high"
                          ? "border-red-400 text-red-400"
                          : rec.priority === "medium"
                            ? "border-yellow-400 text-yellow-400"
                            : "border-gray-400 text-gray-400"
                      )}
                    >
                      {rec.priority}
                    </Badge>
                  </div>
                  <Button
                    size="sm"
                    onClick={() => router.push(rec.link)}
                    className="bg-tanium-accent hover:bg-blue-600"
                  >
                    {rec.action}
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * Module 3 Assessment Results Component
 * Displays comprehensive assessment results for the 9-section structure
 */

"use client";

import { useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import {
  TrendingUp,
  TrendingDown,
  Target,
  Clock,
  CheckCircle,
  XCircle,
  AlertTriangle,
  BookOpen,
  Award,
  BarChart3,
  Lightbulb,
  ArrowRight
} from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Module3Section,
  MODULE_3_SECTIONS
} from "@/lib/module3-section-definitions";
import { type Module3AssessmentResult } from "@/lib/module3-assessment-engine";

interface Module3AssessmentResultsProps {
  result: Module3AssessmentResult;
  onRetakeSection?: (sectionId: Module3Section) => void;
  onStudySection?: (sectionId: Module3Section) => void;
  onRetakeAll?: () => void;
  className?: string;
}

export function Module3AssessmentResults({
  result,
  onRetakeSection,
  onStudySection,
  onRetakeAll,
  className
}: Module3AssessmentResultsProps) {
  const {
    overallScore,
    overallAccuracy,
    totalTimeSpent,
    passed,
    sectionResults,
    strengths,
    weaknesses,
    gapsIdentified,
    recommendations,
    certificationReadiness
  } = result;

  const formatTime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    if (hours > 0) {
      return `${hours}h ${minutes}m`;
    }
    return `${minutes}m`;
  };

  const getScoreColor = (score: number) => {
    if (score >= 0.85) return "text-green-600";
    if (score >= 0.75) return "text-yellow-600";
    return "text-red-600";
  };

  const getReadinessColor = (readiness: string) => {
    switch (readiness) {
      case "ready": return "text-green-600 bg-green-50 border-green-200";
      case "almost_ready": return "text-yellow-600 bg-yellow-50 border-yellow-200";
      case "needs_work": return "text-red-600 bg-red-50 border-red-200";
      default: return "text-gray-600 bg-gray-50 border-gray-200";
    }
  };

  const sortedSections = useMemo(() => {
    return Object.entries(sectionResults).sort(([, a], [, b]) => b.score - a.score);
  }, [sectionResults]);

  return (
    <div className={cn("space-y-6", className)}>
      {/* Overall Results Header */}
      <Card className={cn("border-2", passed ? "border-green-200 bg-green-50/50" : "border-red-200 bg-red-50/50")}>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-2xl flex items-center gap-2">
              {passed ? (
                <CheckCircle className="w-8 h-8 text-green-600" />
              ) : (
                <XCircle className="w-8 h-8 text-red-600" />
              )}
              Module 3 Assessment {passed ? "Passed" : "Failed"}
            </CardTitle>
            <Badge variant={passed ? "default" : "destructive"} className="text-lg px-4 py-2">
              {Math.round(overallScore * 100)}%
            </Badge>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-3 gap-6 mb-6">
            <div className="text-center">
              <div className="text-3xl font-bold text-primary">
                {Math.round(overallScore * 100)}%
              </div>
              <div className="text-sm text-muted-foreground">Overall Score</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-primary">
                {Math.round(overallAccuracy * 100)}%
              </div>
              <div className="text-sm text-muted-foreground">Accuracy</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-primary">
                {formatTime(totalTimeSpent)}
              </div>
              <div className="text-sm text-muted-foreground">Time Spent</div>
            </div>
          </div>
          <Progress value={overallScore * 100} className="h-3" />
        </CardContent>
      </Card>

      {/* Certification Readiness */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Award className="w-5 h-5" />
            Certification Readiness
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className={cn("p-4 rounded-lg border", getReadinessColor(certificationReadiness.overallReadiness))}>
            <div className="flex items-center justify-between mb-2">
              <span className="font-semibold text-lg">
                {certificationReadiness.overallReadiness.replace("_", " ").toUpperCase()}
              </span>
              <span className="text-2xl font-bold">
                {certificationReadiness.score}%
              </span>
            </div>
            <div className="text-sm opacity-80">
              {certificationReadiness.overallReadiness === "ready" &&
                "You're ready for the TCO exam! Continue practicing to maintain your skills."}
              {certificationReadiness.overallReadiness === "almost_ready" &&
                "You're close to being ready. Focus on the areas below for improvement."}
              {certificationReadiness.overallReadiness === "needs_work" &&
                "More preparation needed. Review the priority areas and retake practice sessions."}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Section Performance */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <BarChart3 className="w-5 h-5" />
            Section Performance
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {sortedSections.map(([sectionId, sectionResult]) => {
            const section = MODULE_3_SECTIONS[sectionId as Module3Section];
            const readiness = certificationReadiness.areas[sectionId as Module3Section];

            return (
              <div key={sectionId} className="p-4 border rounded-lg">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-3">
                    <div className="flex items-center gap-2">
                      {sectionResult.passed ? (
                        <CheckCircle className="w-4 h-4 text-green-500" />
                      ) : (
                        <XCircle className="w-4 h-4 text-red-500" />
                      )}
                      <span className="font-medium">{section.title}</span>
                    </div>
                    <Badge variant="outline" className="text-xs">
                      {section.difficulty}
                    </Badge>
                    <Badge
                      variant={readiness === "strong" ? "default" : readiness === "adequate" ? "secondary" : "destructive"}
                      className="text-xs"
                    >
                      {readiness.replace("_", " ")}
                    </Badge>
                  </div>
                  <span className={cn("font-bold text-lg", getScoreColor(sectionResult.score))}>
                    {Math.round(sectionResult.score * 100)}%
                  </span>
                </div>

                <div className="grid grid-cols-4 gap-4 mb-3 text-sm">
                  <div>
                    <span className="text-muted-foreground">Questions:</span>
                    <span className="ml-1 font-medium">
                      {sectionResult.questionsCorrect}/{sectionResult.questionsAttempted}
                    </span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">Accuracy:</span>
                    <span className="ml-1 font-medium">
                      {Math.round(sectionResult.accuracy * 100)}%
                    </span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">Time:</span>
                    <span className="ml-1 font-medium">
                      {formatTime(sectionResult.timeSpent)}
                    </span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">Objectives:</span>
                    <span className="ml-1 font-medium">
                      {sectionResult.objectivesMet.length}/{sectionResult.objectivesMet.length + sectionResult.objectivesMissed.length}
                    </span>
                  </div>
                </div>

                <Progress value={sectionResult.score * 100} className="h-2 mb-3" />

                {sectionResult.recommendations.length > 0 && (
                  <div className="bg-muted/30 p-3 rounded text-sm">
                    <div className="font-medium mb-1 flex items-center gap-1">
                      <Lightbulb className="w-3 h-3" />
                      Recommendations:
                    </div>
                    <ul className="space-y-1">
                      {sectionResult.recommendations.map((rec, index) => (
                        <li key={index} className="text-muted-foreground">• {rec}</li>
                      ))}
                    </ul>
                  </div>
                )}

                <div className="flex gap-2 mt-3">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onStudySection?.(sectionId as Module3Section)}
                  >
                    <BookOpen className="w-3 h-3 mr-1" />
                    Study
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => onRetakeSection?.(sectionId as Module3Section)}
                  >
                    <Target className="w-3 h-3 mr-1" />
                    Practice
                  </Button>
                </div>
              </div>
            );
          })}
        </CardContent>
      </Card>

      {/* Strengths and Weaknesses */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Strengths */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-green-600">
              <TrendingUp className="w-5 h-5" />
              Strengths
            </CardTitle>
          </CardHeader>
          <CardContent>
            {strengths.length > 0 ? (
              <ul className="space-y-2">
                {strengths.map(sectionId => (
                  <li key={sectionId} className="flex items-center gap-2">
                    <CheckCircle className="w-4 h-4 text-green-500" />
                    <span>{MODULE_3_SECTIONS[sectionId].title}</span>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-muted-foreground">Focus on improving overall performance to identify strengths.</p>
            )}
          </CardContent>
        </Card>

        {/* Weaknesses */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-red-600">
              <TrendingDown className="w-5 h-5" />
              Areas for Improvement
            </CardTitle>
          </CardHeader>
          <CardContent>
            {weaknesses.length > 0 || gapsIdentified.length > 0 ? (
              <div className="space-y-3">
                {weaknesses.length > 0 && (
                  <div>
                    <div className="text-sm font-medium mb-2">Weak Performance:</div>
                    <ul className="space-y-1">
                      {weaknesses.map(sectionId => (
                        <li key={sectionId} className="flex items-center gap-2 text-sm">
                          <XCircle className="w-3 h-3 text-red-500" />
                          <span>{MODULE_3_SECTIONS[sectionId].title}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {gapsIdentified.length > 0 && (
                  <div>
                    <div className="text-sm font-medium mb-2">Not Attempted:</div>
                    <ul className="space-y-1">
                      {gapsIdentified.map(sectionId => (
                        <li key={sectionId} className="flex items-center gap-2 text-sm">
                          <AlertTriangle className="w-3 h-3 text-yellow-500" />
                          <span>{MODULE_3_SECTIONS[sectionId].title}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            ) : (
              <p className="text-muted-foreground">Great job! No major areas of concern identified.</p>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Recommendations */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Lightbulb className="w-5 h-5" />
            Recommendations
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {recommendations.priorityAreas.length > 0 && (
            <div>
              <h4 className="font-medium mb-2">Priority Areas:</h4>
              <div className="flex flex-wrap gap-2">
                {recommendations.priorityAreas.map(sectionId => (
                  <Badge key={sectionId} variant="outline">
                    {MODULE_3_SECTIONS[sectionId].title}
                  </Badge>
                ))}
              </div>
            </div>
          )}

          <div>
            <h4 className="font-medium mb-2">Suggested Study Time:</h4>
            <div className="flex items-center gap-2">
              <Clock className="w-4 h-4 text-muted-foreground" />
              <span>{recommendations.suggestedStudyTime} minutes additional study recommended</span>
            </div>
          </div>

          <div>
            <h4 className="font-medium mb-2">Next Steps:</h4>
            <ul className="space-y-1">
              {recommendations.nextSteps.map((step, index) => (
                <li key={index} className="flex items-start gap-2 text-sm">
                  <ArrowRight className="w-3 h-3 mt-0.5 text-muted-foreground" />
                  <span>{step}</span>
                </li>
              ))}
            </ul>
          </div>
        </CardContent>
      </Card>

      {/* Action Buttons */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-wrap gap-3">
            {!passed && (
              <Button onClick={onRetakeAll} className="flex-1">
                <Target className="w-4 h-4 mr-2" />
                Retake Assessment
              </Button>
            )}
            <Button variant="outline" className="flex-1">
              <BookOpen className="w-4 h-4 mr-2" />
              Continue Studying
            </Button>
            <Button variant="outline" className="flex-1">
              <BarChart3 className="w-4 h-4 mr-2" />
              View Detailed Analytics
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { ReactNode, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { useRouter } from "next/navigation";

function getAdminSet(): Set<string> {
  const raw = (process.env.NEXT_PUBLIC_ADMIN_EMAILS || "").trim();
  if (!raw) return new Set();
  return new Set(raw.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean));
}

export function AdminGuard({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const router = useRouter();
  const admins = useMemo(() => getAdminSet(), []);
  const email = (user?.email || "").toLowerCase();
  const allowed = !!email && (admins.size === 0 ? false : admins.has(email));

  if (!user) {
    return (
      <div className="mx-auto max-w-2xl p-6">
        <Card className="glass border-white/10">
          <CardHeader>
            <CardTitle className="text-white">Sign in required</CardTitle>
          </CardHeader>
          <CardContent className="flex items-center justify-between text-gray-200">
            <div>Sign in with an admin account to access this page.</div>
            <Button onClick={() => router.push("/auth/signin")}>Sign in</Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!allowed) {
    return (
      <div className="mx-auto max-w-2xl p-6">
        <Card className="glass border-white/10">
          <CardHeader>
            <CardTitle className="text-white">Access denied</CardTitle>
          </CardHeader>
          <CardContent className="text-gray-200">
            Your account ({email || "unknown"}) is not authorized to access admin tools.
          </CardContent>
        </Card>
      </div>
    );
  }

  return <>{children}</>;
}

"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { Loader2, Shield } from "lucide-react";
import { useState, type ReactNode } from "react";
import { SignInForm } from "./SignInForm";

interface AuthGuardProps {
  children: ReactNode;
  fallback?: ReactNode;
  requireAuth?: boolean;
}

export function AuthGuard({ children, fallback, requireAuth = true }: AuthGuardProps) {
  const { user, loading } = useAuth();
  const [showAuthModal, setShowAuthModal] = useState(false);

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="text-center">
          <Loader2 className="mx-auto mb-4 h-8 w-8 animate-spin" />
          <p className="text-muted-foreground">Loading...</p>
        </div>
      </div>
    );
  }

  if (!requireAuth) {
    return <>{children}</>;
  }

  if (!user) {
    return (
      <>
        {fallback || (
          <div className="flex min-h-screen items-center justify-center p-4">
            <Card className="w-full max-w-md">
              <CardHeader className="text-center">
                <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-blue-100 dark:bg-blue-900">
                  <Shield className="h-6 w-6 text-blue-600 dark:text-blue-400" />
                </div>
                <CardTitle>Authentication Required</CardTitle>
                <CardDescription>
                  Please sign in to access your Tanium TCO exam progress and continue your
                  certification journey.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <Button onClick={() => setShowAuthModal(true)} className="w-full">
                  Sign In
                </Button>
                <p className="text-center text-sm text-muted-foreground">
                  Don&rsquo;t have an account?{" "}
                  <button
                    onClick={() => setShowAuthModal(true)}
                    className="text-primary hover:underline"
                  >
                    Create one now
                  </button>
                </p>
              </CardContent>
            </Card>
          </div>
        )}

        {showAuthModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
            <div className="w-full max-w-md rounded-lg bg-white p-6 dark:bg-slate-800">
              <div className="mb-4 flex items-center justify-between">
                <h2 className="text-xl font-semibold">Sign In</h2>
                <button
                  onClick={() => setShowAuthModal(false)}
                  className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                >
                  ✕
                </button>
              </div>
              <SignInForm onSuccess={() => setShowAuthModal(false)} />
            </div>
          </div>
        )}
      </>
    );
  }

  return <>{children}</>;
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Loader2, Eye, EyeOff } from "lucide-react";

interface LoginFormProps {
  onSuccess?: () => void;
  onSwitchToSignUp?: () => void;
}

export function LoginForm({ onSuccess, onSwitchToSignUp }: LoginFormProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { signIn } = useAuth();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setError(null);
    setIsSubmitting(true);

    try {
      const { error } = await signIn(email, password);

      if (error) {
        setError(error.message);
      } else {
        onSuccess?.();
      }
    } catch (error) {
      setError("An unexpected error occurred. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Card className="mx-auto w-full max-w-md">
      <CardHeader>
        <CardTitle>Sign In</CardTitle>
        <CardDescription>
          Access your Tanium TCO exam progress and continue your certification journey.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <Alert variant="destructive">
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          <div className="space-y-2">
            <label htmlFor="email" className="text-sm font-medium">
              Email
            </label>
            <Input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="your.email@example.com"
              required
              disabled={isSubmitting}
            />
          </div>

          <div className="space-y-2">
            <label htmlFor="password" className="text-sm font-medium">
              Password
            </label>
            <div className="relative">
              <Input
                id="password"
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter your password"
                required
                disabled={isSubmitting}
                className="pr-10"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute inset-y-0 right-0 flex items-center pr-3"
                disabled={isSubmitting}
              >
                {showPassword ? (
                  <EyeOff className="h-4 w-4 text-gray-400" />
                ) : (
                  <Eye className="h-4 w-4 text-gray-400" />
                )}
              </button>
            </div>
          </div>

          <Button type="submit" className="w-full" disabled={isSubmitting}>
            {isSubmitting ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Signing In...
              </>
            ) : (
              "Sign In"
            )}
          </Button>

          <div className="space-y-2 text-center">
