  return (
    <div className="space-y-6">
      {/* Main Encouragement Display */}
      <AnimatePresence mode="wait">
        {activeMessage && showEncouragement && (
          <motion.div
            key={activeMessage.id}
            initial={{ opacity: 0, y: 20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -20, scale: 0.95 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className={`relative p-6 rounded-2xl bg-gradient-to-r ${getConfidenceColor(currentConfidence)} shadow-lg`}
          >
            <div className="flex items-start space-x-4">
              <motion.div
                initial={{ rotate: 0 }}
                animate={{ rotate: [0, 10, -10, 0] }}
                transition={{ duration: 2, ease: "easeInOut", repeat: Infinity, repeatDelay: 3 }}
                className="flex-shrink-0 rounded-xl border border-primary/30 bg-surface/70 p-3 backdrop-blur-sm"
              >
                <activeMessage.icon className="w-8 h-8 text-white" />
              </motion.div>

              <div className="flex-1 space-y-2">
                <div className="flex items-center justify-between">
                  <span className="rounded-full bg-primary/15 px-3 py-1 text-xs font-semibold text-primary">
                    {getConfidenceMessage(currentConfidence)}
                  </span>
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    onClick={() => setActiveMessage(null)}
                    className="rounded-full p-1 text-foreground/70 transition-colors hover:bg-foreground/10 hover:text-foreground"
                  >
                    ✕
                  </motion.button>
                </div>

                <p className="text-lg font-medium text-white leading-relaxed">
