"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { buildExamConfig, type ExamModeSim } from "@/lib/exam-simulator";
import { useAssessment } from "@/hooks/useAssessment";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/contexts/AuthContext";
import { saveQuickNote } from "@/services/notesService";
import { toast } from "@/hooks/use-toast";

export default function ExamSimulator() {
  const { user } = useAuth();
  const {
    startAssessment,
    submitAnswer,
    submitAssessment,
    updateProgress,
    trackEvent,
    cancelAssessment,
    currentSession,
    currentResult,
    isLoading,
  } = useAssessment();
  const [mode, setMode] = useState<ExamModeSim | null>(null);
  const [index, setIndex] = useState(0);
  const [timeRemaining, setTimeRemaining] = useState<number>(0);
  const questionStartRef = useRef<number | null>(null);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const storageKey = user?.id && currentSession?.id ? `tco-exam-answers:${user.id}:${currentSession.id}` : null;

  const handleStart = async (m: ExamModeSim) => {
    setMode(m);
    const config = buildExamConfig(m, {});
    await startAssessment(config);
    };

  // Timer management: initialize on session start
  useEffect(() => {
    if (!currentSession?.timeLimit || !currentSession?.startTime) return;
    const endAt = currentSession.startTime.getTime() + (currentSession.timeLimit || 0) * 60 * 1000;
    const tick = () => {
      const now = Date.now();
      const remaining = Math.max(0, Math.floor((endAt - now) / 1000));
      setTimeRemaining(remaining);
      if (remaining === 0) {
        // Auto-submit when time runs out
        submitAssessment();
      }
    };
    tick();
    const id = window.setInterval(tick, 1000);
    return () => window.clearInterval(id);
  }, [currentSession?.id, currentSession?.timeLimit, currentSession?.startTime]);

  // Load persisted answers/index when a session starts
  useEffect(() => {
    try {
      if (!storageKey) return;
      const raw = localStorage.getItem(storageKey);
      if (!raw) return;
      const parsed = JSON.parse(raw) as { answers?: Record<string, string>; index?: number };
      if (parsed.answers) setAnswers(parsed.answers);
      if (typeof parsed.index === "number") setIndex(Math.max(0, Math.min((currentSession?.questions?.length ?? 1) - 1, parsed.index)));
    } catch {
      // ignore
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [storageKey]);

  // Set question start timer on index change
  useEffect(() => {
    questionStartRef.current = Date.now();
    if (currentSession) {
      trackEvent({
        type: "question_navigated",
        userId: user?.id ?? "",
        sessionId: currentSession.id,
        data: { index, questionId: currentSession.questions[index]?.id },
        timestamp: new Date(),
      });
    }
    // Persist index as part of session state
    try {
      if (storageKey) {
        const existing = localStorage.getItem(storageKey);
        const parsed = existing ? JSON.parse(existing) : {};
        parsed.index = index;
        parsed.answers = parsed.answers || answers;
        localStorage.setItem(storageKey, JSON.stringify(parsed));
      }
    } catch {
      // ignore storage errors
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [index, currentSession?.id]);

  const question = useMemo(() => currentSession?.questions?.[index], [currentSession?.questions, index]);
  const isLast = useMemo(() => {
    const len = currentSession?.questions?.length ?? 0;
    return len > 0 && index === len - 1;
  }, [index, currentSession?.questions?.length]);

  async function handleSelect(answerId: string) {
    if (!currentSession || !question) return;
    const startedAt = questionStartRef.current ?? Date.now();
    const timeSpent = Math.max(0, Math.floor((Date.now() - startedAt) / 1000));
    const isCorrect = answerId === question.correctAnswerId;

    // Persist locally for navigation/review
    setAnswers((prev) => {
      const next = { ...prev, [question.id]: answerId };
      try {
        if (storageKey) {
          const existing = localStorage.getItem(storageKey);
          const parsed = existing ? JSON.parse(existing) : {};
          localStorage.setItem(storageKey, JSON.stringify({ ...parsed, answers: next, index }));
        }
      } catch {
        // ignore
      }
      return next;
    });

    // Submit via hook (tracks analytics internally)
    await submitAnswer(question.id, {
      questionId: question.id,
      selectedAnswer: answerId,
      selectedAnswers: [answerId],
      attempts: 1,
      isCorrect,
      timeSpent,
      timestamp: new Date(),
    } as any);

    // Update question-level progress
    await updateProgress({
      userId: user?.id ?? "",
      questionId: question.id,
      isCorrect,
      timeSpent,
      sessionId: currentSession.id,
      timestamp: new Date(),
    } as any);
  }

  function formatTime(secs: number) {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${m}:${s.toString().padStart(2, "0")}`;
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <Button disabled={isLoading} onClick={() => handleStart("practice-test")}>Start Practice Test</Button>
        <Button variant="secondary" disabled={isLoading} onClick={() => handleStart("mock-exam")}>
          Start Mock Exam
        </Button>
      </div>

      {currentSession ? (
        <div data-testid="exam-session" className="rounded border p-4 space-y-4">
          <div className="flex items-center justify-between text-sm text-slate-600 dark:text-slate-300">
            <span>Session: {currentSession.id} · Type: {mode}</span>
            <span aria-live="polite" aria-label="Time remaining">⏱ {formatTime(timeRemaining)}</span>
          </div>
          <div className="font-medium">Question {index + 1} of {currentSession.questions.length}</div>

          {question ? (
            <div>
              <div className="mb-3 flex items-start justify-between gap-3">
                <div className="flex-1">{question.question}</div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={async () => {
                    const text = `Q: ${question.question}\nAnswer: ${question.choices?.find((c) => c.id === question.correctAnswerId)?.text || ""}${question.explanation ? `\nWhy: ${question.explanation}` : ""}`;
                    await saveQuickNote(text, { tags: ["exam", question.domain, question.difficulty], user });
                    toast({ title: "Added to Notes", description: "View it under Notes for spaced review." });
                  }}
                >
                  Add to Notes
                </Button>
              </div>
              <div className="space-y-2">
                {question.choices?.map((c) => (
                  <label key={c.id} className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name={`q-${question.id}`}
                      value={c.id}
                      onChange={() => handleSelect(c.id)}
                      checked={answers[question.id] === c.id}
                      data-testid="answer-radio"
                      disabled={!!currentSession?.completedAt}
                    />
                    <span>{c.text}</span>
                  </label>
                ))}
              </div>

              {/* Mini-map navigation */}
              <div className="mt-4">
                <div className="text-xs text-slate-500 mb-1">Jump to question</div>
                <div className="flex flex-wrap gap-2" data-testid="mini-map">
                  {currentSession.questions.map((q, i) => {
                    const sel = answers[q.id];
                    const completed = !!currentSession.completedAt;
                    const isCurrent = i === index;
                    let cls = "px-2 py-1 rounded text-xs";
                    if (isCurrent) cls += " bg-blue-600 text-white";
                    else if (completed) {
                      const correct = sel && sel === q.correctAnswerId;
                      cls += correct ? " bg-green-600 text-white" : sel ? " bg-red-600 text-white" : " bg-slate-200 dark:bg-slate-700";
                    } else {
                      cls += sel ? " bg-blue-100 dark:bg-blue-900 text-blue-700" : " bg-slate-200 dark:bg-slate-700";
                    }
                    return (
                      <button
                        key={q.id}
                        type="button"
                        className={cls}
                        data-testid="mini-map-item"
                        aria-label={`Go to question ${i + 1}`}
                        onClick={() => setIndex(i)}
                        disabled={!!currentSession?.completedAt}
                      >
                        {i + 1}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          ) : null}

          <div className="flex items-center justify-between mt-4">
            <Button
              variant="outline"
              onClick={() => setIndex((v) => Math.max(0, v - 1))}
              disabled={index === 0}
            >
              Previous
            </Button>
            <div className="flex items-center gap-2">
              {!isLast && (
                <Button onClick={() => setIndex((v) => Math.min((currentSession?.questions?.length ?? 1) - 1, v + 1))}>
                  Next
                </Button>
              )}
              {isLast && (
                <Button onClick={async () => {
                  await submitAssessment();
                  try { if (storageKey) localStorage.removeItem(storageKey); } catch {}
                }}>
                  Submit Exam
                </Button>
              )}
            </div>
          </div>
        </div>
      ) : null}

      {/* Review Panel */}
      {currentSession && (currentSession as any).status === 'completed' ? (
        <div className="rounded border p-4 space-y-3" data-testid="review-panel">
          <div className="flex items-center justify-between">
            <div className="font-semibold">Exam Review</div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                onClick={() => {
                  // Back to start: clear session/results
                  cancelAssessment();
                  setIndex(0);
                  setAnswers({});
                  setTimeRemaining(0);
                  try { if (storageKey) localStorage.removeItem(storageKey); } catch {}
                }}
              >
                Back to start
              </Button>
              <Button
                onClick={async () => {
                  const m = mode ?? "practice-test";
                  setIndex(0);
                  setAnswers({});
                  setTimeRemaining(0);
                  await startAssessment(buildExamConfig(m, {}));
                }}
              >
                Retake Exam
              </Button>
            </div>
          </div>

          <ReviewSummary result={currentResult as any} />
          <div className="space-y-3">
            {currentSession.questions.map((q) => {
              const selected = answers[q.id];
              const correct = q.correctAnswerId;
              const isCorrect = selected === correct;
              const getText = (id?: string) => q.choices.find((c) => c.id === id)?.text || '';
              return (
                <div key={q.id} className="border rounded p-3" data-testid="review-item">
                  <div className="mb-2">{q.question}</div>
                  <div className="text-sm">Your answer: <span className={isCorrect ? 'text-green-600' : 'text-red-600'}>{getText(selected)}</span></div>
                  {!isCorrect && (
                    <div className="text-sm">Correct answer: <span className="text-green-600">{getText(correct)}</span></div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      ) : null}
    </div>
  );
}

function ReviewSummary({ result }: { result: any | null }) {
  if (!result) return null;
  const percent = typeof result.overallScore === 'number' ? Math.round(result.overallScore * 100) : null;
  const time = (result.timeSpent ?? result.totalTime ?? 0) as number;
  const minutes = Math.floor(time / 60);
  const seconds = time % 60;
  return (
    <div className="rounded bg-slate-50 dark:bg-slate-900 border p-3 text-sm">
      <div>Score: {percent !== null ? `${percent}%` : '—'} · Passed: {String(result.passed)}</div>
      <div>
        Questions: {result.correctAnswers ?? 0} correct / {result.incorrectAnswers ?? 0} incorrect of {result.totalQuestions ?? 0}
      </div>
      <div>Time Spent: {minutes}:{seconds.toString().padStart(2, '0')}</div>
      {result.domainBreakdown ? (
        <div className="mt-2">
          <div className="font-medium">Domain Breakdown</div>
          <ul className="mt-1 grid grid-cols-1 sm:grid-cols-2 gap-1">
            {Object.entries(result.domainBreakdown as Record<string, any>).map(([domain, d]) => {
              const pct = typeof d.score === 'number' ? Math.round(d.score * 100) : d.score;
              return (
                <li key={domain} className="flex justify-between">
                  <span>{domain}</span>
                  <span>
                    {(d.correct ?? 0)}/{(d.total ?? 0)} · {pct}%
                  </span>
                </li>
              );
            })}
          </ul>
        </div>
      ) : null}
      <div className="mt-2 text-slate-500">
        Progress saved via ProgressService (score, totals, domain breakdown).
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useExam } from "@/contexts/ExamContext";
import { useSettings } from "@/contexts/SettingsContext";
import { ExamMode, type Question, TCODomain, Difficulty } from "@/types/exam";
import {
  selectAdaptiveQuestions,
  filterQuestions,
  getPracticeQuestions,
  getDomainQuestions,
  getAllAvailableQuestions,
} from "@/lib/examLogic";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { saveQuickNote } from "@/services/notesService";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/hooks/use-toast";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import {
  Timer,
  Clock,
  CheckCircle,
  XCircle,
  ArrowRight,
  ArrowLeft,
  BookOpen,
  Target,
} from "lucide-react";

interface PracticeSessionProps {
  domain?: TCODomain;
  difficulty?: Difficulty;
  questionCount?: number;
  mode?: "adaptive" | "random" | "domain-specific";
}

export function PracticeSession({
  domain,
  difficulty,
  questionCount = 10,
  mode = "adaptive",
}: PracticeSessionProps) {
  const {
    state,
    startExam,
    answerQuestion,
    nextQuestion,
    previousQuestion,
    finishExam,
    getCurrentQuestion,
    getProgress,
    getScore,
  } = useExam();
  const { state: settings } = useSettings();
  const { user } = useAuth();
  const [selectedAnswer, setSelectedAnswer] = useState<string>("");
  const [showExplanation, setShowExplanation] = useState(false);
  const [sessionStarted, setSessionStarted] = useState(false);
  const [timeSpent, setTimeSpent] = useState(0);

  // Timer for tracking time spent
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (sessionStarted && state.currentSession && !state.currentSession.completed) {
      interval = setInterval(() => {
        setTimeSpent((prev) => prev + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [sessionStarted, state.currentSession]);

  const startPracticeSession = () => {
    // Get available questions count from centralized database
    const availableQuestions = getAllAvailableQuestions();
    console.log("Starting practice session with questions:", availableQuestions.length);
    console.log("Questions available:", availableQuestions.length > 0 ? "YES" : "NO");
    let selectedQuestions: Question[] = [];

    if (mode === "adaptive") {
      // Use adaptive question selection (placeholder for user performance data)
      selectedQuestions = selectAdaptiveQuestions({}, questionCount, {
        focusOnWeakAreas: true,
        difficultyProgression: true,
        spaceRepetition: false,
      });
    } else if (mode === "domain-specific" && domain) {
      // Get questions from specific domain using centralized database
      const domainQuestions = getDomainQuestions(domain);
      let filteredQuestions = domainQuestions;

      // Filter by difficulty if specified
      if (difficulty) {
        filteredQuestions = domainQuestions.filter((q) => q.difficulty === difficulty);
      }

      // Shuffle and take requested count
      selectedQuestions = filteredQuestions.sort(() => Math.random() - 0.5).slice(0, questionCount);
    } else {
      // Random selection using centralized database
      selectedQuestions = getPracticeQuestions(
        undefined,
        questionCount,
        difficulty ? [difficulty] : undefined
      );
    }

    if (selectedQuestions.length === 0) {
      console.warn("No questions available for the selected criteria");
      return;
    }

    startExam(ExamMode.PRACTICE, selectedQuestions);
    setSessionStarted(true);
    setTimeSpent(0);
  };

  const handleAnswerSelect = (answerId: string) => {
    setSelectedAnswer(answerId);
    const currentQuestion = getCurrentQuestion();
    if (currentQuestion) {
      answerQuestion(currentQuestion.id, answerId);
      if (settings.settings.showExplanations) {
        setShowExplanation(true);
      }
    }
  };

  const handleNextQuestion = () => {
    nextQuestion();
    setSelectedAnswer("");
    setShowExplanation(false);
  };

  const handlePreviousQuestion = () => {
    previousQuestion();
    const currentQuestion = getCurrentQuestion();
    if (currentQuestion && state.currentSession?.answers[currentQuestion.id]) {
      setSelectedAnswer(state.currentSession.answers[currentQuestion.id]);
      if (settings.settings.showExplanations) {
        setShowExplanation(true);
      }
    } else {
      setSelectedAnswer("");
      setShowExplanation(false);
    }
  };

  const handleFinishSession = () => {
    finishExam();
    setSessionStarted(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  if (state.isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="border-tanium-orange h-8 w-8 animate-spin rounded-full border-b-2"></div>
        <span className="ml-2 text-gray-400">Loading practice session...</span>
      </div>
    );
  }

  if (!state.currentSession) {
    return (
      <Card className="border-tanium-secondary/20 bg-tanium-dark/50">
        <CardHeader>
          <CardTitle className="text-tanium-orange flex items-center gap-2">
            <Target className="h-5 w-5" />
            Start Practice Session
          </CardTitle>
          <CardDescription>
            {mode === "adaptive" && "Adaptive practice with questions tailored to your performance"}
            {mode === "domain-specific" && domain && `Focused practice on ${domain} domain`}
            {mode === "random" && "Random questions from all domains"}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
            <div className="text-center">
              <div className="text-tanium-orange text-2xl font-bold">{questionCount}</div>
              <div className="text-sm text-gray-400">Questions</div>
            </div>
            <div className="text-center">
              <div className="text-tanium-orange text-2xl font-bold">
                ~{Math.ceil(questionCount * 1.5)}
              </div>
              <div className="text-sm text-gray-400">Minutes</div>
            </div>
            <div className="text-center">
              <div className="text-tanium-orange text-2xl font-bold">Mixed</div>
              <div className="text-sm text-gray-400">Difficulty</div>
            </div>
            <div className="text-center">
              <div className="text-tanium-orange text-2xl font-bold">✓</div>
              <div className="text-sm text-gray-400">Feedback</div>
            </div>
          </div>
          <Button
            onClick={startPracticeSession}
            className="bg-tanium-orange hover:bg-tanium-orange/80 w-full"
          >
            <BookOpen className="mr-2 h-4 w-4" />
            Start Practice Session
          </Button>
        </CardContent>
      </Card>
    );
  }

  const currentQuestion = getCurrentQuestion();
  const progress = getProgress();
  const score = getScore();

  if (state.currentSession.completed) {
    return (
      <Card className="border-tanium-secondary/20 bg-tanium-dark/50">
        <CardHeader>
          <CardTitle className="text-tanium-orange flex items-center gap-2">
            <CheckCircle className="h-5 w-5" />
            Practice Session Complete
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
            <div className="text-center">
              <div className="text-tanium-orange text-3xl font-bold">{score}%</div>
              <div className="text-sm text-gray-400">Score</div>
            </div>
            <div className="text-center">
              <div className="text-tanium-orange text-3xl font-bold">
                {
                  state.currentSession.questions.filter(
                    (q) => state.currentSession!.answers[q.id] === q.correctAnswerId
                  ).length
                }
              </div>
              <div className="text-sm text-gray-400">Correct</div>
            </div>
            <div className="text-center">
              <div className="text-tanium-orange text-3xl font-bold">{formatTime(timeSpent)}</div>
              <div className="text-sm text-gray-400">Time</div>
            </div>
            <div className="text-center">
              <div className="text-tanium-orange text-3xl font-bold">
                {Math.round(timeSpent / state.currentSession.questions.length)}
              </div>
              <div className="text-sm text-gray-400">Avg/Question</div>
            </div>
          </div>

          <div className="space-y-2">
            <h3 className="text-lg font-semibold text-white">Performance by Domain</h3>
            {Object.values(TCODomain).map((domain) => {
              const domainQuestions = state.currentSession!.questions.filter(
                (q) => q.domain === domain
              );
              if (domainQuestions.length === 0) return null;

              const domainCorrect = domainQuestions.filter(
                (q) => state.currentSession!.answers[q.id] === q.correctAnswerId
              ).length;
              const domainScore = Math.round((domainCorrect / domainQuestions.length) * 100);

              return (
                <div key={domain} className="flex items-center justify-between">
                  <span className="text-gray-300">{domain}</span>
                  <div className="flex items-center gap-2">
                    <span className="text-tanium-orange">
                      {domainCorrect}/{domainQuestions.length}
                    </span>
                    <Badge variant={domainScore >= 70 ? "default" : "destructive"}>
                      {domainScore}%
                    </Badge>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="flex gap-2">
            <Button
              onClick={() => window.location.reload()}
              className="bg-tanium-orange hover:bg-tanium-orange/80 flex-1"
            >
              Practice Again
            </Button>
            <Button variant="outline" onClick={() => setSessionStarted(false)} className="flex-1">
              Back to Menu
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!currentQuestion) {
    return <div className="text-center text-gray-400">No questions available</div>;
  }

  const isAnswered = selectedAnswer !== "";
  const isCorrect = selectedAnswer === currentQuestion.correctAnswerId;

  return (
    <div className="space-y-6">
      {/* Progress Header */}
      <Card className="border-tanium-secondary/20 bg-tanium-dark/30">
        <CardContent className="pt-6">
          <div className="mb-4 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Badge variant="outline" className="border-tanium-orange text-tanium-orange">
                Question {progress.current} of {progress.total}
              </Badge>
              <Badge variant="outline" className="border-tanium-secondary text-tanium-secondary">
                {currentQuestion.domain}
              </Badge>
              <Badge
                variant={
                  currentQuestion.difficulty === Difficulty.BEGINNER
                    ? "default"
                    : currentQuestion.difficulty === Difficulty.INTERMEDIATE
                      ? "secondary"
                      : "destructive"
                }
              >
                {currentQuestion.difficulty}
              </Badge>
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2 text-gray-400">
                <Clock className="h-4 w-4" />
                <span>{formatTime(timeSpent)}</span>
              </div>
              <div className="text-tanium-orange font-semibold">Score: {score}%</div>
            </div>
          </div>
          <Progress value={progress.percentage} className="h-2" />
        </CardContent>
      </Card>

      {/* Question */}
      <Card className="border-tanium-secondary/20 bg-tanium-dark/50">
        <CardHeader>
          <div className="flex items-start justify-between gap-3">
            <CardTitle className="leading-relaxed text-white">{currentQuestion.question}</CardTitle>
            <Button
              variant="outline"
              size="sm"
              onClick={async () => {
                const text = `Q: ${currentQuestion.question}\nAnswer: ${currentQuestion.choices.find((c) => c.id === currentQuestion.correctAnswerId)?.text || ""}${currentQuestion.explanation ? `\nWhy: ${currentQuestion.explanation}` : ""}`;
                await saveQuickNote(text, { tags: ["practice", currentQuestion.domain, currentQuestion.difficulty], user });
                toast({ title: "Added to Notes", description: "View it under Notes for spaced review." });
              }}
            >
              Add to Notes
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <RadioGroup value={selectedAnswer} onValueChange={handleAnswerSelect}>
            {currentQuestion.choices.map((choice) => (
              <div key={choice.id} className="flex items-center space-x-2">
                <RadioGroupItem
                  value={choice.id}
                  id={choice.id}
                  disabled={isAnswered && !settings.settings.showExplanations}
                />
                <Label
                  htmlFor={choice.id}
                  className={`flex-1 cursor-pointer rounded-lg border p-3 transition-colors ${
                    isAnswered
                      ? choice.id === currentQuestion.correctAnswerId
                        ? "border-green-500 bg-green-500/10 text-green-400"
                        : choice.id === selectedAnswer &&
                            choice.id !== currentQuestion.correctAnswerId
                          ? "border-red-500 bg-red-500/10 text-red-400"
                          : "border-tanium-secondary/20 text-gray-300"
                      : "hover:border-tanium-orange/50 border-tanium-secondary/20 text-gray-300 hover:text-white"
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span>{choice.text}</span>
                    {isAnswered && (
                      <>
                        {choice.id === currentQuestion.correctAnswerId && (
                          <CheckCircle className="h-4 w-4 text-green-500" />
                        )}
                        {choice.id === selectedAnswer &&
                          choice.id !== currentQuestion.correctAnswerId && (
                            <XCircle className="h-4 w-4 text-red-500" />
                          )}
                      </>
                    )}
                  </div>
                </Label>
              </div>
            ))}
          </RadioGroup>

          {/* Explanation */}
          {showExplanation && currentQuestion.explanation && isAnswered && (
            <div
              className={`mt-4 rounded-lg border p-4 ${
                isCorrect ? "border-green-500/20 bg-green-500/5" : "border-red-500/20 bg-red-500/5"
              }`}
            >
              <div className="mb-2 flex items-center gap-2">
                {isCorrect ? (
                  <CheckCircle className="h-5 w-5 text-green-500" />
                ) : (
                  <XCircle className="h-5 w-5 text-red-500" />
                )}
                <span className={`font-semibold ${isCorrect ? "text-green-400" : "text-red-400"}`}>
                  {isCorrect ? "Correct!" : "Incorrect"}
                </span>
              </div>
              <p className="text-gray-300">{currentQuestion.explanation}</p>
            </div>
          )}

          {/* Navigation */}
          <div className="mt-6 flex items-center justify-between">
            <Button
              variant="outline"
              onClick={handlePreviousQuestion}
              disabled={progress.current === 1}
            >
              <ArrowLeft className="mr-2 h-4 w-4" />
              Previous
            </Button>

            <div className="flex gap-2">
              {progress.current === progress.total ? (
                <Button
                  onClick={handleFinishSession}
                  className="bg-tanium-orange hover:bg-tanium-orange/80"
                >
                  Finish Session
                </Button>
              ) : (
                <Button
                  onClick={handleNextQuestion}
                  disabled={!isAnswered}
                  className="bg-tanium-orange hover:bg-tanium-orange/80"
                >
                  Next
                  <ArrowRight className="ml-2 h-4 w-4" />
                </Button>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useExam } from "@/contexts/ExamContext";
import { Card, CardContent } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Clock, AlertTriangle } from "lucide-react";
import { ExamTooltip } from "@/components/ui/help-tooltip";
import { cn } from "@/lib/utils";

interface ExamTimerProps {
  totalTimeMinutes: number;
  onTimeUp?: () => void;
  onWarning?: (remainingMinutes: number) => void;
  className?: string;
}

export function ExamTimer({ totalTimeMinutes, onTimeUp, onWarning, className }: ExamTimerProps) {
  const { state, updateTimer, timeUp } = useExam();
  const [remainingSeconds, setRemainingSeconds] = useState(totalTimeMinutes * 60);
  const [isWarning, setIsWarning] = useState(false);
  const [isCritical, setIsCritical] = useState(false);

  useEffect(() => {
    if (remainingSeconds <= 0) {
      onTimeUp?.();
      timeUp();
      return;
    }

    const interval = setInterval(() => {
      setRemainingSeconds((prev) => {
        const newValue = prev - 1;

        // Ensure we don't go below 0
        if (newValue < 0) {
          return 0;
        }

        // Warning thresholds
        const warningThreshold = totalTimeMinutes * 60 * 0.25; // 25% remaining
        const criticalThreshold = totalTimeMinutes * 60 * 0.1; // 10% remaining

        if (newValue <= criticalThreshold && !isCritical) {
          setIsCritical(true);
          onWarning?.(Math.floor(newValue / 60));
        } else if (newValue <= warningThreshold && !isWarning) {
          setIsWarning(true);
          onWarning?.(Math.floor(newValue / 60));
        }

        // Update context with remaining time - ensure updateTimer is available
        if (updateTimer && typeof updateTimer === "function") {
          updateTimer(newValue);
        }

        return newValue;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [
    remainingSeconds,
    totalTimeMinutes,
    onTimeUp,
    onWarning,
    isWarning,
    isCritical,
    updateTimer,
    timeUp,
  ]);

  const formatTime = (seconds: number) => {
    // Handle edge cases for invalid seconds
    if (isNaN(seconds) || seconds < 0) {
      return "0:00";
    }

    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    if (hours > 0) {
      return `${hours}:${minutes.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
    }
    return `${minutes}:${secs.toString().padStart(2, "0")}`;
  };

  const getProgressPercentage = () => {
    const totalSeconds = totalTimeMinutes * 60;
    if (totalSeconds === 0 || isNaN(remainingSeconds)) {
      return 0;
    }
    return Math.max(0, Math.min(100, ((totalSeconds - remainingSeconds) / totalSeconds) * 100));
  };

  const getTimerVariant = () => {
    if (isCritical) return "critical";
    if (isWarning) return "warning";
    return "default";
  };

  const getTimerColor = () => {
    if (isCritical) return "text-red-600 dark:text-red-400";
    if (isWarning) return "text-amber-600 dark:text-amber-400";
    return "text-foreground";
  };

  const getProgressColor = () => {
    if (isCritical) return "bg-red-600";
    if (isWarning) return "bg-amber-600";
    return "bg-primary";
  };

  return (
    <Card className={cn("glass border-white/10", className)}>
      <CardContent className="p-4">
        <div className="mb-2 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Clock className={cn("h-4 w-4", getTimerColor())} />
            <span className="text-sm font-medium text-muted-foreground">Time Remaining</span>
            <ExamTooltip
              type="time"
              context={`${Math.floor(remainingSeconds / 60)} minutes remaining`}
            />
          </div>

          {(isWarning || isCritical) && (
            <Badge
              variant={isCritical ? "destructive" : "default"}
              className="flex items-center space-x-1"
            >
              <AlertTriangle className="h-3 w-3" />
              <span>{isCritical ? "Critical" : "Warning"}</span>
            </Badge>
          )}
        </div>

        <div className="mb-3 text-center">
          <div className={cn("font-mono text-2xl font-bold", getTimerColor())}>
            {formatTime(remainingSeconds)}
          </div>
          <div className="text-xs text-muted-foreground">
            {Math.floor(remainingSeconds / 60)} minutes left
          </div>
        </div>

        <Progress
          value={getProgressPercentage()}
          className="h-2"
          style={
            {
              "--progress-background": getProgressColor(),
            } as any
          }
        />

        <div className="mt-2 flex justify-between text-xs text-muted-foreground">
          <span>Started</span>
          <span>Ends at {new Date(Date.now() + remainingSeconds * 1000).toLocaleTimeString()}</span>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import { useState, memo, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { CheckCircle, XCircle, Clock, BookOpen } from "lucide-react";
import type { Question } from "@/types/exam";
import { cn, getDifficultyColor } from "@/lib/utils";

interface QuestionCardProps {
  question: Question;
  questionNumber: number;
  totalQuestions: number;
  selectedAnswer?: string;
  showResult?: boolean;
  showExplanation?: boolean;
  showCorrectAnswer?: boolean;
  onAnswerSelect: (answerId: string) => void;
  onSubmit?: () => void;
  isSubmitted?: boolean;
  mode?: string;
  disabled?: boolean;
}

export const QuestionCard = memo(function QuestionCard({
  question,
  questionNumber,
  totalQuestions,
  selectedAnswer,
  showResult = false,
  showExplanation = false,
  showCorrectAnswer = false,
  onAnswerSelect,
  onSubmit,
  isSubmitted = false,
  mode,
  disabled = false,
}: QuestionCardProps) {
  const [localAnswer, setLocalAnswer] = useState(selectedAnswer || "");

  const handleAnswerChange = (value: string) => {
    setLocalAnswer(value);
    onAnswerSelect(value);
  };

  const isCorrect = showResult && selectedAnswer === question.correctAnswerId;
  const isIncorrect = showResult && selectedAnswer !== question.correctAnswerId && selectedAnswer;

  // Memoize choices to prevent re-renders
  const memoizedChoices = useMemo(() => question.choices, [question.choices]);

  return (
    <Card className="question-card mx-auto w-full max-w-4xl">
      <CardHeader>
        <div className="mb-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Badge variant="outline" className="text-sm">
              Question {questionNumber} of {totalQuestions}
            </Badge>
            <div className="flex items-center gap-1">
              <Badge variant="secondary">{question.domain}</Badge>
            </div>
            <div className="flex items-center gap-1">
              <Badge
                variant="outline"
                className={cn("text-sm", getDifficultyColor(question.difficulty))}
              >
                {question.difficulty}
              </Badge>
            </div>
          </div>
          <div className="flex items-center gap-1 text-sm text-muted-foreground">
            <Clock className="h-4 w-4" />
            <span>2 min</span>
          </div>
        </div>

        <CardTitle className="text-xl leading-relaxed text-foreground">
          {question.question}
        </CardTitle>
      </CardHeader>

      <CardContent className="space-y-6">
        <div className="mb-4 flex items-center gap-2">
          <span className="text-sm text-muted-foreground">Select your answer:</span>
        </div>

        <div className="space-y-4" role="radiogroup">
          {memoizedChoices.map((choice) => {
            const isSelected = localAnswer === choice.id;
            const isCorrectChoice = showResult && choice.id === question.correctAnswerId;
            const isIncorrectChoice =
              showResult && isSelected && choice.id !== question.correctAnswerId;

            return (
              <div
                key={`choice-${choice.id}-${question.id}`}
                className={cn(
                  "flex items-center space-x-3 rounded-lg border p-4 transition-all",
                  "cursor-pointer hover:bg-accent/50",
                  isSelected && !showResult && "border-primary bg-accent",
                  isCorrectChoice &&
                    "border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-900/20",
                  isIncorrectChoice &&
                    "border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-900/20"
                )}
                onClick={() => !isSubmitted && !disabled && handleAnswerChange(choice.id)}
              >
                <div className="relative">
                  <input
                    type="radio"
                    id={`${choice.id}-${question.id}`}
                    name={`question-${question.id}`}
                    value={choice.id}
                    checked={isSelected}
                    onChange={() => handleAnswerChange(choice.id)}
                    disabled={isSubmitted || disabled}
                    className={cn("sr-only")}
                  />
                  <div
                    className={cn(
                      "flex h-4 w-4 items-center justify-center rounded-full border-2 transition-all",
                      isSelected ? "border-primary bg-primary" : "border-muted-foreground",
                      isCorrectChoice && "border-green-600 bg-green-600",
                      isIncorrectChoice && "border-red-600 bg-red-600",
                      (isSubmitted || disabled) && "opacity-50"
                    )}
                  >
                    {isSelected && <div className="h-1.5 w-1.5 rounded-full bg-white" />}
                  </div>
                </div>
                <label
                  htmlFor={`${choice.id}-${question.id}`}
                  className="flex-1 cursor-pointer text-base leading-relaxed"
                >
                  {choice.text}
                </label>
                {showResult && isCorrectChoice && (
                  <CheckCircle className="h-5 w-5 text-green-600" />
                )}
                {showResult && isIncorrectChoice && <XCircle className="h-5 w-5 text-red-600" />}
              </div>
            );
          })}
        </div>

        {showResult && question.explanation && (
          <Alert className="border-blue-200 bg-blue-50 dark:border-blue-800 dark:bg-blue-900/20">
            <BookOpen className="h-4 w-4 text-blue-600" />
            <AlertDescription className="text-blue-800 dark:text-blue-200">
              <strong>Explanation:</strong> {question.explanation}
            </AlertDescription>
          </Alert>
        )}

        {!showResult && onSubmit && (
          <div className="flex items-center justify-between pt-4">
            <div className="text-sm text-muted-foreground">
              {localAnswer ? "Answer selected" : "Select an answer to continue"}
            </div>
            <Button
              onClick={onSubmit}
              disabled={!localAnswer || isSubmitted}
              className="bg-tanium-accent hover:bg-blue-600"
            >
              {isSubmitted ? "Submitting..." : "Submit Answer"}
            </Button>
          </div>
        )}

        {showResult && (
          <div className="flex items-center justify-center pt-4">
            <div
              className={cn(
                "flex items-center gap-2 text-lg font-medium",
                isCorrect ? "text-green-600" : "text-red-600"
              )}
            >
              {isCorrect ? (
                <>
                  <CheckCircle className="h-6 w-6" />
                  Correct!
                </>
              ) : (
                <>
                  <XCircle className="h-6 w-6" />
                  Incorrect
                </>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
});

