export function ResultsTable() {
  const [results] = useState<ExamResult[]>(mockResults);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterMode, setFilterMode] = useState<string>("all");
  const [filterStatus, setFilterStatus] = useState<string>("all");

  const filteredResults = results.filter((result) => {
    const matchesSearch =
      result.domain?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      result.mode.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMode = filterMode === "all" || result.mode === filterMode;
    const matchesStatus = filterStatus === "all" || result.status === filterStatus;

    return matchesSearch && matchesMode && matchesStatus;
  });

  const getStatusBadge = (status: ExamResult["status"]) => {
    switch (status) {
      case "completed":
        return (
          <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">
            Completed
          </Badge>
        );
      case "in_progress":
        return (
          <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200">
            In Progress
          </Badge>
        );
      case "abandoned":
        return (
          <Badge className="bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200">
            Abandoned
          </Badge>
        );
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  const getModeBadge = (mode: ExamResult["mode"]) => {
    switch (mode) {
      case "mock":
        return <Badge variant="default">Mock Exam</Badge>;
      case "practice":
        return <Badge variant="secondary">Practice</Badge>;
      case "review":
        return <Badge variant="outline">Review</Badge>;
      default:
        return <Badge variant="outline">{mode}</Badge>;
    }
  };

  const averageScore =
    results.length > 0
      ? Math.round(results.reduce((sum, result) => sum + result.score, 0) / results.length)
      : 0;

  const totalQuestions = results.reduce((sum, result) => sum + result.totalQuestions, 0);
  const totalCorrect = results.reduce((sum, result) => sum + result.correctAnswers, 0);

  return (
    <div className="space-y-6">
      {/* Statistics Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card className="glass border-white/10">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-200">Total Sessions</CardTitle>
            <Calendar className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-white">{results.length}</div>
            <p className="text-xs text-gray-400">exam sessions</p>
          </CardContent>
        </Card>

        <Card className="glass border-white/10">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-200">Average Score</CardTitle>
            <CheckCircle className="h-4 w-4 text-green-400" />
          </CardHeader>
          <CardContent>
            <div className={cn("text-2xl font-bold", getScoreColor(averageScore))}>
              {averageScore}%
            </div>
            <p className="text-xs text-gray-400">across all sessions</p>
          </CardContent>
        </Card>

        <Card className="glass border-white/10">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-200">Questions Answered</CardTitle>
            <CheckCircle className="h-4 w-4 text-blue-400" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-white">
              {totalCorrect}/{totalQuestions}
            </div>
            <p className="text-xs text-gray-400">
              {Math.round((totalCorrect / totalQuestions) * 100)}% accuracy
            </p>
          </CardContent>
        </Card>

        <Card className="glass border-white/10">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-200">Time Invested</CardTitle>
            <Clock className="h-4 w-4 text-orange-400" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-white">
              {Math.round(results.reduce((sum, result) => sum + result.timeSpent, 0) / 3600)}h
            </div>
            <p className="text-xs text-gray-400">total study time</p>
          </CardContent>
        </Card>
      </div>

      {/* Filters and Search */}
      <Card className="glass border-white/10">
        <CardHeader>
          <CardTitle className="text-white">Exam Results</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="mb-6 flex flex-col gap-4 sm:flex-row">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-gray-400" />
                <Input
                  placeholder="Search by domain or mode..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="glass border-white/20 pl-8 text-white placeholder:text-gray-400"
