                <SelectValue placeholder="Filter by status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="completed">Completed</SelectItem>
                <SelectItem value="in_progress">In Progress</SelectItem>
                <SelectItem value="abandoned">Abandoned</SelectItem>
              </SelectContent>
            </Select>

            <Button
              variant="outline"
              className="glass border-white/20 text-white hover:bg-white/10"
            >
              <Download className="mr-2 h-4 w-4" />
              Export
            </Button>
          </div>

          {/* Results Table */}
          <div className="overflow-hidden rounded-lg border border-white/10">
            <Table>
              <TableCaption className="text-gray-400">
                {filteredResults.length} of {results.length} exam sessions
              </TableCaption>
              <TableHeader>
                <TableRow className="border-white/10 hover:bg-white/5">
                  <TableHead className="text-gray-200">Date</TableHead>
                  <TableHead className="text-gray-200">Mode</TableHead>
                  <TableHead className="text-gray-200">Domain</TableHead>
                  <TableHead className="text-gray-200">Score</TableHead>
                  <TableHead className="text-gray-200">Questions</TableHead>
                  <TableHead className="text-gray-200">Time</TableHead>
                  <TableHead className="text-gray-200">Status</TableHead>
                  <TableHead className="text-gray-200">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredResults.map((result) => (
                  <TableRow
                    key={result.id}
                    className="border-white/10 text-gray-200 hover:bg-white/5"
                  >
                    <TableCell className="font-medium">
                      {result.date.toLocaleDateString()}
                    </TableCell>
                    <TableCell>{getModeBadge(result.mode)}</TableCell>
                    <TableCell>{result.domain || "-"}</TableCell>
                    <TableCell>
                      <div className="flex items-center space-x-2">
                        <span className={cn("font-medium", getScoreColor(result.score))}>
                          {result.score}%
                        </span>
                        {result.score >= 80 ? (
                          <CheckCircle className="h-4 w-4 text-green-400" />
                        ) : (
                          <XCircle className="h-4 w-4 text-red-400" />
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      {result.correctAnswers}/{result.totalQuestions}
                    </TableCell>
                    <TableCell>{formatTime(result.timeSpent)}</TableCell>
                    <TableCell>{getStatusBadge(result.status)}</TableCell>
                    <TableCell>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="text-gray-300 hover:bg-white/10 hover:text-white"
                      >
                        <Eye className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>

          {filteredResults.length === 0 && (
            <div className="py-8 text-center">
              <p className="text-gray-400">No results match your filters.</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

