  'beginner': 'text-green-600 bg-green-100',
  'intermediate': 'text-yellow-600 bg-yellow-100',
  'advanced': 'text-red-600 bg-red-100'
};

const importanceColors = {
  'critical': 'text-red-600 bg-red-100',
  'important': 'text-orange-600 bg-orange-100',
  'useful': 'text-blue-600 bg-blue-100'
};

export function InteractiveGlossary({ 
  className = '', 
  onTermSelect,
  initialCategory = 'basic-it',
  showOnlyExamRelevant = false 
}: InteractiveGlossaryProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTerm, setSelectedTerm] = useState<TermDefinition | null>(null);
  const [filters, setFilters] = useState<FilterState>({
    category: initialCategory,
    difficulty: 'all',
    importance: 'all',
    examRelevant: showOnlyExamRelevant ? true : null,
    taniumSpecific: null
  });
  const [showFilters, setShowFilters] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Initialize terminology search
  const terminologySearch = useMemo(() => new TerminologySearch(), []);

  // Filtered and searched terms
  const filteredTerms = useMemo(() => {
    setIsLoading(true);

    let results: TermDefinition[] = [];

    if (searchTerm.trim()) {
      results = terminologySearch.search(searchTerm);
    } else {
      results = terminologySearch.search('', { limit: 1000 });
    }

    // Apply filters
    results = results.filter(term => {
      if (filters.category !== 'all' && term.category !== filters.category) return false;
      if (filters.difficulty !== 'all' && term.difficulty !== filters.difficulty) return false;
      if (filters.importance !== 'all' && term.importance !== filters.importance) return false;
      if (filters.examRelevant !== null && term.examRelevance !== filters.examRelevant) return false;
      if (filters.taniumSpecific !== null && term.taniumSpecific !== filters.taniumSpecific) return false;
      return true;
    });

    setIsLoading(false);
    return results;
  }, [searchTerm, filters, terminologySearch]);

  // Handle term selection
  const handleTermSelect = (term: TermDefinition) => {
    setSelectedTerm(term);
    onTermSelect?.(term);
  };

  // Reset filters
  const resetFilters = () => {
    setFilters({
      category: 'all',
      difficulty: 'all',
      importance: 'all',
      examRelevant: null,
      taniumSpecific: null
    });
  };

  // Get active filter count
  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.category !== 'all') count++;
    if (filters.difficulty !== 'all') count++;
    if (filters.importance !== 'all') count++;
    if (filters.examRelevant !== null) count++;
    if (filters.taniumSpecific !== null) count++;
    return count;
  }, [filters]);

  return (
    <div className={`bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden ${className}`}>
      {/* Header */}
      <div className="bg-gradient-to-r from-cyan-500 to-sky-600 px-6 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <BookOpen className="w-6 h-6 text-white" />
            <div>
              <h2 className="text-xl font-bold text-white">Interactive Glossary</h2>
              <p className="text-cyan-100 text-sm">
                {filteredTerms.length} terms • Search and explore TCO terminology
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Search and Filters */}
      <div className="p-6 border-b border-gray-200">
        <div className="space-y-4">
          {/* Search Bar */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Search terms, definitions, examples..."
              className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-cyan-500 focus:border-transparent"
            />
            {searchTerm && (
              <button
                onClick={() => setSearchTerm('')}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                ×
              </button>
            )}
          </div>

          {/* Filter Toggle */}
          <div className="flex items-center justify-between">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
            >
              <Filter className="w-4 h-4" />
              <span>Filters</span>
              {activeFilterCount > 0 && (
                <span className="bg-cyan-500 text-white text-xs rounded-full px-2 py-1">
                  {activeFilterCount}
                </span>
              )}
            </button>
            {activeFilterCount > 0 && (
              <button
                onClick={resetFilters}
                className="text-sm text-cyan-600 hover:text-cyan-800"
              >
                Clear all filters
              </button>
            )}
          </div>

          {/* Filter Panel */}
          <AnimatePresence>
            {showFilters && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.2 }}
                className="overflow-hidden"
              >
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 p-4 bg-gray-50 rounded-lg">
                  {/* Category Filter */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Category</label>
                    <select
                      value={filters.category}
                      onChange={(e) => setFilters({ ...filters, category: e.target.value as TermCategory | 'all' })}
                      className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-cyan-500"
                    >
                      <option value="all">All Categories</option>
                      <option value="basic-it">Basic IT</option>
                      <option value="networking">Networking</option>
                      <option value="security">Security</option>
                      <option value="endpoint-management">Endpoint Management</option>
                      <option value="tanium-platform">Tanium Platform</option>
                      <option value="tanium-modules">Tanium Modules</option>
                      <option value="enterprise-operations">Enterprise Operations</option>
                      <option value="compliance">Compliance</option>
                      <option value="advanced-concepts">Advanced Concepts</option>
                    </select>
                  </div>

                  {/* Difficulty Filter */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Difficulty</label>
                    <select
                      value={filters.difficulty}
                      onChange={(e) => setFilters({ ...filters, difficulty: e.target.value as FilterState['difficulty'] })}
                      className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-cyan-500"
                    >
                      <option value="all">All Levels</option>
                      <option value="beginner">Beginner</option>
                      <option value="intermediate">Intermediate</option>
                      <option value="advanced">Advanced</option>
                    </select>
                  </div>

                  {/* Importance Filter */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Importance</label>
                    <select
                      value={filters.importance}
                      onChange={(e) => setFilters({ ...filters, importance: e.target.value as FilterState['importance'] })}
                      className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-cyan-500"
                    >
                      <option value="all">All Importance</option>
                      <option value="critical">Critical</option>
                      <option value="important">Important</option>
                      <option value="useful">Useful</option>
                    </select>
                  </div>

                  {/* Boolean Filters */}
                  <div className="col-span-full">
                    <div className="flex flex-wrap gap-4">
                      <label className="flex items-center space-x-2">
                        <input
                          type="checkbox"
                          checked={filters.examRelevant === true}
                          onChange={(e) => setFilters({ 
                            ...filters, 
                            examRelevant: e.target.checked ? true : null 
                          })}
                          className="rounded border-gray-300 text-cyan-600 focus:ring-cyan-500"
                        />
                        <span className="text-sm text-gray-700">Exam Relevant Only</span>
                      </label>
                      <label className="flex items-center space-x-2">
                        <input
                          type="checkbox"
                          checked={filters.taniumSpecific === true}
                          onChange={(e) => setFilters({ 
                            ...filters, 
                            taniumSpecific: e.target.checked ? true : null 
                          })}
                          className="rounded border-gray-300 text-cyan-600 focus:ring-cyan-500"
                        />
                        <span className="text-sm text-gray-700">Tanium Specific Only</span>
                      </label>
                    </div>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* Content */}
      <div className="flex h-96">
        {/* Terms List */}
        <div className="w-1/2 border-r border-gray-200 overflow-y-auto">
          {isLoading ? (
            <div className="flex items-center justify-center h-full">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div>
            </div>
          ) : filteredTerms.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-gray-500 p-6">
              <Search className="w-12 h-12 mb-4" />
              <p className="text-lg font-medium">No terms found</p>
              <p className="text-sm text-center">Try adjusting your search or filters</p>
            </div>
          ) : (
            <div className="p-4 space-y-2">
              {filteredTerms.map((term, index) => {
                const IconComponent = categoryIcons[term.category];
                return (
                  <motion.div
                    key={term.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                    onClick={() => handleTermSelect(term)}
                    className={`p-3 rounded-lg cursor-pointer transition-all hover:shadow-md ${
                      selectedTerm?.id === term.id 
                        ? 'bg-cyan-50 border border-cyan-200' 
                        : 'bg-gray-50 hover:bg-gray-100'
                    }`}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-2">
                          <IconComponent className="w-4 h-4 text-gray-500" />
                          <h3 className="font-medium text-gray-900">{term.term}</h3>
                        </div>
                        <p className="text-sm text-gray-600 mt-1 line-clamp-2">
                          {term.beginnerExplanation}
                        </p>
                        <div className="flex items-center space-x-2 mt-2">
                          <span className={`px-2 py-1 text-xs rounded-full ${categoryColors[term.category]}`}>
                            {term.category}
                          </span>
                          <span className={`px-2 py-1 text-xs rounded-full ${difficultyColors[term.difficulty]}`}>
                            {term.difficulty}
                          </span>
                          {term.examRelevance && (
                            <span className="px-2 py-1 text-xs rounded-full bg-green-100 text-green-800">
                              Exam
                            </span>
                          )}
                        </div>
                      </div>
                      <ChevronRight className="w-4 h-4 text-gray-400" />
                    </div>
                  </motion.div>
                );
              })}
            </div>
          )}
        </div>

        {/* Term Details */}
        <div className="w-1/2 overflow-y-auto">
          {selectedTerm ? (
            <div className="p-6">
              <div className="space-y-6">
                {/* Term Header */}
                <div>
                  <div className="flex items-center space-x-3 mb-2">
                    {React.createElement(categoryIcons[selectedTerm.category], { 
                      className: "w-6 h-6 text-cyan-600" 
                    })}
                    <h2 className="text-2xl font-bold text-gray-900">{selectedTerm.term}</h2>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <span className={`px-3 py-1 text-sm rounded-full ${categoryColors[selectedTerm.category]}`}>
                      {selectedTerm.category}
                    </span>
                    <span className={`px-3 py-1 text-sm rounded-full ${difficultyColors[selectedTerm.difficulty]}`}>
                      {selectedTerm.difficulty}
                    </span>
                    <span className={`px-3 py-1 text-sm rounded-full ${importanceColors[selectedTerm.importance]}`}>
                      {selectedTerm.importance}
                    </span>
                    {selectedTerm.examRelevance && (
                      <span className="px-3 py-1 text-sm rounded-full bg-green-100 text-green-800">
                        Exam Relevant
                      </span>
                    )}
                    {selectedTerm.taniumSpecific && (
                      <span className="px-3 py-1 text-sm rounded-full bg-cyan-100 text-cyan-800">
                        Tanium Specific
                      </span>
                    )}
                  </div>
                </div>

                {/* Definitions */}
                <div className="space-y-4">
                  <div>
                    <h3 className="font-semibold text-gray-900 mb-2">Definition</h3>
                    <p className="text-gray-700 leading-relaxed">{selectedTerm.definition}</p>
                  </div>

                  <div>
                    <h3 className="font-semibold text-gray-900 mb-2">Beginner Explanation</h3>
                    <p className="text-gray-700 leading-relaxed">{selectedTerm.beginnerExplanation}</p>
                  </div>
                </div>

                {/* Examples */}
                {selectedTerm.examples && selectedTerm.examples.length > 0 && (
                  <div>
                    <h3 className="font-semibold text-gray-900 mb-2">Examples</h3>
                    <ul className="space-y-1">
                      {selectedTerm.examples.map((example, index) => (
                        <li key={index} className="flex items-start space-x-2">
                          <span className="text-cyan-500 mt-1">•</span>
                          <span className="text-gray-700">{example}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Related Terms */}
                {selectedTerm.relatedTerms && selectedTerm.relatedTerms.length > 0 && (
                  <div>
                    <h3 className="font-semibold text-gray-900 mb-2">Related Terms</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedTerm.relatedTerms.map((relatedTerm, index) => {
                        const related = terminologySearch.getById(relatedTerm);
                        return (
                          <button
                            key={index}
                            onClick={() => related && handleTermSelect(related)}
                            className="px-3 py-1 text-sm bg-cyan-100 text-cyan-700 rounded-full hover:bg-cyan-200 transition-colors"
                          >
                            {related?.term || relatedTerm}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-full text-gray-500 p-6">
              <BookOpen className="w-16 h-16 mb-4" />
              <h3 className="text-lg font-medium mb-2">Select a term to learn more</h3>
              <p className="text-sm text-center">
                Click on any term from the list to see detailed explanations, examples, and related concepts
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default InteractiveGlossary;

/**
 * StudyGuideList Component - Display available study guides
 * Provides overview of all study guides with progress indicators and filtering
 * Matches existing ModuleList styling and functionality
 */

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  FileText,
  Clock,
  CheckCircle,
  Play,
  Search,
  Filter,
  BookOpen,
  Target,
  User,
  Calendar,
  Eye,
} from "lucide-react";
import { type StudyGuide, StudyGuideProgress } from "@/types/module";
import { useModule } from "@/contexts/ModuleContext";
import { cn } from "@/lib/utils";

interface StudyGuideListProps {
  studyGuides: StudyGuide[];
  onGuideSelect?: (guideId: string) => void;
  className?: string;
}

export function StudyGuideList({ studyGuides, onGuideSelect, className }: StudyGuideListProps) {
  const { state } = useModule();
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedModule, setSelectedModule] = useState<string>("all");
  const [sortBy, setSortBy] = useState<string>("title");

  // Filter guides based on search and filters
  const filteredGuides = studyGuides.filter((guide) => {
    const matchesSearch =
      guide.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      guide.description.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesModule = selectedModule === "all" || guide.moduleId === selectedModule;

    return matchesSearch && matchesModule;
  });

  // Sort guides
  const sortedGuides = [...filteredGuides].sort((a, b) => {
    switch (sortBy) {
      case "title":
        return a.title.localeCompare(b.title);
      case "readingTime":
        return a.estimatedReadingTime - b.estimatedReadingTime;
      case "lastUpdated":
        return new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime();
      case "progress":
        const progressA = getProgressInfo(a).progress;
        const progressB = getProgressInfo(b).progress;
        return progressB - progressA;
      default:
        return 0;
    }
  });

  // Get unique module IDs
  const moduleIds = Array.from(new Set(studyGuides.map((g) => g.moduleId)));

  const handleGuideClick = (guideId: string) => {
    onGuideSelect?.(guideId);
  };

  const getProgressInfo = (guide: StudyGuide) => {
    const progress = undefined as any;
    return {
      progress: progress?.readingProgress || 0,
      sectionsRead: progress?.sectionsRead?.length || 0,
      totalSections: guide.sections.length,
      checkpointsCompleted: progress?.checkpointsCompleted?.length || 0,
      totalCheckpoints: guide.checkpoints.length,
      totalReadingTime: progress?.totalReadingTime || 0,
      lastPosition: progress?.lastPosition,
      hasStarted: !!progress,
    };
  };

  const getStatusColor = (progress: number) => {
    if (progress >= 100) return "text-green-600 dark:text-green-400";
    if (progress > 0) return "text-blue-600 dark:text-blue-400";
    return "text-gray-600 dark:text-gray-400";
  };

  const getStatusIcon = (progress: number) => {
    if (progress >= 100) return <CheckCircle className="h-5 w-5" />;
    if (progress > 0) return <Play className="h-5 w-5" />;
    return <FileText className="h-5 w-5" />;
  };

  return (
    <div className={cn("space-y-6", className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="space-y-1">
          <h2 className="text-2xl font-bold tracking-tight">Study Guides</h2>
          <p className="text-muted-foreground">
            Comprehensive study guides for quick reference and review
          </p>
        </div>
        <div className="flex items-center space-x-2">
          <Badge variant="outline" className="flex items-center space-x-1">
            <FileText className="h-4 w-4" />
            <span>{filteredGuides.length} guides</span>
          </Badge>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center text-lg">
            <Filter className="mr-2 h-5 w-5" />
            Filters & Search
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 gap-4 md:grid-cols-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Search</label>
              <div className="relative">
                <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search guides..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-9"
                />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Module</label>
              <Select value={selectedModule} onValueChange={setSelectedModule}>
                <SelectTrigger>
                  <SelectValue placeholder="All modules" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Modules</SelectItem>
                  {moduleIds.map((moduleId) => (
                    <SelectItem key={moduleId} value={moduleId}>
                      Module {moduleId}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Sort By</label>
              <Select value={sortBy} onValueChange={setSortBy}>
                <SelectTrigger>
                  <SelectValue placeholder="Sort by" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="title">Title</SelectItem>
                  <SelectItem value="readingTime">Reading Time</SelectItem>
                  <SelectItem value="progress">Progress</SelectItem>
                  <SelectItem value="lastUpdated">Last Updated</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex items-end">
              <Button
                variant="outline"
                onClick={() => {
                  setSearchQuery("");
                  setSelectedModule("all");
                  setSortBy("title");
                }}
                className="w-full"
              >
                Clear Filters
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Guide Grid */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
        {sortedGuides.map((guide) => {
          const progressInfo = getProgressInfo(guide);
          const statusClass = getStatusColor(progressInfo.progress);

          return (
            <Card
              key={guide.id}
              className="glass group cursor-pointer transition-all hover:scale-[1.02] hover:shadow-lg"
              onClick={() => handleGuideClick(guide.id)}
            >
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="space-y-2">
                    <div className="flex items-center space-x-2">
                      <div className={statusClass}>{getStatusIcon(progressInfo.progress)}</div>
                      <CardTitle className="text-lg group-hover:text-primary">
                        {guide.title}
                      </CardTitle>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Badge variant="outline" className="text-xs">
                        Module {guide.moduleId}
                      </Badge>
                      {progressInfo.hasStarted && (
                        <Badge variant="secondary" className="text-xs">
                          {progressInfo.progress >= 100 ? "Completed" : "In Progress"}
                        </Badge>
                      )}
                    </div>
                  </div>
                </div>
                <p className="line-clamp-2 text-sm text-muted-foreground">{guide.description}</p>
              </CardHeader>
              <CardContent className="space-y-4">
                {/* Progress */}
                {progressInfo.progress > 0 && (
                  <div className="space-y-2">
                    <div className="flex justify-between text-sm">
                      <span>Reading Progress</span>
                      <span>{progressInfo.progress}%</span>
                    </div>
                    <Progress value={progressInfo.progress} className="h-2" />
                    <div className="flex justify-between text-xs text-muted-foreground">
                      <span>
                        {progressInfo.sectionsRead}/{progressInfo.totalSections} sections
                      </span>
                      <span>
                        {progressInfo.checkpointsCompleted}/{progressInfo.totalCheckpoints}{" "}
                        checkpoints
                      </span>
                    </div>
                  </div>
                )}

                {/* Guide Info */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-sm text-muted-foreground">
                    <div className="flex items-center space-x-1">
                      <Eye className="h-4 w-4" />
                      <span>{guide.estimatedReadingTime} min read</span>
                    </div>
                    <div className="flex items-center space-x-1">
                      <Target className="h-4 w-4" />
                      <span>{guide.sections.length} sections</span>
                    </div>
                  </div>

                  {guide.checkpoints.length > 0 && (
                    <div className="flex items-center space-x-1 text-sm text-muted-foreground">
                      <CheckCircle className="h-4 w-4" />
                      <span>{guide.checkpoints.length} checkpoints</span>
                    </div>
                  )}
                </div>

                {/* Reading time spent */}
                {progressInfo.totalReadingTime > 0 && (
                  <div className="flex items-center justify-between text-xs text-muted-foreground">
                    <span>Time spent: {progressInfo.totalReadingTime} min</span>
                    <span>Updated: {new Date(guide.lastUpdated).toLocaleDateString()}</span>
                  </div>
                )}

                {/* Action Button */}
                <Button
                  className="w-full"
                  variant={progressInfo.progress >= 100 ? "outline" : "default"}
                >
                  {progressInfo.progress >= 100
                    ? "Review Guide"
                    : progressInfo.hasStarted
                      ? "Continue Reading"
                      : "Start Reading"}
                </Button>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Empty State */}
      {filteredGuides.length === 0 && (
        <Card className="glass">
          <CardContent className="py-8 text-center">
            <FileText className="mx-auto mb-4 h-16 w-16 text-muted-foreground" />
            <p className="mb-2 text-lg font-medium">No study guides found</p>
            <p className="text-muted-foreground">Try adjusting your search criteria or filters</p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

/**
 * StudyGuideViewer Component - Display study guide content
 * Handles markdown rendering, progress tracking, and navigation
 */

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  BookOpen,
  Clock,
  CheckCircle,
  Circle,
  ArrowLeft,
  ArrowRight,
  Bookmark,
  BookmarkCheck,
} from "lucide-react";
import type { StudyGuide, StudyGuideProgress } from "@/types/module";
import { cn } from "@/lib/utils";

interface StudyGuideViewerProps {
  guide: StudyGuide;
  progress?: StudyGuideProgress;
  onProgressUpdate?: (progress: Partial<StudyGuideProgress>) => void;
  onSectionComplete?: (sectionId: string) => void;
  className?: string;
}

export function StudyGuideViewer({
  guide,
  progress,
  onProgressUpdate,
  onSectionComplete,
  className,
}: StudyGuideViewerProps) {
  const [currentSectionIndex, setCurrentSectionIndex] = useState(0);
  const [isBookmarked, setIsBookmarked] = useState(false);

  const currentSection = guide.sections[currentSectionIndex];
  const isFirstSection = currentSectionIndex === 0;
  const isLastSection = currentSectionIndex === guide.sections.length - 1;

  // Calculate progress
  const completedSections = progress?.sectionsRead || [];
  const guideProgress = Math.round((completedSections.length / guide.sections.length) * 100);

  useEffect(() => {
    if (currentSection && !completedSections.includes(currentSection.id)) {
      // Mark section as read
      onSectionComplete?.(currentSection.id);
      onProgressUpdate?.({
        sectionsRead: [...completedSections, currentSection.id],
        readingProgress: Math.round(((completedSections.length + 1) / guide.sections.length) * 100),
        lastPosition: currentSection.id,
      });
    }
  }, [
    currentSection?.id,
    completedSections,
    onSectionComplete,
    onProgressUpdate,
    currentSection,
    guide.sections.length,
  ]);

  const navigateToSection = (index: number) => {
    if (index >= 0 && index < guide.sections.length) {
      setCurrentSectionIndex(index);
      onProgressUpdate?.({
        lastPosition: guide.sections[index].id,
      });
    }
  };

  const renderMarkdownContent = (content: string) => {
    // Simple markdown-like rendering (for more complex markdown, use a library like react-markdown)
    return (
      <div className="prose prose-slate dark:prose-invert max-w-none">
        <div dangerouslySetInnerHTML={{ __html: content.replace(/\n/g, "<br/>") }} />
      </div>
    );
  };

  if (!currentSection) {
    return (
      <Card className={className}>
        <CardContent className="py-8 text-center">
          <BookOpen className="mx-auto mb-4 h-16 w-16 text-muted-foreground" />
          <p className="text-muted-foreground">No study guide content available</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className={cn("space-y-6", className)}>
      {/* Guide Header */}
      <Card>
        <CardHeader>
          <div className="flex items-start justify-between">
            <div className="space-y-2">
              <CardTitle className="flex items-center">
                <BookOpen className="mr-2 h-6 w-6" />
                {guide.title}
              </CardTitle>
              <p className="text-muted-foreground">{guide.description}</p>
              <div className="flex items-center space-x-4 text-sm text-muted-foreground">
                <span className="flex items-center">
                  <Clock className="mr-1 h-4 w-4" />
                  {guide.estimatedReadingTime} min read
                </span>
                <Badge variant="outline">{guide.sections.length} sections</Badge>
                <Badge variant="secondary">Study Guide</Badge>
              </div>
            </div>
            <Button variant="outline" size="sm" onClick={() => setIsBookmarked(!isBookmarked)}>
              {isBookmarked ? (
                <BookmarkCheck className="h-4 w-4" />
              ) : (
                <Bookmark className="h-4 w-4" />
              )}
            </Button>
          </div>

          {/* Progress indicator */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span>Reading Progress</span>
              <span>{guideProgress}% complete</span>
            </div>
            <Progress value={guideProgress} className="h-2" />
          </div>
        </CardHeader>
      </Card>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-4">
        {/* Section Navigation */}
        <Card className="lg:col-span-1">
          <CardHeader>
            <CardTitle className="text-lg">Sections</CardTitle>
          </CardHeader>
          <CardContent>
            <ScrollArea className="h-[400px]">
              <div className="space-y-2">
                {guide.sections.map((section, index) => {
                  const isRead = completedSections.includes(section.id);
                  const isCurrent = index === currentSectionIndex;

                  return (
                    <Button
                      key={section.id}
                      variant={isCurrent ? "default" : "ghost"}
                      className={cn(
                        "h-auto w-full justify-start p-3 text-left",
                        isRead && "bg-green-50 hover:bg-green-100 dark:bg-green-950/20"
                      )}
                      onClick={() => navigateToSection(index)}
                    >
                      <div className="flex w-full items-start">
                        {isRead ? (
                          <CheckCircle className="mr-2 mt-0.5 h-4 w-4 flex-shrink-0 text-green-600" />
                        ) : (
                          <Circle className="mr-2 mt-0.5 h-4 w-4 flex-shrink-0" />
                        )}
                        <div className="text-left">
                          <div className="text-sm font-medium">{section.title}</div>
                          <div className="text-xs text-muted-foreground">Level {section.level}</div>
                        </div>
                      </div>
                    </Button>
                  );
                })}
              </div>
            </ScrollArea>
          </CardContent>
        </Card>

        {/* Main Content */}
        <Card className="lg:col-span-3">
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle>{currentSection.title}</CardTitle>
              <Badge variant="outline">
                Section {currentSectionIndex + 1} of {guide.sections.length}
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Section content */}
            <div className="min-h-[400px]">{renderMarkdownContent(currentSection.content)}</div>

            {/* Section actions */}
            <div className="flex items-center justify-between border-t pt-4">
              <Button
                variant="outline"
                onClick={() => navigateToSection(currentSectionIndex - 1)}
                disabled={isFirstSection}
              >
                <ArrowLeft className="mr-2 h-4 w-4" />
                Previous
              </Button>

              <div className="flex space-x-2">
                <Button
                  onClick={() => navigateToSection(currentSectionIndex + 1)}
                  disabled={isLastSection}
                >
                  Next
                  <ArrowRight className="ml-2 h-4 w-4" />
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { TCODomain } from "@/types/exam";
import { useEffect, useMemo, useState } from "react";
import { useProgress } from "@/contexts/ProgressContext";
import { Heart, Sparkles, BookOpen, Target, Trophy, ArrowUpRight, ArrowDownRight, Minus } from "lucide-react";

export function HomePage() {
  const router = useRouter();
  const [totalQuestions, setTotalQuestions] = useState<number>(0);
  // Defer heavy question bank import to reduce initial bundle
  useEffect(() => {
    let active = true;
    const idle = (window as any).requestIdleCallback as undefined | ((cb: any) => void);
    const load = async () => {
      try {
        const mod = await import("@/lib/questionLoader");
        if (active) setTotalQuestions(mod.getAllQuestions().length);
      } catch {
        // swallow; keep 0 if not available
      }
    };
    if (idle) idle(load);
    else setTimeout(load, 200);
    return () => { active = false; };
  }, []);
  const { getDomainStats, state: progressState } = useProgress();
  const tcoDomains = [
    TCODomain.ASKING_QUESTIONS,
    TCODomain.REFINING_TARGETING,
    TCODomain.TAKING_ACTION,
    TCODomain.NAVIGATION_MODULES,
    TCODomain.REPORTING_EXPORT,
  ];
  const domainPerf = useMemo(() => {
    const stats = getDomainStats();
    const map = new Map<string, { score: number; answered: number; correct: number }>();
    for (const s of stats) {
      map.set(s.domain as string, { score: s.percentage, answered: s.questionsAnswered, correct: s.correctAnswers });
    }
    return tcoDomains.map((d) => ({
      domain: d,
      score: map.get(d)?.score || 0,
      answered: map.get(d)?.answered || 0,
      correct: map.get(d)?.correct || 0,
    }));
  }, [getDomainStats]);

  // Weakest domain among those with data
  const weakest = useMemo(() => {
    const withData = domainPerf.filter((d) => d.answered > 0);
    if (withData.length === 0) return null;
    return withData.reduce((min, d) => (d.score < min.score ? d : min), withData[0]);
  }, [domainPerf]);

  // Trend (delta of last two sessions per domain)
  const domainTrends = useMemo(() => {
    const trends = new Map<string, number>();
    const recent = progressState.progress.recentSessions || [];
    for (const d of tcoDomains) {
      const ds = recent.filter((s) => s.domain === d).slice(0, 2);
      const delta = ds.length >= 2 ? ds[0].score - ds[1].score : 0;
      trends.set(d, delta);
    }
    return trends;
  }, [progressState.progress.recentSessions]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-blue-900 to-cyan-900">
      <div className="container mx-auto px-4 py-8">
        {/* Welcome Section */}
        <div className="text-center mb-12">
          <div className="flex items-center justify-center space-x-3 mb-4">
            <Heart className="h-8 w-8 text-pink-400" />
            <h1 className="text-4xl font-bold text-white">Welcome to TCO Preparation</h1>
            <Sparkles className="h-8 w-8 text-yellow-400" />
          </div>
          <p className="text-xl text-gray-200 max-w-3xl mx-auto">
            Master the Tanium Certified Operator exam with interactive practice and comprehensive study modules
          </p>
        </div>

        {/* Weakest Domain Callout */}
        <div className="mb-6 flex items-center justify-center">
          <div className="rounded-lg border border-yellow-400/40 bg-yellow-500/10 px-4 py-3 text-yellow-200">
            {weakest ? (
              <span>
                Weakest domain: <span className="font-semibold">{weakest.domain}</span> — accuracy {weakest.score}%
                <button
                  onClick={() => router.push(`/practice?domain=${encodeURIComponent(weakest.domain)}&count=25&quick=1&reveal=1`)}
                  className="ml-3 inline-flex items-center rounded bg-yellow-500/20 px-2 py-1 text-xs text-yellow-100 hover:bg-yellow-500/30"
                >
                  Drill now
                </button>
              </span>
            ) : (
              <span>No practice data yet — start a quick drill to identify your weakest domain.</span>
            )}
          </div>
        </div>

        {/* Quick Stats */}
          <div className="grid gap-6 md:grid-cols-3 mb-12">
            <div className="bg-white/10 backdrop-blur-sm border border-white/20 rounded-lg p-6 text-center">
              <Trophy className="h-8 w-8 text-yellow-400 mx-auto mb-2" />
              <div className="text-2xl font-bold text-white">{totalQuestions}</div>
              <p className="text-gray-300">Practice Questions</p>
            </div>

          <div className="bg-white/10 backdrop-blur-sm border border-white/20 rounded-lg p-6 text-center">
            <BookOpen className="h-8 w-8 text-blue-400 mx-auto mb-2" />
            <div className="text-2xl font-bold text-white">5</div>
            <p className="text-gray-300">Study Domains</p>
          </div>

          <div className="bg-white/10 backdrop-blur-sm border border-white/20 rounded-lg p-6 text-center">
            <Target className="h-8 w-8 text-green-400 mx-auto mb-2" />
            <div className="text-2xl font-bold text-white">78%</div>
            <p className="text-gray-300">Average Score</p>
          </div>
        </div>

        {/* Study Domains */}
        <div className="space-y-6">
          <h2 className="text-2xl font-bold text-white text-center">Study Domains</h2>
          <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
            {[
              { title: "Asking Questions", desc: "Master Tanium's query system", progress: 72, domain: TCODomain.ASKING_QUESTIONS },
              { title: "Refining Questions & Targeting", desc: "Advanced computer group management", progress: 85, domain: TCODomain.REFINING_TARGETING },
              { title: "Taking Action", desc: "Package deployment workflows", progress: 58, domain: TCODomain.TAKING_ACTION },
              { title: "Navigation & Module Functions", desc: "Console navigation expertise", progress: 43, domain: TCODomain.NAVIGATION_MODULES },
              { title: "Reporting & Data Export", desc: "Data export and reporting", progress: 67, domain: TCODomain.REPORTING_EXPORT },
              { title: "Mock Exam", desc: "Full TCO simulation", progress: 0, domain: null }
            ].map((d, index) => (
              <div key={index} className="bg-white/10 backdrop-blur-sm border border-white/20 rounded-lg p-6 hover:bg-white/15 transition-colors cursor-pointer">
                <h3 className="text-lg font-semibold text-white mb-2">{d.title}</h3>
                <p className="text-gray-300 text-sm mb-4">{d.desc}</p>
                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-300">Progress</span>
                    <span className="text-white font-medium">{d.progress}%</span>
                  </div>
                  <div className="w-full bg-gray-700 rounded-full h-2">
                    <div 
                      className="bg-gradient-to-r from-blue-500 to-cyan-500 h-2 rounded-full transition-all duration-300" 
                      style={{ width: `${d.progress}%` }}
                    ></div>
                  </div>
                </div>
                {d.domain ? (
                  <div className="mt-4 flex justify-end">
                    <button
                      onClick={() => router.push(`/practice?domain=${encodeURIComponent(d.domain)}&count=25&quick=1&reveal=1`)}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-md text-sm"
                    >
                      Quick Drill (25)
                    </button>
                  </div>
                ) : (
                  <div className="mt-4 flex justify-end">
                    <button
                      onClick={() => router.push("/mock?variant=A")}
                      className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-md text-sm"
                    >
                      Start Mock Exam
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Your Domain Performance */}
        <div className="space-y-6">
          <h2 className="text-2xl font-bold text-white text-center">Your Domain Performance</h2>
          <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-5">
            {domainPerf.map((d) => (
              <div key={d.domain} className="bg-white/10 backdrop-blur-sm border border-white/20 rounded-lg p-4">
                <div className="text-sm text-blue-200 mb-1">{d.domain}</div>
                <div className="text-white text-2xl font-bold">{d.score}%</div>
                <div className="text-xs text-gray-300">Accuracy</div>
                <div className="mt-1 text-xs text-gray-300 flex items-center gap-1">
                  {(() => {
                    const delta = domainTrends.get(d.domain) || 0;
                    if (delta > 0) return (<><ArrowUpRight className="h-3 w-3 text-green-400" /> <span className="text-green-400">+{delta}</span></>);
                    if (delta < 0) return (<><ArrowDownRight className="h-3 w-3 text-red-400" /> <span className="text-red-400">{delta}</span></>);
                    return (<><Minus className="h-3 w-3 text-gray-400" /> <span className="text-gray-400">0</span></>);
                  })()}
                </div>
                <div className="mt-2 text-white/90 text-sm">
                  {d.correct}/{d.answered} correct
                </div>
                <div className="mt-3 flex justify-end">
                  <button
                    onClick={() => router.push(`/practice?domain=${encodeURIComponent(d.domain)}&count=25&quick=1&reveal=1`)}
