  onComplete?: (labId: string, score: number) => void;
}

export function InteractiveLabSystem({ labId, onComplete }: InteractiveLabSystemProps) {
  const [selectedLab, setSelectedLab] = useState<Lab | null>(null);
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<Set<string>>(new Set());
  const [userInput, setUserInput] = useState("");
  const [isValidating, setIsValidating] = useState(false);
  const [validationResult, setValidationResult] = useState<{
    success: boolean;
    message: string;
  } | null>(null);
  const [labStartTime, setLabStartTime] = useState<Date | null>(null);
  const [elapsedTime, setElapsedTime] = useState(0);

  // Timer effect
  useEffect(() => {
    if (labStartTime) {
      const interval = setInterval(() => {
        setElapsedTime(Math.floor((Date.now() - labStartTime.getTime()) / 1000));
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [labStartTime]);

  // Auto-select lab if labId provided
  useEffect(() => {
    if (labId) {
      const lab = sampleLabs.find((l) => l.id === labId);
      if (lab) {
        setSelectedLab(lab);
        setLabStartTime(new Date());
      }
    }
  }, [labId]);

  const handleLabSelect = (lab: Lab) => {
    setSelectedLab(lab);
    setCurrentStep(0);
    setCompletedSteps(new Set());
    setUserInput("");
    setValidationResult(null);
    setLabStartTime(new Date());
  };

  const validateStep = async (step: LabStep) => {
    setIsValidating(true);

    // Simulate validation (in real implementation, this would validate against actual Tanium console)
    await new Promise((resolve) => setTimeout(resolve, 1500));

    let success = false;

    // Simple validation simulation
    switch (step.validation.type) {
      case "code":
        success = new RegExp(step.validation.pattern, "i").test(userInput);
        break;
      case "interface":
      case "result":
        // Simulate successful validation for demo
        success = true;
        break;
    }

    setValidationResult({
      success,
      message: success
        ? step.validation.feedback
        : "Validation failed. Please check your input and try again.",
    });

    if (success) {
      setCompletedSteps((prev) => new Set([...prev, step.id]));

      // Move to next step after delay
      setTimeout(() => {
        if (currentStep < selectedLab!.steps.length - 1) {
          setCurrentStep((prev) => prev + 1);
          setUserInput("");
          setValidationResult(null);
        } else {
          // Lab completed
          const score = Math.round(
            ((selectedLab!.steps.length - 0) / selectedLab!.steps.length) * 100
          );
          onComplete?.(selectedLab!.id, score);
        }
      }, 2000);
    }

    setIsValidating(false);
  };

  const resetLab = () => {
    setCurrentStep(0);
    setCompletedSteps(new Set());
    setUserInput("");
    setValidationResult(null);
    setLabStartTime(new Date());
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  const calculateProgress = () => {
    if (!selectedLab) return 0;
    return (completedSteps.size / selectedLab.steps.length) * 100;
  };

  if (!selectedLab) {
    return (
      <div className="space-y-6">
        <div className="text-center">
          <h2 className="mb-4 text-3xl font-bold text-white">Interactive Lab System</h2>
          <p className="mb-8 text-gray-300">
            Practice real Tanium procedures with step-by-step guided exercises
          </p>
        </div>

        <div className="grid gap-6 md:grid-cols-2">
          {sampleLabs.map((lab) => (
            <Card
              key={lab.id}
              className="glass cursor-pointer border-white/10 transition-all hover:border-white/20"
            >
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div>
                    <CardTitle className="text-lg text-white">{lab.title}</CardTitle>
                    <p className="mt-1 text-sm text-gray-400">{lab.domain}</p>
                  </div>
                  <Badge
                    variant="outline"
                    className={
                      lab.difficulty === "Beginner"
                        ? "border-green-500 text-green-400"
                        : lab.difficulty === "Intermediate"
                          ? "border-yellow-500 text-yellow-400"
                          : "border-red-500 text-red-400"
                    }
                  >
                    {lab.difficulty}
                  </Badge>
                </div>
                <p className="mt-2 text-sm text-gray-300">{lab.description}</p>
              </CardHeader>
              <CardContent>
                <div className="mb-4 flex items-center justify-between">
                  <div className="flex items-center space-x-4 text-sm text-gray-400">
                    <div className="flex items-center space-x-1">
                      <Clock className="h-4 w-4" />
                      <span>{lab.estimatedTime} min</span>
                    </div>
                    <div className="flex items-center space-x-1">
                      <Code className="h-4 w-4" />
                      <span>{lab.steps.length} steps</span>
                    </div>
                  </div>
                </div>
                <Button
                  className="w-full bg-tanium-accent hover:bg-blue-600"
                  onClick={() => handleLabSelect(lab)}
                >
                  <Play className="mr-2 h-4 w-4" />
                  Start Lab
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  const currentStepData = selectedLab.steps[currentStep];
  const isCompleted = completedSteps.size === selectedLab.steps.length;

  return (
    <div className="space-y-6">
      {/* Lab Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">{selectedLab.title}</h2>
          <p className="text-gray-400">{selectedLab.domain}</p>
        </div>
        <div className="flex items-center space-x-4">
          <div className="text-right">
            <div className="text-sm text-gray-400">Elapsed Time</div>
            <div className="font-mono text-lg text-white">{formatTime(elapsedTime)}</div>
          </div>
          <Button variant="outline" size="sm" onClick={resetLab}>
            <RotateCcw className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Progress Bar */}
      <div className="space-y-2">
        <div className="flex justify-between text-sm">
          <span className="text-gray-400">Progress</span>
          <span className="text-white">
            {completedSteps.size}/{selectedLab.steps.length} steps
          </span>
        </div>
        <Progress value={calculateProgress()} className="h-2" />
      </div>

      {isCompleted ? (
        // Completion Screen
        <Card className="glass border-green-500/50 bg-green-500/10">
          <CardContent className="p-8 text-center">
            <Trophy className="mx-auto mb-4 h-16 w-16 text-yellow-400" />
            <h3 className="mb-2 text-2xl font-bold text-white">Lab Completed!</h3>
            <p className="mb-4 text-gray-300">
              You successfully completed {selectedLab.title} in {formatTime(elapsedTime)}
            </p>
            <div className="flex justify-center space-x-4">
              <Button onClick={() => setSelectedLab(null)}>Return to Labs</Button>
              <Button variant="outline" onClick={resetLab}>
                Retry Lab
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : (
        // Active Lab Step
        <div className="grid gap-6 lg:grid-cols-2">
          {/* Instructions Panel */}
          <Card className="glass border-white/10">
            <CardHeader>
              <CardTitle className="flex items-center text-white">
                <Terminal className="mr-2 h-5 w-5" />
                Step {currentStep + 1}: {currentStepData.title}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <Alert>
                <Code className="h-4 w-4" />
                <AlertDescription className="text-gray-300">
                  {currentStepData.instruction}
                </AlertDescription>
              </Alert>

              <div className="space-y-2">
                <h4 className="font-semibold text-white">Expected Result:</h4>
                <p className="rounded bg-gray-800/50 p-3 text-sm text-gray-300">
                  {currentStepData.expectedResult}
                </p>
              </div>

              {currentStepData.hint && (
                <Alert className="border-yellow-500/50">
                  <Zap className="h-4 w-4" />
                  <AlertDescription className="text-yellow-200">
                    <strong>Hint:</strong> {currentStepData.hint}
                  </AlertDescription>
                </Alert>
              )}
            </CardContent>
          </Card>

          {/* Validation Panel */}
          <Card className="glass border-white/10">
            <CardHeader>
              <CardTitle className="text-white">Validation</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {currentStepData.validation.type === "code" && (
                <div className="space-y-2">
                  <label className="text-sm text-gray-400">Enter your query/command:</label>
                  <textarea
                    className="w-full rounded border border-gray-600 bg-gray-800 p-3 font-mono text-white"
                    rows={3}
                    value={userInput}
                    onChange={(e) => setUserInput(e.target.value)}
                    placeholder="Enter your Tanium query here..."
                  />
                </div>
              )}

              {validationResult && (
                <Alert
                  className={
                    validationResult.success
                      ? "border-green-500/50 bg-green-500/10"
                      : "border-red-500/50 bg-red-500/10"
                  }
                >
                  {validationResult.success ? (
                    <CheckCircle className="h-4 w-4 text-green-400" />
                  ) : (
                    <XCircle className="h-4 w-4 text-red-400" />
                  )}
                  <AlertDescription
                    className={validationResult.success ? "text-green-300" : "text-red-300"}
                  >
                    {validationResult.message}
                  </AlertDescription>
                </Alert>
              )}

              <Button
                className="w-full"
                onClick={() => validateStep(currentStepData)}
                disabled={
                  isValidating || (currentStepData.validation.type === "code" && !userInput.trim())
                }
              >
                {isValidating ? (
                  <>
                    <div className="mr-2 h-4 w-4 animate-spin rounded-full border-b-2 border-white" />
                    Validating...
                  </>
                ) : (
                  <>
                    <CheckCircle className="mr-2 h-4 w-4" />
                    Validate Step
                  </>
                )}
              </Button>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Step Navigation */}
      <div className="flex items-center justify-between">
        <div className="flex space-x-2">
          {selectedLab.steps.map((step, index) => (
            <div
              key={step.id}
              className={`flex h-8 w-8 items-center justify-center rounded-full text-sm font-medium ${
                completedSteps.has(step.id)
                  ? "bg-green-500 text-white"
                  : index === currentStep
                    ? "bg-tanium-accent text-white"
                    : "bg-gray-700 text-gray-400"
              }`}
            >
              {completedSteps.has(step.id) ? <CheckCircle className="h-4 w-4" /> : index + 1}
            </div>
          ))}
        </div>

        <Button
          variant="ghost"
          onClick={() => setSelectedLab(null)}
          className="text-gray-400 hover:text-white"
        >
          Exit Lab
        </Button>
      </div>
    </div>
  );
}

"use client";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { AnimatePresence, motion } from "framer-motion";
import {
  Award,
  BookOpen,
  CheckCircle,
  ChevronLeft,
  ChevronRight,
  Clock,
  Eye,
  EyeOff,
  Pause,
  Play,
  RotateCcw,
  Target,
  XCircle,
} from "lucide-react";
import React, { useCallback, useEffect, useState } from "react";

import { labProgressService } from "@/lib/supabase/labProgressService";
import type {
  ConsoleState,
  LabAchievement,
  LabExercise,
  LabProgress,
  ValidationResult,
} from "@/types/lab";
import { CheckpointValidator } from "./CheckpointValidator";
import { ConsoleSimulator } from "./ConsoleSimulator";

interface LabExercisePlayerProps {
  exercise: LabExercise;
  userId: string;
  onComplete?: (results: ValidationResult[]) => void;
  onExit?: () => void;
  className?: string;
}

interface PlayerState {
  currentStepIndex: number;
  session: LabProgress | null;
  stepResults: ValidationResult[];
  consoleState: ConsoleState;
  isValidating: boolean;
  showHints: boolean;
  timer: {
    startTime: number;
    elapsed: number;
    isActive: boolean;
  };
  achievements: LabAchievement[];
}

export const LabExercisePlayer: React.FC<LabExercisePlayerProps> = ({
  exercise,
  userId,
  onComplete,
  onExit,
  className = "",
}) => {
  const [state, setState] = useState<PlayerState>({
    currentStepIndex: 0,
    session: null,
    stepResults: [],
    consoleState: {
      currentModule: "interact",
      currentView: "Questions",
      sessionData: {},
      queries: [],
      computerGroups: [],
      packages: [],
      actions: [],
    },
    isValidating: false,
    showHints: false,
    timer: {
      startTime: 0,
      elapsed: 0,
      isActive: false,
    },
    achievements: [],
  });

  // Initialize lab session
  useEffect(() => {
    const initializeSession = async () => {
      try {
        const session = await labProgressService.startLab(
          userId,
          exercise.id,
          exercise.title,
          exercise.domain,
          exercise.steps.length
        );
        setState((prev) => ({
          ...prev,
          session: exercise as any, // Temporary fix - store exercise instead of progress
          timer: {
            ...prev.timer,
            startTime: Date.now(),
            isActive: true,
          },
        }));
      } catch (error) {
        console.error("Failed to initialize lab session:", error);
      }
    };

    initializeSession();
  }, [userId, exercise.id]);

  // Timer effect
  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (state.timer.isActive) {
      interval = setInterval(() => {
        setState((prev) => ({
          ...prev,
          timer: {
            ...prev.timer,
            elapsed: Date.now() - prev.timer.startTime,
          },
        }));
      }, 1000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [state.timer.isActive]);

  const formatTime = (milliseconds: number): string => {
    const minutes = Math.floor(milliseconds / 60000);
    const seconds = Math.floor((milliseconds % 60000) / 1000);
    return `${minutes.toString().padStart(2, "0")}:${seconds.toString().padStart(2, "0")}`;
  };

  const currentStep = exercise.steps[state.currentStepIndex];
  const isLastStep = state.currentStepIndex === exercise.steps.length - 1;
  const progress = ((state.currentStepIndex + 1) / exercise.steps.length) * 100;

  // Handle console state updates
  const handleConsoleStateChange = useCallback((newState: ConsoleState) => {
    setState((prev) => ({ ...prev, consoleState: newState }));
  }, []);

  // Validate current step
  const handleValidateStep = async () => {
    if (!currentStep || !state.session) return;

    setState((prev) => ({ ...prev, isValidating: true }));

    try {
      await labProgressService.completeStep(
        state.session.labId,
        state.currentStepIndex + 1, // stepNumber (1-based)
        currentStep.title,
        1, // validationAttempts
        state.showHints, // hintUsed
        JSON.stringify(state.consoleState) // userInput
      );

      // Create a mock step result for UI purposes
      const stepResult: ValidationResult = {
        success: true, // Assume passed for now
        score: 100,
        feedback: "Step completed successfully",
        criteria: [],
        suggestions: [],
      };

      const newStepResults = [...state.stepResults, stepResult];

      setState((prev) => ({
        ...prev,
        stepResults: newStepResults,
        isValidating: false,
      }));

      // Check for achievements
      checkAchievements(stepResult, newStepResults);

      if (stepResult.success) {
        // Auto-advance to next step after a brief delay
        setTimeout(() => {
          if (!isLastStep) {
            nextStep();
          } else {
            completeExercise(newStepResults);
          }
        }, 1500);
      }
    } catch (error) {
      console.error("Failed to validate step:", error);
      setState((prev) => ({ ...prev, isValidating: false }));
    }
  };

  // Check for achievements
  const checkAchievements = async (
    stepResult: ValidationResult,
    allResults: ValidationResult[]
  ) => {
    const newAchievements: LabAchievement[] = [];

    // Perfect step achievement
    if (stepResult.score === 100) {
      newAchievements.push({
        id: `perfect-${currentStep.id}`,
        title: "Perfect Execution",
        description: "Completed step with 100% accuracy",
        type: "performance",
        criteria: {
          type: "score",
          threshold: 100,
          comparison: "equal",
        },
        reward: {
          points: 100,
          badge: "Perfect Execution Badge",
          title: "Perfect Execution",
        },
        rarity: "rare",
      });
    }

    // Speed achievements
    const expectedTime = (currentStep.timeLimit || 300) * 1000; // Convert seconds to milliseconds
    const timeSpent = state.timer.elapsed; // Use timer elapsed time
    if (timeSpent < expectedTime * 0.5) {
      newAchievements.push({
        id: `speed-${currentStep.id}`,
        title: "Speed Demon",
        description: "Completed step in record time",
        type: "efficiency",
        criteria: {
          type: "time",
          threshold: expectedTime * 0.5,
          comparison: "less",
        },
        reward: {
          points: 50,
          badge: "Speed Demon Badge",
          title: "Speed Demon",
        },
        rarity: "uncommon",
      });
    }

    // No hints achievement
    if (!state.showHints && stepResult.score >= 90) {
      newAchievements.push({
        id: `no-hints-${currentStep.id}`,
        title: "Independent Learner",
        description: "Completed step without using hints",
        type: "mastery",
        criteria: {
          type: "hints",
          threshold: 0,
          comparison: "equal",
        },
        reward: {
          points: 75,
          badge: "Independent Learner Badge",
          title: "Independent Learner",
        },
        rarity: "common",
      });
    }

    if (newAchievements.length > 0) {
      setState((prev) => ({
        ...prev,
        achievements: [...prev.achievements, ...newAchievements],
      }));

      // Save achievements to database (commented out - method not available)
      // for (const achievement of newAchievements) {
      //   await labProgressService.recordAchievement(userId, achievement);
      // }
    }
  };

  // Navigate to next step
  const nextStep = () => {
    if (state.currentStepIndex < exercise.steps.length - 1) {
      setState((prev) => ({
        ...prev,
        currentStepIndex: prev.currentStepIndex + 1,
        showHints: false,
      }));
    }
  };

  // Navigate to previous step
  const previousStep = () => {
    if (state.currentStepIndex > 0) {
      setState((prev) => ({
        ...prev,
        currentStepIndex: prev.currentStepIndex - 1,
      }));
    }
  };

  // Complete entire exercise
  const completeExercise = async (results: ValidationResult[]) => {
    if (!state.session) return;

    try {
      await labProgressService.completeLab(
        state.session.labId,
        Math.round(
          (state.stepResults.filter((r) => r.success).length / state.stepResults.length) * 100
        ),
        Math.round(state.timer.elapsed / 1000)
      );

      setState((prev) => ({
        ...prev,
        timer: { ...prev.timer, isActive: false },
      }));

      onComplete?.(results);
    } catch (error) {
      console.error("Failed to complete exercise:", error);
    }
  };

  // Reset exercise
  const resetExercise = () => {
    setState((prev) => ({
      ...prev,
      currentStepIndex: 0,
      stepResults: [],
      consoleState: {
        currentModule: "interact",
        currentView: "Questions",
        sessionData: {},
        queries: [],
        computerGroups: [],
        packages: [],
        actions: [],
      },
      showHints: false,
      timer: {
        startTime: Date.now(),
        elapsed: 0,
        isActive: true,
      },
    }));
  };

  // Toggle hints
  const toggleHints = () => {
    setState((prev) => ({ ...prev, showHints: !prev.showHints }));
  };

  // Pause/resume timer
  const toggleTimer = () => {
    setState((prev) => ({
      ...prev,
      timer: {
        ...prev.timer,
        isActive: !prev.timer.isActive,
        startTime: prev.timer.isActive ? 0 : Date.now() - prev.timer.elapsed,
      },
    }));
  };

  if (!currentStep) {
    return (
      <Card className="mx-auto w-full max-w-4xl">
        <CardContent className="p-8 text-center">
          <div className="text-muted-foreground">Loading exercise...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className={`mx-auto w-full max-w-7xl space-y-6 ${className}`}>
      {/* Header with progress and controls */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="space-y-2">
              <CardTitle className="text-xl">{exercise.title}</CardTitle>
              <div className="flex items-center gap-4">
                <Badge variant="outline">
                  <Target className="mr-1 h-3 w-3" />
                  {exercise.domain}
                </Badge>
                <Badge variant="outline">
                  <Clock className="mr-1 h-3 w-3" />
                  {formatTime(state.timer.elapsed)}
                </Badge>
                <Badge variant="outline">
                  Step {state.currentStepIndex + 1} of {exercise.steps.length}
                </Badge>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Button variant="outline" size="sm" onClick={toggleHints}>
                {state.showHints ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                {state.showHints ? "Hide Hints" : "Show Hints"}
              </Button>

              <Button variant="outline" size="sm" onClick={toggleTimer}>
                {state.timer.isActive ? (
                  <Pause className="h-4 w-4" />
                ) : (
                  <Play className="h-4 w-4" />
                )}
                {state.timer.isActive ? "Pause" : "Resume"}
              </Button>

              <Button variant="outline" size="sm" onClick={resetExercise}>
                <RotateCcw className="h-4 w-4" />
                Reset
              </Button>

              {onExit && (
                <Button variant="outline" size="sm" onClick={onExit}>
                  Exit
                </Button>
              )}
            </div>
          </div>

          <Progress value={progress} className="w-full" />
        </CardHeader>
      </Card>

      {/* Achievement notifications */}
      <AnimatePresence>
        {state.achievements.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="space-y-2"
          >
            {state.achievements.slice(-3).map((achievement) => (
              <Alert key={achievement.id} className="border-yellow-200 bg-yellow-50">
                <Award className="h-4 w-4 text-yellow-600" />
                <AlertDescription>
                  <strong>{achievement.title}</strong>: {achievement.description}
                </AlertDescription>
              </Alert>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Main content */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Instructions panel */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <BookOpen className="h-5 w-5" />
              Instructions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <h3 className="mb-2 text-lg font-medium">{currentStep.title}</h3>
              <p className="mb-4 text-muted-foreground">{currentStep.instruction}</p>

              <div className="space-y-2">
                <h4 className="font-medium">Steps:</h4>
                <ol className="list-inside list-decimal space-y-1 text-sm">
                  {[currentStep.instruction].map((instruction, index) => (
                    <li key={index} className="text-muted-foreground">
                      {instruction}
                    </li>
                  ))}
                </ol>
              </div>
            </div>

            {/* Hints */}
            {state.showHints && currentStep.hints && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                className="rounded-lg border border-blue-200 bg-blue-50 p-4"
              >
                <h4 className="mb-2 font-medium text-blue-900">💡 Hints:</h4>
                <ul className="list-inside list-disc space-y-1 text-sm text-blue-800">
                  {currentStep.hints.map((hint, index) => (
                    <li key={index}>{hint.content}</li>
                  ))}
                </ul>
              </motion.div>
            )}

            {/* Navigation and validation */}
            <div className="flex items-center justify-between border-t pt-4">
              <Button
                variant="outline"
                onClick={previousStep}
                disabled={state.currentStepIndex === 0}
              >
                <ChevronLeft className="mr-1 h-4 w-4" />
                Previous
              </Button>

              <Button
                onClick={handleValidateStep}
                disabled={state.isValidating}
                className="bg-green-600 hover:bg-green-700"
              >
                {state.isValidating ? (
                  <>
                    <div className="mr-2 h-4 w-4 animate-spin rounded-full border-b-2 border-white" />
                    Validating...
                  </>
                ) : (
                  <>
                    <CheckCircle className="mr-2 h-4 w-4" />
                    Validate Step
                  </>
                )}
              </Button>

              <Button
                variant="outline"
                onClick={nextStep}
                disabled={isLastStep || !state.stepResults[state.currentStepIndex]?.success}
              >
                Next
                <ChevronRight className="ml-1 h-4 w-4" />
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Console simulator */}
        <Card>
          <CardHeader>
            <CardTitle>Tanium Console</CardTitle>
          </CardHeader>
          <CardContent>
            <ConsoleSimulator
              initialState={state.consoleState}
              onStateChange={handleConsoleStateChange}
              onAction={(action) => {
                console.log("Console action:", action);
              }}
            />
          </CardContent>
        </Card>
      </div>

      {/* Validation results */}
      {currentStep.validation && (
        <Card>
          <CardHeader>
            <CardTitle>Step Validation</CardTitle>
          </CardHeader>
          <CardContent>
            <CheckpointValidator
              step={currentStep}
              consoleState={state.consoleState}
              userActions={[]}
              onValidationCompleteAction={(result) => {
                console.log("Validation complete:", result);
              }}
              onHintRequestAction={() => {
                setState((prev) => ({ ...prev, showHints: true }));
              }}
            />
          </CardContent>
        </Card>
      )}

      {/* Step results summary */}
      {state.stepResults.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Progress Summary</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
              {state.stepResults.map((result, index) => (
                <div
                  key={index}
                  className={`rounded-lg border p-3 ${
                    result.success ? "border-green-200 bg-green-50" : "border-red-200 bg-red-50"
                  }`}
                >
                  <div className="mb-2 flex items-center justify-between">
                    <span className="text-sm font-medium">Step {index + 1}</span>
                    {result.success ? (
                      <CheckCircle className="h-4 w-4 text-green-600" />
                    ) : (
                      <XCircle className="h-4 w-4 text-red-600" />
                    )}
                  </div>
                  <div className="text-sm text-muted-foreground">Score: {result.score}%</div>
                  <div className="text-xs text-muted-foreground">
                    Time: {formatTime(state.timer.elapsed)}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

"use client";

import { useState, useEffect } from "react";
import { AppHeader } from "./app-header";
import { Sidebar } from "./sidebar";
import { BreadcrumbNav } from "./breadcrumb-nav";
import NavigationHelper from "@/components/navigation/NavigationHelper";
import BeginnerModeToggle from "@/components/navigation/BeginnerModeToggle";
import ConfidenceBuilder from "@/components/confidence/ConfidenceBuilder";

interface BeginnerLayoutProps {
  children: React.ReactNode;
}

export function BeginnerLayout({ children }: BeginnerLayoutProps) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isBeginnerMode, setIsBeginnerMode] = useState(true);
  const [currentConfidence, setCurrentConfidence] = useState<'building' | 'growing' | 'strong' | 'expert'>('building');
  const [studyProgress, setStudyProgress] = useState(0);
  const [showConfidenceBuilder, setShowConfidenceBuilder] = useState(false);

  // Initialize beginner mode and progress from localStorage
  useEffect(() => {
    const beginnerModeStored = localStorage.getItem('tanium-beginner-mode');
    const confidenceStored = localStorage.getItem('tanium-confidence-level');
    const progressStored = localStorage.getItem('tanium-study-progress');

    if (beginnerModeStored !== null) {
      setIsBeginnerMode(JSON.parse(beginnerModeStored));
    }

    if (confidenceStored) {
      setCurrentConfidence(confidenceStored as 'building' | 'growing' | 'strong' | 'expert');
    }

    if (progressStored) {
      setStudyProgress(parseInt(progressStored, 10));
    }

    // Show confidence builder for new beginners
    const isFirstVisit = localStorage.getItem('tanium-first-visit') === null;
    if (isFirstVisit) {
      setShowConfidenceBuilder(true);
      localStorage.setItem('tanium-first-visit', 'false');
    }
  }, []);

  // Handle beginner mode toggle
  const handleBeginnerModeChange = (enabled: boolean) => {
    setIsBeginnerMode(enabled);
    localStorage.setItem('tanium-beginner-mode', JSON.stringify(enabled));
  };

  // Handle confidence boost
  const handleBoostConfidence = () => {
    const confidenceLevels: Array<'building' | 'growing' | 'strong' | 'expert'> = 
      ['building', 'growing', 'strong', 'expert'];
    const currentIndex = confidenceLevels.indexOf(currentConfidence);
    if (currentIndex < confidenceLevels.length - 1) {
      const newLevel = confidenceLevels[currentIndex + 1];
      setCurrentConfidence(newLevel);
      localStorage.setItem('tanium-confidence-level', newLevel);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-tanium-dark via-tanium-secondary to-tanium-primary relative">
      {/* Beginner Mode Toggle - Fixed Position */}
      <div className="fixed top-20 right-4 z-40">
        <BeginnerModeToggle 
          defaultEnabled={isBeginnerMode}
          onToggle={handleBeginnerModeChange}
        />
      </div>

      {/* Header */}
      <AppHeader onMenuClick={() => setSidebarOpen(true)} currentScore={78} studyStreak={7} />

      {/* Sidebar */}
      <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />

      {/* Confidence Builder - Only show in beginner mode */}
      {isBeginnerMode && (
        <div className="fixed top-32 right-4 z-30 max-w-sm">
          <ConfidenceBuilder
            currentConfidence={currentConfidence}
            studyProgress={studyProgress}
            showEncouragement={showConfidenceBuilder}
            onBoostConfidence={handleBoostConfidence}
          />
        </div>
      )}

      {/* Navigation Helper - Only show in beginner mode */}
      {isBeginnerMode && (
        <NavigationHelper />
      )}

      {/* Main content */}
      <main
        id="main-content"
        className={`min-h-[calc(100vh-4rem)] transition-all duration-300 ${
          isBeginnerMode ? 'md:ml-64 mr-4' : 'md:ml-64'
        }`}
        tabIndex={-1}
        role="main"
        aria-label="Main content"
      >
        <div className="container mx-auto px-4 py-8">
          {/* Beginner-friendly breadcrumb with extra context */}
          <BreadcrumbNav 
            className={`mb-6 ${isBeginnerMode ? 'bg-white/5 backdrop-blur-sm rounded-lg px-4 py-2 border border-white/10' : ''}`}
          />

          {/* Beginner Welcome Message */}
          {isBeginnerMode && studyProgress < 10 && (
            <div className="mb-6 rounded-lg bg-gradient-to-r from-blue-500/20 to-cyan-500/20 border border-blue-500/30 p-6">
              <div className="flex items-start space-x-4">
                <div className="text-2xl">👋</div>
                <div>
                  <h3 className="text-lg font-semibold text-white mb-2">
                    Welcome to Your Tanium Journey!
                  </h3>
                  <p className="text-blue-100 mb-4">
                    You're about to master one of the most powerful endpoint management platforms in the world. 
                    Don't worry if you're completely new to Tanium - we'll guide you every step of the way.
                  </p>
                  <div className="flex flex-wrap gap-2">
                    <div className="px-3 py-1 bg-white/10 rounded-full text-xs text-white">
                      🎯 No prior experience required
                    </div>
                    <div className="px-3 py-1 bg-white/10 rounded-full text-xs text-white">
                      📚 Step-by-step learning
                    </div>
                    <div className="px-3 py-1 bg-white/10 rounded-full text-xs text-white">
                      🏆 Certification-focused
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {children}
        </div>
      </main>
    </div>
  );
}

