export default function LearningProgressTracker() {
  const [moduleProgress, setModuleProgress] = useState<ModuleProgress[]>([]);
  const [learningStats, setLearningStats] = useState<LearningStats>({
    totalModules: 6,
    completedModules: 0,
    totalExercises: 50,
    completedExercises: 0,
    totalTimeSpent: 0,
    currentStreak: 0,
