                    <Trophy className="w-8 h-8 text-purple-500" />
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Next Steps */}
            <Card className="bg-blue-50 border-blue-200">
              <CardHeader className="pb-3">
                <h3 className="font-semibold flex items-center gap-2">
                  <Flag className="w-5 h-5 text-blue-600" />
