'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ChevronLeft,
  ChevronRight,
  Clock,
  Target,
  CheckCircle,
  BookOpen,
  Play,
  Pause,
  RotateCcw,
  Award
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useLearningProgress } from './LearningProgressProvider';

interface StudyModuleWrapperProps {
  children: React.ReactNode;
  moduleId: string;
  domainId: string;
  title: string;
  description?: string;
  estimatedTime?: number;
  objectives?: string[];
  prerequisites?: string[];
  className?: string;
}

export function StudyModuleWrapper({
  children,
  moduleId,
  domainId,
  title,
  description,
  estimatedTime = 15,
  objectives = [],
  prerequisites = [],
  className
}: StudyModuleWrapperProps) {
  const router = useRouter();
  const {
    updateModuleProgress,
    getModuleProgress,
    navigateToPreviousModule,
    navigateToNextModule,
    domains,
    currentDomain,
    currentModule
  } = useLearningProgress();

  const [timeSpent, setTimeSpent] = useState(0);
  const [isActive, setIsActive] = useState(false);
  const [moduleStartTime, setModuleStartTime] = useState<Date | null>(null);

  // Get current module and navigation info - with safety checks
  const domain = domains?.find(d => d.id === domainId);
  const currentModuleIndex = domain?.modules?.findIndex(m => m.id === moduleId) ?? -1;
  const previousModule = currentModuleIndex > 0 ? domain?.modules?.[currentModuleIndex - 1] : null;
  const nextModule = currentModuleIndex < (domain?.modules?.length ?? 0) - 1 ? domain?.modules?.[currentModuleIndex + 1] : null;

  const moduleProgress = getModuleProgress(domainId, moduleId);

  // Timer logic
  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (isActive && moduleStartTime) {
      interval = setInterval(() => {
        const now = new Date();
        const elapsed = Math.floor((now.getTime() - moduleStartTime.getTime()) / 1000 / 60);
        setTimeSpent(elapsed);
      }, 1000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isActive, moduleStartTime]);

  // Auto-start timer when component mounts
  useEffect(() => {
    setModuleStartTime(new Date());
    setIsActive(true);

    return () => {
      // Update progress when leaving module
      if (timeSpent > 0) {
        updateModuleProgress(domainId, moduleId, {
          timeSpent: Math.max(timeSpent, moduleProgress.timeSpent || 0),
          lastAccessed: new Date().toISOString()
        });
      }
    };
  }, []);

  const handleStartModule = () => {
    setModuleStartTime(new Date());
    setIsActive(true);
    updateModuleProgress(domainId, moduleId, {
      status: 'in_progress',
      startedAt: new Date().toISOString()
    });
  };

  const handleCompleteModule = () => {
    setIsActive(false);
    updateModuleProgress(domainId, moduleId, {
      status: 'completed',
      completedAt: new Date().toISOString(),
      timeSpent: timeSpent,
      score: 100 // Default completion score
    });
  };

  const handleResetProgress = () => {
    setTimeSpent(0);
    setModuleStartTime(new Date());
    setIsActive(true);
    updateModuleProgress(domainId, moduleId, {
      status: 'not_started',
      timeSpent: 0,
      startedAt: undefined,
      completedAt: undefined,
      score: undefined
    });
  };

  const handlePreviousModule = () => {
    if (previousModule) {
      navigateToPreviousModule();
      router.push(`/learning/${domainId}/${previousModule.id}`);
    }
  };

  const handleNextModule = () => {
    if (nextModule) {
      navigateToNextModule();
      router.push(`/learning/${domainId}/${nextModule.id}`);
    } else {
      // Navigate back to domain overview if this is the last module
      router.push(`/learning/${domainId}`);
    }
  };

  const progressPercentage = moduleProgress.status === 'completed' ? 100 :
    moduleProgress.status === 'in_progress' ? Math.min((timeSpent / estimatedTime) * 100, 95) : 0;

  return (
    <div className={cn("space-y-6", className)}>
      {/* Module Header */}
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-black/40 backdrop-blur-sm rounded-xl border border-cyan-500/30 p-6"
      >
        <div className="flex items-start justify-between mb-4">
          <div className="flex-1">
            <div className="flex items-center gap-3 mb-2">
              <div className="p-2 bg-cyan-500/20 rounded-lg">
                <BookOpen className="h-5 w-5 text-cyan-400" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-white">{title}</h1>
                <div className="text-sm text-gray-400">
                  Module {currentModuleIndex + 1} of {domain?.modules.length}
                </div>
              </div>
            </div>
            {description && (
              <p className="text-gray-300 mb-4">{description}</p>
            )}
          </div>

          {/* Module Status */}
          <div className="flex items-center gap-4">
            <div className="text-right">
              <div className="flex items-center gap-2 text-sm">
                <Clock className="h-4 w-4 text-cyan-400" />
                <span className="text-gray-300">
                  {timeSpent}min / {estimatedTime}min
                </span>
              </div>
              <div className="text-xs text-gray-400 mt-1">
                Status: <span className={cn(
                  moduleProgress.status === 'completed' && 'text-green-400',
                  moduleProgress.status === 'in_progress' && 'text-blue-400',
                  moduleProgress.status === 'not_started' && 'text-gray-400'
                )}>
                  {moduleProgress.status === 'completed' ? 'Completed' :
                   moduleProgress.status === 'in_progress' ? 'In Progress' : 'Not Started'}
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Progress Bar */}
        <div className="w-full bg-gray-700 rounded-full h-2 mb-4">
          <motion.div
            className="bg-gradient-to-r from-cyan-500 to-blue-500 h-2 rounded-full"
            initial={{ width: 0 }}
            animate={{ width: `${progressPercentage}%` }}
            transition={{ duration: 0.5 }}
          />
        </div>

        {/* Learning Objectives */}
        {objectives.length > 0 && (
          <div className="grid md:grid-cols-2 gap-4 mb-4">
            <div>
              <h3 className="text-sm font-medium text-white mb-2 flex items-center gap-2">
                <Target className="h-4 w-4 text-cyan-400" />
                Learning Objectives
              </h3>
              <ul className="space-y-1">
                {objectives.map((objective, index) => (
                  <li key={index} className="text-sm text-gray-300 flex items-start gap-2">
                    <CheckCircle className="h-3 w-3 text-green-400 mt-0.5 flex-shrink-0" />
                    {objective}
                  </li>
                ))}
              </ul>
            </div>

            {/* Prerequisites */}
            {prerequisites.length > 0 && (
              <div>
                <h3 className="text-sm font-medium text-white mb-2">Prerequisites</h3>
                <ul className="space-y-1">
                  {prerequisites.map((prereq, index) => (
                    <li key={index} className="text-sm text-gray-400">
                      • {prereq}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}

        {/* Module Controls */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            {moduleProgress.status === 'not_started' && (
              <button
                onClick={handleStartModule}
                className="inline-flex items-center gap-2 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 text-white rounded-lg transition-colors"
              >
                <Play className="h-4 w-4" />
                Start Module
              </button>
            )}

            {moduleProgress.status === 'in_progress' && (
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setIsActive(!isActive)}
                  className="inline-flex items-center gap-2 px-3 py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-lg transition-colors"
                >
                  {isActive ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
                  {isActive ? 'Pause' : 'Resume'}
                </button>
                <button
                  onClick={handleCompleteModule}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-green-500 hover:bg-green-600 text-white rounded-lg transition-colors"
                >
                  <CheckCircle className="h-4 w-4" />
                  Complete Module
                </button>
              </div>
            )}

            {moduleProgress.status === 'completed' && (
              <div className="flex items-center gap-2">
                <div className="inline-flex items-center gap-2 px-3 py-2 bg-green-500/20 text-green-400 rounded-lg">
                  <Award className="h-4 w-4" />
                  Completed
                </div>
                <button
                  onClick={handleResetProgress}
                  className="inline-flex items-center gap-2 px-3 py-2 bg-gray-600 hover:bg-gray-700 text-white rounded-lg transition-colors"
                >
                  <RotateCcw className="h-4 w-4" />
                  Reset
                </button>
              </div>
            )}
          </div>

          {/* Navigation */}
          <div className="flex items-center gap-2">
            <button
              onClick={handlePreviousModule}
              disabled={!previousModule}
              className={cn(
                "inline-flex items-center gap-2 px-3 py-2 rounded-lg transition-colors",
                previousModule
                  ? "bg-gray-600 hover:bg-gray-700 text-white"
                  : "bg-gray-800 text-gray-500 cursor-not-allowed"
              )}
            >
              <ChevronLeft className="h-4 w-4" />
              Previous
            </button>

            <button
              onClick={handleNextModule}
              disabled={!nextModule && moduleProgress.status !== 'completed'}
              className={cn(
                "inline-flex items-center gap-2 px-3 py-2 rounded-lg transition-colors",
                (nextModule || moduleProgress.status === 'completed')
                  ? "bg-cyan-500 hover:bg-cyan-600 text-white"
                  : "bg-gray-800 text-gray-500 cursor-not-allowed"
              )}
            >
              {nextModule ? 'Next' : 'Finish'}
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      </motion.div>

      {/* Module Content */}
      <AnimatePresence mode="wait">
        <motion.div
          key={moduleId}
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -20 }}
          transition={{ duration: 0.3 }}
          className="bg-black/40 backdrop-blur-sm rounded-xl border border-cyan-500/30 p-6"
        >
          {children}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { CheckCircle2, FileText, Target, Lightbulb, ChevronRight, Trophy } from 'lucide-react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Checkbox } from '@/components/ui/checkbox';
import { Progress } from '@/components/ui/progress';

interface ProjectTask {
  id: string;
  title: string;
  description: string;
  hints?: string[];
  validation?: string;
}

interface MiniProjectProps {
  title: string;
  description: string;
  estimatedTime: string;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  objectives: string[];
  tasks: ProjectTask[];
  successCriteria: string[];
}

export default function MiniProject({
  title,
  description,
  estimatedTime,
  difficulty,
  objectives,
  tasks,
  successCriteria
}: MiniProjectProps) {
  const [completedTasks, setCompletedTasks] = useState<Set<string>>(new Set());
  const [showHints, setShowHints] = useState<Set<string>>(new Set());
  const [projectComplete, setProjectComplete] = useState(false);

  const toggleTask = (taskId: string) => {
    const newCompleted = new Set(completedTasks);
    if (newCompleted.has(taskId)) {
      newCompleted.delete(taskId);
    } else {
      newCompleted.add(taskId);
    }
    setCompletedTasks(newCompleted);

    // Check if all tasks are complete
    if (newCompleted.size === tasks.length) {
      setProjectComplete(true);
      // Save to localStorage
      const progress = JSON.parse(localStorage.getItem('miniProjectProgress') || '{}');
      progress[title] = {
        completed: true,
        timestamp: new Date().toISOString()
      };
      localStorage.setItem('miniProjectProgress', JSON.stringify(progress));
    } else {
      setProjectComplete(false);
    }
  };

  const toggleHint = (taskId: string) => {
    const newHints = new Set(showHints);
    if (newHints.has(taskId)) {
      newHints.delete(taskId);
    } else {
      newHints.add(taskId);
    }
    setShowHints(newHints);
  };

  const progressPercentage = (completedTasks.size / tasks.length) * 100;

  const getDifficultyColor = () => {
    switch(difficulty) {
      case 'beginner': return 'text-green-600 bg-green-50';
      case 'intermediate': return 'text-yellow-600 bg-yellow-50';
      case 'advanced': return 'text-red-600 bg-red-50';
    }
  };

  return (
    <Card className="my-8 border-2 border-purple-200">
      <CardHeader className="bg-gradient-to-r from-purple-50 to-indigo-50">
        <div className="flex items-start justify-between">
          <div>
            <CardTitle className="flex items-center gap-2 text-xl">
              <Target className="w-6 h-6 text-purple-600" />
              {title}
            </CardTitle>
            <CardDescription className="mt-2">{description}</CardDescription>
          </div>
          <div className="flex flex-col items-end gap-2">
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${getDifficultyColor()}`}>
              {difficulty.charAt(0).toUpperCase() + difficulty.slice(1)}
            </span>
            <span className="text-sm text-gray-500">⏱️ {estimatedTime}</span>
          </div>
        </div>
      </CardHeader>

      <CardContent className="pt-6">
        <Tabs defaultValue="objectives" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="objectives">Objectives</TabsTrigger>
            <TabsTrigger value="tasks">Tasks</TabsTrigger>
            <TabsTrigger value="criteria">Success Criteria</TabsTrigger>
          </TabsList>

          <TabsContent value="objectives" className="space-y-2 mt-4">
            <h3 className="font-semibold mb-3">Learning Objectives</h3>
            {objectives.map((objective, index) => (
              <div key={index} className="flex items-start gap-2">
                <ChevronRight className="w-4 h-4 text-purple-600 mt-0.5" />
                <span className="text-sm">{objective}</span>
              </div>
            ))}
          </TabsContent>

          <TabsContent value="tasks" className="mt-4">
            <div className="space-y-4">
              <div className="mb-4">
                <Progress value={progressPercentage} className="h-2" />
                <p className="text-sm text-gray-500 mt-1">
                  {completedTasks.size} of {tasks.length} tasks completed
                </p>
              </div>

              {tasks.map((task) => (
                <div
                  key={task.id}
                  className={`border rounded-lg p-4 transition-all ${
                    completedTasks.has(task.id) ? 'bg-green-50 border-green-300' : 'bg-white'
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <Checkbox
                      id={task.id}
                      checked={completedTasks.has(task.id)}
                      onCheckedChange={() => toggleTask(task.id)}
                      className="mt-1"
                    />
                    <div className="flex-1">
                      <label
                        htmlFor={task.id}
                        className={`font-medium cursor-pointer ${
                          completedTasks.has(task.id) ? 'line-through text-gray-500' : ''
                        }`}
                      >
                        {task.title}
                      </label>
                      <p className="text-sm text-gray-600 mt-1">{task.description}</p>

                      {task.validation && (
                        <div className="mt-2 p-2 bg-blue-50 rounded text-sm">
                          <strong>Validation:</strong> {task.validation}
                        </div>
                      )}

                      {task.hints && task.hints.length > 0 && (
                        <div className="mt-2">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => toggleHint(task.id)}
                            className="text-xs"
                          >
                            <Lightbulb className="w-3 h-3 mr-1" />
                            {showHints.has(task.id) ? 'Hide' : 'Show'} Hints
                          </Button>

                          {showHints.has(task.id) && (
                            <div className="mt-2 p-3 bg-yellow-50 rounded-lg">
                              {task.hints.map((hint, index) => (
                                <p key={index} className="text-sm text-yellow-800">
                                  💡 {hint}
                                </p>
                              ))}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </TabsContent>

          <TabsContent value="criteria" className="space-y-2 mt-4">
            <h3 className="font-semibold mb-3">Success Criteria</h3>
            {successCriteria.map((criterion, index) => (
              <div key={index} className="flex items-start gap-2">
                <CheckCircle2 className="w-4 h-4 text-green-600 mt-0.5" />
                <span className="text-sm">{criterion}</span>
              </div>
            ))}
          </TabsContent>
        </Tabs>

        {projectComplete && (
          <Alert className="mt-6 border-green-500 bg-green-50">
            <Trophy className="w-5 h-5 text-green-600" />
            <AlertDescription className="text-green-700">
              <strong>Congratulations!</strong> You've completed all tasks in this mini-project.
              You're ready to move on to the next module!
            </AlertDescription>
          </Alert>
        )}
      </CardContent>

      <CardFooter className="bg-gray-50">
        <div className="flex items-center gap-2 text-sm text-gray-600">
          <FileText className="w-4 h-4" />
          <span>Complete all tasks to demonstrate mastery of the module concepts</span>
        </div>
      </CardFooter>
    </Card>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import {
  CheckCircle2,
  XCircle,
  ChevronRight,
  Lock,
  Unlock,
  Trophy,
  AlertCircle,
  RotateCcw
} from 'lucide-react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

interface Skill {
  id: string;
  name: string;
  description: string;
  tested: boolean;
  passed: boolean;
}

interface Challenge {
  question: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  skillId: string;
}

interface ModuleTransitionProps {
  currentModuleId: string;
  currentModuleTitle: string;
  nextModuleId: string;
  nextModuleTitle: string;
  requiredSkills: Skill[];
  challenges: Challenge[];
  minimumScore?: number; // Default 80%
}

export default function ModuleTransition({
  currentModuleId,
  currentModuleTitle,
  nextModuleId,
  nextModuleTitle,
  requiredSkills,
  challenges,
  minimumScore = 0.8
}: ModuleTransitionProps) {
  const [skills, setSkills] = useState<Skill[]>(requiredSkills);
  const [currentChallengeIndex, setCurrentChallengeIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [score, setScore] = useState(0);
  const [completed, setCompleted] = useState(false);
  const [unlocked, setUnlocked] = useState(false);
  const [attempts, setAttempts] = useState(0);

  useEffect(() => {
    // Load progress from localStorage
    const savedProgress = localStorage.getItem(`transition-${currentModuleId}-${nextModuleId}`);
    if (savedProgress) {
      const progress = JSON.parse(savedProgress);
      setSkills(progress.skills || requiredSkills);
      setScore(progress.score || 0);
      setCompleted(progress.completed || false);
      setUnlocked(progress.unlocked || false);
      setAttempts(progress.attempts || 0);
    }
  }, [currentModuleId, nextModuleId, requiredSkills]);

  const saveProgress = () => {
    const progress = {
      skills,
      score,
      completed,
      unlocked,
      attempts,
      timestamp: new Date().toISOString()
    };
    localStorage.setItem(`transition-${currentModuleId}-${nextModuleId}`, JSON.stringify(progress));
  };

  const handleAnswerSelect = (answerIndex: number) => {
    if (showExplanation) return;
    setSelectedAnswer(answerIndex);
  };

  const handleSubmitAnswer = () => {
    if (selectedAnswer === null) return;

    const currentChallenge = challenges[currentChallengeIndex];
    const isCorrect = selectedAnswer === currentChallenge.correctAnswer;

    // Update skill status
    const updatedSkills = skills.map(skill => {
      if (skill.id === currentChallenge.skillId) {
        return {
          ...skill,
          tested: true,
          passed: isCorrect || skill.passed // Keep passed if already passed
        };
      }
      return skill;
    });
    setSkills(updatedSkills);

    if (isCorrect) {
      setScore(score + 1);
    }

    setShowExplanation(true);
    saveProgress();
  };

  const handleNextChallenge = () => {
    if (currentChallengeIndex < challenges.length - 1) {
      setCurrentChallengeIndex(currentChallengeIndex + 1);
      setSelectedAnswer(null);
      setShowExplanation(false);
    } else {
      // All challenges completed
      const finalScore = score / challenges.length;
      const passed = finalScore >= minimumScore;

      setCompleted(true);
      setUnlocked(passed);
      setAttempts(attempts + 1);
      saveProgress();
    }
  };

  const handleRetry = () => {
    setSkills(requiredSkills.map(s => ({ ...s, tested: false, passed: false })));
    setCurrentChallengeIndex(0);
    setSelectedAnswer(null);
    setShowExplanation(false);
    setScore(0);
    setCompleted(false);
    setUnlocked(false);
    setAttempts(attempts + 1);
    saveProgress();
  };

  const currentChallenge = challenges[currentChallengeIndex];
  const progressPercentage = ((currentChallengeIndex + (showExplanation ? 1 : 0)) / challenges.length) * 100;
  const scorePercentage = (score / challenges.length) * 100;
  const passedSkillsCount = skills.filter(s => s.passed).length;

  if (completed) {
    return (
      <Card className="my-8 border-2 border-blue-200">
        <CardHeader className="bg-gradient-to-r from-blue-50 to-indigo-50">
          <CardTitle className="flex items-center gap-2 text-xl">
            {unlocked ? (
              <>
                <Trophy className="w-6 h-6 text-yellow-500" />
                Module Transition Complete!
              </>
            ) : (
              <>
                <AlertCircle className="w-6 h-6 text-orange-500" />
                Additional Practice Needed
              </>
            )}
          </CardTitle>
          <CardDescription>
            {currentModuleTitle} → {nextModuleTitle}
          </CardDescription>
        </CardHeader>

        <CardContent className="pt-6 space-y-6">
          {/* Final Score */}
          <div className="text-center space-y-2">
            <div className="text-4xl font-bold">
              {Math.round(scorePercentage)}%
            </div>
            <div className="text-sm text-gray-600">
              {score} out of {challenges.length} correct
            </div>
            <div className="text-sm">
              Required: {Math.round(minimumScore * 100)}%
            </div>
          </div>

          {/* Skills Summary */}
          <div className="space-y-3">
            <h3 className="font-semibold">Skills Assessment:</h3>
            {skills.map((skill) => (
              <div key={skill.id} className="flex items-center justify-between p-2 rounded-lg bg-gray-50">
                <span className="text-sm">{skill.name}</span>
                {skill.passed ? (
                  <CheckCircle2 className="w-4 h-4 text-green-600" />
                ) : (
                  <XCircle className="w-4 h-4 text-red-600" />
                )}
              </div>
            ))}
          </div>

          {/* Action Buttons */}
          <div className="space-y-3">
            {unlocked ? (
              <Button
                className="w-full bg-green-600 hover:bg-green-700"
                onClick={() => window.location.href = `/modules/${nextModuleId}`}
              >
                <Unlock className="w-4 h-4 mr-2" />
                Continue to {nextModuleTitle}
              </Button>
            ) : (
              <>
                <Alert className="border-orange-200 bg-orange-50">
                  <AlertCircle className="w-4 h-4 text-orange-600" />
                  <AlertDescription className="text-orange-700">
                    You need {Math.round(minimumScore * 100)}% to unlock the next module.
                    Review the skills you missed and try again.
                  </AlertDescription>
                </Alert>
                <Button
                  onClick={handleRetry}
                  className="w-full"
                  variant="outline"
                >
                  <RotateCcw className="w-4 h-4 mr-2" />
                  Retry Assessment (Attempt {attempts + 1})
                </Button>
              </>
            )}
          </div>

          {/* Attempt History */}
          {attempts > 1 && (
            <div className="text-center text-sm text-gray-500">
              Attempts made: {attempts}
            </div>
          )}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="my-8 border-2 border-blue-200">
      <CardHeader className="bg-gradient-to-r from-blue-50 to-indigo-50">
        <div className="flex items-start justify-between">
          <div>
            <CardTitle className="flex items-center gap-2 text-xl">
              <Lock className="w-6 h-6 text-blue-600" />
              Module Transition Checkpoint
            </CardTitle>
            <CardDescription className="mt-2">
              Complete this assessment to unlock: {nextModuleTitle}
            </CardDescription>
          </div>
          <Badge variant="outline" className="text-sm">
            {currentChallengeIndex + 1} / {challenges.length}
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="pt-6">
        <Tabs defaultValue="assessment" className="w-full">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="assessment">Assessment</TabsTrigger>
            <TabsTrigger value="skills">Required Skills</TabsTrigger>
          </TabsList>

          <TabsContent value="assessment" className="space-y-4 mt-4">
            {/* Progress Bar */}
            <div>
              <div className="flex justify-between text-sm text-gray-600 mb-2">
                <span>Progress</span>
                <span>{Math.round(progressPercentage)}%</span>
              </div>
              <Progress value={progressPercentage} className="h-2" />
            </div>

            {/* Current Challenge */}
            <div className="space-y-4">
              <div className="p-4 bg-gray-50 rounded-lg">
                <p className="font-medium text-lg">{currentChallenge.question}</p>
              </div>

              {/* Answer Options */}
              <div className="space-y-2">
                {currentChallenge.options.map((option, index) => (
                  <button
                    key={index}
                    onClick={() => handleAnswerSelect(index)}
                    disabled={showExplanation}
                    className={`w-full text-left p-4 rounded-lg border-2 transition-all ${
                      selectedAnswer === index
                        ? showExplanation
                          ? index === currentChallenge.correctAnswer
                            ? 'border-green-500 bg-green-50'
                            : 'border-red-500 bg-red-50'
                          : 'border-blue-500 bg-blue-50'
                        : showExplanation && index === currentChallenge.correctAnswer
                        ? 'border-green-500 bg-green-50'
                        : 'border-gray-200 hover:bg-gray-50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <span>{option}</span>
                      {showExplanation && (
                        <>
                          {index === currentChallenge.correctAnswer && (
                            <CheckCircle2 className="w-5 h-5 text-green-600" />
                          )}
                          {index === selectedAnswer && index !== currentChallenge.correctAnswer && (
                            <XCircle className="w-5 h-5 text-red-600" />
                          )}
                        </>
                      )}
                    </div>
                  </button>
                ))}
              </div>

              {/* Explanation */}
              {showExplanation && (
                <Alert className="border-blue-200 bg-blue-50">
                  <AlertCircle className="w-4 h-4 text-blue-600" />
                  <AlertDescription className="text-blue-900">
                    <strong>Explanation:</strong> {currentChallenge.explanation}
                  </AlertDescription>
                </Alert>
              )}

              {/* Action Button */}
              {!showExplanation ? (
                <Button
                  onClick={handleSubmitAnswer}
                  disabled={selectedAnswer === null}
                  className="w-full"
                >
                  Submit Answer
                </Button>
              ) : (
                <Button
                  onClick={handleNextChallenge}
                  className="w-full"
                >
                  {currentChallengeIndex < challenges.length - 1 ? (
                    <>
                      Next Question
                      <ChevronRight className="w-4 h-4 ml-2" />
                    </>
                  ) : (
                    <>
                      View Results
                      <Trophy className="w-4 h-4 ml-2" />
                    </>
                  )}
                </Button>
              )}
            </div>

            {/* Current Score */}
            <div className="text-center text-sm text-gray-600">
              Current Score: {score} / {currentChallengeIndex + (showExplanation ? 1 : 0)}
            </div>
          </TabsContent>

          <TabsContent value="skills" className="mt-4">
            <div className="space-y-3">
              <p className="text-sm text-gray-600 mb-4">
                Master these skills from {currentModuleTitle} to proceed:
              </p>
              {skills.map((skill) => (
                <div
                  key={skill.id}
                  className={`p-3 rounded-lg border ${
                    skill.tested
                      ? skill.passed
                        ? 'bg-green-50 border-green-300'
                        : 'bg-red-50 border-red-300'
                      : 'bg-white border-gray-200'
                  }`}
                >
                  <div className="flex items-start justify-between">
                    <div>
                      <h4 className="font-medium">{skill.name}</h4>
                      <p className="text-sm text-gray-600 mt-1">{skill.description}</p>
                    </div>
                    <div className="mt-1">
                      {skill.tested ? (
                        skill.passed ? (
                          <CheckCircle2 className="w-5 h-5 text-green-600" />
                        ) : (
                          <XCircle className="w-5 h-5 text-red-600" />
                        )
                      ) : (
                        <div className="w-5 h-5 rounded-full border-2 border-gray-300" />
                      )}
                    </div>
                  </div>
                </div>
              ))}
              <div className="pt-4 text-center">
                <div className="text-sm text-gray-600">
                  Skills Mastered: {passedSkillsCount} / {skills.length}
                </div>
              </div>
            </div>
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

'use client';

import React, { useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { CheckCircle2, XCircle, HelpCircle, Play, RotateCcw, Lightbulb } from 'lucide-react';
import { Textarea } from '@/components/ui/textarea';

interface QueryPlaygroundProps {
  title?: string;
  instruction: string;
  expectedQuery: string;
  expectedResult?: string;
  hint?: string;
  difficulty?: 'beginner' | 'intermediate' | 'advanced';
  children?: React.ReactNode;
}

export default function QueryPlayground({
  title = "Practice Query",
  instruction,
  expectedQuery,
  expectedResult = "Query results would appear here",
  hint,
  difficulty = 'beginner',
  children
}: QueryPlaygroundProps) {
  const [userQuery, setUserQuery] = useState('');
  const [showResult, setShowResult] = useState(false);
  const [showHint, setShowHint] = useState(false);
  const [feedback, setFeedback] = useState<'correct' | 'incorrect' | null>(null);
  const [attempts, setAttempts] = useState(0);

  const normalizeQuery = (query: string): string => {
    return query
      .toLowerCase()
      .replace(/\s+/g, ' ')
      .trim()
      .replace(/['"]/g, '')
      .replace(/\s*,\s*/g, ',');
  };

  const checkQuery = useCallback(() => {
    const normalized = normalizeQuery(userQuery);
    const expected = normalizeQuery(expectedQuery);

    // Check for exact match or close match
    const isCorrect = normalized === expected ||
      (normalized.includes('get') &&
       normalized.includes('from all machines') &&
       expectedQuery.split(' ').every(word =>
         normalized.includes(word.toLowerCase().replace(/[,'"]/g, ''))
       ));

    setFeedback(isCorrect ? 'correct' : 'incorrect');
    setShowResult(isCorrect);
    setAttempts(prev => prev + 1);

    // Save progress to localStorage
    if (isCorrect) {
      const progress = JSON.parse(localStorage.getItem('queryPlaygroundProgress') || '{}');
      progress[title] = {
        completed: true,
        attempts: attempts + 1,
        timestamp: new Date().toISOString()
      };
      localStorage.setItem('queryPlaygroundProgress', JSON.stringify(progress));
    }
  }, [userQuery, expectedQuery, title, attempts]);

  const reset = () => {
    setUserQuery('');
    setShowResult(false);
    setFeedback(null);
    setShowHint(false);
    setAttempts(0);
  };

  const getDifficultyColor = () => {
    switch(difficulty) {
      case 'beginner': return 'text-green-600';
      case 'intermediate': return 'text-yellow-600';
      case 'advanced': return 'text-red-600';
      default: return 'text-gray-600';
    }
  };

  return (
    <Card className="my-6 border-2 border-gray-200">
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2">
            <Play className="w-5 h-5" />
            {title}
          </CardTitle>
          <span className={`text-sm font-medium ${getDifficultyColor()}`}>
            {difficulty.charAt(0).toUpperCase() + difficulty.slice(1)}
          </span>
        </div>
        <CardDescription>{instruction}</CardDescription>
      </CardHeader>

      <CardContent className="space-y-4">
        <div>
          <label htmlFor="query-input" className="block text-sm font-medium mb-2">
            Enter your Tanium query:
          </label>
          <Textarea
            id="query-input"
            value={userQuery}
            onChange={(e) => setUserQuery(e.target.value)}
            placeholder="Get Computer Name from all machines"
            className="font-mono text-sm"
            rows={3}
          />
        </div>

        {feedback && (
          <Alert className={feedback === 'correct' ? 'border-green-500' : 'border-red-500'}>
            <div className="flex items-center gap-2">
              {feedback === 'correct' ? (
                <>
                  <CheckCircle2 className="w-5 h-5 text-green-600" />
                  <AlertDescription className="text-green-700">
                    Excellent! Your query is correct.
                  </AlertDescription>
                </>
              ) : (
                <>
                  <XCircle className="w-5 h-5 text-red-600" />
                  <AlertDescription className="text-red-700">
                    Not quite right. {attempts >= 2 ? 'Try using the hint below.' : 'Give it another try!'}
                  </AlertDescription>
                </>
              )}
            </div>
          </Alert>
        )}

        {showResult && (
          <div className="bg-gray-50 p-4 rounded-lg">
            <p className="text-sm font-medium mb-2">Query Results:</p>
            <pre className="text-xs bg-white p-3 rounded border overflow-x-auto">
              {expectedResult}
            </pre>
          </div>
        )}

        {showHint && hint && (
          <Alert className="border-blue-300 bg-blue-50">
            <Lightbulb className="w-4 h-4 text-blue-600" />
            <AlertDescription className="text-blue-700">
              <strong>Hint:</strong> {hint}
            </AlertDescription>
          </Alert>
        )}

        {children && (
          <div className="mt-4 p-4 bg-gray-50 rounded-lg">
            {children}
          </div>
        )}
      </CardContent>

      <CardFooter className="flex justify-between">
        <div className="flex gap-2">
          <Button
            onClick={checkQuery}
            disabled={!userQuery.trim()}
            className="flex items-center gap-2"
          >
            <Play className="w-4 h-4" />
            Run Query
          </Button>
          <Button
            onClick={reset}
            variant="outline"
            className="flex items-center gap-2"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </Button>
        </div>

        {hint && !showHint && attempts >= 1 && feedback !== 'correct' && (
          <Button
            onClick={() => setShowHint(true)}
            variant="ghost"
            className="flex items-center gap-2"
          >
            <HelpCircle className="w-4 h-4" />
            Show Hint
          </Button>
        )}
      </CardFooter>
    </Card>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { CheckCircle2, XCircle, Lock, Unlock, RefreshCw, Trophy } from 'lucide-react';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Label } from '@/components/ui/label';
import { Progress } from '@/components/ui/progress';

interface Question {
  question: string;
  options: string[];
  correctAnswer: number;
  explanation?: string;
}

interface SkillGateProps {
  title?: string;
  requiredScore?: number;
  questions: Question[];
  nextSection?: string;
  prerequisite?: string;
  onComplete?: () => void;
}

export default function SkillGate({
  title = "Skill Checkpoint",
  requiredScore = 80,
  questions,
  nextSection = "next section",
  prerequisite,
  onComplete
}: SkillGateProps) {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<(number | null)[]>(
    new Array(questions.length).fill(null)
  );
  const [showResults, setShowResults] = useState(false);
  const [score, setScore] = useState(0);
  const [isUnlocked, setIsUnlocked] = useState(false);
  const [attempts, setAttempts] = useState(0);

  useEffect(() => {
    // Check if this gate was previously completed
    const progress = JSON.parse(localStorage.getItem('skillGateProgress') || '{}');
    if (progress[title]?.completed) {
      setIsUnlocked(true);
    }
  }, [title]);

  const handleAnswerSelect = (answerIndex: number) => {
    const newAnswers = [...selectedAnswers];
    newAnswers[currentQuestion] = answerIndex;
    setSelectedAnswers(newAnswers);
  };

  const handleNext = () => {
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    }
  };

  const handlePrevious = () => {
    if (currentQuestion > 0) {
      setCurrentQuestion(currentQuestion - 1);
    }
  };

  const calculateScore = () => {
    let correct = 0;
    questions.forEach((q, index) => {
      if (selectedAnswers[index] === q.correctAnswer) {
        correct++;
      }
    });
    return Math.round((correct / questions.length) * 100);
  };

  const handleSubmit = () => {
    const finalScore = calculateScore();
    setScore(finalScore);
    setShowResults(true);
    setAttempts(attempts + 1);

    const passed = finalScore >= requiredScore;
    setIsUnlocked(passed);

    // Save progress
    const progress = JSON.parse(localStorage.getItem('skillGateProgress') || '{}');
    progress[title] = {
      completed: passed,
      score: finalScore,
      attempts: attempts + 1,
      timestamp: new Date().toISOString()
    };
    localStorage.setItem('skillGateProgress', JSON.stringify(progress));

    if (passed && onComplete) {
      onComplete();
    }
  };

  const handleRetry = () => {
    setSelectedAnswers(new Array(questions.length).fill(null));
    setCurrentQuestion(0);
    setShowResults(false);
    setScore(0);
  };

  if (isUnlocked && !showResults) {
    return (
      <Card className="my-6 border-2 border-green-500 bg-green-50">
        <CardContent className="pt-6">
          <div className="flex items-center justify-center space-x-3">
            <Unlock className="w-6 h-6 text-green-600" />
            <p className="text-green-700 font-medium">
              ✓ Checkpoint Complete - {nextSection} is unlocked!
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!showResults) {
    const question = questions[currentQuestion];
    const progressPercentage = ((currentQuestion + 1) / questions.length) * 100;

    return (
      <Card className="my-6 border-2 border-gray-300">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <Lock className="w-5 h-5" />
              {title}
            </CardTitle>
            <span className="text-sm text-gray-500">
              Question {currentQuestion + 1} of {questions.length}
            </span>
          </div>
          {prerequisite && (
            <CardDescription>
              Complete this checkpoint to unlock: <strong>{nextSection}</strong>
            </CardDescription>
          )}
          <Progress value={progressPercentage} className="mt-2" />
        </CardHeader>

        <CardContent className="space-y-4">
          <div className="space-y-4">
            <p className="font-medium text-lg">{question.question}</p>

            <RadioGroup
              value={selectedAnswers[currentQuestion]?.toString()}
              onValueChange={(value) => handleAnswerSelect(parseInt(value))}
            >
              {question.options.map((option, index) => (
                <div key={index} className="flex items-center space-x-2 p-3 rounded-lg hover:bg-gray-50">
                  <RadioGroupItem value={index.toString()} id={`option-${index}`} />
                  <Label htmlFor={`option-${index}`} className="cursor-pointer flex-1">
                    {option}
                  </Label>
                </div>
              ))}
            </RadioGroup>
          </div>
        </CardContent>

        <CardFooter className="flex justify-between">
          <Button
            onClick={handlePrevious}
            disabled={currentQuestion === 0}
            variant="outline"
          >
            Previous
          </Button>

          <span className="text-sm text-gray-500">
            {selectedAnswers.filter(a => a !== null).length} of {questions.length} answered
          </span>

          {currentQuestion === questions.length - 1 ? (
            <Button
              onClick={handleSubmit}
              disabled={selectedAnswers.includes(null)}
              className="bg-blue-600 hover:bg-blue-700"
            >
              Submit Checkpoint
            </Button>
          ) : (
            <Button
              onClick={handleNext}
              disabled={selectedAnswers[currentQuestion] === null}
            >
              Next
            </Button>
          )}
        </CardFooter>
      </Card>
    );
  }

  // Show results
  const passed = score >= requiredScore;

  return (
    <Card className={`my-6 border-2 ${passed ? 'border-green-500' : 'border-red-500'}`}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          {passed ? (
            <>
              <Trophy className="w-6 h-6 text-green-600" />
              Checkpoint Passed!
            </>
          ) : (
            <>
              <XCircle className="w-6 h-6 text-red-600" />
              Not Quite There Yet
            </>
          )}
        </CardTitle>
      </CardHeader>

      <CardContent className="space-y-4">
        <div className="text-center">
          <p className="text-4xl font-bold mb-2">{score}%</p>
          <p className="text-gray-600">
            Required: {requiredScore}% | Attempts: {attempts}
          </p>
        </div>

        {passed ? (
          <Alert className="border-green-500 bg-green-50">
            <CheckCircle2 className="w-5 h-5 text-green-600" />
            <AlertDescription className="text-green-700">
              Excellent work! You've demonstrated mastery of this content.
              You can now proceed to {nextSection}.
            </AlertDescription>
          </Alert>
        ) : (
          <Alert className="border-red-500 bg-red-50">
            <XCircle className="w-5 h-5 text-red-600" />
            <AlertDescription className="text-red-700">
              You need {requiredScore}% to pass. Review the content and try again.
              {attempts >= 2 && ' Consider reviewing the prerequisite material.'}
            </AlertDescription>
          </Alert>
        )}

        <div className="space-y-3">
          <h3 className="font-medium">Review Your Answers:</h3>
          {questions.map((q, index) => {
            const isCorrect = selectedAnswers[index] === q.correctAnswer;
            return (
              <div key={index} className={`p-3 rounded-lg ${isCorrect ? 'bg-green-50' : 'bg-red-50'}`}>
                <div className="flex items-start gap-2">
                  {isCorrect ? (
                    <CheckCircle2 className="w-5 h-5 text-green-600 mt-0.5" />
                  ) : (
                    <XCircle className="w-5 h-5 text-red-600 mt-0.5" />
                  )}
                  <div className="flex-1">
                    <p className="font-medium">{q.question}</p>
                    <p className="text-sm mt-1">
                      Your answer: {q.options[selectedAnswers[index] || 0]}
                    </p>
                    {!isCorrect && (
                      <p className="text-sm text-green-700 mt-1">
                        Correct: {q.options[q.correctAnswer]}
                      </p>
                    )}
                    {q.explanation && !isCorrect && (
                      <p className="text-sm text-gray-600 mt-2">{q.explanation}</p>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </CardContent>

      <CardFooter className="flex justify-center">
        {passed ? (
          <Button
            onClick={() => setShowResults(false)}
            className="bg-green-600 hover:bg-green-700"
          >
            Continue to {nextSection}
          </Button>
        ) : (
          <Button
            onClick={handleRetry}
            className="flex items-center gap-2"
          >
            <RefreshCw className="w-4 h-4" />
            Try Again
          </Button>
        )}
      </CardFooter>
    </Card>
  );
}

