const getDifficultyColor = (difficulty: string) => {
  switch (difficulty) {
    case "Beginner":
      return "bg-green-900/50 text-green-200 border-green-500/50";
    case "Intermediate":
      return "bg-yellow-900/50 text-yellow-200 border-yellow-500/50";
    case "Advanced":
      return "bg-red-900/50 text-red-200 border-red-500/50";
    default:
      return "bg-gray-900/50 text-gray-200 border-gray-500/50";
  }
};

const convertStringToDifficulty = (difficulty: string): Difficulty => {
  switch (difficulty) {
    case "Beginner":
      return Difficulty.BEGINNER;
    case "Intermediate":
      return Difficulty.INTERMEDIATE;
    case "Advanced":
      return Difficulty.ADVANCED;
    default:
      return Difficulty.BEGINNER; // Default fallback
  }
};

export default function ModuleRenderer({ moduleData }: ModuleRendererProps) {
  const { frontmatter, content } = moduleData;
  const containerRef = useRef<HTMLDivElement | null>(null);
  const { user } = useAuth();
  const db = useDatabase();

  type SectionState = { id: string; title: string; level: number; completed: boolean; needsReview: boolean; etaMin?: number };
  const [sections, setSections] = useState<SectionState[]>([]);
  const [lastViewed, setLastViewed] = useState<string | null>(null);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [showToc, setShowToc] = useState(false);
  const [activeTab, setActiveTab] = useState<'content' | 'review'>('content');

  // Track time-in-section
  const lastActiveIdRef = useRef<string | null>(null);
  const lastChangeMsRef = useRef<number>(Date.now());
  const timeSpentRef = useRef<Record<string, number>>({}); // seconds per section id

  const moduleId = frontmatter.id;
  const storageKey = `tco-study-progress:${moduleId}`;
  const [dbEtaMap, setDbEtaMap] = useState<Record<string, number>>({});

  function slugify(s: string) {
    return s
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, "")
      .trim()
      .replace(/\s+/g, "-");
  }

  function stripEtaSuffix(title: string) {
    return title.replace(/\s*\((?:\d+(?:\.\d+)?\s*(?:min|minutes|m|h|hour|hours))\)\s*$/i, '').trim();
  }

  function formatMinutes(min?: number) {
    if (!min || min <= 0) return '0m';
    if (min < 60) return `${min}m`;
    const h = Math.floor(min / 60);
    const m = min % 60;
    return m > 0 ? `${h}h ${m}m` : `${h}h`;
  }

  // Load persisted progress (local)
  useEffect(() => {
    try {
      const raw = localStorage.getItem(storageKey);
      if (!raw) return;
      const parsed = JSON.parse(raw);
      if (parsed?.lastViewed) setLastViewed(parsed.lastViewed);
      if (Array.isArray(parsed?.sections)) setSections(parsed.sections);
    } catch {}
  }, [storageKey]);

  // Build TOC from rendered content and merge with persisted state
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const heads = Array.from(el.querySelectorAll("h1, h2, h3")) as HTMLHeadingElement[];
    const discovered: SectionState[] = heads.map((h) => {
      const title = h.innerText.trim();
      const id = h.id || slugify(title);
      if (!h.id) h.id = id;
      const level = h.tagName === "H3" ? 3 : h.tagName === 'H2' ? 2 : 1;
      let etaMin: number | undefined;
      const tm = title.match(/\(([^)]+)\)\s*$/);
      if (tm) {
        const t = tm[1].toLowerCase();
        const m = t.match(/^(\d+(?:\.\d+)?)\s*(min|minutes|m|h|hour|hours)$/);
        if (m) {
          const val = parseFloat(m[1]);
          etaMin = /h/.test(m[2]) ? Math.round(val * 60) : Math.round(val);
        }
      }
      const existing = sections.find((s) => s.id === id);
      const norm = stripEtaSuffix(title).toLowerCase();
      const dbEta = dbEtaMap[norm];
      return existing || { id, title, level, completed: false, needsReview: false, etaMin: dbEta ?? etaMin };
    });
    setSections(discovered);

    // Observe headings to highlight active section
  const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => (a.target as HTMLElement).offsetTop - (b.target as HTMLElement).offsetTop);
        if (visible[0]) {
          const id = (visible[0].target as HTMLElement).id;
          if (id) setActiveId(id);
        }
      },
      { root: el, rootMargin: "-20% 0px -60% 0px", threshold: [0, 1] }
    );
    heads.forEach((h) => observer.observe(h));
    return () => observer.disconnect();
  }, [content]);

  // Fetch DB-estimated times (public) and merge when available
  useEffect(() => {
    // TODO: Implement getStudySectionsPublic method in database hook
    // Temporarily disabled to fix TypeScript build errors
    // Will fetch public study section time estimates from the database
    setDbEtaMap({});
  }, [db, moduleId]);

  // Persist progress locally
  useEffect(() => {
    try {
      localStorage.setItem(storageKey, JSON.stringify({ sections, lastViewed }));
    } catch {}
  }, [sections, lastViewed, storageKey]);

  // Track scrolling to update last viewed section
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const onScroll = () => {
      const heads = Array.from(el.querySelectorAll("h2, h3")) as HTMLHeadingElement[];
      const top = heads.find((h) => h.getBoundingClientRect().top >= 0 && h.getBoundingClientRect().top < 200);
      if (top) setLastViewed(top.id);
    };
    const p = el;
    p.addEventListener("scroll", onScroll, { passive: true } as any);
    return () => p.removeEventListener("scroll", onScroll as any);
  }, []);

  // Update URL hash for shareable deep-links when active section changes
  useEffect(() => {
    if (!activeId) return;
    try {
      const url = new URL(window.location.href);
      if (url.hash.replace(/^#/, '') !== activeId) {
        url.hash = `#${activeId}`;
        window.history.replaceState({}, '', url.toString());
      }
    } catch {}
  }, [activeId]);

  // Accumulate time spent per active section and periodically sync
  useEffect(() => {
    const now = Date.now();
    const prevId = lastActiveIdRef.current;
    const deltaSec = Math.max(0, Math.floor((now - lastChangeMsRef.current) / 1000));
    if (prevId) {
      timeSpentRef.current[prevId] = (timeSpentRef.current[prevId] || 0) + deltaSec;
    }
    lastActiveIdRef.current = activeId;
    lastChangeMsRef.current = now;
  }, [activeId]);

  useEffect(() => {
    if (!user) return;
    const flush = async () => {
      const copy = { ...timeSpentRef.current };
      timeSpentRef.current = {};
      for (const [id, sec] of Object.entries(copy)) {
        if (!id) continue;
        const minutes = Math.max(0, Math.round(sec / 60));
        if (minutes <= 0) continue;
        try {
          await db.upsertUserStudyProgress({ module_id: moduleId, section_id: id, status: 'in_progress', time_spent_minutes: minutes });
        } catch {}
      }
    };
    const interval = setInterval(flush, 60000);
    return () => {
      clearInterval(interval);
      // final flush
      flush().catch(() => {});
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id, moduleId]);

  // Update HUD time spent display (client-only; simple counter since load)
  useEffect(() => {
    let seconds = 0;
    const el = () => document.getElementById('hud-time-spent');
    const tick = () => {
      seconds += 1;
      const m = Math.floor(seconds / 60).toString().padStart(2, '0');
      const s = (seconds % 60).toString().padStart(2, '0');
      try { el()!.textContent = `${m}:${s}`; } catch {}
    };
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  // Handle deep-link hash on initial load
  useEffect(() => {
    try {
      const hash = decodeURIComponent((window.location.hash || "").replace(/^#/, ""));
      if (!hash) return;
      const target = document.getElementById(hash);
      if (target) {
        target.scrollIntoView({ behavior: "smooth", block: "start" });
        setLastViewed(hash);
      }
    } catch {}
  }, []);

  // DB sync (best-effort) when marking complete/needs review
  const markSection = async (id: string, status: "completed" | "needs_review" | "in_progress" | "not_started") => {
    let nextSections: SectionState[] = [];
    setSections((prev) => {
      nextSections = prev.map((s) =>
        s.id === id ? { ...s, completed: status === 'completed', needsReview: status === 'needs_review' } : s
      );
      return nextSections;
    });
    analytics.capture("study_section_mark", { moduleId, id, status });
    if (!user) return;
    try {
      await db.upsertUserStudyProgress({ module_id: moduleId, section_id: id, status });
      // Update module summary
      const total = nextSections.length || 0;
      const completedCount = nextSections.filter((s) => s.completed).length;
      await db.upsertModuleProgress({
        module_id: moduleId,
        total_sections: total || undefined,
        completed_sections: completedCount || undefined,
        status: completedCount >= total && total > 0 ? 'completed' : (completedCount > 0 ? 'in_progress' : 'not_started'),
      });
    } catch {}
  };

  const domainForPractice = useMemo(() => {
    const map: Record<string, string> = {
      ASKING_QUESTIONS: "Asking Questions",
      REFINING_QUESTIONS: "Refining Questions & Targeting",
      TAKING_ACTION: "Taking Action",
      NAVIGATION_MODULES: "Navigation and Basic Module Functions",
      REPORTING_EXPORT: "Report Generation and Data Export",
      PLATFORM_FOUNDATION: "Fundamentals",
    };
    return map[String(frontmatter.domainEnum)] || String(frontmatter.domainEnum);
  }, [frontmatter.domainEnum]);

  return (
    <div className="container mx-auto max-w-4xl px-4 py-8">
      {/* Module Header */}
      <div className="mb-8">
        <div className="mb-4 flex flex-wrap items-center gap-3">
          <Badge variant="outline" className="border-blue-500/50 bg-blue-900/50 text-blue-200">
            {frontmatter.domainEnum.replace(/_/g, " ")}
          </Badge>
          <Badge variant="outline" className={getDifficultyColor(frontmatter.difficulty)}>
            {frontmatter.difficulty}
          </Badge>
          <div className="flex items-center gap-1 text-gray-400">
            <Clock className="h-4 w-4" />
            <span className="text-sm">{frontmatter.estimatedTime}</span>
          </div>
        </div>

        <h1 className="mb-4 bg-gradient-to-r from-blue-400 to-cyan-400 bg-clip-text text-4xl font-bold text-transparent">
          {frontmatter.title}
        </h1>

        {frontmatter.description && (
          <p className="mb-6 text-xl leading-relaxed text-gray-300">{frontmatter.description}</p>
        )}

        {/* Learning Objectives */}
        {frontmatter.learningObjectives && frontmatter.learningObjectives.length > 0 && (
          <Card className="mb-6 border-blue-500/30 bg-gradient-to-r from-blue-950/30 to-cyan-950/30">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-blue-200">
                <Target className="h-5 w-5" />
                Learning Objectives
              </CardTitle>
            </CardHeader>
            <CardContent>
              <ul className="space-y-2">
                {frontmatter.learningObjectives.map((objective, index) => (
                  <li key={index} className="flex items-start gap-2 text-gray-200">
                    <CheckCircle className="mt-0.5 h-5 w-5 flex-shrink-0 text-green-400" />
                    <span>{objective}</span>
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Mini Progress HUD */}
      <Card className="mb-6 border-cyan-500/30 bg-gradient-to-r from-cyan-950/30 to-blue-950/20">
        <CardContent className="flex flex-wrap items-center justify-between gap-4 pt-4">
          <div className="text-cyan-100">
            <span className="text-sm">Sections</span>
            <div className="text-lg font-semibold">
              {sections.filter((s) => s.completed).length}/{sections.length} completed
            </div>
          </div>
          <div className="flex-1">
            <div className="mb-1 flex justify-between text-sm text-cyan-200">
              <span>Progress</span>
              <span>
                {sections.length > 0
                  ? Math.round((sections.filter((s) => s.completed).length / sections.length) * 100)
                  : 0}%
              </span>
            </div>
            <div className="h-2 w-full overflow-hidden rounded bg-cyan-900/40">
              <div
                className="h-2 rounded bg-cyan-500"
                style={{ width: `${sections.length > 0 ? Math.round((sections.filter((s) => s.completed).length / sections.length) * 100) : 0}%` }}
              />
            </div>
          </div>
          <div className="text-cyan-100">
            <span className="text-sm">Time Spent</span>
            <div className="text-lg font-semibold" id="hud-time-spent"></div>
          </div>
          <div className="text-cyan-100">
            <span className="text-sm">Remaining</span>
            <div className="text-lg font-semibold">
              {(() => {
                const total = sections.reduce((sum, s) => sum + (s.etaMin || 0), 0);
                const done = sections.reduce((sum, s) => sum + (s.completed ? (s.etaMin || 0) : 0), 0);
                return formatMinutes(Math.max(0, total - done));
              })()}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Tabs */}
      <div className="mb-4 flex gap-2">
        <Button
          variant={activeTab === 'content' ? 'default' : 'outline'}
          className={activeTab === 'content' ? 'bg-cyan-700 hover:bg-cyan-600' : 'border-cyan-700 text-cyan-200 hover:bg-cyan-900/30'}
          onClick={() => setActiveTab('content')}
        >
          Content
        </Button>
        <Button
          variant={activeTab === 'review' ? 'default' : 'outline'}
          className={activeTab === 'review' ? 'bg-cyan-700 hover:bg-cyan-600' : 'border-cyan-700 text-cyan-200 hover:bg-cyan-900/30'}
          onClick={() => setActiveTab('review')}
        >
          Review ({sections.filter(s => s.needsReview && !s.completed).length})
        </Button>
      </div>

      {/* Mobile TOC toggle */}
      <div className="mb-4 lg:hidden">
        <Button
          variant="outline"
          className="border-cyan-600/40 text-cyan-200 hover:bg-cyan-900/30"
          onClick={() => setShowToc((v) => !v)}
          aria-expanded={showToc}
          aria-controls="module-toc"
        >
          {showToc ? 'Hide' : 'Show'} Section List
        </Button>
        {showToc && (
          <Card className="mt-3 border-cyan-500/30 bg-gradient-to-b from-gray-900/50 to-cyan-900/20" id="module-toc">
            <CardContent className="pt-4">
              <ul className="space-y-2">
                {sections.map((s) => (
                  <li key={s.id}>
                    <button
                      className={cn('text-left text-sm hover:underline', activeId === s.id ? 'text-cyan-300' : 'text-blue-100')}
                      onClick={() => {
                        const el = document.getElementById(s.id);
                        if (el) {
                          el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                          setLastViewed(s.id);
                          setShowToc(false);
                          analytics.capture('study_section_view', { moduleId, id: s.id });
                        }
                      }}
                    >
                      {s.title}
                    </button>
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Content + Sidebar */}
      <div className="relative flex gap-8">
        <div ref={containerRef} className="prose prose-lg prose-invert max-w-none flex-1 overflow-y-auto max-h-[70vh] pr-2">
          {/* Sticky current section header */}
          <div className="sticky top-0 z-10 -mx-2 mb-2 border-b border-cyan-900/40 bg-gray-950/60 px-2 backdrop-blur">
            <div className="flex h-10 items-center justify-between">
              <div className="truncate text-sm text-cyan-200">
                {stripEtaSuffix((sections.find((s) => s.id === activeId)?.title || sections[0]?.title || frontmatter.title))}
              </div>
              <div className="text-xs text-cyan-300">
                {formatMinutes(sections.find((s) => s.id === activeId)?.etaMin)}
              </div>
            </div>
          </div>
          {/* Review panel */}
          {activeTab === 'review' && (
            <Card className="mb-4 border-yellow-500/40 bg-yellow-900/20">
              <CardHeader className="pb-3">
                <CardTitle className="flex items-center gap-2 text-yellow-200">
                  <AlertCircle className="h-5 w-5" />
                  Needs Review
                </CardTitle>
              </CardHeader>
              <CardContent>
                {sections.filter(s => s.needsReview && !s.completed).length === 0 ? (
                  <div className="text-gray-200">No sections flagged for review.</div>
                ) : (
                  <ul className="space-y-2">
                    {sections.filter(s => s.needsReview && !s.completed).map((s) => (
                      <li key={s.id} className="flex items-center gap-3">
                        <button
                          className="text-left text-sm text-yellow-200 hover:underline"
                          onClick={() => {
                            const el = document.getElementById(s.id);
                            if (el) {
                              setActiveTab('content');
                              el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                              setLastViewed(s.id);
                              analytics.capture('study_section_view', { moduleId, id: s.id, from: 'reviewTab' });
                            }
                          }}
                        >
                          {s.title}
                        </button>
                        <Button size="sm" className="ml-auto bg-green-700 hover:bg-green-600" onClick={() => markSection(s.id, 'completed')}>
                          Mark complete
                        </Button>
                        <Button size="sm" variant="outline" className="border-yellow-600 text-yellow-200 hover:bg-yellow-900/30" onClick={() => markSection(s.id, 'in_progress')}>
                          Clear flag
                        </Button>
                      </li>
                    ))}
                  </ul>
                )}
              </CardContent>
            </Card>
          )}

          {/* Main content */}
          <ClientMDXContent content={content} />
        </div>
        {/* Study progress sidebar */}
        <aside className="sticky top-24 hidden w-80 shrink-0 lg:block">
          <Card className="border-blue-500/30 bg-gradient-to-b from-gray-900/50 to-blue-900/30">
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center gap-2 text-blue-200">
                <Book className="h-5 w-5" /> Study Progress
              </CardTitle>
              <div className="mt-2 flex gap-2">
                <Button
                  size="sm"
                  className="bg-green-700 hover:bg-green-600"
                  onClick={async () => {
                    for (const s of sections) {
                      if (!s.completed) await markSection(s.id, 'completed');
                    }
                    analytics.capture('study_mark_all_complete', { moduleId });
                  }}
                >
                  Mark all complete
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  className="border-yellow-600 text-yellow-200 hover:bg-yellow-900/30"
                  onClick={async () => {
                    for (const s of sections) {
                      if (s.needsReview) await markSection(s.id, 'in_progress');
                    }
                    analytics.capture('study_clear_all_review', { moduleId });
                  }}
                >
                  Clear all review
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  className="border-gray-600 text-gray-200 hover:bg-gray-900/30"
                  onClick={async () => {
                    // Reset local section state
                    setSections((prev) => prev.map((s) => ({ ...s, completed: false, needsReview: false })));
                    // Persist to DB best-effort
                    if (user) {
                      try {
                        for (const s of sections) {
                          await markSection(s.id, 'not_started');
                        }
                        analytics.capture('study_reset_progress', { moduleId });
                      } catch {}
                    }
                    // Update local storage immediately
                    try {
                      localStorage.setItem(storageKey, JSON.stringify({ sections: sections.map((s) => ({ ...s, completed: false, needsReview: false })), lastViewed }));
                    } catch {}
                  }}
                >
                  Reset progress
                </Button>
              </div>
              {lastViewed && (
                <CardDescription>
                  <Button
                    size="sm"
                    className="mt-2 bg-cyan-700 hover:bg-cyan-600"
                    onClick={() => {
                      const el = document.getElementById(lastViewed!);
                      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }}
                  >
                    Continue where you left off
                  </Button>
                </CardDescription>
              )}
            </CardHeader>
            <CardContent>
              <ul className="space-y-2">
                {sections.map((s) => (
                  <li key={s.id} className={cn("flex items-start gap-2", activeId === s.id ? "opacity-100" : "opacity-80")}> 
                    <input
                      type="checkbox"
                      className="mt-1"
                      checked={s.completed}
                      onChange={(e) => markSection(s.id, e.target.checked ? 'completed' : 'in_progress')}
                      aria-label={`Mark ${s.title} complete`}
                    />
                    <button
                      className={cn("text-left text-sm hover:underline", activeId === s.id ? "text-cyan-300" : "text-blue-100")}
                      onClick={() => {
                        const el = document.getElementById(s.id);
                        if (el) {
                          el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                          setLastViewed(s.id);
                          analytics.capture('study_section_view', { moduleId, id: s.id });
                        }
                      }}
                      aria-current={activeId === s.id ? "true" : undefined}
                    >
                      {s.title}
                    </button>
                    {typeof s.etaMin === 'number' && (
                      <span className="ml-2 inline-flex items-center gap-1 text-[11px] text-gray-300">
                        <Clock className="h-3 w-3" /> {s.etaMin}m
                      </span>
                    )}
                    {!s.completed && (
                      <button
                        className="ml-auto text-[11px] text-yellow-300 hover:underline"
                        onClick={() => markSection(s.id, 'needs_review')}
                        aria-label={`Mark ${s.title} needs review`}
                      >
                        needs review
                      </button>
                    )}
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        </aside>
      </div>

      {/* Module Footer - Practice Button */}
      {frontmatter.practiceConfig && (
        <div className="mt-12 border-t border-gray-700 pt-8">
          <Card className="border-blue-500/30 bg-gradient-to-r from-gray-900/50 to-blue-900/50">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-blue-200">
                <BookOpen className="h-5 w-5" />
                Ready to Practice?
              </CardTitle>
              <CardDescription className="text-gray-300">
                Test your knowledge with practice questions based on this module's content.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <PracticeButton
                variant="primary"
                className="w-full"
                href={`/practice?domain=${encodeURIComponent(domainForPractice)}&count=25&quick=1&reveal=1`}
                onClick={() => analytics.capture('module_practice_start', { moduleId, domain: domainForPractice })}
              >
                Start {frontmatter.title} Practice
              </PracticeButton>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  BookOpen,
  CheckCircle,
  Clock,
  Play,
  ArrowLeft,
  ArrowRight,
  Trophy,
  Target,
  Brain,
} from "lucide-react";
import { type Module, ModuleSection, type ModuleProgress } from "@/data/modules/module-definitions";
import { cn } from "@/lib/utils";

interface ModuleViewerProps {
  module: Module;
  progress?: ModuleProgress;
  onSectionComplete: (sectionId: string) => void;
  onObjectiveComplete: (objectiveId: string) => void;
  onModuleComplete: () => void;
  className?: string;
}

export function ModuleViewer({
  module,
  progress,
  onSectionComplete,
  onObjectiveComplete,
  onModuleComplete,
  className,
}: ModuleViewerProps) {
  const [currentSection, setCurrentSection] = useState(0);
  const [completedObjectives, setCompletedObjectives] = useState<Set<string>>(new Set());
  const [completedSections, setCompletedSections] = useState<Set<string>>(new Set());

  // Calculate progress percentages
  const objectiveProgress = Math.round((completedObjectives.size / module.objectives.length) * 100);
  const sectionProgress = Math.round((completedSections.size / module.sections.length) * 100);
  const overallProgress = Math.round((objectiveProgress + sectionProgress) / 2);

  // Domain color mapping
  const getDomainColors = (domain: string) => {
    const colors = {
      ASKING_QUESTIONS: {
        color: "text-green-400",
        bgColor: "bg-green-900/20",
        borderColor: "border-green-400",
      },
      REFINING_QUESTIONS: {
        color: "text-blue-400",
        bgColor: "bg-blue-900/20",
        borderColor: "border-blue-400",
      },
      TAKING_ACTION: {
        color: "text-cyan-400",
        bgColor: "bg-cyan-900/20",
        borderColor: "border-cyan-400",
      },
      NAVIGATION_MODULES: {
        color: "text-yellow-400",
        bgColor: "bg-yellow-900/20",
        borderColor: "border-yellow-400",
      },
      REPORTING_EXPORT: {
        color: "text-red-400",
        bgColor: "bg-red-900/20",
        borderColor: "border-red-400",
      },
    };
    return colors[domain as keyof typeof colors] || colors["NAVIGATION_MODULES"];
  };

  const domainColors = getDomainColors(module.domain);

  const handleObjectiveToggle = (objectiveId: string) => {
    const newCompleted = new Set(completedObjectives);
    if (newCompleted.has(objectiveId)) {
      newCompleted.delete(objectiveId);
    } else {
      newCompleted.add(objectiveId);
    }
    setCompletedObjectives(newCompleted);
    onObjectiveComplete(objectiveId);
  };

  const handleSectionComplete = (sectionId: string) => {
    const newCompleted = new Set(completedSections);
    newCompleted.add(sectionId);
    setCompletedSections(newCompleted);
    onSectionComplete(sectionId);
  };

  const nextSection = () => {
    if (currentSection < module.sections.length - 1) {
      setCurrentSection(currentSection + 1);
    }
  };

  const prevSection = () => {
    if (currentSection > 0) {
      setCurrentSection(currentSection - 1);
    }
  };

  const currentSectionData = module.sections[currentSection];
  const isLastSection = currentSection === module.sections.length - 1;
  const isFirstSection = currentSection === 0;

  return (
    <div className={cn("space-y-6", className)}>
      {/* Module Header */}
      <Card className={cn("glass border-2", domainColors.borderColor, domainColors.bgColor)}>
        <CardHeader>
          <div className="flex items-start justify-between">
            <div className="flex items-center gap-4">
              <div className="text-4xl">{module.icon}</div>
              <div>
                <CardTitle className="text-2xl text-white">{module.title}</CardTitle>
                <p className="mt-2 text-gray-300">{module.description}</p>
                <div className="mt-3 flex items-center gap-4">
                  <Badge variant="outline" className={cn("border-white/20", domainColors.color)}>
                    <Clock className="mr-1 h-3 w-3" />
                    {module.estimatedTime}
                  </Badge>
                  <Badge variant="outline" className={cn("border-white/20", domainColors.color)}>
                    <Target className="mr-1 h-3 w-3" />
                    {module.objectives.length} objectives
                  </Badge>
                  <Badge variant="outline" className={cn("border-white/20", domainColors.color)}>
                    <Trophy className="mr-1 h-3 w-3" />
                    {module.examWeight}% exam weight
                  </Badge>
                </div>
              </div>
            </div>
            <div className="text-right">
              <div className="text-3xl font-bold text-white">{overallProgress}%</div>
              <div className="text-sm text-gray-300">Complete</div>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <Progress value={overallProgress} className="h-3" />
            <div className="grid grid-cols-2 gap-4">
