"use client";

import * as React from "react";
import { ColumnDef, flexRender, getCoreRowModel, getFilteredRowModel, getSortedRowModel, SortingState, useReactTable, ColumnFiltersState, VisibilityState } from "@tanstack/react-table";
import type { ModuleListRow } from "./module-table-types";
import { moduleColumnsStatic } from "./module-table-columns";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuCheckboxItem, DropdownMenuContent, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { ChevronDown } from "lucide-react";
import { Toggle } from "@/components/ui/toggle";
import { usePersistentState } from "@/lib/usePersistentState";
import { useAuth } from "@/contexts/AuthContext";

export function ModulesStaticTable({ rows }: { rows: ModuleListRow[] }) {
  const columns = React.useMemo<ColumnDef<ModuleListRow>[]>(() => moduleColumnsStatic, []);
  const { user } = useAuth();
  const scope = user?.id ? `:u:${user.id}` : "";
  const [sorting, setSorting] = usePersistentState<SortingState>(`tco:table:modules-static:sorting${scope}`, []);
  const [columnFilters, setColumnFilters] = usePersistentState<ColumnFiltersState>(`tco:table:modules-static:filters${scope}`, []);
  const [columnVisibility, setColumnVisibility] = usePersistentState<VisibilityState>(`tco:table:modules-static:visibility${scope}`, {});
  const [selectedDomains, setSelectedDomains] = usePersistentState<string[]>(`tco:table:modules-static:facets:domains${scope}`, []);
  const [selectedLevels, setSelectedLevels] = usePersistentState<string[]>(`tco:table:modules-static:facets:levels${scope}`, []);
  const [maxTime, setMaxTime] = usePersistentState<number | null>(`tco:table:modules-static:facet:maxTime${scope}`, null);

  const table = useReactTable({
    data: rows,
    columns,
    state: { sorting, columnFilters, columnVisibility },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
  });

  // Unique facet values
  const uniqueDomains = React.useMemo(() => Array.from(new Set(rows.map(r => r.domain))), [rows]);
  const uniqueLevels = React.useMemo(() => Array.from(new Set(rows.map(r => r.difficulty))), [rows]);

  // Apply filters
  React.useEffect(() => {
    table.getColumn('domain')?.setFilterValue(selectedDomains);
  }, [selectedDomains, table]);
  React.useEffect(() => {
    table.getColumn('difficulty')?.setFilterValue(selectedLevels);
  }, [selectedLevels, table]);
  React.useEffect(() => {
    if (maxTime == null) {
      table.getColumn('estimatedTimeMinutes')?.setFilterValue(undefined);
    } else {
      table.getColumn('estimatedTimeMinutes')?.setFilterValue({ max: maxTime });
    }
  }, [maxTime, table]);

  // custom filter for estimated time
  const estCol = table.getColumn('estimatedTimeMinutes');
  if (estCol && !estCol.getFilterFn()) {
    // monkey-patch filter behavior via columnDef provided filterFn isn't easily changed at runtime
    // We will rely on getFilteredRowModel with a predicate using setFilterValue shape
  }

  // client-side filter on rows for estimatedTimeMinutes max (simple approach to avoid custom filter wiring)
  const filteredRows = React.useMemo(() => {
    const rows0 = table.getRowModel().rows;
    if (maxTime == null) return rows0;
    return rows0.filter(r => {
      const v = Number(r.getValue('estimatedTimeMinutes'));
      return !Number.isNaN(v) && v <= maxTime;
    });
  }, [table.getRowModel().rows, maxTime]);

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center gap-2">
        <Input
          placeholder="Filter title/domain..."
          value={(table.getColumn('title')?.getFilterValue() as string) ?? ''}
          onChange={(e) => table.getColumn('title')?.setFilterValue(e.target.value)}
          className="h-8 w-[240px]"
        />

        {/* Domain facets */}
        <div className="hidden flex-wrap gap-1 md:flex">
          {uniqueDomains.map((d) => (
            <Toggle
              key={d}
              size="sm"
              pressed={selectedDomains.includes(d)}
              onPressedChange={(v) => setSelectedDomains(prev => v ? Array.from(new Set([...prev, d])) : prev.filter(x => x !== d))}
              className="data-[state=on]:bg-primary/20 data-[state=on]:text-primary"
            >
              {d}
            </Toggle>
          ))}
        </div>

        {/* Difficulty facets */}
        <div className="hidden flex-wrap gap-1 md:flex">
          {uniqueLevels.map((lv) => (
            <Toggle
              key={lv}
              size="sm"
              pressed={selectedLevels.includes(lv)}
              onPressedChange={(v) => setSelectedLevels(prev => v ? Array.from(new Set([...prev, lv])) : prev.filter(x => x !== lv))}
              className="data-[state=on]:bg-primary/20 data-[state=on]:text-primary"
            >
              {lv}
            </Toggle>
          ))}
        </div>

        {/* Estimated time thresholds */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="gap-1">
              {maxTime == null ? 'Any time' : `≤ ${maxTime} min`}
              <ChevronDown className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent>
            <DropdownMenuLabel>Max Estimated Time</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {[null, 30, 45, 60, 90, 120, 180].map((t, i) => (
              <DropdownMenuCheckboxItem
                key={i}
                checked={maxTime === t}
                onCheckedChange={() => setMaxTime(t as any)}
              >
                {t == null ? 'Any' : `≤ ${t} min`}
              </DropdownMenuCheckboxItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>

        <Button
          variant="ghost"
          size="sm"
          onClick={() => {
            table.resetColumnFilters();
            table.resetSorting();
            setSelectedDomains([]);
            setSelectedLevels([]);
            setMaxTime(null);
          }}
        >
          Clear
        </Button>

        <div className="ml-auto">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm" className="gap-1">
                Columns
                <ChevronDown className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuLabel>Toggle columns</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {table.getAllLeafColumns().filter((c) => c.getCanHide()).map((column) => (
                <DropdownMenuCheckboxItem
                  key={column.id}
                  checked={column.getIsVisible()}
                  onCheckedChange={(v) => column.toggleVisibility(!!v)}
                >
                  {column.columnDef.header as any}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      <div className="rounded-md border border-white/10 max-h-[480px] overflow-auto">
        <table className="w-full text-sm">
          <thead className="sticky top-0 z-10 bg-background/80 backdrop-blur supports-[backdrop-filter]:bg-background/60">
            {table.getHeaderGroups().map((hg) => (
              <tr key={hg.id}>
                {hg.headers.map((header) => (
                  <th
                    key={header.id}
                    className="px-3 py-2 text-left font-medium text-gray-200 select-none"
                    onClick={header.column.getToggleSortingHandler()}
                  >
                    {flexRender(header.column.columnDef.header, header.getContext())}
                    {header.column.getIsSorted() === "asc" ? " ↑" : header.column.getIsSorted() === "desc" ? " ↓" : ""}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {filteredRows.map((row) => (
              <tr key={row.id} className="border-t border-white/5 hover:bg-white/[0.02]">
                {row.getVisibleCells().map((cell) => (
                  <td key={cell.id} className="px-3 py-2 text-gray-300">
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useDatabase } from "@/contexts/DatabaseContext";
import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { AlertTriangle, BookOpen } from "lucide-react";

type ModuleMap = Record<string, { slug: string; title: string }>;

export default function ReviewCenter({ modules }: { modules: ModuleMap }) {
  const { user } = useAuth();
  const db = useDatabase();

  const [items, setItems] = useState<
    Array<{ module_id: string; module_title: string; slug: string; section_id: string; section_title: string }>
  >([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;

    const load = async () => {
      setLoading(true);
      try {
        if (user) {
          const rows = await db.getUserStudyProgress();
          const need = (rows as any[]).filter((r) => r.status === "needs_review");
          // Fetch section titles per module
          const byModule: Record<string, string[]> = {};
          for (const r of need) {
            const mid = r.module_id as string;
            const sid = r.section_id as string;
            if (!mid || !sid) continue;
            (byModule[mid] ||= []).push(sid);
          }
          const out: Array<{ module_id: string; module_title: string; slug: string; section_id: string; section_title: string }>
            = [];
          for (const [mid, sids] of Object.entries(byModule)) {
            const meta = modules[mid];
            if (!meta) continue;
            // TODO: Implement getStudySectionsPublic method
            // For now, use section IDs directly as titles
            for (const sid of sids) {
              out.push({ module_id: mid, module_title: meta.title, slug: meta.slug, section_id: sid, section_title: `Section ${sid}` });
            }
          }
          if (mounted) setItems(out);
        } else {
          // Local fallback
          const out: Array<{ module_id: string; module_title: string; slug: string; section_id: string; section_title: string }> = [];
          for (const [mid, meta] of Object.entries(modules)) {
            const key = `tco-study-progress:${mid}`;
            try {
              const raw = localStorage.getItem(key);
              if (!raw) continue;
              const v = JSON.parse(raw);
              const secs = Array.isArray(v?.sections) ? v.sections : [];
              for (const s of secs) {
                if (s?.needsReview && !s?.completed) {
                  out.push({ module_id: mid, module_title: meta.title, slug: meta.slug, section_id: s.id || "", section_title: s.title || "Section" });
                }
              }
            } catch {}
          }
          if (mounted) setItems(out);
        }
      } catch {
        if (mounted) setItems([]);
      } finally {
        if (mounted) setLoading(false);
      }
    };

    load();
    return () => {
      mounted = false;
    };
  }, [user?.id]);

  const grouped = useMemo(() => {
    const g = new Map<string, { title: string; slug: string; items: Array<{ id: string; title: string }> }>();
    for (const it of items) {
      const key = it.module_id;
      if (!g.has(key)) g.set(key, { title: it.module_title, slug: it.slug, items: [] });
      g.get(key)!.items.push({ id: it.section_id, title: it.section_title });
    }
    return Array.from(g.entries()).map(([id, v]) => ({ id, ...v }));
  }, [items]);

  if (loading) {
    return (
      <div className="text-center text-gray-300">Loading review items…</div>
    );
  }

  const uniqueDomains = useMemo(() => {
    const set = new Set<string>();
    for (const it of items) {
      const slug = it.slug;
      const slugToDomain: Record<string, string> = {
        'platform-foundation': 'Fundamentals',
        'asking-questions': 'Asking Questions',
        'refining-questions-targeting': 'Refining Questions & Targeting',
        'taking-action-packages-actions': 'Taking Action',
        'navigation-basic-modules': 'Navigation and Basic Module Functions',
        'reporting-data-export': 'Report Generation and Data Export',
      };
      const domain = slugToDomain[slug];
      if (domain) set.add(domain);
    }
    return Array.from(set);
  }, [items]);

  const mixedPracticeHref = useMemo(() => {
    if (uniqueDomains.length === 0) return null;
    const domainsParam = encodeURIComponent(uniqueDomains.join(','));
    const count = Math.min(items.length || 25, 25);
    return `/practice?domains=${domainsParam}&count=${count}&quick=1&reveal=1`;
  }, [uniqueDomains, items.length]);

  return (
    <div className="space-y-6">
      {mixedPracticeHref && (
        <div className="flex justify-end">
          <Button className="bg-cyan-700 hover:bg-cyan-600" asChild>
            <Link href={mixedPracticeHref}>Start Mixed Review</Link>
          </Button>
        </div>
      )}
      {grouped.length === 0 ? (
        <Card className="border-green-500/30 bg-green-900/20">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-green-200">
              <BookOpen className="h-5 w-5" /> You're all caught up!
            </CardTitle>
          </CardHeader>
          <CardContent className="text-green-100">No sections are flagged for review. Keep studying!</CardContent>
        </Card>
      ) : (
        grouped.map((m) => (
          <Card key={m.id} className="border-yellow-500/30 bg-yellow-900/20">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-yellow-200">
                <AlertTriangle className="h-5 w-5" /> {m.title}
                <Badge variant="outline" className="ml-2 border-yellow-500/50 text-yellow-200">
                  {m.items.length} to review
                </Badge>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="mb-3 flex justify-end">
                {(() => {
                  const slugToDomain: Record<string, string> = {
                    'platform-foundation': 'Fundamentals',
                    'asking-questions': 'Asking Questions',
                    'refining-questions-targeting': 'Refining Questions & Targeting',
                    'taking-action-packages-actions': 'Taking Action',
                    'navigation-basic-modules': 'Navigation and Basic Module Functions',
                    'reporting-data-export': 'Report Generation and Data Export',
                  };
                  const domain = slugToDomain[m.slug] || '';
                  return domain ? (
                    <Button
                      className="bg-cyan-700 hover:bg-cyan-600"
                      asChild
                      title={`Start practice for ${m.title}`}
                    >
                      <Link href={`/practice?domain=${encodeURIComponent(domain)}&count=25&quick=1&reveal=1`}>
                        Start Practice
                      </Link>
                    </Button>
                  ) : null;
                })()}
              </div>
              <ul className="space-y-2">
                {m.items.map((s) => (
                  <li key={s.id}>
                    <Link
                      href={`/modules/${m.slug}#${encodeURIComponent(s.id)}`}
                      className="text-yellow-100 hover:underline"
                    >
                      {s.title}
                    </Link>
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        ))
      )}
    </div>
  );
}

