  slug: string;
  title: string;
  icon: React.ElementType;
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced';
  estimatedTime: string;
  weight: number;
  description: string;
}

const modules: ModuleInfo[] = [
  {
    slug: 'asking-questions',
    title: 'Asking Questions',
    icon: BookOpen,
    difficulty: 'Beginner',
    estimatedTime: '45 min',
    weight: 22,
    description: 'Master natural language queries and sensor management'
  },
  {
    slug: 'refining-questions',
    title: 'Refining Questions & Targeting',
    icon: Target,
    difficulty: 'Intermediate',
    estimatedTime: '50 min',
    weight: 23,
    description: 'Advanced targeting with computer groups and filters'
  },
  {
    slug: 'taking-action',
    title: 'Taking Action',
    icon: Package,
    difficulty: 'Intermediate',
    estimatedTime: '55 min',
    weight: 15,
    description: 'Safe package deployment and action execution'
  },
  {
    slug: 'navigation-modules',
    title: 'Navigation & Modules',
    icon: Navigation,
    difficulty: 'Beginner',
    estimatedTime: '40 min',
    weight: 23,
    description: 'Platform navigation and core module operations'
  },
  {
    slug: 'reporting-export',
    title: 'Reporting & Data Export',
    icon: FileSpreadsheet,
    difficulty: 'Intermediate',
    estimatedTime: '35 min',
    weight: 17,
    description: 'Report creation and data export systems'
  }
];

const getDifficultyColor = (difficulty: string) => {
  switch (difficulty) {
    case 'Beginner':
      return 'bg-green-100 text-green-700 border-green-300 dark:bg-green-900/50 dark:text-green-200 dark:border-green-500/50';
    case 'Intermediate':
      return 'bg-orange-100 text-orange-700 border-orange-300 dark:bg-orange-900/50 dark:text-orange-200 dark:border-orange-500/50';
    case 'Advanced':
      return 'bg-red-100 text-red-700 border-red-300 dark:bg-red-900/50 dark:text-red-200 dark:border-red-500/50';
    default:
      return 'bg-slate-100 text-slate-700 border-slate-300 dark:bg-slate-900/50 dark:text-slate-200 dark:border-slate-500/50';
  }
};

interface ModuleNavigationProps {
  currentSlug?: string;
  showAllModules?: boolean;
}

export default function ModuleNavigation({ currentSlug, showAllModules = false }: ModuleNavigationProps) {
  const pathname = usePathname() || '';
  const currentModuleIndex = modules.findIndex(m => m.slug === currentSlug);
  const previousModule = currentModuleIndex > 0 ? modules[currentModuleIndex - 1] : null;
  const nextModule = currentModuleIndex < modules.length - 1 ? modules[currentModuleIndex + 1] : null;

  if (showAllModules) {
    return (
      <div className="space-y-6">
        {/* Header */}
        <div className="text-center">
          <h2 className="mb-2 text-3xl font-bold text-slate-900 dark:text-slate-100">
            TCO Study Modules
          </h2>
          <p className="text-slate-600 dark:text-slate-400">
            Complete certification preparation across all 5 domains
          </p>
        </div>

        {/* Module Grid */}
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {modules.map((module) => {
            const Icon = module.icon;
            const isActive = pathname.includes(module.slug);

            // Determine card color based on difficulty
            const getCardColor = (difficulty: string) => {
              switch (difficulty) {
                case 'Beginner':
                  return 'border-green-200 bg-gradient-to-br from-green-50 to-green-100 dark:border-green-800 dark:from-green-900/20 dark:to-green-800/20';
                case 'Intermediate':
                  return 'border-orange-200 bg-gradient-to-br from-orange-50 to-orange-100 dark:border-orange-800 dark:from-orange-900/20 dark:to-orange-800/20';
                case 'Advanced':
                  return 'border-red-200 bg-gradient-to-br from-red-50 to-red-100 dark:border-red-800 dark:from-red-900/20 dark:to-red-800/20';
                default:
                  return 'border-blue-200 bg-gradient-to-br from-blue-50 to-blue-100 dark:border-blue-800 dark:from-blue-900/20 dark:to-blue-800/20';
              }
            };

            const getIconColor = (difficulty: string) => {
              switch (difficulty) {
                case 'Beginner':
                  return 'text-green-600 dark:text-green-400';
                case 'Intermediate':
                  return 'text-orange-600 dark:text-orange-400';
                case 'Advanced':
                  return 'text-red-600 dark:text-red-400';
                default:
                  return 'text-blue-600 dark:text-blue-400';
              }
            };

            return (
              <Link key={module.slug} href={`/modules/${module.slug}`}>
                <Card className={cn(
                  "group transition-all duration-200 hover:scale-105 cursor-pointer hover:shadow-md",
                  getCardColor(module.difficulty),
                  isActive && "ring-2 ring-blue-500"
                )}>
                  <CardContent className="p-6">
                    <div className="flex items-center gap-3 mb-3">
                      <div className={cn("p-2 rounded-lg", 
                        module.difficulty === 'Beginner' ? 'bg-green-500/20' :
                        module.difficulty === 'Intermediate' ? 'bg-orange-500/20' :
                        module.difficulty === 'Advanced' ? 'bg-red-500/20' : 'bg-blue-500/20'
                      )}>
                        <Icon className={cn("h-6 w-6", getIconColor(module.difficulty))} />
                      </div>
                      <div className="flex-1">
                        <h3 className="font-semibold text-slate-900 dark:text-slate-100 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                          {module.title}
                        </h3>
                        <div className="flex items-center gap-2 mt-1">
                          <Badge variant="outline" className={getDifficultyColor(module.difficulty)}>
                            {module.difficulty}
                          </Badge>
                          <span className="text-sm text-slate-600 dark:text-slate-400">{module.estimatedTime}</span>
                        </div>
                      </div>
                    </div>

                    <p className="text-sm text-slate-700 dark:text-slate-300 mb-3">
                      {module.description}
                    </p>

                    <div className="flex items-center justify-between">
                      <span className="text-xs text-slate-600 dark:text-slate-400">
                        Exam Weight: {module.weight}%
                      </span>
                      <ChevronRight className="h-4 w-4 text-slate-400 group-hover:text-blue-500 transition-colors" />
                    </div>
                  </CardContent>
                </Card>
              </Link>
            );
          })}
        </div>

        {/* AI Assistant Card */}
        <Card className="border-cyan-200 bg-gradient-to-br from-cyan-50 to-cyan-100 dark:border-cyan-800 dark:from-cyan-900/20 dark:to-cyan-800/20">
          <CardContent className="p-6">
            <div className="flex items-center gap-3 mb-3">
              <div className="p-2 rounded-lg bg-cyan-500/20">
                <Brain className="h-6 w-6 text-cyan-600 dark:text-cyan-400" />
              </div>
              <div>
                <h3 className="font-semibold text-cyan-700 dark:text-cyan-300 flex items-center gap-2">
                  AI Study Assistant
                  <Sparkles className="h-4 w-4 text-yellow-500" />
                </h3>
                <p className="text-sm text-cyan-600 dark:text-cyan-400">
                  Get personalized help, explanations, and practice questions
                </p>
              </div>
            </div>
            <Button className="w-full bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-700 hover:to-blue-700 text-white">
              Launch AI Assistant
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Navigation for individual module pages
  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <nav className="flex items-center space-x-2 text-sm text-gray-400">
        <Link href="/" className="hover:text-blue-400 transition-colors">
          <Home className="h-4 w-4" />
        </Link>
        <ChevronRight className="h-4 w-4" />
        <Link href="/modules" className="hover:text-blue-400 transition-colors">
          Study Modules
        </Link>
        {currentSlug && (
          <>
            <ChevronRight className="h-4 w-4" />
            <span className="text-blue-400 font-medium">
              {modules.find(m => m.slug === currentSlug)?.title}
            </span>
          </>
        )}
      </nav>

      {/* Previous/Next Navigation */}
      {currentSlug && (
        <div className="flex justify-between items-center">
          {previousModule ? (
            <Link href={`/modules/${previousModule.slug}`}>
              <Button variant="outline" className="flex items-center gap-2">
                <ChevronLeft className="h-4 w-4" />
                <div className="text-left">
                  <div className="text-xs text-gray-400">Previous</div>
                  <div className="text-sm">{previousModule.title}</div>
                </div>
              </Button>
            </Link>
          ) : (
            <div />
          )}

          <Link href="/modules">
            <Button variant="ghost" className="text-blue-400 hover:text-blue-300">
              All Modules
            </Button>
          </Link>

          {nextModule ? (
            <Link href={`/modules/${nextModule.slug}`}>
              <Button variant="outline" className="flex items-center gap-2">
                <div className="text-right">
                  <div className="text-xs text-gray-400">Next</div>
                  <div className="text-sm">{nextModule.title}</div>
                </div>
                <ChevronRight className="h-4 w-4" />
              </Button>
            </Link>
          ) : (
            <div />
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  HelpCircle,
  X,
  ChevronRight,
  ChevronLeft,
  Home,
  BookOpen,
  Target,
  Trophy,
  MessageCircle,
  Compass,
  Map,
  Lightbulb,
  Info,
  ArrowRight,
  MousePointer,
  Sparkles,
  CheckCircle
} from 'lucide-react';
import { usePathname } from 'next/navigation';
import { getArchonOverlay, getHoverGradient } from '@/lib/archon-theme';

// TypeScript interfaces for navigation helper
interface NavigationTip {
  id: string;
  path: string;
  title: string;
  description: string;
  icon: React.ComponentType<{ className?: string }>;
  tips: string[];
  nextStep?: string;
  isBeginnerEssential: boolean;
}

interface NavigationStep {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  description: string;
  path: string;
  order: number;
  isCompleted: boolean;
}

interface NavigationHelperProps {
  isBeginnerMode?: boolean;
  showHelper?: boolean;
  onClose?: () => void;
  completedPaths?: string[];
}

export default function NavigationHelper({
  isBeginnerMode = true,
  showHelper = true,
  onClose,
  completedPaths = []
}: NavigationHelperProps) {
  const pathname = usePathname();
  const [isExpanded, setIsExpanded] = useState(false);
  const [showTips, setShowTips] = useState(true);
  const [currentTip, setCurrentTip] = useState<NavigationTip | null>(null);
  const [visitedPaths, setVisitedPaths] = useState<string[]>([]);
  const [showWelcome, setShowWelcome] = useState(false);

  // Navigation tips for different pages
  const navigationTips: NavigationTip[] = [
    {
      id: 'home',
      path: '/',
      title: 'Welcome to Tanium TCO Platform',
      description: 'Your journey to certification starts here',
      icon: Home,
      tips: [
        'Start with Phase 0: Foundation if you\'re new to Tanium',
        'Check your progress dashboard regularly',
        'Use the quick links for easy navigation',
        'Enable beginner mode for extra guidance'
      ],
      nextStep: '/study',
      isBeginnerEssential: true
    },
    {
      id: 'study',
      path: '/study',
      title: 'Study Modules',
      description: 'Structured learning path to certification',
      icon: BookOpen,
      tips: [
        'Begin with Phase 0: Foundation (blue banner at top)',
        'Complete modules in order for best results',
        'Each module builds on previous knowledge',
        'Track your progress with the progress bars'
      ],
      nextStep: '/practice',
      isBeginnerEssential: true
    },
    {
      id: 'practice',
      path: '/practice',
      title: 'Practice Questions',
      description: 'Test your knowledge with real exam questions',
      icon: Target,
      tips: [
        'Start with "Foundation" difficulty questions',
        'Review explanations for both correct and incorrect answers',
        'Use practice mode before attempting timed tests',
        'Focus on domains where you scored lowest'
      ],
      nextStep: '/labs',
      isBeginnerEssential: true
    },
    {
      id: 'labs',
      path: '/labs',
      title: 'Hands-On Labs',
      description: 'Apply your knowledge in simulated environments',
      icon: Compass,
      tips: [
        'Complete study modules before attempting labs',
        'Follow step-by-step instructions carefully',
        'Use hints if you get stuck',
        'Practice labs multiple times for mastery'
      ],
      nextStep: '/progress',
      isBeginnerEssential: true
    },
    {
      id: 'progress',
      path: '/progress',
      title: 'Progress Tracking',
      description: 'Monitor your learning journey',
      icon: Trophy,
      tips: [
        'Review your confidence level progression',
        'Check milestone achievements',
        'Identify weak areas for focused study',
        'Celebrate your accomplishments!'
      ],
      nextStep: '/exam',
      isBeginnerEssential: false
    },
    {
      id: 'exam',
      path: '/exam',
      title: 'Mock Exam',
      description: 'Full-length practice exam simulation',
      icon: CheckCircle,
      tips: [
        'Complete all study modules first',
        'Take practice questions to prepare',
        'Simulate real exam conditions (105 minutes)',
        'Review all incorrect answers thoroughly'
      ],
      isBeginnerEssential: false
    }
  ];

  // Beginner's learning journey steps
  const learningJourney: NavigationStep[] = [
    {
      id: 'welcome',
      label: 'Welcome & Orientation',
      icon: Sparkles,
      description: 'Get familiar with the platform',
      path: '/',
      order: 1,
      isCompleted: visitedPaths.includes('/')
    },
    {
      id: 'foundation',
      label: 'Phase 0: Foundation',
      icon: BookOpen,
      description: 'Build your Tanium knowledge base',
      path: '/study',
      order: 2,
      isCompleted: completedPaths.includes('phase-0-foundation')
    },
    {
      id: 'practice-basics',
      label: 'Practice Fundamentals',
      icon: Target,
      description: 'Test your foundation knowledge',
      path: '/practice',
      order: 3,
      isCompleted: completedPaths.includes('foundation-practice')
    },
    {
      id: 'first-lab',
      label: 'First Hands-On Lab',
      icon: Compass,
      description: 'Apply knowledge practically',
      path: '/labs',
      order: 4,
      isCompleted: completedPaths.includes('first-lab')
    },
    {
      id: 'progress-check',
      label: 'Progress Review',
      icon: Trophy,
      description: 'Check your achievements',
      path: '/progress',
      order: 5,
      isCompleted: completedPaths.includes('progress-review')
    }
  ];

  // Get current page tip
  useEffect(() => {
    const tip = navigationTips.find(t => t.path === pathname);
    setCurrentTip(tip || null);

    // Track visited paths
    if (pathname && !visitedPaths.includes(pathname)) {
      setVisitedPaths(prev => [...prev, pathname]);
    }

    // Show welcome for first-time visitors
    if (visitedPaths.length === 0 && pathname === '/') {
      setShowWelcome(true);
    }
  }, [pathname, visitedPaths]);

  // Calculate journey progress
  const journeyProgress = Math.round(
    (learningJourney.filter(step => step.isCompleted).length / learningJourney.length) * 100
  );

  const getCurrentStepIndex = (): number => {
    const currentStep = learningJourney.findIndex(step => step.path === pathname);
    return currentStep >= 0 ? currentStep : 0;
  };

  const getNextStep = (): NavigationStep | null => {
    const incompleteSteps = learningJourney.filter(step => !step.isCompleted);
    return incompleteSteps.length > 0 ? incompleteSteps[0] : null;
  };

  if (!showHelper || !isBeginnerMode) return null;

  return (
    <>
      {/* Floating Helper Button */}
      <motion.button
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        onClick={() => setIsExpanded(!isExpanded)}
        className="fixed bottom-6 right-6 z-40 p-4 text-white rounded-full shadow-lg transition-colors border"
        style={{
          background: getArchonOverlay().background,
          borderColor: 'rgba(0, 255, 255, 0.3)',
          backdropFilter: 'blur(12px)'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.background = getHoverGradient();
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.background = getArchonOverlay().background;
        }}
      >
        <div className="relative">
          <HelpCircle className="w-6 h-6" />
          {currentTip?.isBeginnerEssential && (
            <span className="absolute -top-1 -right-1 w-3 h-3 bg-yellow-400 rounded-full animate-pulse" />
          )}
        </div>
      </motion.button>

      {/* Expanded Helper Panel */}
      <AnimatePresence>
        {isExpanded && (
          <motion.div
            initial={{ opacity: 0, x: 400 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 400 }}
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
            className="fixed right-0 top-0 h-full w-96 shadow-2xl z-50 overflow-y-auto border-l"
            style={{
              background: getArchonOverlay().background,
              backdropFilter: 'blur(20px)',
              borderColor: 'rgba(0, 255, 255, 0.3)'
            }}
          >
            <div className="p-6 space-y-6">
              {/* Header */}
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-2">
                  <Compass className="w-6 h-6 text-cyan-400" />
                  <h2 className="text-xl font-bold text-cyan-100">Navigation Helper</h2>
                </div>
                <button
                  onClick={() => setIsExpanded(false)}
                  aria-label="Close navigation helper"
                  className="p-2 text-cyan-300 hover:text-cyan-100 rounded-lg transition-colors"
                  style={{
                    backgroundColor: 'rgba(0, 255, 255, 0.1)'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = 'rgba(0, 255, 255, 0.2)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = 'rgba(0, 255, 255, 0.1)';
                  }}
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              {/* Beginner Mode Badge */}
              <div className="flex items-center justify-center p-3 rounded-lg border" style={{
                background: 'rgba(0, 255, 255, 0.1)',
                borderColor: 'rgba(0, 255, 255, 0.3)'
              }}>
                <Sparkles className="w-5 h-5 text-cyan-400 mr-2" />
                <span className="text-sm font-semibold text-cyan-100">
                  Beginner Mode Active
                </span>
              </div>

              {/* Journey Progress */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-semibold text-cyan-100">Your Learning Journey</h3>
                  <span className="text-sm text-cyan-300/80">{journeyProgress}% Complete</span>
                </div>
                <div className="w-full rounded-full h-2" style={{
                  background: 'rgba(0, 255, 255, 0.1)',
                  border: '1px solid rgba(0, 255, 255, 0.2)'
                }}>
                  <motion.div
                    className="h-2 rounded-full"
                    style={{ background: getHoverGradient() }}
                    initial={{ width: 0 }}
                    animate={{ width: `${journeyProgress}%` }}
                    transition={{ duration: 1, ease: "easeOut" }}
                  />
                </div>
              </div>

              {/* Current Page Tips */}
              {currentTip && (
                <div className="space-y-4 p-4 rounded-lg border" style={{
                  background: 'rgba(0, 255, 255, 0.05)',
                  borderColor: 'rgba(0, 255, 255, 0.2)'
                }}>
                  <div className="flex items-start space-x-3">
                    <currentTip.icon className="w-6 h-6 text-cyan-400 flex-shrink-0 mt-1" />
                    <div className="flex-1 space-y-2">
                      <h3 className="font-semibold text-cyan-100">{currentTip.title}</h3>
                      <p className="text-sm text-cyan-200/80">{currentTip.description}</p>
                    </div>
                  </div>

                  {showTips && (
                    <div className="space-y-2">
                      <h4 className="text-sm font-semibold text-cyan-100 flex items-center">
                        <Lightbulb className="w-4 h-4 text-cyan-400 mr-1" />
                        Tips for This Page:
                      </h4>
                      <ul className="space-y-1">
                        {currentTip.tips.map((tip, index) => (
                          <li key={index} className="text-sm text-cyan-200/80 flex items-start space-x-2">
                            <span className="text-cyan-400 mt-1">•</span>
                            <span>{tip}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              )}

              {/* Learning Journey Steps */}
              <div className="space-y-3">
                <h3 className="text-sm font-semibold text-cyan-100">Learning Path</h3>
                <div className="space-y-2">
                  {learningJourney.map((step, index) => {
                    const isCurrent = step.path === pathname;
                    const isPast = step.isCompleted;
                    const isFuture = !isPast && !isCurrent;

                    return (
                      <motion.div
                        key={step.id}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: index * 0.1 }}
                        className="flex items-center space-x-3 p-3 rounded-lg transition-colors border"
                        style={{
                          background: isCurrent 
                            ? 'rgba(0, 255, 255, 0.15)' 
                            : isPast 
                              ? 'rgba(34, 211, 238, 0.1)'
                              : 'rgba(0, 255, 255, 0.05)',
                          borderColor: isCurrent 
                            ? 'rgba(0, 255, 255, 0.4)' 
                            : isPast 
                              ? 'rgba(34, 211, 238, 0.3)'
                              : 'rgba(0, 255, 255, 0.2)'
                        }}
                      >
                        <div className="flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-white"
                          style={{
                            background: isPast 
                              ? 'rgba(34, 211, 238, 0.8)'
                              : isCurrent
                                ? 'rgba(0, 255, 255, 0.8)'
                                : 'rgba(100, 116, 139, 0.6)'
                          }}>
                          {isPast ? (
                            <CheckCircle className="w-4 h-4" />
                          ) : (
                            <span className="text-xs font-bold">{step.order}</span>
                          )}
                        </div>

                        <div className="flex-1">
                          <div className="flex items-center space-x-2">
                            <step.icon className={`w-4 h-4 ${
                              isCurrent ? 'text-cyan-400' : isPast ? 'text-cyan-400' : 'text-cyan-300/60'
                            }`} />
                            <span className={`text-sm font-medium ${
                              isCurrent ? 'text-cyan-100' : isPast ? 'text-cyan-200' : 'text-cyan-200/80'
                            }`}>
                              {step.label}
                            </span>
                          </div>
                          <p className="text-xs text-cyan-300/70 mt-1">
                            {step.description}
                          </p>
                        </div>

                        {isCurrent && (
                          <span className="px-2 py-1 text-xs text-white rounded-full font-semibold" style={{
                            background: 'rgba(0, 255, 255, 0.8)'
                          }}>
                            You are here
                          </span>
                        )}
                      </motion.div>
                    );
                  })}
                </div>
              </div>

              {/* Next Step Suggestion */}
              {(() => {
                const nextStep = getNextStep();
                return nextStep && (
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="p-4 rounded-lg border"
                    style={{
                      background: 'rgba(34, 211, 238, 0.1)',
                      borderColor: 'rgba(34, 211, 238, 0.3)'
                    }}
                  >
                    <div className="flex items-center justify-between mb-2">
                      <h4 className="text-sm font-semibold text-cyan-200">Suggested Next Step</h4>
                      <ArrowRight className="w-4 h-4 text-cyan-400" />
                    </div>
                    <div className="flex items-center space-x-3">
                      <nextStep.icon className="w-5 h-5 text-cyan-400" />
                      <div>
                        <p className="text-sm font-medium text-cyan-100">{nextStep.label}</p>
                        <p className="text-xs text-cyan-200/80">{nextStep.description}</p>
                      </div>
                    </div>
                    <motion.button
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      className="w-full mt-3 px-4 py-2 text-white text-sm font-semibold rounded-lg transition-colors border"
                      style={{
                        background: 'rgba(34, 211, 238, 0.6)',
                        borderColor: 'rgba(34, 211, 238, 0.4)'
                      }}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.background = 'rgba(34, 211, 238, 0.8)';
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.background = 'rgba(34, 211, 238, 0.6)';
                      }}
                    >
                      Go to {nextStep.label}
                    </motion.button>
                  </motion.div>
                );
              })()}

              {/* Quick Actions */}
              <div className="space-y-3">
                <h3 className="text-sm font-semibold text-cyan-100">Quick Actions</h3>
                <div className="grid grid-cols-2 gap-2">
                  <button className="p-3 text-sm rounded-lg transition-colors text-left border" style={{
                    background: 'rgba(0, 255, 255, 0.05)',
                    borderColor: 'rgba(0, 255, 255, 0.2)'
                  }}>
                    <Map className="w-4 h-4 text-cyan-400 mb-1" />
                    <span className="text-xs text-cyan-200/80">Site Map</span>
                  </button>
                  <button className="p-3 text-sm rounded-lg transition-colors text-left border" style={{
                    background: 'rgba(0, 255, 255, 0.05)',
                    borderColor: 'rgba(0, 255, 255, 0.2)'
                  }}>
                    <MessageCircle className="w-4 h-4 text-cyan-400 mb-1" />
                    <span className="text-xs text-cyan-200/80">Get Help</span>
                  </button>
                  <button className="p-3 text-sm rounded-lg transition-colors text-left border" style={{
                    background: 'rgba(0, 255, 255, 0.05)',
                    borderColor: 'rgba(0, 255, 255, 0.2)'
                  }}>
                    <BookOpen className="w-4 h-4 text-cyan-400 mb-1" />
                    <span className="text-xs text-cyan-200/80">Glossary</span>
                  </button>
                  <button className="p-3 text-sm rounded-lg transition-colors text-left border" style={{
                    background: 'rgba(0, 255, 255, 0.05)',
                    borderColor: 'rgba(0, 255, 255, 0.2)'
                  }}>
                    <Info className="w-4 h-4 text-cyan-400 mb-1" />
                    <span className="text-xs text-cyan-200/80">About TCO</span>
