"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import {
  BookOpen,
  CheckCircle,
  ArrowRight,
  User,
  Brain,
  Target,
  Trophy,
  Sparkles,
  Heart,
} from "lucide-react";

interface OnboardingStep {
  id: string;
  title: string;
  description: string;
  icon: React.ComponentType<{ className?: string }>;
  completed: boolean;
  action: () => void;
}

interface OnboardingCoordinatorProps {
  onComplete?: () => void;
}

export function OnboardingCoordinator({ onComplete }: OnboardingCoordinatorProps) {
  const router = useRouter();
  const [currentStep, setCurrentStep] = useState(0);
  const [hasSeenIntro, setHasSeenIntro] = useState(false);

  // Initialize onboarding state
  useEffect(() => {
    const introSeen = localStorage.getItem('tanium-intro-seen') === 'true';
    setHasSeenIntro(introSeen);
  }, []);

  // Onboarding steps
  const steps: OnboardingStep[] = [
    {
      id: 'intro',
      title: 'Welcome to Tanium Learning',
      description: 'Let us introduce you to the most powerful endpoint management platform',
      icon: Heart,
      completed: hasSeenIntro,
      action: () => {
        localStorage.setItem('tanium-intro-seen', 'true');
        setHasSeenIntro(true);
        setCurrentStep(1);
      }
    },
    {
      id: 'beginner-mode',
      title: 'Enable Beginner Mode',
      description: 'Turn on extra guidance, tips, and confidence-building features',
      icon: User,
      completed: localStorage.getItem('tanium-beginner-mode') === 'true',
      action: () => {
        localStorage.setItem('tanium-beginner-mode', 'true');
        setCurrentStep(2);
      }
    },
    {
      id: 'foundation',
      title: 'Start Foundation Learning',
      description: 'Begin with the essentials - no prior Tanium knowledge needed',
      icon: Brain,
      completed: localStorage.getItem('tanium-foundation-started') === 'true',
      action: () => {
        localStorage.setItem('tanium-foundation-started', 'true');
        router.push('/beginner');
        onComplete?.();
      }
    },
  ];

  const completedSteps = steps.filter(step => step.completed).length;
  const progress = (completedSteps / steps.length) * 100;

  if (completedSteps === steps.length) {
    return (
      <div className="text-center space-y-6 p-8">
        <div className="mx-auto w-16 h-16 bg-green-500 rounded-full flex items-center justify-center">
          <Trophy className="h-8 w-8 text-white" />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">You're All Set!</h2>
          <p className="text-gray-300 mb-6">
            Your beginner-friendly learning environment is ready. Let's start your Tanium journey!
          </p>
          <Button 
            onClick={() => router.push('/beginner')}
            className="bg-tanium-accent hover:bg-blue-600"
          >
            <Sparkles className="mr-2 h-4 w-4" />
            Begin Learning
          </Button>
        </div>
      </div>
    );
  }

  const currentStepData = steps[currentStep];

  return (
    <div className="max-w-2xl mx-auto space-y-8">
      {/* Progress Header */}
      <div className="text-center">
        <h1 className="text-3xl font-bold text-white mb-4">Let's Get You Started</h1>
        <p className="text-gray-300 mb-6">
          We'll set up your personalized learning experience in just a few steps
        </p>
        <div className="space-y-2">
          <Progress value={progress} className="h-2" />
          <p className="text-sm text-gray-400">
            Step {currentStep + 1} of {steps.length}
          </p>
        </div>
      </div>

      {/* Current Step */}
      <Card className="glass border-white/10">
        <CardHeader className="text-center">
          <div className="mx-auto w-16 h-16 bg-blue-500 rounded-full flex items-center justify-center mb-4">
            <currentStepData.icon className="h-8 w-8 text-white" />
          </div>
          <CardTitle className="text-2xl text-white">{currentStepData.title}</CardTitle>
          <p className="text-gray-300">{currentStepData.description}</p>
        </CardHeader>
        <CardContent className="text-center">
          {currentStep === 0 && (
            <div className="space-y-4">
              <p className="text-gray-200">
                Tanium helps IT teams see, control, and secure every endpoint instantly. 
                Whether you're completely new to endpoint management or just new to Tanium, 
                we'll guide you every step of the way.
              </p>
              <div className="grid grid-cols-2 gap-4 my-6">
                <div className="bg-white/5 rounded-lg p-4">
                  <Target className="h-6 w-6 text-blue-400 mx-auto mb-2" />
                  <p className="text-sm text-gray-300">Beginner-Friendly</p>
                </div>
                <div className="bg-white/5 rounded-lg p-4">
                  <BookOpen className="h-6 w-6 text-green-400 mx-auto mb-2" />
                  <p className="text-sm text-gray-300">Step-by-Step</p>
                </div>
              </div>
            </div>
          )}

          {currentStep === 1 && (
            <div className="space-y-4">
              <p className="text-gray-200">
                Beginner Mode adds helpful features like:
              </p>
              <ul className="text-left space-y-2 max-w-md mx-auto">
                <li className="flex items-center text-gray-300">
                  <CheckCircle className="h-4 w-4 text-green-400 mr-2" />
                  Extra explanations and context
                </li>
                <li className="flex items-center text-gray-300">
                  <CheckCircle className="h-4 w-4 text-green-400 mr-2" />
                  Confidence-building encouragement
                </li>
                <li className="flex items-center text-gray-300">
                  <CheckCircle className="h-4 w-4 text-green-400 mr-2" />
                  Navigation assistance
                </li>
                <li className="flex items-center text-gray-300">
                  <CheckCircle className="h-4 w-4 text-green-400 mr-2" />
                  Progress celebration
                </li>
              </ul>
            </div>
          )}

          {currentStep === 2 && (
            <div className="space-y-4">
              <p className="text-gray-200">
                Your foundation learning covers everything you need to know about Tanium, 
                starting from the very beginning. Perfect for complete beginners!
              </p>
              <div className="bg-gradient-to-r from-blue-500/20 to-cyan-500/20 rounded-lg p-4 border border-blue-500/30">
                <p className="text-blue-100 text-sm">
                  <strong>5 modules • 85 minutes • No prerequisites</strong>
                </p>
              </div>
            </div>
          )}

          <Button
            onClick={currentStepData.action}
            className="w-full bg-tanium-accent hover:bg-blue-600 mt-6"
            size="lg"
          >
            {currentStep === steps.length - 1 ? (
              <>
                <BookOpen className="mr-2 h-4 w-4" />
                Start Learning
              </>
            ) : (
              <>
                Continue
                <ArrowRight className="ml-2 h-4 w-4" />
              </>
            )}
          </Button>
        </CardContent>
      </Card>

      {/* Step Overview */}
      <div className="grid grid-cols-3 gap-4">
        {steps.map((step, index) => (
          <Card 
            key={step.id} 
            className={`glass border-white/10 ${
              index === currentStep ? 'border-blue-500/50 bg-blue-500/10' : ''
            } ${step.completed ? 'border-green-500/50 bg-green-500/5' : ''}`}
          >
            <CardContent className="p-4 text-center">
              <div className={`mx-auto w-8 h-8 rounded-full flex items-center justify-center mb-2 ${
                step.completed ? 'bg-green-500' : index === currentStep ? 'bg-blue-500' : 'bg-gray-600'
              }`}>
                {step.completed ? (
                  <CheckCircle className="h-4 w-4 text-white" />
                ) : (
                  <step.icon className="h-4 w-4 text-white" />
                )}
              </div>
              <p className="text-xs text-gray-300 font-medium">{step.title}</p>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useCallback, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { 
  KnowledgeAssessment, 
  KnowledgeQuestion, 
  AssessmentResult,
  LearningPath,
  LEARNING_PATHS 
} from '@/lib/knowledge-check';
import {
  CheckCircle,
  XCircle,
  Clock,
  Brain,
  Target,
  TrendingUp,
  AlertTriangle,
  BookOpen,
  Zap,
  Award,
  ArrowRight,
  RotateCcw,
  Lightbulb
} from 'lucide-react';

interface PrerequisitesCheckProps {
  onComplete: (result: AssessmentResult) => void;
  onSkip?: () => void;
}

interface QuestionState {
  currentQuestionIndex: number;
  selectedAnswer: number | null;
  showFeedback: boolean;
  isCorrect: boolean;
  explanation: string;
}

interface AssessmentStats {
  correct: number;
  total: number;
  timeStarted: Date;
  timePerQuestion: number[];
}

export const PrerequisitesCheck: React.FC<PrerequisitesCheckProps> = ({ 
  onComplete, 
  onSkip 
}) => {
  const [assessment] = useState(() => new KnowledgeAssessment());
  const [questions, setQuestions] = useState<KnowledgeQuestion[]>([]);
  const [questionState, setQuestionState] = useState<QuestionState>({
    currentQuestionIndex: 0,
    selectedAnswer: null,
    showFeedback: false,
    isCorrect: false,
    explanation: ''
  });
  const [assessmentStats, setAssessmentStats] = useState<AssessmentStats>({
    correct: 0,
    total: 0,
    timeStarted: new Date(),
    timePerQuestion: []
  });
  const [isStarted, setIsStarted] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [result, setResult] = useState<AssessmentResult | null>(null);
  const [questionStartTime, setQuestionStartTime] = useState<Date>(new Date());

  // Initialize questions when component mounts
  useEffect(() => {
    const assessmentQuestions = assessment.getAssessmentQuestions(10);
    setQuestions(assessmentQuestions);
    setAssessmentStats(prev => ({ ...prev, total: assessmentQuestions.length }));
  }, [assessment]);

  const startAssessment = useCallback(() => {
    setIsStarted(true);
    setQuestionStartTime(new Date());
    setAssessmentStats(prev => ({ ...prev, timeStarted: new Date() }));
  }, []);

  const selectAnswer = useCallback((answerIndex: number) => {
    if (questionState.showFeedback) return;

    const currentQuestion = questions[questionState.currentQuestionIndex];
    if (!currentQuestion) return;

    // Record time taken for this question
    const timeNow = new Date();
    const timeTaken = timeNow.getTime() - questionStartTime.getTime();

    // Record answer in assessment
    const feedback = assessment.recordAnswer(currentQuestion.id, answerIndex);

    // Update stats
    setAssessmentStats(prev => ({
      ...prev,
      correct: prev.correct + (feedback.correct ? 1 : 0),
      timePerQuestion: [...prev.timePerQuestion, timeTaken]
    }));

    // Show feedback
    setQuestionState(prev => ({
      ...prev,
      selectedAnswer: answerIndex,
      showFeedback: true,
      isCorrect: feedback.correct,
      explanation: feedback.explanation
    }));
  }, [questionState, questions, assessment, questionStartTime]);

  const nextQuestion = useCallback(() => {
    const nextIndex = questionState.currentQuestionIndex + 1;

    if (nextIndex >= questions.length) {
      // Assessment complete
      const assessmentResult = assessment.calculateResults(questions);
      setResult(assessmentResult);
      setIsCompleted(true);
      onComplete(assessmentResult);
    } else {
      // Move to next question
      setQuestionState({
        currentQuestionIndex: nextIndex,
        selectedAnswer: null,
        showFeedback: false,
        isCorrect: false,
        explanation: ''
      });
      setQuestionStartTime(new Date());
    }
  }, [questionState.currentQuestionIndex, questions, assessment, onComplete]);

  const restartAssessment = useCallback(() => {
    assessment.reset();
    const newQuestions = assessment.getAssessmentQuestions(10);
    setQuestions(newQuestions);
    setQuestionState({
      currentQuestionIndex: 0,
      selectedAnswer: null,
      showFeedback: false,
      isCorrect: false,
      explanation: ''
    });
    setAssessmentStats({
      correct: 0,
      total: newQuestions.length,
      timeStarted: new Date(),
      timePerQuestion: []
    });
    setIsStarted(false);
    setIsCompleted(false);
    setResult(null);
  }, [assessment]);

  const currentQuestion = questions[questionState.currentQuestionIndex];
  const progress = questions.length > 0 ? ((questionState.currentQuestionIndex + (questionState.showFeedback ? 1 : 0)) / questions.length) * 100 : 0;

  // Introduction screen
  if (!isStarted && !isCompleted) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-4xl mx-auto p-6"
      >
        <Card className="bg-gradient-to-br from-blue-50 to-sky-50 border-blue-200">
          <CardContent className="p-8">
            <div className="text-center mb-8">
              <div className="inline-flex items-center justify-center w-16 h-16 bg-blue-100 rounded-full mb-4">
                <Brain className="h-8 w-8 text-blue-600" />
              </div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">
                Knowledge Assessment
              </h1>
              <p className="text-lg text-gray-600 max-w-2xl mx-auto">
                Let's determine your current knowledge level and recommend the perfect learning path for your TCO certification journey.
              </p>
            </div>

            <div className="grid md:grid-cols-2 gap-6 mb-8">
              <div className="space-y-4">
                <div className="flex items-start space-x-3">
                  <CheckCircle className="h-5 w-5 text-green-500 mt-1" />
                  <div>
                    <h3 className="font-semibold text-gray-900">Personalized Learning Path</h3>
                    <p className="text-sm text-gray-600">Get recommendations based on your current knowledge level</p>
                  </div>
                </div>
                <div className="flex items-start space-x-3">
                  <Target className="h-5 w-5 text-blue-500 mt-1" />
                  <div>
                    <h3 className="font-semibold text-gray-900">Focused Study Plan</h3>
                    <p className="text-sm text-gray-600">Identify your strengths and areas for improvement</p>
                  </div>
                </div>
                <div className="flex items-start space-x-3">
                  <Clock className="h-5 w-5 text-cyan-500 mt-1" />
                  <div>
                    <h3 className="font-semibold text-gray-900">Quick Assessment</h3>
                    <p className="text-sm text-gray-600">Only 10 questions, takes about 5-7 minutes</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg p-6 border">
                <h3 className="font-semibold text-gray-900 mb-4">Assessment Coverage</h3>
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">Basic IT Concepts</span>
                    <Badge variant="outline">Foundation</Badge>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">Networking Fundamentals</span>
                    <Badge variant="outline">Intermediate</Badge>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">Security Principles</span>
                    <Badge variant="outline">Intermediate</Badge>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">Systems Administration</span>
                    <Badge variant="outline">Advanced</Badge>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600">Enterprise Operations</span>
                    <Badge variant="outline">Advanced</Badge>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex justify-center space-x-4">
              <Button 
                onClick={startAssessment}
                size="lg"
                className="bg-blue-600 hover:bg-blue-700 text-white px-8"
              >
                <Brain className="h-4 w-4 mr-2" />
                Start Assessment
              </Button>
              {onSkip && (
                <Button 
                  onClick={onSkip}
                  variant="outline"
                  size="lg"
                  className="px-8"
                >
                  Skip Assessment
                </Button>
              )}
            </div>

            <div className="mt-6 text-center">
              <p className="text-xs text-gray-500">
                Don't worry - there's no pressure! This helps us customize your learning experience.
              </p>
            </div>
          </CardContent>
        </Card>
      </motion.div>
    );
  }

  // Results screen
  if (isCompleted && result) {
    const pathConfidenceColor = result.recommendedPath.confidence >= 90 ? 'green' : 
                               result.recommendedPath.confidence >= 70 ? 'blue' : 'orange';

    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="max-w-5xl mx-auto p-6"
      >
        <Card className="bg-gradient-to-br from-green-50 to-blue-50 border-green-200">
          <CardContent className="p-8">
            <div className="text-center mb-8">
              <div className="inline-flex items-center justify-center w-16 h-16 bg-green-100 rounded-full mb-4">
                <Award className="h-8 w-8 text-green-600" />
              </div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">
                Assessment Complete!
              </h1>
              <p className="text-lg text-gray-600">
                Here's your personalized learning path recommendation
              </p>
            </div>

            {/* Score Overview */}
            <div className="grid md:grid-cols-3 gap-6 mb-8">
              <Card>
                <CardContent className="p-6 text-center">
                  <div className="text-3xl font-bold text-blue-600 mb-1">
                    {result.percentage}%
                  </div>
                  <p className="text-sm text-gray-600">Overall Score</p>
                  <p className="text-xs text-gray-500 mt-1">
                    {result.totalScore} of {result.maxScore} points
                  </p>
                </CardContent>
              </Card>

              <Card>
                <CardContent className="p-6 text-center">
                  <div className="text-3xl font-bold text-green-600 mb-1">
                    {assessmentStats.correct}
                  </div>
                  <p className="text-sm text-gray-600">Correct Answers</p>
                  <p className="text-xs text-gray-500 mt-1">
                    out of {assessmentStats.total} questions
                  </p>
                </CardContent>
              </Card>

              <Card>
                <CardContent className="p-6 text-center">
                  <div className="text-3xl font-bold text-cyan-600 mb-1">
                    {Math.round(assessmentStats.timePerQuestion.reduce((a, b) => a + b, 0) / assessmentStats.timePerQuestion.length / 1000)}s
                  </div>
                  <p className="text-sm text-gray-600">Avg. Time</p>
                  <p className="text-xs text-gray-500 mt-1">
                    per question
                  </p>
                </CardContent>
              </Card>
            </div>

            {/* Recommended Learning Path */}
            <Card className="mb-6 border-2 border-blue-200 bg-blue-50">
              <CardContent className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center space-x-3">
                    <div className={`inline-flex items-center justify-center w-10 h-10 rounded-full bg-${pathConfidenceColor}-100`}>
                      <Target className={`h-5 w-5 text-${pathConfidenceColor}-600`} />
                    </div>
                    <div>
                      <h3 className="text-xl font-semibold text-gray-900">
                        {result.recommendedPath.name}
                      </h3>
                      <p className="text-sm text-gray-600">
                        {result.recommendedPath.description}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <Badge className={`bg-${pathConfidenceColor}-100 text-${pathConfidenceColor}-800 border-${pathConfidenceColor}-200`}>
                      {result.recommendedPath.confidence}% confidence
                    </Badge>
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <h4 className="font-semibold text-gray-900 mb-2">Duration & Difficulty</h4>
                    <div className="space-y-2">
                      <div className="flex items-center space-x-2">
                        <Clock className="h-4 w-4 text-gray-500" />
                        <span className="text-sm text-gray-600">{result.recommendedPath.duration}</span>
                      </div>
                      <div className="flex items-center space-x-2">
