  }, [progress.currentStep]);

  const currentStep = steps[progress.currentStep];
  const progressPercentage = Math.round(((progress.currentStep + 1) / steps.length) * 100);
  const isLastStep = progress.currentStep === steps.length - 1;
  const isFirstStep = progress.currentStep === 0;

  return (
    <div className={cn("mx-auto max-w-4xl space-y-6", className)}>
      {/* Progress Header */}
      <div className="text-center">
        <h1 className="mb-2 text-3xl font-bold text-white">Welcome to TCO Certification</h1>
        <p className="mb-4 text-gray-300">Foundation building for complete beginners</p>
        <div className="flex items-center justify-center gap-4 mb-4">
          <Progress value={progressPercentage} className="h-2 w-48" />
          <Badge variant="outline" className="text-tanium-accent border-tanium-accent">
            Step {progress.currentStep + 1} of {steps.length}
          </Badge>
        </div>
      </div>

      {/* Main Content Card */}
      <Card className={cn("glass border-2", currentStep.bgColor, "border-white/10")}>
        <CardHeader>
          <div className="flex items-center gap-3">
            <div className={cn("rounded-full p-2 border-2", currentStep.bgColor, "border-current")}>
              <currentStep.icon className={cn("h-6 w-6", currentStep.color)} />
            </div>
            <div>
              <CardTitle className="text-white">{currentStep.title}</CardTitle>
              <p className="text-sm text-gray-400">{currentStep.subtitle}</p>
            </div>
          </div>
        </CardHeader>

        <CardContent>
          {currentStep.content}
        </CardContent>
      </Card>

      {/* Navigation Controls */}
      <div className="flex items-center justify-between">
        <Button
          variant="outline"
          onClick={goToPreviousStep}
          disabled={isFirstStep}
          className="border-white/20 text-white hover:bg-white/10"
        >
          <ArrowLeft className="mr-2 h-4 w-4" />
          Previous
        </Button>

        <div className="flex gap-3">
          {onSkip && (
            <Button
              variant="ghost"
              onClick={onSkip}
              className="text-gray-400 hover:text-white"
            >
              Skip Introduction
            </Button>
          )}

          {isLastStep ? (
            <Button
              onClick={finishOnboarding}
              className="bg-tanium-accent hover:bg-blue-600"
              disabled={!progress.completedSteps.has(progress.currentStep)}
            >
              <BookOpen className="mr-2 h-4 w-4" />
              Start Learning Journey
            </Button>
          ) : (
            <Button
              onClick={() => {
                completeCurrentStep();
                goToNextStep();
              }}
              className="bg-tanium-accent hover:bg-blue-600"
            >
              Continue
              <ArrowRight className="ml-2 h-4 w-4" />
            </Button>
          )}
        </div>
      </div>

      {/* Step Indicator Dots */}
      <div className="flex justify-center gap-2">
        {steps.map((_, index) => (
          <div
            key={index}
            className={cn(
              "h-2 w-2 rounded-full transition-all",
              index === progress.currentStep
                ? "bg-tanium-accent w-6"
                : progress.completedSteps.has(index)
                ? "bg-green-400"
                : "bg-gray-600"
            )}
          />
        ))}
      </div>
    </div>
  );
}

/**
 * Module 3 Practice Session Component
 * Enhanced practice session interface for the expanded 9-section structure
 */

"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import { usePractice } from "@/contexts/PracticeContext";
import { useAuth } from "@/contexts/AuthContext";
import {
  Module3Section,
  MODULE_3_SECTIONS,
  getSectionCoverage,
  getModule3LearningPath
} from "@/lib/module3-section-definitions";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Slider } from "@/components/ui/slider";
import { Separator } from "@/components/ui/separator";
import {
  Play,
  Target,
  Brain,
  Clock,
  TrendingUp,
  Settings,
  CheckCircle,
  AlertCircle,
  BookOpen,
  Zap
} from "lucide-react";
import { cn } from "@/lib/utils";

interface Module3PracticeSessionProps {
  initialSectionId?: Module3Section;
  autoStart?: boolean;
  className?: string;
}

export function Module3PracticeSession({
  initialSectionId,
  autoStart = false,
  className
}: Module3PracticeSessionProps) {
  const router = useRouter();
  const { user } = useAuth();
  const {
    startModule3SectionPractice,
    startModule3ComprehensivePractice,
    getModule3SectionProgress,
    getModule3Recommendations,
    validateModule3SectionAvailability,
    currentSession,
    isLoading
  } = usePractice();

  // Session Configuration State
  const [sessionType, setSessionType] = useState<"single" | "multiple" | "comprehensive">("single");
  const [selectedSections, setSelectedSections] = useState<Module3Section[]>(
    initialSectionId ? [initialSectionId] : []
  );
  const [questionCount, setQuestionCount] = useState<number[]>([15]);
  const [timeLimit, setTimeLimit] = useState<number[]>([30]);
  const [includePrerequisites, setIncludePrerequisites] = useState(true);
  const [includeRelatedSections, setIncludeRelatedSections] = useState(false);
  const [adaptiveDifficulty, setAdaptiveDifficulty] = useState(true);
  const [focusOnGaps, setFocusOnGaps] = useState(true);
  const [randomizeOrder, setRandomizeOrder] = useState(true);
  const [showAdvanced, setShowAdvanced] = useState(false);

  // Progress and Recommendations
  const [sectionProgress, setSectionProgress] = useState<Partial<Record<Module3Section, any>>>({});
  const [recommendations, setRecommendations] = useState<any>(null);
  const [availabilitySummary, setAvailabilitySummary] = useState<Partial<Record<Module3Section, any>>>({});

  const learningPath = getModule3LearningPath();

  // Load user progress and recommendations
  useEffect(() => {
    if (!user) return;

    try {
      const progress = getModule3SectionProgress();
      setSectionProgress(progress);

      const recs = getModule3Recommendations();
      setRecommendations(recs);

      // Auto-select recommended sections if none selected
      if (selectedSections.length === 0 && recs.prioritySections.length > 0) {
        setSelectedSections([recs.prioritySections[0]]);
      }
    } catch (error) {
      console.error("Failed to load Module 3 progress:", error);
    }
  }, [user, getModule3SectionProgress, getModule3Recommendations]);

  // Validate section availability
  useEffect(() => {
    const summary: Partial<Record<Module3Section, any>> = {};
    learningPath.forEach(sectionId => {
      try {
        summary[sectionId] = validateModule3SectionAvailability(sectionId);
      } catch (error) {
        console.error(`Failed to validate section ${sectionId}:`, error);
        summary[sectionId] = { available: false, questionCount: 0, coverage: 0 };
      }
    });
    setAvailabilitySummary(summary);
  }, [validateModule3SectionAvailability]);

  // Auto-start session if requested
  useEffect(() => {
    if (autoStart && initialSectionId && selectedSections.includes(initialSectionId)) {
      handleStartSession();
    }
  }, [autoStart, initialSectionId]);

  const handleSectionToggle = useCallback((sectionId: Module3Section, checked: boolean) => {
    setSelectedSections(prev => {
      if (checked) {
        return [...prev, sectionId];
      } else {
        return prev.filter(id => id !== sectionId);
      }
    });
  }, []);

  const handleStartSession = useCallback(async () => {
    if (selectedSections.length === 0) {
      alert("Please select at least one section to practice.");
      return;
    }

    try {
      let success = false;

      if (sessionType === "single" && selectedSections.length === 1) {
        success = await startModule3SectionPractice(selectedSections[0], {
          includePrerequisites,
          includeRelatedSections,
          adaptiveDifficulty,
          focusOnGaps,
          questionCount: questionCount[0]
        });
      } else {
        success = await startModule3ComprehensivePractice(selectedSections, {
          questionsPerSection: Math.floor(questionCount[0] / selectedSections.length),
          randomizeOrder,
          focusOnWeakAreas: focusOnGaps,
          timeLimit: timeLimit[0]
        });
      }

      if (success && currentSession) {
        router.push(`/practice/session/${currentSession.id}`);
      }
    } catch (error) {
      console.error("Failed to start Module 3 practice session:", error);
      alert("Failed to start practice session. Please try again.");
    }
  }, [
    selectedSections,
    sessionType,
    questionCount,
    timeLimit,
    includePrerequisites,
    includeRelatedSections,
    adaptiveDifficulty,
    focusOnGaps,
    randomizeOrder,
    startModule3SectionPractice,
    startModule3ComprehensivePractice,
    currentSession,
    router
  ]);

  const getSectionStatusIcon = (sectionId: Module3Section) => {
    const availability = availabilitySummary[sectionId];
    const progress = sectionProgress[sectionId];

    if (!availability?.available) {
      return <AlertCircle className="w-4 h-4 text-red-500" />;
    }
    if (progress?.accuracy >= 0.8) {
      return <CheckCircle className="w-4 h-4 text-green-500" />;
    }
    if (progress?.questionsAttempted > 0) {
      return <TrendingUp className="w-4 h-4 text-blue-500" />;
    }
    return <Target className="w-4 h-4 text-gray-400" />;
  };

  const getEstimatedTime = () => {
    if (sessionType === "single") {
      return Math.ceil(questionCount[0] * 1.5); // 1.5 minutes per question
    }
    return Math.ceil((questionCount[0] / selectedSections.length) * selectedSections.length * 1.5);
  };

  return (
    <div className={cn("space-y-6", className)}>
      {/* Header with Recommendations */}
      {recommendations && (
        <Card className="border-blue-200 bg-blue-50/50">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Brain className="w-5 h-5 text-blue-600" />
              <CardTitle className="text-lg">Smart Recommendations</CardTitle>
            </div>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex items-center gap-2">
              <Badge variant="outline" className="text-blue-700 border-blue-300">
                {recommendations.recommendedSessionType}
              </Badge>
              <span className="text-sm text-muted-foreground">
                Suggested duration: {recommendations.suggestedDuration} minutes
              </span>
            </div>
            <div className="text-sm">
              <span className="font-medium">Priority sections: </span>
              {recommendations.prioritySections.map((sectionId: Module3Section, index: number) => (
                <span key={sectionId}>
                  {MODULE_3_SECTIONS[sectionId].title}
                  {index < recommendations.prioritySections.length - 1 && ", "}
                </span>
              ))}
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                setSelectedSections(recommendations.prioritySections);
                setQuestionCount([15]);
                setTimeLimit([recommendations.suggestedDuration]);
              }}
            >
              <Zap className="w-3 h-3 mr-1" />
              Use Smart Recommendations
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Session Configuration */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Settings className="w-5 h-5" />
            Practice Session Configuration
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Session Type Selection */}
          <div className="space-y-2">
            <label className="text-sm font-medium">Session Type</label>
            <Select value={sessionType} onValueChange={(value: any) => setSessionType(value)}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="single">Single Section Focus</SelectItem>
                <SelectItem value="multiple">Multiple Sections</SelectItem>
                <SelectItem value="comprehensive">Comprehensive Review</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Section Selection */}
          <div className="space-y-3">
            <label className="text-sm font-medium">Select Sections</label>
            <div className="grid grid-cols-1 gap-2 max-h-64 overflow-y-auto">
              {learningPath.map(sectionId => {
                const section = MODULE_3_SECTIONS[sectionId];
                const availability = availabilitySummary[sectionId];
                const progress = sectionProgress[sectionId];
                const coverage = getSectionCoverage(sectionId);
                const isSelected = selectedSections.includes(sectionId);

                return (
                  <div
                    key={sectionId}
                    className={cn(
                      "flex items-center space-x-3 p-3 rounded-lg border transition-colors",
                      isSelected ? "bg-accent border-accent" : "hover:bg-muted/50",
                      !availability?.available && "opacity-50"
                    )}
                  >
                    <Checkbox
                      checked={isSelected}
                      onCheckedChange={(checked) => handleSectionToggle(sectionId, checked as boolean)}
                      disabled={!availability?.available}
                    />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        {getSectionStatusIcon(sectionId)}
                        <span className="font-medium text-sm">{section.title}</span>
                        <Badge variant="outline" className="text-xs">
                          {section.difficulty}
                        </Badge>
                      </div>
                      <div className="flex items-center gap-4 mt-1">
                        <span className="text-xs text-muted-foreground">
                          {availability?.questionCount || 0} questions ({coverage}% coverage)
                        </span>
                        {progress && (
                          <span className="text-xs text-muted-foreground">
                            Last: {Math.round(progress.accuracy * 100)}% accuracy
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Basic Configuration */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Questions: {questionCount[0]}</label>
              <Slider
                value={questionCount}
                onValueChange={setQuestionCount}
                max={50}
                min={5}
                step={5}
                className="w-full"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Time Limit: {timeLimit[0]} min</label>
              <Slider
                value={timeLimit}
                onValueChange={setTimeLimit}
                max={60}
                min={10}
                step={5}
                className="w-full"
              />
            </div>
          </div>

          {/* Advanced Options */}
          <div className="space-y-3">
            <Button
              variant="ghost"
              onClick={() => setShowAdvanced(!showAdvanced)}
              className="w-full justify-between"
            >
              Advanced Options
              <span className={cn("transition-transform", showAdvanced && "rotate-180")}>▼</span>
            </Button>

            {showAdvanced && (
              <div className="space-y-3 pt-2 border-t">
                <div className="grid grid-cols-2 gap-3">
                  <label className="flex items-center space-x-2">
                    <Checkbox
                      checked={includePrerequisites}
                      onCheckedChange={(checked) => setIncludePrerequisites(checked === true)}
                    />
                    <span className="text-sm">Include Prerequisites</span>
                  </label>
                  <label className="flex items-center space-x-2">
                    <Checkbox
                      checked={includeRelatedSections}
                      onCheckedChange={(checked) => setIncludeRelatedSections(checked === true)}
                    />
                    <span className="text-sm">Include Related Sections</span>
                  </label>
                  <label className="flex items-center space-x-2">
                    <Checkbox
                      checked={adaptiveDifficulty}
                      onCheckedChange={(checked) => setAdaptiveDifficulty(checked === true)}
                    />
                    <span className="text-sm">Adaptive Difficulty</span>
                  </label>
                  <label className="flex items-center space-x-2">
                    <Checkbox
                      checked={focusOnGaps}
                      onCheckedChange={(checked) => setFocusOnGaps(checked === true)}
                    />
                    <span className="text-sm">Focus on Weak Areas</span>
                  </label>
                  <label className="flex items-center space-x-2">
                    <Checkbox
                      checked={randomizeOrder}
                      onCheckedChange={(checked) => setRandomizeOrder(checked === true)}
                    />
                    <span className="text-sm">Randomize Order</span>
                  </label>
                </div>
              </div>
            )}
          </div>

          <Separator />

          {/* Session Summary */}
          <div className="bg-muted/30 p-4 rounded-lg space-y-2">
            <h4 className="font-medium">Session Summary</h4>
            <div className="grid grid-cols-3 gap-4 text-sm">
              <div>
                <span className="text-muted-foreground">Sections:</span>
                <span className="ml-2 font-medium">{selectedSections.length}</span>
              </div>
              <div>
                <span className="text-muted-foreground">Questions:</span>
                <span className="ml-2 font-medium">{questionCount[0]}</span>
              </div>
              <div>
                <span className="text-muted-foreground">Estimated Time:</span>
                <span className="ml-2 font-medium">{getEstimatedTime()} min</span>
              </div>
            </div>
          </div>

          {/* Start Button */}
          <Button
            onClick={handleStartSession}
            disabled={selectedSections.length === 0 || isLoading}
            className="w-full"
            size="lg"
          >
            {isLoading ? (
              "Starting..."
            ) : (
              <>
                <Play className="w-4 h-4 mr-2" />
                Start Practice Session
              </>
            )}
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Clock, CheckCircle, XCircle, AlertCircle, BookOpen } from "lucide-react";
import type { PracticeQuestion as PracticeQuestionType } from "@/types/practice-session";
import { TCODomain, Difficulty } from "@/types/exam";
import { cn } from "@/lib/utils";

interface PracticeQuestionProps {
  question: PracticeQuestionType;
  questionNumber: number;
  totalQuestions: number;
  onAnswer: (questionId: string, choiceId: string) => void;
  onNext?: () => void;
  onPrevious?: () => void;
  showFeedback?: boolean;
  canGoNext?: boolean;
  canGoPrevious?: boolean;
  timeRemaining?: number;
  className?: string;
}

const DOMAIN_COLORS: Record<TCODomain, string> = {
  [TCODomain.ASKING_QUESTIONS]: "bg-blue-100 text-blue-700 border-blue-200",
  [TCODomain.REFINING_QUESTIONS]: "bg-green-100 text-green-700 border-green-200",
  [TCODomain.REFINING_TARGETING]: "bg-green-100 text-green-700 border-green-200", // Alias uses same color
  [TCODomain.TAKING_ACTION]: "bg-orange-100 text-orange-700 border-orange-200",
  [TCODomain.NAVIGATION_MODULES]: "bg-cyan-100 text-cyan-700 border-cyan-200",
  [TCODomain.REPORTING_EXPORT]: "bg-teal-100 text-teal-700 border-teal-200",
  // Additional domain colors
  [TCODomain.SECURITY]: "bg-red-100 text-red-700 border-red-200",
  [TCODomain.FUNDAMENTALS]: "bg-sky-100 text-sky-700 border-sky-200",
  [TCODomain.TROUBLESHOOTING]: "bg-pink-100 text-pink-700 border-pink-200",
};

const DIFFICULTY_COLORS: Record<Difficulty, string> = {
  [Difficulty.BEGINNER]: "bg-gray-100 text-gray-600",
  [Difficulty.INTERMEDIATE]: "bg-yellow-100 text-yellow-700",
  [Difficulty.ADVANCED]: "bg-red-100 text-red-700",
  [Difficulty.EXPERT]: "bg-black text-white",
};

export function PracticeQuestion({
  question,
  questionNumber,
  totalQuestions,
  onAnswer,
  onNext,
  onPrevious,
  showFeedback = false,
  canGoNext = false,
  canGoPrevious = false,
  timeRemaining,
  className,
}: PracticeQuestionProps) {
  const [selectedChoice, setSelectedChoice] = useState<string>(question.userAnswer || "");
  const [questionStartTime] = useState<number>(Date.now());
  const [timeSpent, setTimeSpent] = useState<number>(0);

  // Track time spent on current question
  useEffect(() => {
    const interval = setInterval(() => {
      setTimeSpent(Math.floor((Date.now() - questionStartTime) / 1000));
    }, 1000);

    return () => clearInterval(interval);
  }, [questionStartTime]);

  const handleChoiceSelect = (choiceId: string) => {
    setSelectedChoice(choiceId);
    onAnswer(question.id, choiceId);
  };

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  const getChoiceIcon = (choiceId: string) => {
    if (!showFeedback || !question.userAnswer) return null;

    if (choiceId === question.correctAnswerId) {
      return <CheckCircle className="h-4 w-4 text-green-600" />;
    } else if (choiceId === question.userAnswer && choiceId !== question.correctAnswerId) {
      return <XCircle className="h-4 w-4 text-red-600" />;
    }

    return null;
  };

  const getChoiceStyle = (choiceId: string) => {
    if (!showFeedback || !question.userAnswer) {
      return selectedChoice === choiceId
        ? "border-primary bg-primary/5"
        : "border-muted hover:border-muted-foreground/50";
    }

    if (choiceId === question.correctAnswerId) {
      return "border-green-500 bg-green-50";
    } else if (choiceId === question.userAnswer && choiceId !== question.correctAnswerId) {
      return "border-red-500 bg-red-50";
    }

    return "border-muted opacity-60";
  };

  const progressPercentage = (questionNumber / totalQuestions) * 100;

  return (
    <div className={cn("space-y-6", className)}>
      {/* Progress Header */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-muted-foreground">
              Question {questionNumber} of {totalQuestions}
            </span>
            <Progress value={progressPercentage} className="h-2 w-32" />
          </div>

          <div className="flex items-center gap-4">
            {timeRemaining !== undefined && (
              <div className="flex items-center gap-1 text-sm">
                <Clock className="h-4 w-4" />
                <span
                  className={cn(
                    timeRemaining < 60 ? "font-medium text-red-600" : "text-muted-foreground"
                  )}
                >
                  {formatTime(timeRemaining)}
                </span>
              </div>
            )}

            <div className="flex items-center gap-1 text-sm text-muted-foreground">
              <Clock className="h-4 w-4" />
              <span>{formatTime(timeSpent)}</span>
            </div>
          </div>
        </div>

        {/* Question Metadata */}
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="outline" className={DOMAIN_COLORS[question.domain]}>
            {question.domain}
          </Badge>
          <Badge variant="outline" className={DIFFICULTY_COLORS[question.difficulty]}>
            {question.difficulty}
          </Badge>
          {question.tags?.map((tag) => (
            <Badge key={tag} variant="secondary" className="text-xs">
              {tag}
            </Badge>
          ))}
        </div>
      </div>

      {/* Question Card */}
      <Card>
        <CardHeader>
          <CardTitle className="text-xl leading-relaxed">{question.question}</CardTitle>
          {question.category && <CardDescription>Category: {question.category}</CardDescription>}
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Choices */}
          <RadioGroup
            value={selectedChoice}
            onValueChange={handleChoiceSelect}
            disabled={showFeedback}
            className="space-y-3"
          >
            {question.choices.map((choice) => (
              <div
                key={choice.id}
                className={cn(
                  "flex items-center space-x-3 rounded-lg border-2 p-4 transition-colors",
                  getChoiceStyle(choice.id)
                )}
              >
                <RadioGroupItem value={choice.id} id={choice.id} disabled={showFeedback} />
                <Label htmlFor={choice.id} className="flex-1 cursor-pointer leading-relaxed">
                  {choice.text}
                </Label>
                {getChoiceIcon(choice.id)}
              </div>
            ))}
          </RadioGroup>

          {/* Feedback */}
          {showFeedback && question.userAnswer && (
            <div className="space-y-4 border-t pt-4">
              <div
                className={cn(
                  "flex items-start gap-3 rounded-lg p-4",
                  question.isCorrect
                    ? "border border-green-200 bg-green-50"
                    : "border border-red-200 bg-red-50"
                )}
              >
                {question.isCorrect ? (
                  <CheckCircle className="mt-0.5 h-5 w-5 text-green-600" />
                ) : (
                  <XCircle className="mt-0.5 h-5 w-5 text-red-600" />
                )}
                <div>
                  <p
                    className={cn(
                      "font-medium",
                      question.isCorrect ? "text-green-800" : "text-red-800"
                    )}
                  >
                    {question.isCorrect ? "Correct!" : "Incorrect"}
                  </p>
                  {question.explanation && (
                    <p
                      className={cn(
                        "mt-1 text-sm",
                        question.isCorrect ? "text-green-700" : "text-red-700"
                      )}
                    >
                      {question.explanation}
                    </p>
                  )}
                </div>
              </div>

              {/* Additional Resources */}
              {(question.studyGuideRef || question.officialRef) && (
                <div className="flex items-start gap-3 rounded-lg border border-blue-200 bg-blue-50 p-4">
                  <BookOpen className="mt-0.5 h-5 w-5 text-blue-600" />
                  <div className="space-y-1">
                    <p className="font-medium text-blue-800">Additional Resources</p>
                    {question.studyGuideRef && (
                      <p className="text-sm text-blue-700">Study Guide: {question.studyGuideRef}</p>
                    )}
                    {question.officialRef && (
                      <p className="text-sm text-blue-700">Official Docs: {question.officialRef}</p>
                    )}
                  </div>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Navigation */}
      <div className="flex items-center justify-between">
        <Button
          variant="outline"
          onClick={onPrevious}
          disabled={!canGoPrevious}
          className="flex items-center gap-2"
        >
          ← Previous
        </Button>

        <div className="flex items-center gap-2">
          {!selectedChoice && (
            <div className="flex items-center gap-1 text-sm text-amber-600">
              <AlertCircle className="h-4 w-4" />
              <span>Please select an answer</span>
            </div>
          )}
        </div>

        <Button onClick={onNext} disabled={!canGoNext} className="flex items-center gap-2">
          Next →
        </Button>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useQuestions } from "@/contexts/QuestionsContext";
import { useModule } from "@/contexts/ModuleContext";
import { useAuth } from "@/contexts/AuthContext";
import { PracticeQuestion } from "./PracticeQuestion";
import { PracticeSessionSummary } from "./PracticeSessionSummary";
import { PracticeSessionManager } from "@/lib/practice-session-manager";
import {
  type PracticeSession,
  type PracticeSessionConfig,
  PracticeSessionState,
  type PracticeSessionSummary as SessionSummary,
} from "@/types/practice-session";
import { type TCODomain, Difficulty } from "@/types/exam";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { AlertTriangle, Play, RotateCcw, Target } from "lucide-react";
import { cn } from "@/lib/utils";

interface PracticeSessionContainerProps {
  moduleId: string;
  domain?: TCODomain;
  className?: string;
  onSessionComplete?: (summary: SessionSummary) => void;
  onPassingScoreAchieved?: () => void;
}

const DEFAULT_CONFIG: Omit<PracticeSessionConfig, "moduleId"> = {
  questionCount: 10,
  passingScore: 70, // 70% needed to unlock assessment
  timeLimit: undefined, // No time limit for practice
};

export function PracticeSessionContainer({
  moduleId,
  domain,
  className,
  onSessionComplete,
  onPassingScoreAchieved,
}: PracticeSessionContainerProps) {
  const {
    getQuestionsWithFilters,
    getQuestionsByDomain,
    loading: questionsLoading,
  } = useQuestions();
  const { user } = useAuth();

  const [sessionManager] = useState(() => new PracticeSessionManager());
  const [currentSession, setCurrentSession] = useState<PracticeSession | null>(null);
  const [sessionState, setSessionState] = useState<PracticeSessionState>(
    PracticeSessionState.NOT_STARTED
  );
  const [sessionSummary, setSessionSummary] = useState<SessionSummary | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [timeRemaining, setTimeRemaining] = useState<number | undefined>();

  // Setup session manager callbacks
  useEffect(() => {
    sessionManager.setProgressCallback((progress: any) => {
      console.log("Practice progress updated:", progress);
    });

    sessionManager.setCompleteCallback((summary: any) => {
      setSessionSummary(summary);
      setSessionState(PracticeSessionState.COMPLETED);

      // Check if passing score achieved
      if (summary.passed && onPassingScoreAchieved) {
        onPassingScoreAchieved();
      }

      // Notify parent
      if (onSessionComplete) {
        onSessionComplete(summary);
      }
    });
  }, [sessionManager, onSessionComplete, onPassingScoreAchieved]);

  // Timer management
  useEffect(() => {
    if (!currentSession?.config.timeLimit || sessionState !== PracticeSessionState.IN_PROGRESS) {
      return;
    }

    const startTime = currentSession.startedAt.getTime();
    const timeLimitMs = currentSession.config.timeLimit * 1000;

    const interval = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const remaining = Math.max(0, Math.floor((timeLimitMs - elapsed) / 1000));

      setTimeRemaining(remaining);

      if (remaining === 0) {
        // Auto-complete session when time expires
        handleCompleteSession();
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [currentSession, sessionState]);

  const startPracticeSession = useCallback(async () => {
    if (!user) {
      setError("User not authenticated");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // Get questions for this module/domain
      const questions = domain
        ? await getQuestionsByDomain(domain)
        : await getQuestionsWithFilters({
            tags: [moduleId],
            limit: 50, // Get larger pool for randomization
          });

      if (questions.length === 0) {
        throw new Error("No questions available for practice");
      }

      // Create session config
      const config: PracticeSessionConfig = {
        ...DEFAULT_CONFIG,
        moduleId,
        domain,
      };

      // Start the session
      const session = await sessionManager.startSession(config, user.id, questions);
      setCurrentSession(session);
      setSessionState(PracticeSessionState.IN_PROGRESS);
      setSessionSummary(null);
    } catch (err) {
      console.error("Failed to start practice session:", err);
      setError(err instanceof Error ? err.message : "Failed to start practice session");
    } finally {
      setLoading(false);
    }
  }, [moduleId, domain, user, getQuestionsByDomain, getQuestionsWithFilters, sessionManager]);

  const handleAnswer = useCallback(
    (questionId: string, choiceId: string) => {
      const isCorrect = sessionManager.answerQuestion(questionId, choiceId);
      const updatedSession = sessionManager.getCurrentSession();

      if (updatedSession) {
        setCurrentSession({ ...updatedSession });
      }

      return isCorrect;
    },
    [sessionManager]
  );

  const handleNextQuestion = useCallback(() => {
    const nextQuestion = sessionManager.nextQuestion();
    const updatedSession = sessionManager.getCurrentSession();

    if (updatedSession) {
      setCurrentSession({ ...updatedSession });
    }

    if (!nextQuestion) {
      // Session completed
      setSessionState(PracticeSessionState.COMPLETED);
    }
  }, [sessionManager]);

  const handlePreviousQuestion = useCallback(() => {
    const prevQuestion = sessionManager.previousQuestion();
    const updatedSession = sessionManager.getCurrentSession();

    if (updatedSession) {
      setCurrentSession({ ...updatedSession });
    }
  }, [sessionManager]);

  const handleCompleteSession = useCallback(() => {
    // Force complete the current session
    const session = sessionManager.getCurrentSession();
    if (session && !session.completedAt) {
      // Complete remaining questions as unanswered
      while (sessionManager.nextQuestion() !== null) {
        // This will trigger completion when all questions are processed
      }
    }
  }, [sessionManager]);

  const handleRestartSession = useCallback(() => {
    sessionManager.resetSession();
    setCurrentSession(null);
    setSessionState(PracticeSessionState.NOT_STARTED);
    setSessionSummary(null);
    setTimeRemaining(undefined);
    setError(null);
  }, [sessionManager]);

  // Loading state
  if (questionsLoading || loading) {
    return (
      <div className={cn("space-y-6", className)}>
        <Card>
          <CardContent className="p-6">
            <div className="space-y-4">
              <Skeleton className="h-6 w-48" />
              <Skeleton className="h-4 w-full" />
              <Skeleton className="h-10 w-32" />
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <Card className={cn("border-destructive", className)}>
        <CardContent className="p-6">
          <div className="flex items-start gap-3">
            <AlertTriangle className="mt-0.5 h-5 w-5 text-destructive" />
            <div className="space-y-2">
              <p className="font-medium text-destructive">Practice Session Error</p>
              <p className="text-sm text-muted-foreground">{error}</p>
              <Button variant="outline" size="sm" onClick={() => setError(null)}>
                Try Again
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Session completed - show summary
  if (sessionState === PracticeSessionState.COMPLETED && sessionSummary) {
    return (
      <div className={cn("space-y-6", className)}>
        <PracticeSessionSummary session={currentSession as any} onRestart={handleRestartSession} />
      </div>
    );
  }

  // Session in progress - show current question
  if (sessionState === PracticeSessionState.IN_PROGRESS && currentSession) {
    const currentQuestion = sessionManager.getCurrentQuestion();

    if (!currentQuestion) {
      return (
        <div className={className}>
          <Card>
            <CardContent className="p-6 text-center">
              <p>No questions available</p>
              <Button onClick={handleRestartSession} className="mt-4">
                Restart Session
              </Button>
            </CardContent>
          </Card>
        </div>
      );
    }

    return (
      <div className={className}>
        <PracticeQuestion
          question={currentQuestion}
          questionNumber={currentSession.currentQuestionIndex + 1}
          totalQuestions={currentSession.totalQuestions}
          onAnswer={handleAnswer}
          onNext={handleNextQuestion}
          onPrevious={handlePreviousQuestion}
          canGoNext={sessionManager.canGoToNext()}
          canGoPrevious={sessionManager.canGoToPrevious()}
          timeRemaining={timeRemaining}
        />
      </div>
    );
  }

  // Not started - show start screen
  return (
    <div className={cn("space-y-6", className)}>
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Target className="h-5 w-5 text-primary" />
            <CardTitle>Practice Session</CardTitle>
            {domain && <Badge variant="secondary">{domain}</Badge>}
          </div>
          <CardDescription>
            Test your understanding with practice questions. You need to score{" "}
            {DEFAULT_CONFIG.passingScore}% or higher to unlock the assessment.
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4 text-sm">
            <div>
              <span className="font-medium">Questions:</span>
              <span className="ml-2 text-muted-foreground">{DEFAULT_CONFIG.questionCount}</span>
            </div>
            <div>
              <span className="font-medium">Passing Score:</span>
              <span className="ml-2 text-muted-foreground">{DEFAULT_CONFIG.passingScore}%</span>
            </div>
            <div>
              <span className="font-medium">Time Limit:</span>
              <span className="ml-2 text-muted-foreground">
                {DEFAULT_CONFIG.timeLimit ? `${DEFAULT_CONFIG.timeLimit / 60} minutes` : "None"}
              </span>
            </div>
            <div>
              <span className="font-medium">Domain:</span>
              <span className="ml-2 text-muted-foreground">{domain || "Mixed"}</span>
            </div>
          </div>

          <div className="flex items-center gap-2 pt-4">
            <Button onClick={startPracticeSession} disabled={loading}>
              <Play className="mr-2 h-4 w-4" />
              Start Practice
            </Button>

            {currentSession && (
              <Button variant="outline" onClick={handleRestartSession}>
                <RotateCcw className="mr-2 h-4 w-4" />
                Reset
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
