            <p>No filters applied</p>
            <p className="text-sm mt-1">Add filters to narrow down results</p>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                const newFilter: FilterSelection = {
                  id: `filter-${Date.now()}`,
                  sensor: availableSensors[0] || 'Computer Name',
                  operator: 'contains',
                  value: '',
                  dataType: 'text',
                  logic: 'AND'
                };
                onAdd(newFilter);
              }}
              className="mt-4"
            >
              <Plus className="mr-1 h-3 w-3" />
              Add First Filter
            </Button>
          </div>
        ) : (
          <FilterGroup
            filters={filters}
            depth={0}
            logic={filterLogic}
            onAdd={onAdd}
            onRemove={onRemove}
            onUpdate={onUpdate}
            onLogicChange={onLogicChange}
            availableSensors={availableSensors}
            allowNested={allowNested}
          />
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useState, useRef, useEffect } from 'react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Card } from '@/components/ui/card';
import {
  Sparkles,
  Search,
  ArrowRight,
  Clock,
  Zap,
  Database,
  Hash,
  Code,
  Loader2
} from 'lucide-react';

import {
  NaturalLanguageInputProps,
  QuerySuggestion
} from './types/queryBuilder';

export function NaturalLanguageInput({
  value,
  onChange,
  onSubmit,
  suggestions,
  isProcessing = false,
  placeholder = "Type a natural language query...",
  className = ""
}: NaturalLanguageInputProps) {
  const [isFocused, setIsFocused] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [localValue, setLocalValue] = useState(value);

  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);

  // Update local value when prop changes
  useEffect(() => {
    setLocalValue(value);
  }, [value]);

  // Show suggestions when there are any and input is focused
  useEffect(() => {
    setShowSuggestions(suggestions.length > 0 && isFocused && !isProcessing);
  }, [suggestions, isFocused, isProcessing]);

  // Handle input change
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    setLocalValue(newValue);
    onChange(newValue);
    setSelectedIndex(-1);
  };

  // Handle keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (selectedIndex >= 0 && selectedIndex < suggestions.length) {
        selectSuggestion(suggestions[selectedIndex]);
      } else {
        handleSubmit();
      }
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex((prev) =>
        prev < suggestions.length - 1 ? prev + 1 : prev
      );
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex((prev) => (prev > -1 ? prev - 1 : -1));
    } else if (e.key === 'Escape') {
      setShowSuggestions(false);
      setSelectedIndex(-1);
    }
  };

  // Handle submit
  const handleSubmit = () => {
    if (localValue.trim() && !isProcessing) {
      onSubmit(localValue.trim());
      setShowSuggestions(false);
    }
  };

  // Select a suggestion
  const selectSuggestion = (suggestion: QuerySuggestion) => {
    setLocalValue(suggestion.text);
    onChange(suggestion.text);
    setShowSuggestions(false);
    setSelectedIndex(-1);

    // Auto-submit if it's a complete query suggestion
    if (suggestion.type === 'complete') {
      setTimeout(() => onSubmit(suggestion.text), 100);
    } else {
      // Focus back on input for further editing
      inputRef.current?.focus();
    }
  };

  // Get icon for suggestion type
  const getSuggestionIcon = (type: QuerySuggestion['type']) => {
    switch (type) {
      case 'sensor':
        return <Database className="h-4 w-4" />;
      case 'filter':
        return <Hash className="h-4 w-4" />;
      case 'template':
        return <Code className="h-4 w-4" />;
      case 'complete':
        return <Zap className="h-4 w-4" />;
      default:
        return <Search className="h-4 w-4" />;
    }
  };

  // Get confidence color
  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.8) return 'text-green-400';
    if (confidence >= 0.5) return 'text-yellow-400';
    return 'text-gray-400';
  };

  return (
    <div className={`relative ${className}`}>
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          {isProcessing ? (
            <Loader2 className="h-5 w-5 text-tanium-accent animate-spin" />
          ) : (
            <Sparkles className="h-5 w-5 text-tanium-accent" />
          )}
        </div>

        <Input
          ref={inputRef}
          type="text"
          value={localValue}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          onFocus={() => setIsFocused(true)}
          onBlur={() => {
            // Delay to allow clicking on suggestions
            setTimeout(() => setIsFocused(false), 200);
          }}
          placeholder={placeholder}
          disabled={isProcessing}
          className="pl-10 pr-24 bg-gray-800 border-gray-600 text-white placeholder-gray-400 focus:border-tanium-accent"
        />

        <div className="absolute inset-y-0 right-0 flex items-center pr-2">
          <Button
            size="sm"
            onClick={handleSubmit}
            disabled={!localValue.trim() || isProcessing}
            className="bg-tanium-accent hover:bg-blue-600"
          >
            {isProcessing ? (
              <>Processing...</>
            ) : (
              <>
                Generate
                <ArrowRight className="ml-1 h-3 w-3" />
              </>
            )}
          </Button>
        </div>
      </div>

      {/* Suggestions dropdown */}
      {showSuggestions && (
        <Card
          ref={suggestionsRef}
          className="absolute z-50 w-full mt-1 bg-gray-800 border-gray-600 shadow-lg"
        >
          <ScrollArea className="max-h-80">
            <div className="p-1">
              <div className="text-xs text-gray-400 px-3 py-1 mb-1">
                Suggested queries
              </div>

              {suggestions.map((suggestion, index) => (
                <div
                  key={suggestion.id}
                  className={`
                    flex items-start space-x-3 px-3 py-2 cursor-pointer rounded
                    ${index === selectedIndex ? 'bg-gray-700' : 'hover:bg-gray-700/50'}
                  `}
                  onClick={() => selectSuggestion(suggestion)}
                  onMouseEnter={() => setSelectedIndex(index)}
                >
                  <div className="flex-shrink-0 mt-0.5">
                    {getSuggestionIcon(suggestion.type)}
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="text-sm text-white">
                          {suggestion.displayText}
                        </div>
                        {suggestion.description && (
                          <div className="text-xs text-gray-400 mt-0.5">
                            {suggestion.description}
                          </div>
                        )}
                      </div>

                      <div className="flex items-center space-x-2 ml-2">
                        {suggestion.runtime !== undefined && (
                          <Badge
                            variant="outline"
                            className={`text-xs ${
                              suggestion.runtime < 100
                                ? 'border-green-500 text-green-400'
                                : suggestion.runtime < 500
                                ? 'border-yellow-500 text-yellow-400'
                                : 'border-red-500 text-red-400'
                            }`}
                          >
                            <Clock className="h-3 w-3 mr-1" />
                            {suggestion.runtime}ms
                          </Badge>
                        )}

                        <Badge
                          variant="outline"
                          className={`text-xs ${getConfidenceColor(
                            suggestion.confidence
                          )}`}
                        >
                          {Math.round(suggestion.confidence * 100)}%
                        </Badge>
                      </div>
                    </div>

                    {/* Preview of the actual query */}
                    {suggestion.text !== suggestion.displayText && (
                      <div className="mt-1">
                        <code className="text-xs text-gray-500">
                          {suggestion.text.length > 80
                            ? suggestion.text.substring(0, 80) + '...'
                            : suggestion.text}
                        </code>
                      </div>
                    )}
                  </div>
                </div>
              ))}

              {/* Help text */}
              <div className="border-t border-gray-700 mt-1 pt-1">
                <div className="px-3 py-1 text-xs text-gray-500">
                  Press <kbd className="px-1 py-0.5 bg-gray-700 rounded">↑</kbd>{' '}
                  <kbd className="px-1 py-0.5 bg-gray-700 rounded">↓</kbd> to navigate,{' '}
                  <kbd className="px-1 py-0.5 bg-gray-700 rounded">Enter</kbd> to select,{' '}
                  <kbd className="px-1 py-0.5 bg-gray-700 rounded">Esc</kbd> to close
                </div>
              </div>
            </div>
          </ScrollArea>
        </Card>
      )}

      {/* AI assistance note */}
      {!isProcessing && !showSuggestions && localValue && (
        <div className="absolute mt-1 text-xs text-gray-500">
          Press Enter or click Generate to convert to Tanium query
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import {
  Code,
  AlertCircle,
  Info,
  CheckCircle,
  Copy,
  Eye,
  EyeOff
} from 'lucide-react';

import {
  QueryPreviewProps,
  PartialQuery,
  ValidationState
} from './types/queryBuilder';

export function QueryPreview({
  query,
  validation,
  syntaxHighlight = true,
  showWarnings = true,
  className = ""
}: QueryPreviewProps) {
  const [showRaw, setShowRaw] = React.useState(false);
  const [copied, setCopied] = React.useState(false);

  // Build query string from partial query
  const queryString = useMemo(() => {
    if (query.rawQuery && query.rawQuery.trim()) {
      return query.rawQuery;
    }

    const parts: string[] = [];

    // GET clause
    if (query.sensors.length > 0 || query.aggregates.length > 0) {
      parts.push('Get');

      // Add sensors
      const sensorParts = query.sensors.map(s => {
        let sensorStr = 'name' in s.sensor ? (s.sensor.name || '') : '';
        if (s.filter) {
          sensorStr += ` ${s.filter.operator} "${s.filter.value}"`;
        }
        return sensorStr;
      });

      // Add aggregates
      const aggregateParts = query.aggregates.map(a => {
        return `${a.function}(${a.sensor || ''})`;
      });

      parts.push([...sensorParts, ...aggregateParts].join(' and '));
    }

    // FROM clause
    parts.push('from');
    if (query.scope.type === 'all') {
      parts.push('all machines');
    } else if (query.scope.type === 'group' && query.scope.computerGroup) {
      parts.push(`group "${query.scope.computerGroup}"`);
    } else if (query.scope.type === 'custom' && query.scope.customFilter) {
      // Custom targeting will be handled separately
      parts.push('all machines');
    }

    // WHERE clause
    if (query.filters.length > 0) {
      parts.push('where');
      const filterParts = query.filters.map(f => {
        return `${f.sensor} ${f.operator.replace('_', ' ')} "${f.value}"`;
      });
      parts.push(filterParts.join(` ${query.filterLogic.toLowerCase()} `));
    }

    // GROUP BY clause
    if (query.groupBy.length > 0) {
      parts.push('group by');
      parts.push(query.groupBy.join(', '));
    }

    // ORDER BY clause
    if (query.orderBy.length > 0) {
      parts.push('order by');
      const orderParts = query.orderBy.map(o => {
        return `${o.sensor} ${o.direction}`;
      });
      parts.push(orderParts.join(', '));
    }

    // LIMIT clause
    if (query.limit) {
      parts.push(`limit ${query.limit}`);
    }

    return parts.join(' ');
  }, [query]);

  // Apply syntax highlighting
  const highlightedQuery = useMemo(() => {
    if (!syntaxHighlight || showRaw) {
      return queryString;
    }

    let highlighted = queryString;

    // Keywords
    const keywords = [
      'Get', 'from', 'where', 'with', 'group by', 'order by', 'limit',
      'and', 'or', 'all machines', 'group'
    ];
    keywords.forEach(keyword => {
      const regex = new RegExp(`\\b(${keyword})\\b`, 'gi');
      highlighted = highlighted.replace(regex, `<span class="text-blue-400 font-semibold">$1</span>`);
    });

    // Operators
    const operators = [
      'contains', 'does not contain', 'equals', 'not equals',
      'greater than', 'less than', 'starts with', 'ends with', 'matches'
    ];
    operators.forEach(op => {
      const regex = new RegExp(`\\b(${op})\\b`, 'gi');
      highlighted = highlighted.replace(regex, `<span class="text-purple-400">$1</span>`);
    });

    // Aggregate functions
    const aggregates = ['count', 'min', 'max', 'avg', 'sum'];
    aggregates.forEach(func => {
      const regex = new RegExp(`\\b(${func})\\(`, 'gi');
      highlighted = highlighted.replace(regex, `<span class="text-green-400">$1</span>(`);
    });

    // Strings (quoted values)
    highlighted = highlighted.replace(/"([^"]*)"/g, `<span class="text-yellow-400">"$1"</span>`);

    // Numbers
    highlighted = highlighted.replace(/\b(\d+)\b/g, `<span class="text-orange-400">$1</span>`);

    // Sensor names (capitalize first letter of each word for common sensors)
    const commonSensors = [
      'Computer Name', 'Operating System', 'IP Address', 'CPU Percent',
      'Disk Free GB', 'Memory GB', 'Last Reboot', 'Last Logged In User'
    ];
    commonSensors.forEach(sensor => {
      const regex = new RegExp(`\\b(${sensor})\\b`, 'gi');
      highlighted = highlighted.replace(regex, `<span class="text-cyan-400">$1</span>`);
    });

    return highlighted;
  }, [queryString, syntaxHighlight, showRaw]);

  // Copy to clipboard
  const handleCopy = () => {
    navigator.clipboard.writeText(queryString);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Get validation icon
  const getValidationIcon = () => {
    if (!validation.isValid) {
      return <AlertCircle className="h-4 w-4 text-red-500" />;
    }
    if (validation.warnings.length > 0) {
      return <Info className="h-4 w-4 text-yellow-500" />;
    }
    return <CheckCircle className="h-4 w-4 text-green-500" />;
  };

  return (
    <Card className={`glass border-white/10 ${className}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center text-white">
            <Code className="mr-2 h-5 w-5" />
            Query Preview
          </CardTitle>
          <div className="flex items-center space-x-2">
            {getValidationIcon()}
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setShowRaw(!showRaw)}
              className="text-gray-400 hover:text-white"
            >
              {showRaw ? (
                <>
                  <Eye className="mr-1 h-3 w-3" />
                  Formatted
                </>
              ) : (
                <>
                  <EyeOff className="mr-1 h-3 w-3" />
                  Raw
                </>
              )}
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={handleCopy}
              className="text-gray-400 hover:text-white"
            >
              {copied ? (
                <CheckCircle className="h-4 w-4 text-green-400" />
              ) : (
                <Copy className="h-4 w-4" />
              )}
            </Button>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Query display */}
        <div className="relative">
          <div
            className="p-4 bg-gray-900 rounded border border-gray-700 font-mono text-sm overflow-x-auto"
            style={{ minHeight: '60px' }}
          >
            {queryString ? (
              showRaw ? (
                <pre className="text-gray-300 whitespace-pre-wrap">{queryString}</pre>
              ) : (
                <div
                  className="text-gray-300"
                  dangerouslySetInnerHTML={{ __html: highlightedQuery }}
                />
              )
            ) : (
              <span className="text-gray-500 italic">
                Start building your query above...
              </span>
            )}
          </div>

          {/* Validation overlay for empty query */}
          {!queryString && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <Badge variant="outline" className="border-gray-600 text-gray-400">
                Empty Query
              </Badge>
            </div>
          )}
        </div>

        {/* Validation errors */}
        {validation.errors.length > 0 && (
          <Alert className="border-red-500 bg-red-500/10">
            <AlertCircle className="h-4 w-4 text-red-500" />
            <AlertDescription className="text-red-400">
              <div className="font-semibold mb-1">Query Errors:</div>
              <ul className="list-disc list-inside space-y-1">
                {validation.errors.map((error, index) => (
                  <li key={index} className="text-sm">
                    {error.field && <span className="font-mono">{error.field}: </span>}
                    {error.message}
                  </li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Validation warnings */}
        {showWarnings && validation.warnings.length > 0 && (
          <Alert className="border-yellow-500 bg-yellow-500/10">
            <Info className="h-4 w-4 text-yellow-500" />
            <AlertDescription className="text-yellow-400">
              <div className="font-semibold mb-1">Warnings:</div>
              <ul className="list-disc list-inside space-y-1">
                {validation.warnings.map((warning, index) => (
                  <li key={index} className="text-sm">
                    {warning.field && <span className="font-mono">{warning.field}: </span>}
                    {warning.message}
                    {warning.suggestion && (
                      <div className="ml-4 text-xs text-yellow-300 mt-0.5">
                        💡 {warning.suggestion}
                      </div>
                    )}
                  </li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        {/* Success message */}
        {validation.isValid && queryString && (
          <Alert className="border-green-500 bg-green-500/10">
            <CheckCircle className="h-4 w-4 text-green-500" />
            <AlertDescription className="text-green-400">
              Query is valid and ready to execute
            </AlertDescription>
          </Alert>
        )}

        {/* Query metadata */}
        {queryString && (
          <div className="flex flex-wrap gap-2">
            {query.sensors.length > 0 && (
              <Badge variant="outline" className="text-xs">
                {query.sensors.length} sensor{query.sensors.length !== 1 ? 's' : ''}
              </Badge>
            )}
            {query.aggregates.length > 0 && (
              <Badge variant="outline" className="text-xs">
                {query.aggregates.length} aggregate{query.aggregates.length !== 1 ? 's' : ''}
              </Badge>
            )}
            {query.filters.length > 0 && (
              <Badge variant="outline" className="text-xs">
                {query.filters.length} filter{query.filters.length !== 1 ? 's' : ''}
              </Badge>
            )}
            {query.groupBy.length > 0 && (
              <Badge variant="outline" className="text-xs">
                Grouped by {query.groupBy.length} field{query.groupBy.length !== 1 ? 's' : ''}
              </Badge>
            )}
            {query.orderBy.length > 0 && (
              <Badge variant="outline" className="text-xs">
                Sorted by {query.orderBy.length} field{query.orderBy.length !== 1 ? 's' : ''}
              </Badge>
            )}
            {query.limit && (
              <Badge variant="outline" className="text-xs">
                Limited to {query.limit} rows
              </Badge>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

