  BuilderMode,
  PartialQuery,
  SensorSelection,
  FilterSelection,
  QueryHistoryItem,
  ValidationState,
  ScopeSelection,
} from './types/queryBuilder';

// Query builder reducer
function queryBuilderReducer(
  state: QueryBuilderState,
  action: QueryBuilderAction
): QueryBuilderState {
  switch (action.type) {
    case 'SET_MODE':
      return { ...state, mode: action.mode };

    case 'ADD_SENSOR':
      return {
        ...state,
        query: {
          ...state.query,
          sensors: [...state.query.sensors, action.sensor]
        }
      };

    case 'REMOVE_SENSOR':
      return {
        ...state,
        query: {
          ...state.query,
          sensors: state.query.sensors.filter((_, i) => i !== action.index)
        }
      };

    case 'UPDATE_SENSOR':
      return {
        ...state,
        query: {
          ...state.query,
          sensors: state.query.sensors.map((s, i) =>
            i === action.index ? action.sensor : s
          )
        }
      };

    case 'ADD_FILTER':
      return {
        ...state,
        query: {
          ...state.query,
          filters: [...state.query.filters, action.filter]
        }
      };

    case 'REMOVE_FILTER':
      return {
        ...state,
        query: {
          ...state.query,
          filters: state.query.filters.filter(f => f.id !== action.filterId)
        }
      };

    case 'UPDATE_FILTER':
      return {
        ...state,
        query: {
          ...state.query,
          filters: state.query.filters.map(f =>
            f.id === action.filterId ? action.filter : f
          )
        }
      };

    case 'SET_SCOPE':
      return {
        ...state,
        query: {
          ...state.query,
          scope: action.scope
        }
      };

    case 'SET_GROUP_BY':
      return {
        ...state,
        query: {
          ...state.query,
          groupBy: action.groupBy
        }
      };

    case 'SET_ORDER_BY':
      return {
        ...state,
        query: {
          ...state.query,
          orderBy: action.orderBy
        }
      };

    case 'SET_LIMIT':
      return {
        ...state,
        query: {
          ...state.query,
          limit: action.limit
        }
      };

    case 'SET_RAW_QUERY':
      return {
        ...state,
        query: {
          ...state.query,
          rawQuery: action.query
        }
      };

    case 'SET_VALIDATION':
      return { ...state, validation: action.validation };

    case 'SET_SUGGESTIONS':
      return { ...state, suggestions: action.suggestions };

    case 'SET_RESULT':
      return { ...state, result: action.result };

    case 'SET_EXECUTING':
      return { ...state, isExecuting: action.isExecuting };

    case 'ADD_TO_HISTORY':
      return {
        ...state,
        history: [action.item, ...state.history].slice(0, 50) // Keep last 50
      };

    case 'RESET_QUERY':
      return {
        ...state,
        query: initialQuery,
        validation: initialValidation,
        result: undefined
      };

    default:
      return state;
  }
}

// Initial states
const initialQuery: PartialQuery = {
  sensors: [],
  aggregates: [],
  scope: { type: 'all' },
  filters: [],
  filterLogic: 'AND',
  groupBy: [],
  orderBy: [],
  limit: undefined,
  rawQuery: ''
};

const initialValidation: ValidationState = {
  isValid: false,
  errors: [],
  warnings: [],
  syntaxValid: false,
  semanticValid: false
};

const initialState: QueryBuilderState = {
  mode: 'guided',
  query: initialQuery,
  validation: initialValidation,
  suggestions: [],
  isExecuting: false,
  result: undefined,
  history: []
};

export function QuestionBuilder({
  initialQuery: providedInitialQuery,
  mode = 'guided',
  onQueryChange,
  onExecute,
  readOnly = false,
  showResults = true,
  showHistory = true,
  maxHeight = '800px',
  className = ''
}: QuestionBuilderProps) {
  const [state, dispatch] = useReducer(queryBuilderReducer, {
    ...initialState,
    mode,
    query: providedInitialQuery || initialQuery
  });

  const [queryEngine] = useState(() => new TaniumQueryEngine());
  const [showHistoryPanel, setShowHistoryPanel] = useState(false);

  // Custom hooks
  const { validate, getQueryString } = useQueryValidation();
  const { parse: parseNaturalLanguage, getSuggestions, isProcessing } = useNaturalLanguage();
  const { catalog, search: searchSensors, categories, popularSensors } = useSensorCatalog();

  // Validate query on changes
  useEffect(() => {
    const validation = validate(state.query);
    dispatch({ type: 'SET_VALIDATION', validation });
  }, [state.query, validate]);

  // Notify parent of query changes
  useEffect(() => {
    if (onQueryChange) {
      onQueryChange(state.query);
    }
  }, [state.query, onQueryChange]);

  // Execute query
  const handleExecute = useCallback(async () => {
    if (readOnly || !state.validation.isValid) return;

    dispatch({ type: 'SET_EXECUTING', isExecuting: true });

    try {
      const queryString = getQueryString(state.query);
      const result = await queryEngine.query(queryString);

      dispatch({ type: 'SET_RESULT', result });

      // Add to history
      const historyItem: QueryHistoryItem = {
        id: `query-${Date.now()}`,
        query: queryString,
        timestamp: new Date().toISOString(),
        executionTime: result.execution?.totalTimeMs,
        resultCount: result.rowCount,
        success: result.ok
      };
      dispatch({ type: 'ADD_TO_HISTORY', item: historyItem });

      // Notify parent
      if (onExecute) {
        onExecute(queryString, result);
      }
    } catch (error) {
      console.error('Query execution error:', error);
      const errorResult: QueryResult = {
        ok: false,
        error: error instanceof Error ? error.message : 'Query execution failed'
      };
      dispatch({ type: 'SET_RESULT', result: errorResult });
    } finally {
      dispatch({ type: 'SET_EXECUTING', isExecuting: false });
    }
  }, [state.query, state.validation.isValid, queryEngine, getQueryString, onExecute, readOnly]);

  // Handle natural language input
  const handleNaturalLanguageSubmit = useCallback(async (text: string) => {
    const result = await parseNaturalLanguage(text);
    if (result.query) {
      dispatch({ type: 'RESET_QUERY' });
      // Apply the parsed query
      result.query.sensors.forEach(sensor => {
        dispatch({ type: 'ADD_SENSOR', sensor });
      });
      result.query.filters.forEach(filter => {
        dispatch({ type: 'ADD_FILTER', filter });
      });
      if (result.query.scope) {
        dispatch({ type: 'SET_SCOPE', scope: result.query.scope });
      }
    }
  }, [parseNaturalLanguage]);

  // Load query from history
  const handleLoadFromHistory = useCallback((item: QueryHistoryItem) => {
    dispatch({ type: 'SET_RAW_QUERY', query: item.query });
    if (state.mode === 'advanced') {
      // Parse and load in advanced mode
      handleExecute();
    }
    setShowHistoryPanel(false);
  }, [state.mode, handleExecute]);

  // Get validation status
  const getValidationStatus = () => {
    if (state.validation.errors.length > 0) {
      return { icon: AlertCircle, color: 'text-red-500', text: 'Invalid query' };
    }
    if (state.validation.warnings.length > 0) {
      return { icon: Info, color: 'text-yellow-500', text: 'Query has warnings' };
    }
    if (state.validation.isValid) {
      return { icon: CheckCircle, color: 'text-green-500', text: 'Valid query' };
    }
    return { icon: AlertCircle, color: 'text-gray-500', text: 'Incomplete query' };
  };

  const validationStatus = getValidationStatus();

  return (
    <Card className={`glass border-white/10 ${className}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center text-white">
            <Search className="mr-2 h-5 w-5 text-tanium-accent" />
            Tanium Question Builder
          </CardTitle>
          <div className="flex items-center space-x-2">
            {/* Validation status */}
            <div className="flex items-center space-x-1">
              <validationStatus.icon className={`h-4 w-4 ${validationStatus.color}`} />
              <span className={`text-sm ${validationStatus.color}`}>
                {validationStatus.text}
              </span>
            </div>

            {/* Action buttons */}
            <Button
              size="sm"
              variant="ghost"
              onClick={() => dispatch({ type: 'RESET_QUERY' })}
              disabled={readOnly}
            >
              <RotateCcw className="h-4 w-4" />
            </Button>

            {showHistory && (
              <Button
                size="sm"
                variant="ghost"
                onClick={() => setShowHistoryPanel(!showHistoryPanel)}
              >
                <History className="h-4 w-4" />
                <Badge variant="secondary" className="ml-1">
                  {state.history.length}
                </Badge>
              </Button>
            )}

            <Button
              size="sm"
              onClick={handleExecute}
              disabled={readOnly || !state.validation.isValid || state.isExecuting}
              className="bg-tanium-accent hover:bg-blue-600"
            >
              {state.isExecuting ? (
                <div className="flex items-center">
                  <div className="animate-spin rounded-full h-3 w-3 border-b-2 border-white mr-2" />
                  Executing...
                </div>
              ) : (
                <>
                  <Play className="mr-1 h-4 w-4" />
                  Execute Query
                </>
              )}
            </Button>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4" style={{ maxHeight, overflow: 'auto' }}>
        {/* Mode selector */}
        <Tabs
          value={state.mode}
          onValueChange={(value) => dispatch({ type: 'SET_MODE', mode: value as BuilderMode })}
        >
          <TabsList className="grid w-full grid-cols-3 bg-gray-800">
            <TabsTrigger value="guided" className="flex items-center">
              <MousePointer className="mr-2 h-4 w-4" />
              Guided
            </TabsTrigger>
            <TabsTrigger value="natural-language" className="flex items-center">
              <Sparkles className="mr-2 h-4 w-4" />
              Natural Language
            </TabsTrigger>
            <TabsTrigger value="advanced" className="flex items-center">
              <Code className="mr-2 h-4 w-4" />
              Advanced
            </TabsTrigger>
          </TabsList>

          {/* Guided mode */}
          <TabsContent value="guided" className="space-y-4">
            <div className="space-y-4">
              {/* Sensor selection */}
              <SensorSelector
                selectedSensors={state.query.sensors}
                onAdd={(sensor) => dispatch({ type: 'ADD_SENSOR', sensor })}
                onRemove={(index) => dispatch({ type: 'REMOVE_SENSOR', index })}
                onUpdate={(index, sensor) => dispatch({ type: 'UPDATE_SENSOR', index, sensor })}
                catalog={catalog}
                className="mb-4"
              />

              {/* Filter builder */}
              <FilterBuilder
                filters={state.query.filters}
                onAdd={(filter) => dispatch({ type: 'ADD_FILTER', filter })}
                onRemove={(filterId) => dispatch({ type: 'REMOVE_FILTER', filterId })}
                onUpdate={(filterId, filter) => dispatch({ type: 'UPDATE_FILTER', filterId, filter })}
                availableSensors={catalog.map(c => 'name' in c.sensor ? c.sensor.name : '')}
                filterLogic={state.query.filterLogic}
                onLogicChange={(logic) =>
                  dispatch({
                    type: 'SET_SCOPE',
                    scope: { ...state.query.scope, customFilter: state.query.filters } as ScopeSelection
                  })
                }
                allowNested
                className="mb-4"
              />

              {/* Query preview */}
              <QueryPreview
                query={state.query}
                validation={state.validation}
                syntaxHighlight
                showWarnings
                className="mb-4"
              />
            </div>
          </TabsContent>

          {/* Natural language mode with lazy loading */}
          <TabsContent value="natural-language" className="space-y-4">
            <Suspense fallback={
              <div className="flex items-center justify-center p-8">
                <div className="flex items-center space-x-2">
                  <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-tanium-accent"></div>
                  <span className="text-gray-400">Loading Natural Language mode...</span>
                </div>
              </div>
            }>
              <NaturalLanguageInput
                value={state.query.rawQuery || ''}
                onChange={(value) => dispatch({ type: 'SET_RAW_QUERY', query: value })}
                onSubmit={handleNaturalLanguageSubmit}
                suggestions={state.suggestions}
                isProcessing={isProcessing}
                placeholder="Type a natural language query (e.g., 'Show me all Windows servers with high CPU usage')"
                className="mb-4"
              />
            </Suspense>

            {/* Query preview */}
            {state.query.sensors.length > 0 && (
              <QueryPreview
                query={state.query}
                validation={state.validation}
                syntaxHighlight
                showWarnings
                className="mb-4"
              />
            )}
          </TabsContent>

          {/* Advanced mode */}
          <TabsContent value="advanced" className="space-y-4">
            <div className="space-y-4">
              <textarea
                className="w-full h-32 p-3 bg-gray-800 border border-gray-600 rounded text-white font-mono text-sm"
                placeholder="Enter Tanium query directly (e.g., Get Computer Name from all machines)"
                value={state.query.rawQuery}
                onChange={(e) => dispatch({ type: 'SET_RAW_QUERY', query: e.target.value })}
                disabled={readOnly}
              />

              {/* Validation errors/warnings */}
              {state.validation.errors.length > 0 && (
                <Alert className="border-red-500 bg-red-500/10">
                  <AlertCircle className="h-4 w-4 text-red-500" />
                  <AlertDescription className="text-red-400">
                    {state.validation.errors[0].message}
                  </AlertDescription>
                </Alert>
              )}
            </div>
          </TabsContent>
        </Tabs>

        {/* Results viewer */}
        {showResults && state.result && (
          <ResultsViewer
            result={state.result}
            isLoading={state.isExecuting}
            onExport={(format) => {
              // Export functionality
              console.log('Export as:', format);
            }}
            className="mt-4"
          />
        )}

        {/* History panel */}
        {showHistory && showHistoryPanel && (
          <Card className="glass border-white/10 mt-4">
            <CardHeader>
              <CardTitle className="text-white text-sm">Query History</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2 max-h-64 overflow-y-auto">
                {state.history.map((item) => (
                  <div
                    key={item.id}
                    className="p-2 bg-gray-800 rounded hover:bg-gray-700 cursor-pointer"
                    onClick={() => handleLoadFromHistory(item)}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <code className="text-xs text-gray-300 block">
                          {item.query}
                        </code>
                      </div>
                      <div className="text-xs text-gray-500 ml-2">
                        {new Date(item.timestamp).toLocaleTimeString()}
                      </div>
                    </div>
                    {item.resultCount !== undefined && (
                      <div className="text-xs text-gray-500 mt-1">
                        {item.resultCount} results • {item.executionTime}ms
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useState, useMemo, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { ScrollArea, ScrollBar } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Database,
  Download,
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
  Search,
  Filter,
  ChevronLeft,
  ChevronRight,
  Loader2,
  AlertCircle,
  CheckCircle,
  FileJson,
  FileText,
  BarChart3,
  Eye,
  Table as TableIcon
} from 'lucide-react';
import { VirtualScrollTable } from './components/VirtualScrollTable';

import { ResultsViewerProps } from './types/queryBuilder';
import { QueryResult } from '@/lib/tanium-query-engine/types';

export function ResultsViewer({
  result,
  isLoading = false,
  onExport,
  onSort,
  pageSize = 50,
  className = ""
}: ResultsViewerProps) {
  const [currentPage, setCurrentPage] = useState(1);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortColumn, setSortColumn] = useState<string | null>(null);
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');
  const [viewMode, setViewMode] = useState<'table' | 'virtual' | 'summary'>('table');
  const [useVirtualScroll, setUseVirtualScroll] = useState(false);

  // Filter and sort data
  const processedData = useMemo(() => {
    if (!result || !result.rows) return [];

    let data = [...result.rows];

    // Apply search filter
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      data = data.filter(row =>
        row.some(cell =>
          String(cell).toLowerCase().includes(term)
        )
      );
    }

    // Apply sorting
    if (sortColumn !== null && result.headers) {
      const columnIndex = result.headers.indexOf(sortColumn);
      if (columnIndex >= 0) {
        data.sort((a, b) => {
          const aVal = a[columnIndex];
          const bVal = b[columnIndex];

          if (aVal === null || aVal === undefined) return 1;
          if (bVal === null || bVal === undefined) return -1;

          const comparison = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
          return sortDirection === 'asc' ? comparison : -comparison;
        });
      }
    }

    return data;
  }, [result, searchTerm, sortColumn, sortDirection]);

  // Auto-enable virtual scrolling for large datasets
  useMemo(() => {
    if (processedData.length > 1000 && !useVirtualScroll) {
      setUseVirtualScroll(true);
      setViewMode('virtual');
    }
  }, [processedData.length, useVirtualScroll]);

  // Convert data for VirtualScrollTable
  const tableData = useMemo(() => {
    if (!result || !result.headers || !processedData) return [];

    return processedData.map(row => {
      const obj: Record<string, any> = {};
      result.headers?.forEach((header, index) => {
        obj[header] = row[index];
      });
      return obj;
    });
  }, [result, processedData]);

  // Prepare columns for VirtualScrollTable
  const virtualColumns = useMemo(() => {
    if (!result || !result.headers) return [];

    return result.headers.map(header => ({
      key: header,
      label: header,
      sortable: true,
      render: (value: any) => {
        if (value === null || value === undefined) {
          return <span className="text-gray-500 italic">null</span>;
        }
        if (typeof value === 'boolean') {
          return (
            <Badge
              variant="outline"
              className={value ? 'border-green-500 text-green-400' : 'border-red-500 text-red-400'}
            >
              {String(value)}
            </Badge>
          );
        }
        return String(value);
      }
    }));
  }, [result]);

  // Pagination
  const totalPages = Math.ceil(processedData.length / pageSize);
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    const end = start + pageSize;
    return processedData.slice(start, end);
  }, [processedData, currentPage, pageSize]);

  // Handle column sort
  const handleSort = useCallback((column: string) => {
    if (sortColumn === column) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
      setSortColumn(column);
      setSortDirection('asc');
    }

    if (onSort) {
      onSort(column, sortDirection === 'asc' ? 'desc' : 'asc');
    }
  }, [sortColumn, sortDirection, onSort]);

  // Handle export
  const handleExport = useCallback((format: 'csv' | 'json') => {
    if (!result || !result.rows || !onExport) return;

    if (format === 'csv' && result.csv) {
      // Use pre-generated CSV if available
      const blob = new Blob([result.csv], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `query-results-${Date.now()}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } else {
      onExport(format);
    }
  }, [result, onExport]);

  // Get sort icon
  const getSortIcon = (column: string) => {
    if (sortColumn !== column) {
      return <ArrowUpDown className="h-3 w-3 opacity-50" />;
    }
    return sortDirection === 'asc' ? (
      <ArrowUp className="h-3 w-3" />
    ) : (
      <ArrowDown className="h-3 w-3" />
    );
  };

  // Loading state
  if (isLoading) {
    return (
      <Card className={`glass border-white/10 ${className}`}>
        <CardContent className="flex items-center justify-center py-12">
          <div className="text-center">
            <Loader2 className="h-8 w-8 animate-spin text-tanium-accent mx-auto mb-3" />
            <p className="text-gray-400">Executing query...</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Error state
  if (result && !result.ok) {
    return (
      <Card className={`glass border-white/10 ${className}`}>
        <CardHeader>
          <CardTitle className="flex items-center text-white">
            <Database className="mr-2 h-5 w-5" />
            Query Results
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Alert className="border-red-500 bg-red-500/10">
            <AlertCircle className="h-4 w-4 text-red-500" />
            <AlertDescription className="text-red-400">
              <div className="font-semibold">Query execution failed</div>
              <div className="mt-1 text-sm">{result.error}</div>
            </AlertDescription>
          </Alert>
        </CardContent>
      </Card>
    );
  }

  // No results
  if (!result || !result.rows || result.rows.length === 0) {
    return (
      <Card className={`glass border-white/10 ${className}`}>
        <CardHeader>
          <CardTitle className="flex items-center text-white">
            <Database className="mr-2 h-5 w-5" />
            Query Results
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center py-8 text-gray-400">
            <Database className="h-12 w-12 mx-auto mb-3 opacity-50" />
            <p>No results found</p>
            {result && result.execution && (
              <p className="text-sm mt-2">
                Query executed in {result.execution.totalTimeMs}ms
              </p>
            )}
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={`glass border-white/10 ${className}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center text-white">
            <Database className="mr-2 h-5 w-5" />
            Query Results
            <Badge variant="secondary" className="ml-2">
              {processedData.length} {processedData.length === 1 ? 'row' : 'rows'}
            </Badge>
          </CardTitle>
          <div className="flex items-center space-x-2">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-2 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                type="text"
                placeholder="Search results..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  setCurrentPage(1);
                }}
                className="pl-8 w-48 h-8 bg-gray-800 border-gray-600 text-white"
              />
            </div>

            {/* Export buttons */}
            {onExport && (
              <>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleExport('csv')}
                  className="text-gray-400 hover:text-white"
                >
                  <FileText className="mr-1 h-3 w-3" />
                  CSV
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleExport('json')}
                  className="text-gray-400 hover:text-white"
                >
                  <FileJson className="mr-1 h-3 w-3" />
                  JSON
                </Button>
              </>
            )}
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Execution metrics */}
        {result.execution && (
          <div className="flex flex-wrap gap-2">
            <Badge variant="outline" className="text-xs border-green-500 text-green-400">
              <CheckCircle className="mr-1 h-3 w-3" />
              Success
            </Badge>
            <Badge variant="outline" className="text-xs">
              Execution: {result.execution.totalTimeMs}ms
            </Badge>
            {result.execution.cacheHit && (
              <Badge variant="outline" className="text-xs border-blue-500 text-blue-400">
                Cached
              </Badge>
            )}
            {result.execution.rowsExamined !== undefined && (
              <Badge variant="outline" className="text-xs">
                Examined: {result.execution.rowsExamined} rows
              </Badge>
            )}
          </div>
        )}

        {/* View mode tabs for large datasets */}
        {processedData.length > 100 && (
          <Tabs value={viewMode} onValueChange={(v) => setViewMode(v as any)}>
            <TabsList className="bg-gray-800">
              <TabsTrigger value="table">
                <TableIcon className="h-4 w-4 mr-2" />
                Paginated
              </TabsTrigger>
              <TabsTrigger value="virtual">
                <BarChart3 className="h-4 w-4 mr-2" />
                Virtual Scroll
                {processedData.length > 1000 && (
                  <Badge variant="secondary" className="ml-2 text-xs">
                    Recommended
                  </Badge>
                )}
              </TabsTrigger>
              <TabsTrigger value="summary">
                <Eye className="h-4 w-4 mr-2" />
                Summary
              </TabsTrigger>
            </TabsList>
          </Tabs>
        )}

        {/* Results table - Regular or Virtual */}
        {viewMode === 'table' && (
          <ScrollArea className="w-full">
            <Table>
              <TableHeader>
                <TableRow className="border-gray-700">
                  {result.headers?.map((header, index) => (
                    <TableHead
                      key={index}
                      className="text-gray-300 cursor-pointer hover:text-white"
                      onClick={() => handleSort(header)}
                    >
                      <div className="flex items-center space-x-1">
                        <span>{header}</span>
                        {getSortIcon(header)}
                      </div>
                    </TableHead>
                  ))}
                </TableRow>
              </TableHeader>
              <TableBody>
                {paginatedData.map((row, rowIndex) => (
                  <TableRow key={rowIndex} className="border-gray-700">
                    {row.map((cell, cellIndex) => (
                      <TableCell key={cellIndex} className="text-gray-300">
                        {cell === null || cell === undefined ? (
                          <span className="text-gray-500 italic">null</span>
                        ) : typeof cell === 'boolean' ? (
                          <Badge
                            variant="outline"
                            className={cell ? 'border-green-500 text-green-400' : 'border-red-500 text-red-400'}
                          >
                            {String(cell)}
                          </Badge>
                        ) : (
                          String(cell)
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            <ScrollBar orientation="horizontal" />
          </ScrollArea>
        )}

        {/* Virtual scrolling for large datasets */}
        {viewMode === 'virtual' && (
          <VirtualScrollTable
            data={tableData}
            columns={virtualColumns}
            rowHeight={48}
            containerHeight={600}
            striped={true}
            highlightOnHover={true}
          />
        )}

        {/* Summary view */}
        {viewMode === 'summary' && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <Card className="glass border-white/10">
