  'CPU Percent': ['cpu', 'processor', 'cpu usage', 'processor usage', 'cpu percent'],
  'Memory GB': ['memory', 'ram', 'mem', 'memory usage'],
  'Disk Free GB': ['disk', 'storage', 'disk space', 'free space', 'available space'],
  'Last Logged In User': ['user', 'logged in', 'last user', 'username'],
  'Last Reboot': ['reboot', 'restart', 'boot time', 'uptime'],
  'Compliance Score': ['compliance', 'score', 'compliance score', 'security score'],
  'Is Virtual': ['virtual', 'vm', 'virtual machine', 'virtualized'],
};

// Operator mappings
const operatorMappings: Record<string, string[]> = {
  'contains': ['contains', 'containing', 'includes', 'including', 'with'],
  'equals': ['equals', 'is', 'equal to', 'exactly'],
  'greater_than': ['greater than', 'more than', 'higher than', 'above', '>'],
  'less_than': ['less than', 'lower than', 'below', 'under', '<'],
  'starts_with': ['starts with', 'beginning with', 'starting'],
  'ends_with': ['ends with', 'ending with', 'ending'],
};

export function useNaturalLanguage(): UseNaturalLanguage {
  const [isProcessing, setIsProcessing] = useState(false);

  // Parse natural language to query
  const parse = useCallback(async (text: string): Promise<NaturalLanguageResult> => {
    setIsProcessing(true);

    try {
      // Simulate processing delay
      await new Promise(resolve => setTimeout(resolve, 500));

      const query: PartialQuery = {
        sensors: [],
        aggregates: [],
        scope: { type: 'all' },
        filters: [],
        filterLogic: 'AND',
        groupBy: [],
        orderBy: [],
        limit: undefined
      };

      const alternatives: QueryAlternative[] = [];
      let confidence = 0;
      let interpretation = '';

      // Try to match patterns
      for (const { pattern, type } of queryPatterns) {
        const match = text.match(pattern);
        if (match) {
          switch (type) {
            case 'list':
            case 'query':
              // Extract sensors
              const sensorText = match[1] || match[2];
              const sensors = extractSensors(sensorText);
              sensors.forEach(sensor => {
                query.sensors.push({
                  sensor: { name: sensor, key: sensor.toLowerCase().replace(/\s+/g, '_'), type: 'text', category: 'General' } as Sensor,
                  isValid: true
                });
              });
              confidence = 0.8;
              interpretation = `Query for ${sensors.join(', ')}`;
              break;

            case 'filter':
            case 'contains':
            case 'comparison':
              // Extract filters
              const filterInfo = extractFilters(text);
              query.filters = filterInfo.filters;
              query.sensors = filterInfo.sensors;
              confidence = 0.75;
              interpretation = `Filter by ${filterInfo.filters.map(f => f.sensor).join(', ')}`;
              break;

            case 'count':
            case 'aggregate':
              // Add count aggregate
              query.aggregates.push({ function: 'count' });
              const countSensors = extractSensors(match[1]);
              countSensors.forEach(sensor => {
                query.sensors.push({
                  sensor: { name: sensor, key: sensor.toLowerCase().replace(/\s+/g, '_'), type: 'text', category: 'General' } as Sensor,
                  isValid: true
                });
              });
              confidence = 0.85;
              interpretation = `Count ${countSensors.join(', ')}`;
              break;

            case 'limit':
              // Extract limit
              query.limit = parseInt(match[1]);
              const limitSensors = extractSensors(match[2]);
              limitSensors.forEach(sensor => {
                query.sensors.push({
                  sensor: { name: sensor, key: sensor.toLowerCase().replace(/\s+/g, '_'), type: 'text', category: 'General' } as Sensor,
                  isValid: true
                });
              });
              confidence = 0.9;
              interpretation = `Top ${query.limit} ${limitSensors.join(', ')}`;
              break;
          }
          break;
        }
      }

      // Fallback: try to extract any sensors mentioned
      if (query.sensors.length === 0) {
        const sensors = extractSensors(text);
        if (sensors.length > 0) {
          sensors.forEach(sensor => {
            query.sensors.push({
              sensor: { name: sensor, key: sensor.toLowerCase().replace(/\s+/g, '_'), type: 'text', category: 'General' } as Sensor,
              isValid: true
            });
          });
          confidence = 0.5;
          interpretation = `Query for ${sensors.join(', ')}`;
        } else {
          // Default to Computer Name
          query.sensors.push({
            sensor: { name: 'Computer Name', key: 'computer_name', type: 'text', category: 'System' } as Sensor,
            isValid: true
          });
          confidence = 0.3;
          interpretation = 'Default query for Computer Name';
        }
      }

      // Generate alternatives
      if (confidence < 0.8) {
        alternatives.push({
          query: {
            ...query,
            sensors: [
              { sensor: { name: 'Computer Name', key: 'computer_name', type: 'text', category: 'System' } as Sensor, isValid: true },
              { sensor: { name: 'Operating System', key: 'os_platform', type: 'text', category: 'System' } as Sensor, isValid: true }
            ]
          },
          confidence: 0.6,
          explanation: 'Show computer names and operating systems'
        });

        alternatives.push({
          query: {
            ...query,
            sensors: [{ sensor: { name: 'Computer Name', key: 'computer_name', type: 'text', category: 'System' } as Sensor, isValid: true }],
            filters: [{
              id: 'filter-1',
              sensor: 'Operating System',
              operator: 'contains',
              value: 'Windows',
              dataType: 'text'
            }]
          },
          confidence: 0.5,
          explanation: 'Show Windows computers'
        });
      }

      return {
        query,
        confidence,
        alternatives,
        interpretation
      };
    } finally {
      setIsProcessing(false);
    }
  }, []);

  // Extract sensors from text
  const extractSensors = useCallback((text: string): string[] => {
    const foundSensors: string[] = [];
    const lowerText = text.toLowerCase();

    for (const [sensor, keywords] of Object.entries(sensorMappings)) {
      for (const keyword of keywords) {
        if (lowerText.includes(keyword)) {
          foundSensors.push(sensor);
          break;
        }
      }
    }

    return foundSensors.length > 0 ? foundSensors : ['Computer Name'];
  }, []);

  // Extract filters from text
  const extractFilters = useCallback((text: string): { filters: FilterSelection[], sensors: SensorSelection[] } => {
    const filters: FilterSelection[] = [];
    const sensors: SensorSelection[] = [];
    const lowerText = text.toLowerCase();

    // Look for filter conditions
    for (const [operator, keywords] of Object.entries(operatorMappings)) {
      for (const keyword of keywords) {
        if (lowerText.includes(keyword)) {
          // Try to extract sensor and value
          const pattern = new RegExp(`(\\w+(?:\\s+\\w+)*?)\\s+${keyword}\\s+["']?([^"']+)["']?`, 'i');
          const match = text.match(pattern);

          if (match) {
            const sensorName = extractSensors(match[1])[0] || 'Computer Name';
            filters.push({
              id: `filter-${Date.now()}`,
              sensor: sensorName,
              operator: operator as any,
              value: match[2].trim(),
              dataType: 'text'
            });

            sensors.push({
              sensor: { name: sensorName, key: sensorName.toLowerCase().replace(/\s+/g, '_'), type: 'text', category: 'General' } as Sensor,
              isValid: true
            });
          }
        }
      }
    }

    return { filters, sensors };
  }, [extractSensors]);

  // Get suggestions based on partial input
  const getSuggestions = useCallback((text: string, context: PartialQuery): QuerySuggestion[] => {
    const suggestions: QuerySuggestion[] = [];
    const lowerText = text.toLowerCase();

    if (text.length < 2) return suggestions;

    // Suggest sensors
    for (const [sensor, keywords] of Object.entries(sensorMappings)) {
      if (keywords.some(k => k.includes(lowerText) || lowerText.includes(k))) {
        suggestions.push({
          id: `sensor-${sensor}`,
          type: 'sensor',
          text: `Get ${sensor} from all machines`,
          displayText: sensor,
          description: `Add ${sensor} sensor to query`,
          confidence: 0.8,
          category: 'Sensors'
        });
      }
    }

    // Suggest common templates
    if (lowerText.includes('cpu') || lowerText.includes('high')) {
      suggestions.push({
        id: 'template-high-cpu',
        type: 'template',
        text: 'Get Computer Name and CPU Percent from all machines where CPU Percent greater than 80',
        displayText: 'High CPU usage',
        description: 'Find machines with CPU > 80%',
        confidence: 0.9,
        category: 'Templates',
        runtime: 150
      });
    }

    if (lowerText.includes('disk') || lowerText.includes('space')) {
      suggestions.push({
        id: 'template-low-disk',
        type: 'template',
        text: 'Get Computer Name and Disk Free GB from all machines where Disk Free GB less than 50',
        displayText: 'Low disk space',
        description: 'Find machines with < 50GB free',
        confidence: 0.9,
        category: 'Templates',
        runtime: 120
      });
    }

    if (lowerText.includes('windows')) {
      suggestions.push({
        id: 'filter-windows',
        type: 'filter',
        text: 'where Operating System contains "Windows"',
        displayText: 'Filter Windows machines',
        description: 'Add Windows filter',
        confidence: 0.85,
        category: 'Filters'
      });
    }

    // Sort by confidence
    suggestions.sort((a, b) => b.confidence - a.confidence);

    return suggestions.slice(0, 10);
  }, []);

  return {
    parse,
    getSuggestions,
    isProcessing
  };
}

import { useCallback } from 'react';
import {
  UseQueryValidation,
  PartialQuery,
  ValidationState,
  ValidationError,
  ValidationWarning,
  SensorSelection,
  FilterSelection
} from '../types/queryBuilder';

export function useQueryValidation(): UseQueryValidation {
  // Validate entire query
  const validate = useCallback((query: PartialQuery): ValidationState => {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    // Check if query has at least one sensor or aggregate
    if (query.sensors.length === 0 && query.aggregates.length === 0) {
      errors.push({
        field: 'sensors',
        message: 'Query must have at least one sensor or aggregate function',
        severity: 'error'
      });
    }

    // Validate sensors
    query.sensors.forEach((sensor, index) => {
      const sensorName = 'name' in sensor.sensor ? sensor.sensor.name : undefined;
      if (!sensorName || sensorName.trim() === '') {
        errors.push({
          field: `sensor[${index}]`,
          message: 'Sensor name cannot be empty',
          severity: 'error'
        });
      }

      // Check for parameterized sensors without values
      if (sensor.parameters) {
        Object.entries(sensor.parameters).forEach(([key, value]) => {
          if (value === undefined || value === '') {
            warnings.push({
              field: `sensor[${index}].${key}`,
              message: `Parameter "${key}" is empty`,
              suggestion: 'Provide a value or use default',
              severity: 'warning'
            });
          }
        });
      }
    });

    // Validate filters
    query.filters.forEach((filter) => {
      if (!filter.sensor || filter.sensor.trim() === '') {
        errors.push({
          field: `filter[${filter.id}]`,
          message: 'Filter must have a sensor selected',
          severity: 'error'
        });
      }

      if (filter.value === '' || filter.value === undefined) {
        errors.push({
          field: `filter[${filter.id}]`,
          message: 'Filter value cannot be empty',
          severity: 'error'
        });
      }

      // Type-specific validation
      if (filter.dataType === 'number' && isNaN(Number(filter.value))) {
        errors.push({
          field: `filter[${filter.id}]`,
          message: 'Filter value must be a valid number',
          severity: 'error'
        });
      }
    });

    // Validate GROUP BY
    if (query.groupBy.length > 0) {
      // Check if non-grouped sensors are aggregated
      const groupedSensors = new Set(query.groupBy);
      const hasNonAggregatedSensors = query.sensors.some(
        s => !groupedSensors.has('name' in s.sensor ? (s.sensor.name || '') : '')
      );

      if (hasNonAggregatedSensors && query.aggregates.length === 0) {
        errors.push({
          field: 'groupBy',
          message: 'Non-grouped sensors must be aggregated when using GROUP BY',
          severity: 'error'
        });
      }
    }

    // Validate ORDER BY
    if (query.orderBy.length > 0) {
      query.orderBy.forEach((order, index) => {
        if (!order.sensor || order.sensor.trim() === '') {
          errors.push({
            field: `orderBy[${index}]`,
            message: 'ORDER BY must specify a sensor',
            severity: 'error'
          });
        }
      });
    }

    // Validate LIMIT
    if (query.limit !== undefined) {
      if (query.limit <= 0) {
        errors.push({
          field: 'limit',
          message: 'LIMIT must be greater than 0',
          severity: 'error'
        });
      }
      if (query.limit > 10000) {
        warnings.push({
          field: 'limit',
          message: 'LIMIT is very high',
          suggestion: 'Consider using a smaller limit for better performance',
          severity: 'warning'
        });
      }
    }

    // Performance warnings
    if (query.sensors.length > 10) {
      warnings.push({
        field: 'sensors',
        message: 'Many sensors selected',
        suggestion: 'Consider reducing sensors for better performance',
        severity: 'warning'
      });
    }

    if (query.filters.length === 0 && query.scope.type === 'all') {
      warnings.push({
        field: 'filters',
        message: 'No filters applied',
        suggestion: 'Consider adding filters to reduce result set',
        severity: 'info'
      });
    }

    // Determine overall validity
    const isValid = errors.length === 0;
    const syntaxValid = errors.filter(e => e.severity === 'critical').length === 0;
    const semanticValid = isValid;

    return {
      isValid,
      errors,
      warnings,
      syntaxValid,
      semanticValid
    };
  }, []);

  // Validate individual sensor
  const validateSensor = useCallback((sensor: SensorSelection): boolean => {
    const sensorName = 'name' in sensor.sensor ? sensor.sensor.name : undefined;
    if (!sensorName || sensorName.trim() === '') {
      return false;
    }

    // Check required parameters
    if (sensor.parameters) {
      const hasEmptyRequired = Object.entries(sensor.parameters).some(
        ([_, value]) => value === undefined || value === ''
      );
      if (hasEmptyRequired) {
        return false;
      }
    }

    return true;
  }, []);

  // Validate individual filter
  const validateFilter = useCallback((filter: FilterSelection): boolean => {
    if (!filter.sensor || filter.sensor.trim() === '') {
      return false;
    }

    if (filter.value === '' || filter.value === undefined) {
      return false;
    }

    // Type validation
    if (filter.dataType === 'number' && isNaN(Number(filter.value))) {
      return false;
    }

    return true;
  }, []);

  // Convert partial query to query string
  const getQueryString = useCallback((query: PartialQuery): string => {
    const parts: string[] = [];

    // Handle raw query
    if (query.rawQuery && query.rawQuery.trim()) {
      return query.rawQuery;
    }

    // Build GET clause
    if (query.sensors.length > 0 || query.aggregates.length > 0) {
      parts.push('Get');

      const items: string[] = [];

      // Add sensors
      query.sensors.forEach(s => {
        let sensorStr = 'name' in s.sensor ? (s.sensor.name || '') : '';

        // Add parameters if any
        if (s.parameters && Object.keys(s.parameters).length > 0) {
          const paramStr = Object.entries(s.parameters)
            .map(([key, value]) => `${key}="${value}"`)
            .join(', ');
          sensorStr += `[${paramStr}]`;
        }

        // Add filter if any
        if (s.filter) {
          sensorStr += ` ${s.filter.operator.replace(/_/g, ' ')} "${s.filter.value}"`;
        }

        items.push(sensorStr);
      });

      // Add aggregates
      query.aggregates.forEach(a => {
        const aggStr = a.sensor
          ? `${a.function}(${a.sensor})`
          : `${a.function}()`;
        items.push(aggStr);
      });

      parts.push(items.join(' and '));
    } else {
      // Default to Computer Name if nothing selected
      parts.push('Get Computer Name');
    }

    // Build FROM clause
    parts.push('from');
    if (query.scope.type === 'all') {
      parts.push('all machines');
    } else if (query.scope.type === 'group' && query.scope.computerGroup) {
      parts.push(`group "${query.scope.computerGroup}"`);
    } else {
      parts.push('all machines');
    }

    // Build WHERE clause
    if (query.filters.length > 0) {
      parts.push('where');

      const buildFilterString = (filters: FilterSelection[], parentId?: string): string => {
        const groupFilters = filters.filter(f =>
          parentId ? f.parentId === parentId : !f.parentId && !f.isNested
        );

        const filterStrings = groupFilters.map(f => {
          const operator = f.operator.replace(/_/g, ' ');
          return `${f.sensor} ${operator} "${f.value}"`;
        });

        // Handle nested groups
        const nestedGroups = filters.filter(f =>
          f.isNested && f.parentId === parentId
        );

        nestedGroups.forEach(group => {
          const nestedString = buildFilterString(filters, group.id);
          if (nestedString) {
            filterStrings.push(`(${nestedString})`);
          }
        });

        return filterStrings.join(` ${query.filterLogic.toLowerCase()} `);
      };

      parts.push(buildFilterString(query.filters));
    }

    // Build GROUP BY clause
    if (query.groupBy.length > 0) {
      parts.push('group by');
      parts.push(query.groupBy.join(', '));
    }

    // Build ORDER BY clause
    if (query.orderBy.length > 0) {
      parts.push('order by');
      const orderParts = query.orderBy.map(o =>
        `${o.sensor} ${o.direction}`
      );
      parts.push(orderParts.join(', '));
    }

    // Build LIMIT clause
    if (query.limit) {
      parts.push(`limit ${query.limit}`);
    }

    return parts.join(' ');
  }, []);

  return {
    validate,
    validateSensor,
    validateFilter,
    getQueryString
  };
}

