import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { TCODomain, Difficulty } from "@/types/exam";
import { cn } from "@/lib/utils";
import {
  BookOpen,
  Server,
  Layers,
  Shield,
  Wrench,
  AlertTriangle,
  Filter,
  ChevronUp,
  ChevronDown,
  Search,
} from "lucide-react";

interface ReviewAnalyticsTableProps {
  incorrectAnswers: Array<{
    questionId: string;
    domain: TCODomain;
    difficulty: Difficulty;
    reviewed: boolean;
    timestamp: Date;
  }>;
  onDomainFilter?: (domain: TCODomain | "all") => void;
  onDifficultyFilter?: (difficulty: Difficulty | "all") => void;
}

type AnalyticsRow = {
  domain: TCODomain;
  total: number;
  reviewed: number;
  pending: number;
  percentageReviewed: number;
  byDifficulty: {
    [Difficulty.BEGINNER]: number;
    [Difficulty.INTERMEDIATE]: number;
    [Difficulty.ADVANCED]: number;
    [Difficulty.EXPERT]: number;
  };
};

type SortField = "domain" | "total" | "reviewed" | "pending" | "percentage";
type SortOrder = "asc" | "desc";

export function ReviewAnalyticsTable({
  incorrectAnswers,
  onDomainFilter,
  onDifficultyFilter,
}: ReviewAnalyticsTableProps) {
  const [sortField, setSortField] = useState<SortField>("total");
  const [sortOrder, setSortOrder] = useState<SortOrder>("desc");
  const [searchTerm, setSearchTerm] = useState("");

  // Calculate analytics data
  const analyticsData = useMemo(() => {
    const domainMap = new Map<TCODomain, AnalyticsRow>();

    incorrectAnswers.forEach((answer) => {
      const existing = domainMap.get(answer.domain) || {
        domain: answer.domain,
        total: 0,
        reviewed: 0,
        pending: 0,
        percentageReviewed: 0,
        byDifficulty: {
          [Difficulty.BEGINNER]: 0,
          [Difficulty.INTERMEDIATE]: 0,
          [Difficulty.ADVANCED]: 0,
          [Difficulty.EXPERT]: 0,
        },
      };

      existing.total++;
      if (answer.reviewed) {
        existing.reviewed++;
      } else {
        existing.pending++;
      }
      existing.byDifficulty[answer.difficulty]++;
      existing.percentageReviewed = Math.round((existing.reviewed / existing.total) * 100);

      domainMap.set(answer.domain, existing);
    });

    return Array.from(domainMap.values());
  }, [incorrectAnswers]);

  // Filter and sort data
  const processedData = useMemo(() => {
    let filtered = analyticsData;

    // Apply search filter
    if (searchTerm) {
      filtered = filtered.filter((row) =>
        row.domain.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Sort data
    return [...filtered].sort((a, b) => {
      let aVal: any, bVal: any;

      switch (sortField) {
        case "domain":
          aVal = a.domain;
          bVal = b.domain;
          break;
        case "total":
          aVal = a.total;
          bVal = b.total;
          break;
        case "reviewed":
          aVal = a.reviewed;
          bVal = b.reviewed;
          break;
        case "pending":
          aVal = a.pending;
          bVal = b.pending;
          break;
        case "percentage":
          aVal = a.percentageReviewed;
          bVal = b.percentageReviewed;
          break;
        default:
          return 0;
      }

      if (sortOrder === "asc") {
        return aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      } else {
        return aVal > bVal ? -1 : aVal < bVal ? 1 : 0;
      }
    });
  }, [analyticsData, searchTerm, sortField, sortOrder]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortOrder("desc");
    }
  };

  const getDomainIcon = (domain: TCODomain) => {
    const iconMap = {
      [TCODomain.ASKING_QUESTIONS]: BookOpen,
      [TCODomain.REFINING_QUESTIONS]: Server,
      [TCODomain.REFINING_TARGETING]: Server,
      [TCODomain.TAKING_ACTION]: Layers,
      [TCODomain.NAVIGATION_MODULES]: Shield,
      [TCODomain.REPORTING_EXPORT]: Wrench,
      [TCODomain.SECURITY]: Shield,
      [TCODomain.FUNDAMENTALS]: BookOpen,
      [TCODomain.TROUBLESHOOTING]: AlertTriangle,
    };
    return iconMap[domain] || BookOpen;
  };

  const getDomainColor = (domain: TCODomain) => {
    const colorMap = {
      [TCODomain.ASKING_QUESTIONS]: "text-green-400",
      [TCODomain.REFINING_QUESTIONS]: "text-blue-400",
      [TCODomain.REFINING_TARGETING]: "text-blue-400",
      [TCODomain.TAKING_ACTION]: "text-cyan-400",
      [TCODomain.NAVIGATION_MODULES]: "text-red-400",
      [TCODomain.REPORTING_EXPORT]: "text-yellow-400",
      [TCODomain.SECURITY]: "text-orange-400",
      [TCODomain.FUNDAMENTALS]: "text-cyan-400",
      [TCODomain.TROUBLESHOOTING]: "text-pink-400",
    };
    return colorMap[domain] || "text-gray-400";
  };

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortField !== field) return null;
    return sortOrder === "asc" ? (
      <ChevronUp className="ml-1 h-3 w-3 inline" />
    ) : (
      <ChevronDown className="ml-1 h-3 w-3 inline" />
    );
  };

  // Summary stats
  const totalQuestions = analyticsData.reduce((sum, row) => sum + row.total, 0);
  const totalReviewed = analyticsData.reduce((sum, row) => sum + row.reviewed, 0);
  const totalPending = analyticsData.reduce((sum, row) => sum + row.pending, 0);
  const overallPercentage = totalQuestions > 0 ? Math.round((totalReviewed / totalQuestions) * 100) : 0;

  return (
    <Card className="glass border-white/10">
      <CardHeader className="sticky top-0 z-10 glass border-b border-white/10">
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2 text-white">
            <AlertTriangle className="h-5 w-5 text-yellow-400" />
            Review Analytics
          </CardTitle>
          <div className="flex items-center gap-2">
            <div className="relative">
              <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <Input
                type="search"
                placeholder="Search domains..."
                className="h-8 w-48 pl-8"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <Badge variant="outline" className="text-white">
              {totalQuestions} Total
            </Badge>
            <Badge variant="outline" className="text-green-400">
              {totalReviewed} Reviewed
            </Badge>
            <Badge variant="outline" className="text-yellow-400">
              {totalPending} Pending
            </Badge>
          </div>
        </div>
        <div className="mt-2">
          <Progress value={overallPercentage} className="h-2" />
          <p className="mt-1 text-xs text-gray-400">{overallPercentage}% Complete</p>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        <Table>
          <TableHeader className="sticky top-24 z-9 glass">
            <TableRow className="border-white/10">
              <TableHead
                className="cursor-pointer text-white hover:text-tanium-accent"
                onClick={() => handleSort("domain")}
              >
                Domain <SortIcon field="domain" />
              </TableHead>
              <TableHead
                className="cursor-pointer text-center text-white hover:text-tanium-accent"
                onClick={() => handleSort("total")}
              >
                Total <SortIcon field="total" />
              </TableHead>
              <TableHead
                className="cursor-pointer text-center text-white hover:text-tanium-accent"
                onClick={() => handleSort("reviewed")}
              >
                Reviewed <SortIcon field="reviewed" />
              </TableHead>
              <TableHead
                className="cursor-pointer text-center text-white hover:text-tanium-accent"
                onClick={() => handleSort("pending")}
              >
                Pending <SortIcon field="pending" />
              </TableHead>
              <TableHead className="text-center text-white">By Difficulty</TableHead>
              <TableHead
                className="cursor-pointer text-center text-white hover:text-tanium-accent"
                onClick={() => handleSort("percentage")}
              >
                Progress <SortIcon field="percentage" />
              </TableHead>
              <TableHead className="text-center text-white">Action</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {processedData.map((row) => {
              const Icon = getDomainIcon(row.domain);
              const color = getDomainColor(row.domain);
              return (
                <TableRow key={row.domain} className="border-white/10 hover:bg-white/5">
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Icon className={cn("h-4 w-4", color)} />
                      <span className="text-white">{row.domain}</span>
                    </div>
                  </TableCell>
                  <TableCell className="text-center">
                    <Badge variant="outline" className="text-white">
                      {row.total}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-center">
                    <Badge variant="outline" className="text-green-400">
                      {row.reviewed}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-center">
                    <Badge variant="outline" className="text-yellow-400">
                      {row.pending}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center justify-center gap-1">
                      {row.byDifficulty[Difficulty.BEGINNER] > 0 && (
                        <Badge variant="secondary" className="bg-green-900/20 text-green-400">
                          B:{row.byDifficulty[Difficulty.BEGINNER]}
                        </Badge>
                      )}
                      {row.byDifficulty[Difficulty.INTERMEDIATE] > 0 && (
                        <Badge variant="secondary" className="bg-yellow-900/20 text-yellow-400">
                          I:{row.byDifficulty[Difficulty.INTERMEDIATE]}
                        </Badge>
                      )}
                      {row.byDifficulty[Difficulty.ADVANCED] > 0 && (
                        <Badge variant="secondary" className="bg-red-900/20 text-red-400">
                          A:{row.byDifficulty[Difficulty.ADVANCED]}
                        </Badge>
                      )}
                      {row.byDifficulty[Difficulty.EXPERT] > 0 && (
                        <Badge variant="secondary" className="bg-purple-900/20 text-purple-400">
                          E:{row.byDifficulty[Difficulty.EXPERT]}
                        </Badge>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Progress value={row.percentageReviewed} className="h-2 flex-1" />
                      <span className="text-xs text-gray-400">{row.percentageReviewed}%</span>
                    </div>
                  </TableCell>
                  <TableCell className="text-center">
                    <Button
                      size="sm"
                      variant="ghost"
                      className="text-tanium-accent hover:bg-tanium-accent/20"
                      onClick={() => onDomainFilter?.(row.domain)}
                    >
                      <Filter className="h-3 w-3 mr-1" />
                      Filter
                    </Button>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Search, X, Clock, TrendingUp } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { useSearch } from "@/contexts/SearchContext";
import { cn } from "@/lib/utils";

export function SearchHeader() {
  const { state, setQuery, generateSuggestions, resetSearch } = useSearch();
  const [inputValue, setInputValue] = useState(state.query);
  const [showSuggestions, setShowSuggestions] = useState(false);

  useEffect(() => {
    setInputValue(state.query);
  }, [state.query]);

  const handleInputChange = (value: string) => {
    setInputValue(value);
    setQuery(value);
    generateSuggestions(value);
    setShowSuggestions(value.length > 0);
  };

  const handleSuggestionClick = (suggestion: string) => {
    setInputValue(suggestion);
    setQuery(suggestion);
    setShowSuggestions(false);
  };

  const handleClear = () => {
    setInputValue("");
    setQuery("");
    setShowSuggestions(false);
  };

  const handleShowAll = () => {
    resetSearch();
    setInputValue("");
    setShowSuggestions(false);
  };

  return (
    <div className="relative">
      <div className="flex items-center gap-4">
        {/* Main Search Input */}
        <div className="relative flex-1">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 transform text-gray-400" />
            <Input
              type="text"
              placeholder="Search questions, domains, or topics..."
              value={inputValue}
              onChange={(e) => handleInputChange(e.target.value)}
              onFocus={() => setShowSuggestions(inputValue.length > 0)}
              onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
              className="border-white/20 bg-white/5 pl-10 pr-10 text-white placeholder:text-gray-400 focus:border-tanium-accent"
            />
            {inputValue && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={handleClear}
                className="absolute right-1 top-1/2 h-8 w-8 -translate-y-1/2 transform p-0 text-gray-400 hover:text-white"
              >
                <X className="h-4 w-4" />
              </Button>
            )}
          </div>

          {/* Search Suggestions Dropdown */}
          {showSuggestions && (state.suggestions.length > 0 || state.searchHistory.length > 0) && (
            <Card className="glass absolute left-0 right-0 top-full z-50 mt-2 border-white/10 bg-slate-900/95 backdrop-blur-md">
              <div className="space-y-3 p-4">
                {/* Suggestions */}
                {state.suggestions.length > 0 && (
                  <div>
                    <div className="mb-2 flex items-center gap-2 text-sm text-gray-400">
                      <TrendingUp className="h-4 w-4" />
                      Suggestions
                    </div>
                    <div className="space-y-1">
                      {state.suggestions.map((suggestion, index) => (
                        <button
                          key={index}
                          onClick={() => handleSuggestionClick(suggestion)}
                          className="block w-full rounded-md px-3 py-2 text-left text-white transition-colors hover:bg-white/10"
                        >
                          {suggestion}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Search History */}
                {state.searchHistory.length > 0 && state.suggestions.length > 0 && (
                  <div className="border-t border-white/10 pt-3">
                    <div className="mb-2 flex items-center gap-2 text-sm text-gray-400">
                      <Clock className="h-4 w-4" />
                      Recent Searches
                    </div>
                    <div className="space-y-1">
                      {state.searchHistory.slice(0, 3).map((query, index) => (
                        <button
                          key={index}
                          onClick={() => handleSuggestionClick(query)}
                          className="block w-full rounded-md px-3 py-2 text-left text-gray-300 transition-colors hover:bg-white/10"
                        >
                          {query}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </Card>
          )}
        </div>

        {/* Show All Button */}
        <Button
          onClick={handleShowAll}
          variant="outline"
          className="border-white/20 text-white hover:bg-white/10"
        >
          Show All
        </Button>
      </div>

      {/* Search Stats */}
      <div className="mt-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          {state.isSearching && (
            <div className="flex items-center gap-2 text-gray-300">
              <div className="h-4 w-4 animate-spin rounded-full border-b-2 border-tanium-accent"></div>
              <span className="text-sm">Searching...</span>
            </div>
          )}

          {!state.isSearching && state.totalResults > 0 && (
            <div className="text-sm text-gray-300">
              Found <span className="font-medium text-white">{state.totalResults}</span> question
              {state.totalResults !== 1 ? "s" : ""}
              {state.query && (
                <span>
                  {" "}
                  for &ldquo;<span className="text-tanium-accent">{state.query}</span>&rdquo;
                </span>
              )}
            </div>
          )}

          {/* Active Filters Count */}
          {(() => {
            const activeFilterCount =
              [...state.filters.domains, ...state.filters.difficulties, ...state.filters.categories]
                .length +
              (state.filters.hasExplanation !== undefined ? 1 : 0) +
              (state.filters.hasConsoleSteps !== undefined ? 1 : 0);

            return activeFilterCount > 0 ? (
              <Badge variant="secondary" className="text-xs">
                {activeFilterCount} filter{activeFilterCount !== 1 ? "s" : ""} active
              </Badge>
            ) : null;
          })()}
        </div>

        {/* Quick Domain Filters */}
        <div className="hidden gap-2 lg:flex">
          {(
            [
              "Asking Questions",
              "Refining Questions & Targeting",
              "Taking Action - Packages & Actions",
            ] as const
          ).map((domain) => {
            const isActive = state.filters.domains.includes(domain);
            return (
              <Button
                key={domain}
                variant={isActive ? "default" : "ghost"}
                size="sm"
                onClick={() => {
                  const newDomains = isActive
                    ? state.filters.domains.filter((d) => d !== domain)
                    : [...state.filters.domains, domain];
                  setQuery("");
                  // This would need to call setFilters from the search context
                }}
                className={cn(
                  "text-xs transition-colors",
                  isActive
                    ? "bg-tanium-accent text-white hover:bg-blue-600"
                    : "text-gray-300 hover:bg-white/10 hover:text-white"
                )}
              >
                {domain ? domain.split(" ")[0] : domain} {/* Show first word */}
              </Button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import {
  Search,
  Plus,
  Check,
  ChevronDown,
  ChevronUp,
  BookOpen,
  Lightbulb,
  Terminal,
  Clock,
} from "lucide-react";
import { useSearch } from "@/contexts/SearchContext";
import type { Question } from "@/types/exam";
import { cn } from "@/lib/utils";

interface QuestionResultCardProps {
  question: Question;
  relevanceScore: number;
  matchedFields: string[];
  isSelected: boolean;
  onToggleSelection: () => void;
  searchQuery: string;
}

function QuestionResultCard({
  question,
  relevanceScore,
  matchedFields,
  isSelected,
  onToggleSelection,
  searchQuery,
}: QuestionResultCardProps) {
  const [isExpanded, setIsExpanded] = useState(false);

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case "Beginner":
        return "bg-green-500";
      case "Intermediate":
        return "bg-yellow-500";
      case "Advanced":
        return "bg-red-500";
      default:
        return "bg-gray-500";
    }
  };

  const highlightText = (text: string, query: string) => {
    if (!query.trim()) return text;

    const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi");
    return text.split(regex).map((part, index) =>
      regex.test(part) ? (
        <mark key={index} className="rounded bg-tanium-accent/30 px-1 text-tanium-accent">
          {part}
        </mark>
      ) : (
        part
      )
    );
  };

  return (
    <Card className="glass border-white/10 transition-all duration-200 hover:border-white/20">
      <div className="p-6">
        {/* Header */}
        <div className="mb-4 flex items-start gap-4">
          <Checkbox
            checked={isSelected}
            onCheckedChange={onToggleSelection}
            className="mt-1 border-white/20 data-[state=checked]:bg-tanium-accent"
          />

          <div className="min-w-0 flex-1">
            <div className="mb-2 flex flex-wrap items-center gap-2">
              <Badge
                variant="secondary"
                className={cn("text-xs text-white", getDifficultyColor(question.difficulty))}
              >
                {question.difficulty}
              </Badge>

              <Badge variant="outline" className="border-white/20 text-xs text-gray-300">
                {question.domain}
              </Badge>

              <Badge variant="outline" className="border-white/20 text-xs text-gray-300">
                {question.category}
              </Badge>

              {/* Relevance Score */}
              {relevanceScore > 1 && (
                <Badge
                  variant="secondary"
                  className="bg-tanium-accent/20 text-xs text-tanium-accent"
                >
                  {Math.round(relevanceScore * 10)}% match
                </Badge>
              )}
            </div>

            {/* Question Text */}
            <h3 className="mb-3 font-medium leading-relaxed text-white">
              {highlightText(question.question, searchQuery)}
            </h3>

            {/* Matched Fields */}
            {matchedFields.length > 0 && (
              <div className="mb-3 flex items-center gap-1">
                <span className="text-xs text-gray-400">Matches in:</span>
                {matchedFields.map((field, index) => (
                  <Badge
                    key={index}
                    variant="outline"
                    className="border-tanium-accent/50 text-xs text-tanium-accent"
                  >
                    {field}
                  </Badge>
                ))}
              </div>
            )}

            {/* Features */}
            <div className="flex items-center gap-4 text-xs text-gray-400">
              {question.explanation && (
                <div className="flex items-center gap-1">
                  <Lightbulb className="h-3 w-3" />
                  <span>Detailed explanation</span>
                </div>
              )}

              {question.consoleSteps && question.consoleSteps.length > 0 && (
                <div className="flex items-center gap-1">
                  <Terminal className="h-3 w-3" />
                  <span>Console steps</span>
                </div>
              )}

              {question.studyGuideRef && (
                <div className="flex items-center gap-1">
                  <BookOpen className="h-3 w-3" />
                  <span>Study guide</span>
                </div>
              )}
            </div>
          </div>

          {/* Expand/Select Actions */}
          <div className="flex items-center gap-2">
            {isSelected ? (
              <Button
                onClick={onToggleSelection}
                size="sm"
                className="bg-tanium-accent text-white hover:bg-blue-600"
              >
                <Check className="mr-1 h-4 w-4" />
                Selected
              </Button>
            ) : (
              <Button
                onClick={onToggleSelection}
                variant="outline"
                size="sm"
                className="border-white/20 text-white hover:bg-white/10"
              >
                <Plus className="mr-1 h-4 w-4" />
                Select
              </Button>
            )}

            <Button
              onClick={() => setIsExpanded(!isExpanded)}
              variant="ghost"
              size="sm"
              className="p-2 text-gray-400 hover:text-white"
            >
              {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
            </Button>
          </div>
        </div>

        {/* Expanded Content */}
        <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
          <CollapsibleContent className="space-y-4">
            {/* Answer Choices */}
            <div className="border-t border-white/10 pt-4">
              <h4 className="mb-3 text-sm font-medium text-white">Answer Choices:</h4>
              <div className="space-y-2">
                {question.choices.map((choice, index) => (
                  <div
                    key={choice.id}
                    className={cn(
                      "rounded-lg border p-3 transition-colors",
                      choice.id === question.correctAnswerId
                        ? "border-green-500/50 bg-green-500/10"
                        : "border-white/10 bg-white/5"
                    )}
                  >
                    <div className="flex items-start gap-3">
                      <span className="mt-1 text-sm font-medium text-gray-400">
                        {String.fromCharCode(65 + index)}.
                      </span>
                      <span className="flex-1 text-sm text-gray-300">
                        {highlightText(choice.text, searchQuery)}
                      </span>
                      {choice.id === question.correctAnswerId && (
                        <Badge variant="secondary" className="bg-green-500 text-xs text-white">
                          Correct
                        </Badge>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Explanation */}
            {question.explanation && (
              <div className="border-t border-white/10 pt-4">
                <h4 className="mb-2 flex items-center gap-2 text-sm font-medium text-white">
                  <Lightbulb className="h-4 w-4" />
                  Explanation:
                </h4>
                <p className="text-sm leading-relaxed text-gray-300">
                  {highlightText(question.explanation, searchQuery)}
                </p>
              </div>
            )}

            {/* Console Steps */}
            {question.consoleSteps && question.consoleSteps.length > 0 && (
              <div className="border-t border-white/10 pt-4">
                <h4 className="mb-2 flex items-center gap-2 text-sm font-medium text-white">
                  <Terminal className="h-4 w-4" />
                  Console Steps:
                </h4>
                <div className="space-y-2">
                  {question.consoleSteps.map((step, index) => (
                    <div key={index} className="flex items-start gap-3 rounded bg-slate-800/50 p-2">
                      <span className="mt-1 font-mono text-xs text-gray-400">{index + 1}.</span>
                      <code className="flex-1 font-mono text-xs text-green-400">{step}</code>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Study References */}
            {(question.studyGuideRef || question.officialRef) && (
              <div className="border-t border-white/10 pt-4">
                <h4 className="mb-2 flex items-center gap-2 text-sm font-medium text-white">
                  <BookOpen className="h-4 w-4" />
                  References:
                </h4>
                <div className="space-y-1">
                  {question.studyGuideRef && (
                    <p className="text-xs text-gray-400">
                      Study Guide:{" "}
                      <span className="text-tanium-accent">{question.studyGuideRef}</span>
                    </p>
                  )}
                  {question.officialRef && (
                    <p className="text-xs text-gray-400">
                      Official Docs:{" "}
                      <span className="text-tanium-accent">{question.officialRef}</span>
                    </p>
                  )}
                </div>
              </div>
            )}
          </CollapsibleContent>
        </Collapsible>
      </div>
    </Card>
  );
}

export function SearchResults() {
  const { state, addToSelection, removeFromSelection, setPage } = useSearch();
  const [selectAll, setSelectAll] = useState(false);

  const handleToggleSelection = (question: Question) => {
    const isSelected = state.selectedQuestions.some((q) => q.id === question.id);
    if (isSelected) {
      removeFromSelection(question.id);
    } else {
      addToSelection(question);
    }
  };

  const handleSelectAll = () => {
    if (selectAll) {
      // Clear all selections
      state.selectedQuestions.forEach((q) => removeFromSelection(q.id));
    } else {
      // Select all current results
      state.results.forEach((result) => {
        if (!state.selectedQuestions.some((q) => q.id === result.question.id)) {
          addToSelection(result.question);
        }
      });
    }
    setSelectAll(!selectAll);
  };

  // Calculate pagination
  const { currentPage, itemsPerPage, totalResults } = state;
  const totalPages = Math.ceil(totalResults / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedResults = state.results.slice(startIndex, endIndex);

  if (state.isSearching) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="flex items-center gap-3 text-gray-300">
          <div className="h-6 w-6 animate-spin rounded-full border-b-2 border-tanium-accent"></div>
          <span>Searching questions...</span>
        </div>
      </div>
    );
  }

  if (
    !state.isSearching &&
    state.results.length === 0 &&
    !state.query &&
    Object.values(state.filters).every((v) => !v || (Array.isArray(v) && v.length === 0))
  ) {
    return (
      <div className="py-12 text-center">
        <Card className="glass mx-auto max-w-md border-white/10">
          <div className="p-8">
            <Search className="mx-auto mb-4 h-12 w-12 text-gray-400" />
            <h3 className="mb-2 text-lg font-medium text-white">Ready to Search</h3>
            <p className="text-sm text-gray-300">
              Enter keywords or apply filters to find specific questions from the TCO exam bank.
            </p>
          </div>
        </Card>
      </div>
    );
  }

  if (!state.isSearching && state.results.length === 0) {
    return (
      <div className="py-12 text-center">
        <Card className="glass mx-auto max-w-md border-white/10">
          <div className="p-8">
            <Search className="mx-auto mb-4 h-12 w-12 text-gray-400" />
            <h3 className="mb-2 text-lg font-medium text-white">No questions found</h3>
            <p className="mb-4 text-sm text-gray-300">
              Try different keywords or adjust your filters to find more results.
            </p>
          </div>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Results Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Checkbox
            checked={selectAll}
            onCheckedChange={handleSelectAll}
            className="border-white/20 data-[state=checked]:bg-tanium-accent"
          />
          <span className="text-sm text-gray-300">
            Select all ({paginatedResults.length} questions)
          </span>
        </div>

        {/* Results Info */}
        <div className="text-sm text-gray-400">
          Showing {startIndex + 1}-{Math.min(endIndex, totalResults)} of {totalResults}
        </div>
      </div>

      {/* Results List */}
      <div className="space-y-4">
        {paginatedResults.map((result) => (
          <QuestionResultCard
            key={result.question.id}
            question={result.question}
            relevanceScore={result.relevanceScore}
            matchedFields={result.matchedFields}
            isSelected={state.selectedQuestions.some((q) => q.id === result.question.id)}
            onToggleSelection={() => handleToggleSelection(result.question)}
            searchQuery={state.query}
          />
        ))}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2 pt-6">
          <Button
            onClick={() => setPage(currentPage - 1)}
            disabled={currentPage <= 1}
            variant="outline"
            size="sm"
            className="border-white/20 text-white hover:bg-white/10 disabled:opacity-50"
          >
            Previous
          </Button>

          <div className="flex gap-1">
            {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
              const page = i + 1;
              const isActive = page === currentPage;

              return (
                <Button
                  key={page}
                  onClick={() => setPage(page)}
                  variant={isActive ? "default" : "outline"}
                  size="sm"
                  className={cn(
                    isActive
                      ? "bg-tanium-accent hover:bg-blue-600"
                      : "border-white/20 text-white hover:bg-white/10"
                  )}
                >
                  {page}
                </Button>
              );
            })}

            {totalPages > 5 && (
              <>
                <span className="px-2 text-gray-400">...</span>
                <Button
                  onClick={() => setPage(totalPages)}
                  variant="outline"
                  size="sm"
                  className="border-white/20 text-white hover:bg-white/10"
                >
                  {totalPages}
                </Button>
              </>
            )}
          </div>

          <Button
            onClick={() => setPage(currentPage + 1)}
            disabled={currentPage >= totalPages}
            variant="outline"
            size="sm"
            className="border-white/20 text-white hover:bg-white/10 disabled:opacity-50"
          >
            Next
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import {
  X,
  Play,
  FileText,
  RotateCcw,
  ChevronDown,
  ChevronUp,
  CheckCircle,
  AlertCircle,
} from "lucide-react";
import { useSearch } from "@/contexts/SearchContext";
import { useExam } from "@/contexts/ExamContext";
import { useRouter } from "next/navigation";
import { ExamMode, TCODomain } from "@/types/exam";
import { cn } from "@/lib/utils";

export function SelectedQuestionsPanel() {
  const router = useRouter();
  const { state, removeFromSelection, clearSelection } = useSearch();
  const { startExam } = useExam();
  const [isExpanded, setIsExpanded] = useState(false);

  const handleStartPractice = () => {
    if (state.selectedQuestions.length === 0) return;

    startExam(ExamMode.PRACTICE, state.selectedQuestions);
    clearSelection();
    router.push("/practice");
  };

  const handleCreateMockExam = () => {
    if (state.selectedQuestions.length === 0) return;

    startExam(ExamMode.MOCK, state.selectedQuestions);
    clearSelection();
    router.push("/mock");
  };

  // Calculate domain distribution
  const domainStats = Object.values(TCODomain)
    .map((domain) => {
      const count = state.selectedQuestions.filter((q) => q.domain === domain).length;
      const percentage = count > 0 ? Math.round((count / state.selectedQuestions.length) * 100) : 0;
      return { domain, count, percentage };
    })
    .filter((stat) => stat.count > 0);

  // Calculate difficulty distribution
  const difficultyStats = ["Beginner", "Intermediate", "Advanced"]
    .map((difficulty) => {
      const count = state.selectedQuestions.filter((q) => q.difficulty === difficulty).length;
      const percentage = count > 0 ? Math.round((count / state.selectedQuestions.length) * 100) : 0;
      return { difficulty, count, percentage };
    })
    .filter((stat) => stat.count > 0);

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case "Beginner":
        return "text-green-400";
      case "Intermediate":
        return "text-yellow-400";
      case "Advanced":
        return "text-red-400";
      default:
        return "text-gray-400";
    }
  };

  const getRecommendation = () => {
    const count = state.selectedQuestions.length;
    if (count === 0) return null;
    if (count < 5)
      return { type: "warning", message: "Consider adding more questions for better practice" };
    if (count > 50)
      return {
        type: "warning",
        message: "Large selection - consider breaking into smaller sessions",
      };
    if (count >= 5 && count <= 20)
      return { type: "success", message: "Good selection size for focused practice" };
    if (count >= 21 && count <= 50)
      return { type: "success", message: "Excellent size for comprehensive practice" };
    return null;
  };

  const recommendation = getRecommendation();

  if (state.selectedQuestions.length === 0) {
    return (
      <div className="py-8 text-center">
        <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-white/5">
          <CheckCircle className="h-8 w-8 text-gray-400" />
        </div>
        <h3 className="mb-2 text-sm font-medium text-white">No questions selected</h3>
        <p className="text-xs leading-relaxed text-gray-400">
          Select questions from the search results to create a custom practice session or mock exam.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Selected Count & Actions */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="font-medium text-white">
            {state.selectedQuestions.length} Question
            {state.selectedQuestions.length !== 1 ? "s" : ""}
          </h3>
          <Button
            onClick={clearSelection}
            variant="ghost"
            size="sm"
            className="h-auto p-1 text-gray-400 hover:text-white"
          >
            <RotateCcw className="h-3 w-3" />
          </Button>
        </div>

        {/* Recommendation */}
        {recommendation && (
          <div
            className={cn(
              "flex items-start gap-2 rounded-lg p-3 text-xs",
              recommendation.type === "success"
                ? "border border-green-500/20 bg-green-500/10"
                : "border border-yellow-500/20 bg-yellow-500/10"
            )}
          >
            {recommendation.type === "success" ? (
              <CheckCircle className="mt-0.5 h-3 w-3 shrink-0 text-green-400" />
            ) : (
              <AlertCircle className="mt-0.5 h-3 w-3 shrink-0 text-yellow-400" />
            )}
            <span
              className={recommendation.type === "success" ? "text-green-300" : "text-yellow-300"}
            >
              {recommendation.message}
            </span>
          </div>
        )}

        {/* Action Buttons */}
        <div className="grid grid-cols-1 gap-2">
          <Button
            onClick={handleStartPractice}
            className="justify-center bg-tanium-accent text-white hover:bg-blue-600"
            disabled={state.selectedQuestions.length === 0}
          >
            <Play className="mr-2 h-4 w-4" />
            Start Practice
          </Button>

          <Button
            onClick={handleCreateMockExam}
            variant="outline"
            className="justify-center border-white/20 text-white hover:bg-white/10"
            disabled={state.selectedQuestions.length === 0}
          >
            <FileText className="mr-2 h-4 w-4" />
            Mock Exam
          </Button>
        </div>
      </div>

      <Separator className="bg-white/10" />

      {/* Statistics */}
      <div className="space-y-4">
        {/* Domain Distribution */}
        {domainStats.length > 0 && (
          <div>
            <h4 className="mb-2 text-xs font-medium text-gray-300">Domain Coverage</h4>
            <div className="space-y-2">
              {domainStats.map(({ domain, count, percentage }) => (
                <div key={domain} className="flex items-center justify-between text-xs">
                  <span className="mr-2 flex-1 truncate text-gray-300">
                    {domain.length > 20 ? `${domain.substring(0, 17)}...` : domain}
                  </span>
                  <div className="flex items-center gap-1">
                    <span className="font-medium text-white">{count}</span>
                    <span className="text-gray-400">({percentage}%)</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Difficulty Distribution */}
        {difficultyStats.length > 0 && (
          <div>
            <h4 className="mb-2 text-xs font-medium text-gray-300">Difficulty Mix</h4>
            <div className="space-y-2">
              {difficultyStats.map(({ difficulty, count, percentage }) => (
                <div key={difficulty} className="flex items-center justify-between text-xs">
                  <span className={cn("font-medium", getDifficultyColor(difficulty))}>
                    {difficulty}
                  </span>
                  <div className="flex items-center gap-1">
                    <span className="font-medium text-white">{count}</span>
                    <span className="text-gray-400">({percentage}%)</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <Separator className="bg-white/10" />

      {/* Questions List */}
      <div>
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="flex w-full items-center justify-between text-xs font-medium text-gray-300 transition-colors hover:text-white"
        >
          <span>Selected Questions</span>
          {isExpanded ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
        </button>

        {isExpanded && (
          <ScrollArea className="mt-2 h-64">
            <div className="space-y-2">
              {state.selectedQuestions.map((question, index) => (
                <Card key={question.id} className="border-white/10 bg-white/5 p-3">
                  <div className="flex items-start gap-2">
                    <span className="mt-1 shrink-0 text-xs text-gray-400">{index + 1}.</span>
                    <div className="min-w-0 flex-1">
                      <p className="mb-2 line-clamp-2 text-xs leading-relaxed text-gray-200">
                        {question.question}
                      </p>
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-1">
                          <Badge
                            variant="secondary"
                            className={cn(
                              "px-1 py-0 text-xs",
                              question.difficulty === "Beginner" &&
                                "bg-green-500/20 text-green-300",
                              question.difficulty === "Intermediate" &&
                                "bg-yellow-500/20 text-yellow-300",
                              question.difficulty === "Advanced" && "bg-red-500/20 text-red-300"
                            )}
                          >
                            {question.difficulty.substring(0, 3)}
                          </Badge>
                        </div>
                        <Button
                          onClick={() => removeFromSelection(question.id)}
                          variant="ghost"
                          size="sm"
                          className="h-auto p-1 text-gray-400 hover:text-red-400"
                        >
                          <X className="h-3 w-3" />
                        </Button>
                      </div>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          </ScrollArea>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Card, CardContent } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  AlertTriangle,
  BarChart3,
  Clock,
  Trophy,
  Target,
  TrendingUp,
  CheckCircle,
  BookOpen,
  Brain,
} from "lucide-react";
import { useModules } from "@/contexts/ModuleContext";
import { useProgress } from "@/contexts/ProgressContext";
import { useIncorrectAnswers } from "@/contexts/IncorrectAnswersContext";
import { cn } from "@/lib/utils";
import { TCODomain } from "@/types/exam";

interface ResetProgressDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
}

interface ModuleAnalytics {
  moduleId: string;
  title: string;
  domain: TCODomain;
  timeSpent: number;
  completionPercentage: number;
  questionsAnswered: number;
  accuracy: number;
  lastAccessed: Date | null;
  objectivesCompleted: number;
  totalObjectives: number;
}

export function ResetProgressDialog({
  open,
  onOpenChange,
  onConfirm,
}: ResetProgressDialogProps) {
  const { modules, moduleProgress, resetProgress: resetModuleProgress } = useModules();
  const { state: progressState, getOverallStats, getDomainStats } = useProgress();
  const { state: incorrectState, getTotalIncorrectCount, getDomainStats: getIncorrectDomainStats } = useIncorrectAnswers();

  const [isResetting, setIsResetting] = useState(false);
  const [moduleAnalytics, setModuleAnalytics] = useState<ModuleAnalytics[]>([]);
  const [showFinalWarning, setShowFinalWarning] = useState(false);

  useEffect(() => {
    // Calculate module analytics
    const analytics: ModuleAnalytics[] = modules.map((module) => {
      const progress = moduleProgress[module.id] || {};
      const timeSpent = progress.totalTimeSpent || 0;
      const completionPercentage = progress.overallProgress || 0;
      const objectivesCompleted = Array.isArray(progress.sectionsCompleted)
        ? progress.sectionsCompleted.length
        : 0;
      const totalObjectives = module.objectives?.length || 0;

      return {
        moduleId: module.id,
        title: module.title,
        domain: module.domain as TCODomain,
        timeSpent,
        completionPercentage,
        questionsAnswered: 0, // Would need to calculate from practice sessions
        accuracy: 0, // Would need to calculate from practice sessions
        lastAccessed: progress.lastAccessedAt || null,
        objectivesCompleted,
        totalObjectives,
      };
    });

    setModuleAnalytics(analytics.filter(a => a.timeSpent > 0 || a.completionPercentage > 0));
  }, [modules, moduleProgress]);

  const overallStats = getOverallStats();
  const domainStats = getDomainStats();
  const incorrectDomainStats = getIncorrectDomainStats();
  const totalIncorrect = getTotalIncorrectCount();

  const formatTime = (minutes: number) => {
    if (minutes < 60) return `${minutes}m`;
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}h ${mins}m`;
  };

  const handleReset = async () => {
    setIsResetting(true);

    // Simulate reset process
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Call the actual reset functions
    onConfirm();

    setIsResetting(false);
    setShowFinalWarning(false);
    onOpenChange(false);
  };

  const totalTimeInvested = moduleAnalytics.reduce((sum, m) => sum + m.timeSpent, 0);
  const completedModules = moduleAnalytics.filter(m => m.completionPercentage === 100).length;
  const averageAccuracy = domainStats.reduce((sum, d) => sum + (d.percentage || 0), 0) / (domainStats.length || 1);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[80vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-yellow-400" />
            Reset All Progress
          </DialogTitle>
          <DialogDescription>
            Review your learning journey before resetting. This action cannot be undone.
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-1">
          <Tabs defaultValue="overview" className="w-full">
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="overview">Overview</TabsTrigger>
              <TabsTrigger value="modules">Modules</TabsTrigger>
              <TabsTrigger value="domains">Domains</TabsTrigger>
            </TabsList>

            <TabsContent value="overview" className="space-y-4">
              <Card>
                <CardContent className="pt-6">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Clock className="h-4 w-4" />
                        Total Time Invested
                      </div>
                      <p className="text-2xl font-bold">{formatTime(totalTimeInvested)}</p>
                    </div>

                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Trophy className="h-4 w-4" />
                        Study Streak
                      </div>
                      <p className="text-2xl font-bold">{overallStats.studyStreak} days</p>
                    </div>

                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Target className="h-4 w-4" />
                        Average Score
                      </div>
                      <p className="text-2xl font-bold">{Math.round(averageAccuracy)}%</p>
                    </div>

                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <BookOpen className="h-4 w-4" />
                        Modules Completed
                      </div>
                      <p className="text-2xl font-bold">
                        {completedModules}/{modules.length}
                      </p>
                    </div>
                  </div>
                </CardContent>
              </Card>

              <Alert className="border-yellow-200 bg-yellow-50/10">
                <AlertTriangle className="h-4 w-4 text-yellow-400" />
                <AlertDescription>
                  <strong>You will lose:</strong>
                  <ul className="mt-2 space-y-1 list-disc list-inside">
                    <li>{overallStats.totalQuestions} answered questions</li>
                    <li>{totalIncorrect} questions marked for review</li>
                    <li>All module progress and completion status</li>
                    <li>Performance analytics and insights</li>
                    <li>Study streak of {overallStats.studyStreak} days</li>
                  </ul>
                </AlertDescription>
              </Alert>
            </TabsContent>

            <TabsContent value="modules" className="space-y-4">
              {moduleAnalytics.length === 0 ? (
                <Card>
                  <CardContent className="py-8 text-center text-muted-foreground">
                    No module progress to display
                  </CardContent>
                </Card>
              ) : (
                <div className="space-y-3">
                  {moduleAnalytics.map((module) => (
                    <Card key={module.moduleId}>
                      <CardContent className="py-4">
                        <div className="space-y-3">
                          <div className="flex items-center justify-between">
                            <div>
                              <p className="font-medium">{module.title}</p>
                              <p className="text-sm text-muted-foreground">
                                {module.domain}
                              </p>
                            </div>
                            <div className="text-right">
                              <p className="text-sm font-medium">
                                {module.completionPercentage}% complete
                              </p>
                              <p className="text-xs text-muted-foreground">
                                {formatTime(module.timeSpent)} spent
                              </p>
                            </div>
                          </div>

                          <Progress value={module.completionPercentage} className="h-2" />

                          <div className="flex justify-between text-xs text-muted-foreground">
                            <span>
                              {module.objectivesCompleted}/{module.totalObjectives} objectives
                            </span>
                            {module.lastAccessed && (
                              <span>
                                Last accessed: {new Date(module.lastAccessed).toLocaleDateString()}
                              </span>
                            )}
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              )}
            </TabsContent>

            <TabsContent value="domains" className="space-y-4">
              <div className="space-y-3">
                {domainStats.map((domain) => {
                  const incorrectCount = incorrectDomainStats[domain.domain]?.count || 0;
                  const reviewedCount = incorrectDomainStats[domain.domain]?.reviewed || 0;

                  return (
                    <Card key={domain.domain}>
                      <CardContent className="py-4">
                        <div className="space-y-3">
                          <div className="flex items-center justify-between">
                            <div>
                              <p className="font-medium">{domain.domain}</p>
                              <p className="text-sm text-muted-foreground">
                                {domain.questionsAnswered} questions answered
                              </p>
                            </div>
                            <div className="text-right">
                              <p className="text-sm font-medium">
                                {Math.round(domain.percentage)}% accuracy
                              </p>
                              <p className="text-xs text-muted-foreground">
                                {formatTime(domain.timeSpent)} spent
                              </p>
                            </div>
                          </div>

                          <Progress value={domain.percentage} className="h-2" />

                          {incorrectCount > 0 && (
                            <div className="flex justify-between text-xs">
                              <span className="text-yellow-600">
                                {incorrectCount - reviewedCount} needs review
                              </span>
                              <span className="text-muted-foreground">
                                {reviewedCount} reviewed
                              </span>
                            </div>
                          )}
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            </TabsContent>
          </Tabs>
        </div>

        <DialogFooter className="flex gap-2">
          {!showFinalWarning ? (
            <>
              <Button
                variant="outline"
                onClick={() => onOpenChange(false)}
                disabled={isResetting}
              >
                Cancel
              </Button>
              <Button
                variant="destructive"
                onClick={() => setShowFinalWarning(true)}
                disabled={isResetting}
              >
                <AlertTriangle className="mr-2 h-4 w-4" />
                Continue with Reset
              </Button>
            </>
          ) : (
            <>
              <Alert className="flex-1 border-red-200 bg-red-50/10">
                <AlertTriangle className="h-4 w-4 text-red-400" />
                <AlertDescription>
                  <strong>Final Confirmation:</strong> Type "RESET" to confirm you want to permanently delete all progress.
                </AlertDescription>
              </Alert>
              <Button
                variant="outline"
                onClick={() => setShowFinalWarning(false)}
                disabled={isResetting}
              >
                Back
              </Button>
              <Button
                variant="destructive"
                onClick={handleReset}
                disabled={isResetting}
              >
                {isResetting ? (
                  <>
                    <div className="mr-2 h-4 w-4 animate-spin rounded-full border-b-2 border-white" />
                    Resetting...
                  </>
                ) : (
                  <>
                    <AlertTriangle className="mr-2 h-4 w-4" />
                    Reset Everything
                  </>
                )}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

