interface UserProgress {
  totalQuestions: number;
  correctAnswers: number;
  sessionCount: number;
  studyStreak: number;
  lastStudyDate: string | null;
  hoursStudied: number;
  averageScore: number;
  examReadiness: "Poor" | "Fair" | "Good" | "Excellent";
  domainScores: Record<
    TCODomain,
    {
      score: number;
      questionsAnswered: number;
      correctAnswers: number;
      timeSpent: number;
    }
  >;
  achievements: string[];
  weeklyGoal: number;
  weeklyProgress: number;
  timeSpent?: number; // Total time spent studying in minutes
  // Additional properties that components expect
  moduleProgress?: Record<
    string,
    {
      questionsAttempted: number;
      questionsCorrect: number;
      accuracy: number;
      lastAttempt: Date;
    }
  >;
  assessmentScores?: Record<string, number>;
  streak?: number;
  recentSessions?: Array<{
    domain?: TCODomain;
    score: number; // 0-100
    questions: number;
    time: number; // seconds
    at: string; // iso
  }>;
}

interface ProgressState {
  progress: UserProgress;
  isLoading: boolean;
  error: string | null;
}

type ProgressAction =
  | { type: "LOAD_PROGRESS"; payload: UserProgress }
  | {
      type: "UPDATE_SESSION_STATS";
      payload: { score: number; questionsCount: number; timeSpent: number; domain?: TCODomain };
    }
  | { type: "UPDATE_STUDY_STREAK" }
  | { type: "SET_WEEKLY_GOAL"; payload: number }
  | { type: "ADD_ACHIEVEMENT"; payload: string }
  | { type: "SET_LOADING"; payload: boolean }
  | { type: "SET_ERROR"; payload: string | null }
  | { type: "RESET_PROGRESS" };

interface ProgressContextType {
  state: ProgressState;
  updateSessionStats: (
    score: number,
    questionsCount: number,
    timeSpent: number,
    domain?: TCODomain
  ) => void;
  setWeeklyGoal: (goal: number) => void;
  getOverallStats: () => {
    totalQuestions: number;
    averageScore: number;
    studyStreak: number;
    hoursStudied: number;
    readinessLevel: string;
  };
  getDomainStats: () => Array<{
    domain: TCODomain;
    score: number;
    questionsAnswered: number;
    correctAnswers: number;
    timeSpent: number;
    percentage: number;
  }>;
  getWeeklyProgress: () => { current: number; goal: number; percentage: number };
  resetProgress: () => void;
}

