  timeSpent: 0,
  moduleProgress: {},
  assessmentScores: {},
  streak: 0,
  recentSessions: [],
};

const initialState: ProgressState = {
  progress: initialProgress,
  isLoading: false,
  error: null,
};

function progressReducer(state: ProgressState, action: ProgressAction): ProgressState {
  switch (action.type) {
    case "LOAD_PROGRESS":
      return {
        ...state,
        progress: action.payload,
        isLoading: false,
      };

    case "UPDATE_SESSION_STATS": {
      const { score, questionsCount, timeSpent, domain } = action.payload;
      const newTotalQuestions = state.progress.totalQuestions + questionsCount;
      const newCorrectAnswers =
        state.progress.correctAnswers + Math.round((score / 100) * questionsCount);
      const newAverageScore = Math.round((newCorrectAnswers / newTotalQuestions) * 100);
      const newHoursStudied = state.progress.hoursStudied + timeSpent / 3600; // Convert seconds to hours

      // Determine exam readiness based on average score
      let examReadiness: UserProgress["examReadiness"] = "Poor";
      if (newAverageScore >= 85) examReadiness = "Excellent";
      else if (newAverageScore >= 75) examReadiness = "Good";
      else if (newAverageScore >= 60) examReadiness = "Fair";

      const newProgress: UserProgress = {
        ...state.progress,
        totalQuestions: newTotalQuestions,
        correctAnswers: newCorrectAnswers,
        sessionCount: state.progress.sessionCount + 1,
        hoursStudied: newHoursStudied,
        averageScore: newAverageScore,
        examReadiness,
        weeklyProgress: state.progress.weeklyProgress + 1,
      };

      // Update domain-specific stats if domain is provided
      if (domain) {
        const currentDomainStats = state.progress.domainScores[domain];
        const domainCorrect = Math.round((score / 100) * questionsCount);
        const newDomainQuestions = currentDomainStats.questionsAnswered + questionsCount;
        const newDomainCorrect = currentDomainStats.correctAnswers + domainCorrect;
        const newDomainScore = Math.round((newDomainCorrect / newDomainQuestions) * 100);

        newProgress.domainScores[domain] = {
          score: newDomainScore,
          questionsAnswered: newDomainQuestions,
          correctAnswers: newDomainCorrect,
          timeSpent: currentDomainStats.timeSpent + timeSpent,
        };
      }

      // Track recent sessions (last 10)
      const sessionEntry = {
        domain,
        score,
        questions: questionsCount,
        time: timeSpent,
        at: new Date().toISOString(),
      };
      const nextRecent = [sessionEntry, ...(state.progress.recentSessions || [])].slice(0, 10);
      newProgress.recentSessions = nextRecent;

      return {
        ...state,
        progress: newProgress,
      };
    }

    case "UPDATE_STUDY_STREAK": {
      const today = new Date().toISOString().split("T")[0];
      const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split("T")[0];
      const { lastStudyDate } = state.progress;

      let newStreak = state.progress.studyStreak;

      if (lastStudyDate === yesterday) {
        newStreak += 1;
      } else if (lastStudyDate !== today) {
        newStreak = 1;
      }

      return {
        ...state,
        progress: {
          ...state.progress,
          studyStreak: newStreak,
          lastStudyDate: today,
        },
      };
    }

    case "SET_WEEKLY_GOAL":
      return {
        ...state,
        progress: {
          ...state.progress,
          weeklyGoal: action.payload,
        },
      };

    case "ADD_ACHIEVEMENT": {
      const achievements = [...state.progress.achievements];
      if (!achievements.includes(action.payload)) {
        achievements.push(action.payload);
      }

      return {
        ...state,
        progress: {
          ...state.progress,
          achievements,
        },
      };
    }

    case "SET_LOADING":
      return {
        ...state,
        isLoading: action.payload,
      };

    case "SET_ERROR":
      return {
        ...state,
        error: action.payload,
        isLoading: false,
      };

    case "RESET_PROGRESS":
      return {
        ...initialState,
        progress: { ...initialProgress },
      };

    default:
      return state;
  }
}

const ProgressContext = createContext<ProgressContextType | undefined>(undefined);

export function ProgressProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(progressReducer, initialState);
  const { user } = useAuth();
  const db = useDatabase();
  const lastSavedProgressRef = useRef<string | null>(null);

  // Load progress from database when user is authenticated, fallback to localStorage
  useEffect(() => {
    const loadProgress = async () => {
      if (user) {
        try {
          // TODO: Load from Supabase when user_statistics table is available
          // For now, use initial progress
          dispatch({ type: "LOAD_PROGRESS", payload: initialProgress });
        } catch (error) {
          console.error("Failed to load progress from database:", error);
          // Fallback to localStorage
          loadFromLocalStorage();
        }
      } else {
        // Not authenticated, load from localStorage
        loadFromLocalStorage();
      }
    };

    const loadFromLocalStorage = () => {
      const savedProgress = localStorage.getItem("tco-progress");
      if (savedProgress) {
        try {
          const progress = JSON.parse(savedProgress);
          dispatch({ type: "LOAD_PROGRESS", payload: progress });
        } catch (error) {
          console.error("Failed to load progress from localStorage:", error);
          dispatch({ type: "LOAD_PROGRESS", payload: initialProgress });
        }
      } else {
        dispatch({ type: "LOAD_PROGRESS", payload: initialProgress });
      }
    };

    loadProgress();
  }, [user?.id]);

  // Save progress function with useCallback to prevent infinite loops
  const saveProgress = useCallback(
    async (progress: UserProgress) => {
      if (!state.isLoading && progress.totalQuestions > 0) {
        const progressString = JSON.stringify(progress);

        // Only save if progress has actually changed
        if (lastSavedProgressRef.current !== progressString) {
          lastSavedProgressRef.current = progressString;

          if (user) {
            try {
              // Save domain-specific statistics to database
              const domainEntries = Object.entries(progress.domainScores);

              for (const [domain, stats] of domainEntries) {
                if (stats.questionsAnswered > 0) {
                  await db.upsertUserStatistics({
                    category: domain,
                    total_questions: stats.questionsAnswered,
                    correct_answers: stats.correctAnswers,
                    accuracy_rate: stats.score,
                    average_time:
                      stats.questionsAnswered > 0 ? stats.timeSpent / stats.questionsAnswered : 0,
                  });
                }
              }
            } catch (error) {
              console.error("Failed to save progress to database:", error);
              // Fallback to localStorage
              localStorage.setItem("tco-progress", progressString);
            }
          } else {
            // Not authenticated, save to localStorage
            localStorage.setItem("tco-progress", progressString);
          }
        }
      }
    },
    [user?.id, db] // Added db to dependencies
  );

  // Save progress when specific values change - saveProgress excluded from dependencies (already memoized)
  useEffect(() => {
    saveProgress(state.progress);
  }, [
    state.progress.totalQuestions,
    state.progress.correctAnswers,
    state.progress.sessionCount,
    state.progress.studyStreak,
    state.progress.hoursStudied,
    state.progress.averageScore,
    state.progress.weeklyProgress,
    state.progress.achievements.length,
  ]);

  const updateSessionStats = (
    score: number,
    questionsCount: number,
    timeSpent: number,
    domain?: TCODomain
  ) => {
    dispatch({
      type: "UPDATE_SESSION_STATS",
      payload: { score, questionsCount, timeSpent, domain },
    });
    dispatch({ type: "UPDATE_STUDY_STREAK" });

    // Check for achievements
    if (score === 100) {
      dispatch({ type: "ADD_ACHIEVEMENT", payload: "Perfect Score" });
    }
    if (state.progress.studyStreak >= 7) {
      dispatch({ type: "ADD_ACHIEVEMENT", payload: "Week Warrior" });
    }
    if (state.progress.totalQuestions >= 100) {
      dispatch({ type: "ADD_ACHIEVEMENT", payload: "Centurion" });
    }
  };

  const setWeeklyGoal = (goal: number) => {
    dispatch({ type: "SET_WEEKLY_GOAL", payload: goal });
  };

  const getOverallStats = useCallback(
    () => ({
      totalQuestions: state.progress.totalQuestions,
      averageScore: state.progress.averageScore,
      studyStreak: state.progress.studyStreak,
      hoursStudied: Math.round(state.progress.hoursStudied * 10) / 10,
      readinessLevel: state.progress.examReadiness,
    }),
    [
      state.progress.totalQuestions,
      state.progress.averageScore,
      state.progress.studyStreak,
      state.progress.hoursStudied,
      state.progress.examReadiness,
    ]
  );

  const getDomainStats = useCallback(() => {
    return Object.entries(state.progress.domainScores).map(([domain, stats]) => ({
      domain: domain as TCODomain,
      score: stats.score,
      questionsAnswered: stats.questionsAnswered,
      correctAnswers: stats.correctAnswers,
      timeSpent: stats.timeSpent,
      percentage:
        stats.questionsAnswered > 0
          ? Math.round((stats.correctAnswers / stats.questionsAnswered) * 100)
          : 0,
    }));
  }, [state.progress.domainScores]);

  const getWeeklyProgress = useCallback(
    () => ({
      current: state.progress.weeklyProgress,
      goal: state.progress.weeklyGoal,
      percentage: Math.round((state.progress.weeklyProgress / state.progress.weeklyGoal) * 100),
    }),
    [state.progress.weeklyProgress, state.progress.weeklyGoal]
  );

  const resetProgress = () => {
    localStorage.removeItem("tco-progress");
    lastSavedProgressRef.current = null;
    dispatch({ type: "RESET_PROGRESS" });
  };

  return (
    <ProgressContext.Provider
      value={{
        state,
        updateSessionStats,
        setWeeklyGoal,
        getOverallStats,
        getDomainStats,
        getWeeklyProgress,
        resetProgress,
      }}
    >
      {children}
    </ProgressContext.Provider>
  );
}

export function useProgress() {
  const context = useContext(ProgressContext);
  if (context === undefined) {
    throw new Error("useProgress must be used within a ProgressProvider");
  }
  return context;
}

/**
 * Questions Context
 * Provides questions data from Supabase to the entire application
 */

"use client";

import {
  clearQuestionsCache,
  fetchQuestions,
  fetchQuestionsByCategory,
  fetchQuestionsByDifficulty,
  fetchQuestionsByDomain,
  fetchQuestionsWithFilters,
  loadQuestionsWithFallback,
  searchQuestions,
  subscribeToQuestions,
} from "@/services/questionsService";
import { Difficulty, QuestionCategory, TCODomain, type Question } from "@/types/exam";
import { defaultDifficultyRecord } from '@/lib/difficulty';
import React, { createContext, useCallback, useContext, useEffect, useState } from "react";
import { usePathname } from "next/navigation";

interface QuestionsContextType {
  questions: Question[];
  loading: boolean;
  error: string | null;
  totalQuestions: number;

  // Fetch methods
  refreshQuestions: (forceRefresh?: boolean) => Promise<void>;
  getQuestionsByDomain: (domain: TCODomain) => Promise<Question[]>;
  getQuestionsByDifficulty: (difficulty: Difficulty) => Promise<Question[]>;
  getQuestionsByCategory: (category: QuestionCategory) => Promise<Question[]>;
  getQuestionsWithFilters: (filters: {
    domains?: TCODomain[];
    difficulties?: Difficulty[];
    categories?: QuestionCategory[];
    tags?: string[];
    limit?: number;
  }) => Promise<Question[]>;
  searchQuestionsByText: (searchText: string) => Promise<Question[]>;

  // Assessment methods
  getAssessmentQuestions: (config: {
    type: string;
    moduleId?: string;
    domainFilter?: TCODomain;
    count: number;
  }) => Promise<Question[]>;

  // Utility methods
  getRandomQuestions: (
    count: number,
    filters?: {
      domains?: TCODomain[];
      difficulties?: Difficulty[];
      categories?: QuestionCategory[];
    }
  ) => Question[];
  getQuestionById: (id: string) => Question | undefined;

  // Statistics
  domainDistribution: Record<TCODomain, number>;
  difficultyDistribution: Record<Difficulty, number>;
  categoryDistribution: Record<QuestionCategory, number>;
}

const QuestionsContext = createContext<QuestionsContextType | null>(null);

export function QuestionsProvider({ children }: { children: React.ReactNode }) {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const pathname = typeof window !== 'undefined' ? usePathname() : null;

  // Only load questions on routes that actually need the full bank.
  // This avoids fetching hundreds of questions on pages like /welcome, /mock, /review.
  const shouldLoad = React.useMemo(() => {
    const p = (pathname || "").toLowerCase();
    // Load on admin editor and study/content areas; defer elsewhere
    return [
      "/admin", "/study", "/learn", "/learning", "/modules", "/assessments", "/kb",
    ].some((prefix) => p.startsWith(prefix));
  }, [pathname]);

  const loadInitialQuestions = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      // Use the fallback loader which tries Supabase first, then static data
      const loadedQuestions = await loadQuestionsWithFallback();
      setQuestions(loadedQuestions);
    } catch (err) {
      console.error("Failed to load questions:", err);
      setError("Failed to load questions. Please try again.");
      // Even on error, try to have some questions available
      try {
        const { questionBank } = await import("@/data/sample-questions");
        setQuestions(questionBank);
      } catch {
        setQuestions([]);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  // Load questions only when needed
  useEffect(() => {
    if (!shouldLoad) {
      setLoading(false);
      return;
    }

    let unsub: { unsubscribe: () => void } | null = null;
    loadInitialQuestions();

    // Subscribe to real-time updates only when loading is enabled
    unsub = subscribeToQuestions((payload) => {
      console.log("Questions updated:", payload);
      loadInitialQuestions();
    });

    return () => {
      try { unsub?.unsubscribe(); } catch {}
    };
  }, [loadInitialQuestions, shouldLoad]);

  const refreshQuestions = useCallback(async (forceRefresh = false) => {
    setLoading(true);
    setError(null);

    try {
      if (forceRefresh) {
        clearQuestionsCache();
      }
      const freshQuestions = await fetchQuestions(forceRefresh);
      setQuestions(freshQuestions);
    } catch (err) {
      console.error("Failed to refresh questions:", err);
      setError("Failed to refresh questions.");
    } finally {
      setLoading(false);
    }
  }, []);

  const getQuestionsByDomain = useCallback(
    async (domain: TCODomain) => {
      try {
        return await fetchQuestionsByDomain(domain);
      } catch (err) {
        console.error(`Failed to fetch questions for domain ${domain}:`, err);
        // Fall back to filtering cached questions
        return questions.filter((q) => q.domain === domain);
      }
    },
    [questions]
  );

  const getQuestionsByDifficulty = useCallback(
    async (difficulty: Difficulty) => {
      try {
        return await fetchQuestionsByDifficulty(difficulty);
      } catch (err) {
        console.error(`Failed to fetch questions for difficulty ${difficulty}:`, err);
        // Fall back to filtering cached questions
        return questions.filter((q) => q.difficulty === difficulty);
      }
    },
    [questions]
  );

  const getQuestionsByCategory = useCallback(
    async (category: QuestionCategory) => {
      try {
        return await fetchQuestionsByCategory(category);
      } catch (err) {
        console.error(`Failed to fetch questions for category ${category}:`, err);
        // Fall back to filtering cached questions
        return questions.filter((q) => q.category === category);
      }
    },
    [questions]
  );

  const getQuestionsWithFilters = useCallback(
    async (filters: {
      domains?: TCODomain[];
      difficulties?: Difficulty[];
      categories?: QuestionCategory[];
      tags?: string[];
      limit?: number;
    }) => {
      try {
        return await fetchQuestionsWithFilters(filters);
      } catch (err) {
        console.error("Failed to fetch filtered questions:", err);
        // Fall back to filtering cached questions
        let filtered = [...questions];

        if (filters.domains && filters.domains.length > 0) {
          filtered = filtered.filter((q) => filters.domains!.includes(q.domain));
        }

        if (filters.difficulties && filters.difficulties.length > 0) {
          filtered = filtered.filter((q) => filters.difficulties!.includes(q.difficulty));
        }

        if (filters.categories && filters.categories.length > 0) {
          filtered = filtered.filter((q) => filters.categories!.includes(q.category));
        }

        if (filters.tags && filters.tags.length > 0) {
          filtered = filtered.filter(
            (q) => q.tags && filters.tags!.some((tag) => q.tags!.includes(tag))
          );
        }

        if (filters.limit) {
          filtered = filtered.slice(0, filters.limit);
        }

        return filtered;
      }
    },
    [questions]
  );

  const searchQuestionsByText = useCallback(
    async (searchText: string) => {
      try {
        return await searchQuestions(searchText);
      } catch (err) {
        console.error(`Failed to search questions for "${searchText}":`, err);
        // Fall back to searching cached questions
        const lowerSearch = searchText.toLowerCase();
        return questions.filter(
          (q) =>
            q.question.toLowerCase().includes(lowerSearch) ||
            q.explanation?.toLowerCase().includes(lowerSearch)
        );
      }
    },
    [questions]
  );

  const getRandomQuestions = useCallback(
    (
      count: number,
      filters?: {
        domains?: TCODomain[];
        difficulties?: Difficulty[];
        categories?: QuestionCategory[];
      }
    ): Question[] => {
      if (!questions || !Array.isArray(questions) || questions.length === 0) {
        return [];
      }

      let pool = [...questions];

      // Apply filters if provided
      if (filters) {
        if (filters.domains && filters.domains.length > 0) {
          pool = pool.filter((q) => filters.domains!.includes(q.domain));
        }

        if (filters.difficulties && filters.difficulties.length > 0) {
          pool = pool.filter((q) => filters.difficulties!.includes(q.difficulty));
        }

        if (filters.categories && filters.categories.length > 0) {
          pool = pool.filter((q) => filters.categories!.includes(q.category));
        }
      }

      // Shuffle and take requested count
      const shuffled = pool.sort(() => Math.random() - 0.5);
      return shuffled.slice(0, Math.min(count, shuffled.length));
    },
    [questions]
  );

  const getAssessmentQuestions = useCallback(
    async (config: {
      type: string;
      moduleId?: string;
      domainFilter?: TCODomain;
      count: number;
    }) => {
      try {
        // Start with all questions
        let assessmentQuestions = [...questions];

        // Apply domain filter if provided
        if (config.domainFilter) {
          assessmentQuestions = assessmentQuestions.filter((q) => q.domain === config.domainFilter);
        }

        // Apply module-specific filtering if moduleId is provided
        if (config.moduleId) {
          // Filter questions based on module ID (could be in tags or custom property)
          assessmentQuestions = assessmentQuestions.filter(
            (q) =>
              q.tags?.includes(config.moduleId!) || q.tags?.includes(`module-${config.moduleId}`)
          );
        }

        // For different assessment types, apply different strategies
        switch (config.type) {
          case "practice":
            // Mix of difficulties for practice
            assessmentQuestions = assessmentQuestions.sort(() => Math.random() - 0.5);
            break;
          case "mock_exam":
            // Balanced distribution for mock exams
            const difficulties = [
              Difficulty.BEGINNER,
              Difficulty.INTERMEDIATE,
              Difficulty.ADVANCED,
            ];
            const questionsPerDifficulty = Math.ceil(config.count / difficulties.length);
            let balancedQuestions: Question[] = [];

            difficulties.forEach((difficulty) => {
              const difficultyQuestions = assessmentQuestions
                .filter((q) => q.difficulty === difficulty)
                .sort(() => Math.random() - 0.5)
                .slice(0, questionsPerDifficulty);
              balancedQuestions = balancedQuestions.concat(difficultyQuestions);
            });

            assessmentQuestions = balancedQuestions.sort(() => Math.random() - 0.5);
            break;
          case "final_exam":
            // More advanced questions for final exam
            assessmentQuestions = assessmentQuestions
              .filter(
                (q) =>
                  q.difficulty === Difficulty.INTERMEDIATE || q.difficulty === Difficulty.ADVANCED
              )
              .sort(() => Math.random() - 0.5);
            break;
          default:
            // Default random selection
            assessmentQuestions = assessmentQuestions.sort(() => Math.random() - 0.5);
        }

        // Return the requested number of questions
        return assessmentQuestions.slice(0, config.count);
      } catch (err) {
        console.error("Failed to get assessment questions:", err);
        // Fallback to random selection
        return getRandomQuestions(
          config.count,
          config.domainFilter ? { domains: [config.domainFilter] } : undefined
        );
      }
    },
    [questions, getRandomQuestions]
  );

  const getQuestionById = useCallback(
    (id: string): Question | undefined => {
      return questions.find((q) => q.id === id);
    },
    [questions]
  );

  // Calculate distributions
  const domainDistribution = React.useMemo(() => {
    const dist: Record<TCODomain, number> = {
      [TCODomain.ASKING_QUESTIONS]: 0,
      [TCODomain.REFINING_QUESTIONS]: 0,
      [TCODomain.REFINING_TARGETING]: 0,
      [TCODomain.TAKING_ACTION]: 0,
      [TCODomain.NAVIGATION_MODULES]: 0,
      [TCODomain.REPORTING_EXPORT]: 0,
      [TCODomain.SECURITY]: 0,
      [TCODomain.FUNDAMENTALS]: 0,
      [TCODomain.TROUBLESHOOTING]: 0,
    };

    if (questions && Array.isArray(questions)) {
      questions.forEach((q) => {
        if (q.domain in dist) {
          dist[q.domain]++;
        }
      });
    }

    return dist;
  }, [questions]);

  const difficultyDistribution = React.useMemo(() => {
    const dist: Record<Difficulty, number> = defaultDifficultyRecord(() => 0);

    if (questions && Array.isArray(questions)) {
      questions.forEach((q) => {
        if (q.difficulty in dist) {
          dist[q.difficulty]++;
        }
      });
    }

    return dist;
  }, [questions]);

  const categoryDistribution = React.useMemo(() => {
    const dist: Record<QuestionCategory, number> = {
      [QuestionCategory.PLATFORM_FUNDAMENTALS]: 0,
      [QuestionCategory.CONSOLE_PROCEDURES]: 0,
      [QuestionCategory.TROUBLESHOOTING]: 0,
      [QuestionCategory.PRACTICAL_SCENARIOS]: 0,
      [QuestionCategory.LINEAR_CHAIN]: 0,
    };

    if (questions && Array.isArray(questions)) {
      questions.forEach((q) => {
        if (q.category in dist) {
          dist[q.category]++;
        }
      });
    }

    return dist;
  }, [questions]);

  const value: QuestionsContextType = {
    questions,
    loading,
    error,
    totalQuestions: questions ? questions.length : 0,
    refreshQuestions,
    getQuestionsByDomain,
    getQuestionsByDifficulty,
    getQuestionsByCategory,
    getQuestionsWithFilters,
    searchQuestionsByText,
    getAssessmentQuestions,
    getRandomQuestions,
    getQuestionById,
    domainDistribution,
    difficultyDistribution,
    categoryDistribution,
  };

  return <QuestionsContext.Provider value={value}>{children}</QuestionsContext.Provider>;
}

export function useQuestions() {
  const context = useContext(QuestionsContext);
  if (!context) {
    throw new Error("useQuestions must be used within a QuestionsProvider");
  }
  return context;
}

"use client";

import React, { createContext, useContext, useReducer, useEffect, useCallback } from "react";
import type { Question } from "@/types/exam";
import { useQuestions } from "@/contexts/QuestionsContext";

interface SearchFilters {
  domains: string[];
  difficulties: string[];
  categories: string[];
  hasExplanation?: boolean;
  hasConsoleSteps?: boolean;
}

interface SearchResult {
  question: Question;
  relevanceScore: number;
  matchedFields: string[];
}

interface SearchState {
  query: string;
  filters: SearchFilters;
  results: SearchResult[];
  isSearching: boolean;
  selectedQuestions: Question[];
  searchHistory: string[];
  suggestions: string[];
  currentPage: number;
  itemsPerPage: number;
  totalResults: number;
}

type SearchAction =
  | { type: "SET_QUERY"; query: string }
  | { type: "SET_FILTERS"; filters: Partial<SearchFilters> }
  | { type: "SET_RESULTS"; results: SearchResult[]; totalResults: number }
  | { type: "SET_SEARCHING"; isSearching: boolean }
  | { type: "ADD_TO_SELECTION"; question: Question }
  | { type: "REMOVE_FROM_SELECTION"; questionId: string }
  | { type: "CLEAR_SELECTION" }
  | { type: "SET_PAGE"; page: number }
  | { type: "SET_ITEMS_PER_PAGE"; itemsPerPage: number }
  | { type: "ADD_TO_HISTORY"; query: string }
  | { type: "SET_SUGGESTIONS"; suggestions: string[] }
  | { type: "RESET_SEARCH" };

const initialFilters: SearchFilters = {
  domains: [],
  difficulties: [],
  categories: [],
  hasExplanation: undefined,
  hasConsoleSteps: undefined,
};

const initialState: SearchState = {
  query: "",
  filters: initialFilters,
  results: [],
  isSearching: false,
  selectedQuestions: [],
  searchHistory: [],
  suggestions: [],
  currentPage: 1,
  itemsPerPage: 10,
  totalResults: 0,
};

const searchReducer = (state: SearchState, action: SearchAction): SearchState => {
  switch (action.type) {
    case "SET_QUERY":
      return {
        ...state,
        query: action.query,
        currentPage: 1,
      };

    case "SET_FILTERS":
      return {
        ...state,
        filters: { ...state.filters, ...action.filters },
        currentPage: 1,
      };

    case "SET_RESULTS":
      return {
        ...state,
        results: action.results,
        totalResults: action.totalResults,
        isSearching: false,
      };

    case "SET_SEARCHING":
      return {
        ...state,
        isSearching: action.isSearching,
      };

    case "ADD_TO_SELECTION":
      if (state.selectedQuestions.find((q) => q.id === action.question.id)) {
        return state;
      }
      return {
        ...state,
        selectedQuestions: [...state.selectedQuestions, action.question],
      };

    case "REMOVE_FROM_SELECTION":
      return {
        ...state,
        selectedQuestions: state.selectedQuestions.filter((q) => q.id !== action.questionId),
      };

    case "CLEAR_SELECTION":
      return {
        ...state,
        selectedQuestions: [],
      };

    case "SET_PAGE":
      return {
        ...state,
        currentPage: action.page,
      };

    case "SET_ITEMS_PER_PAGE":
      return {
        ...state,
        itemsPerPage: action.itemsPerPage,
        currentPage: 1,
      };

    case "ADD_TO_HISTORY":
      const newHistory = [
        action.query,
        ...state.searchHistory.filter((q) => q !== action.query),
      ].slice(0, 10); // Keep only last 10 searches
      return {
        ...state,
        searchHistory: newHistory,
      };

    case "SET_SUGGESTIONS":
      return {
        ...state,
        suggestions: action.suggestions,
      };

    case "RESET_SEARCH":
      return {
        ...state,
        query: "",
        filters: initialFilters,
        results: [],
        currentPage: 1,
        totalResults: 0,
      };

    default:
      return state;
  }
};

interface SearchContextValue {
  state: SearchState;
  setQuery: (query: string) => void;
  setFilters: (filters: Partial<SearchFilters>) => void;
  performSearch: () => Promise<void>;
  addToSelection: (question: Question) => void;
  removeFromSelection: (questionId: string) => void;
  clearSelection: () => void;
  setPage: (page: number) => void;
  setItemsPerPage: (itemsPerPage: number) => void;
  resetSearch: () => void;
  generateSuggestions: (query: string) => void;
}

const SearchContext = createContext<SearchContextValue | null>(null);

// Search algorithm with relevance scoring
const calculateRelevanceScore = (
  question: Question,
  query: string,
  filters: SearchFilters
): number => {
  if (
    !query.trim() &&
    Object.values(filters).every((v) => !v || (Array.isArray(v) && v.length === 0))
  ) {
    return 1; // Default score for no search/filters
  }

  let score = 0;
  const queryLower = query.toLowerCase();
  const questionText = question.question.toLowerCase();
  const explanation = question.explanation?.toLowerCase() || "";
  const choices = question.choices.map((c) => c.text.toLowerCase()).join(" ");

  // Text relevance scoring
  if (queryLower) {
    if (questionText.includes(queryLower)) score += 10;
    if (question.domain.toLowerCase().includes(queryLower)) score += 8;
    if (choices.includes(queryLower)) score += 5;
    if (explanation.includes(queryLower)) score += 3;

    // Bonus for exact matches
    if (questionText === queryLower) score += 5;
    if (questionText.startsWith(queryLower)) score += 3;
  }

  return Math.max(score, 0.1); // Minimum score to avoid zero
};

const filterQuestion = (question: Question, filters: SearchFilters): boolean => {
  // Domain filter
  if (filters.domains.length > 0 && !filters.domains.includes(question.domain)) {
    return false;
  }

  // Difficulty filter
  if (filters.difficulties.length > 0 && !filters.difficulties.includes(question.difficulty)) {
    return false;
  }

  // Category filter (if categories exist in question type)
  if (filters.categories.length > 0) {
    // This would need to be implemented based on question categorization
    // For now, we'll skip this filter
  }

  // Has explanation filter
  if (filters.hasExplanation !== undefined) {
    const hasExplanation = !!question.explanation;
    if (filters.hasExplanation !== hasExplanation) {
      return false;
    }
  }

  // Has console steps filter (placeholder for future implementation)
  if (filters.hasConsoleSteps !== undefined) {
    // This would check for console-specific content in questions
    // For now, we'll assume all questions could have console steps
  }

  return true;
};

export function SearchProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(searchReducer, initialState);
  const { questions } = useQuestions();

  // Load search history from localStorage on mount
  useEffect(() => {
    const savedHistory = localStorage.getItem("tco-search-history");
    if (savedHistory) {
      try {
        const history = JSON.parse(savedHistory) as string[];
        history.forEach((query) => {
          dispatch({ type: "ADD_TO_HISTORY", query });
        });
      } catch (error) {
        console.error("Failed to load search history:", error);
      }
    }
  }, []);

  // Save search history to localStorage
  useEffect(() => {
    if (state.searchHistory.length > 0) {
      localStorage.setItem("tco-search-history", JSON.stringify(state.searchHistory));
    }
  }, [state.searchHistory]);

  const setQuery = useCallback((query: string) => {
    dispatch({ type: "SET_QUERY", query });
  }, []);

  const setFilters = useCallback((filters: Partial<SearchFilters>) => {
    dispatch({ type: "SET_FILTERS", filters });
  }, []);

  const performSearch = useCallback(async () => {
    dispatch({ type: "SET_SEARCHING", isSearching: true });

    // Add to search history if query exists
    if (state.query.trim()) {
      dispatch({ type: "ADD_TO_HISTORY", query: state.query.trim() });
    }

    // Simulate async search (in real app, this might be an API call)
    await new Promise((resolve) => setTimeout(resolve, 300));

    try {
      // Check if questions are available before filtering
      if (!questions || !Array.isArray(questions) || questions.length === 0) {
        dispatch({
          type: "SET_RESULTS",
          results: [],
          totalResults: 0,
        });
        dispatch({ type: "SET_SEARCHING", isSearching: false });
        return;
      }

      // Filter and score all questions
      const searchResults: SearchResult[] = questions
        .filter((question) => filterQuestion(question, state.filters))
        .map((question) => ({
          question,
          relevanceScore: calculateRelevanceScore(question, state.query, state.filters),
          matchedFields: getMatchedFields(question, state.query),
        }))
        .filter((result) => result.relevanceScore > 0)
        .sort((a, b) => b.relevanceScore - a.relevanceScore);

      dispatch({
        type: "SET_RESULTS",
        results: searchResults,
        totalResults: searchResults.length,
      });
    } catch (error) {
      console.error("Search failed:", error);
      dispatch({ type: "SET_SEARCHING", isSearching: false });
    }
  }, [state.query, state.filters, questions]);

  // Auto-search when query or filters change (debounced)
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      performSearch();
    }, 300);

    return () => clearTimeout(timeoutId);
  }, [performSearch]);

  const addToSelection = useCallback((question: Question) => {
    dispatch({ type: "ADD_TO_SELECTION", question });
  }, []);

  const removeFromSelection = useCallback((questionId: string) => {
    dispatch({ type: "REMOVE_FROM_SELECTION", questionId });
  }, []);

  const clearSelection = useCallback(() => {
    dispatch({ type: "CLEAR_SELECTION" });
  }, []);

  const setPage = useCallback((page: number) => {
    dispatch({ type: "SET_PAGE", page });
  }, []);

  const setItemsPerPage = useCallback((itemsPerPage: number) => {
    dispatch({ type: "SET_ITEMS_PER_PAGE", itemsPerPage });
  }, []);

  const resetSearch = useCallback(() => {
    dispatch({ type: "RESET_SEARCH" });
  }, []);

  const generateSuggestions = useCallback(
    (query: string) => {
      if (!query.trim()) {
        dispatch({ type: "SET_SUGGESTIONS", suggestions: [] });
        return;
      }

      const queryLower = query.toLowerCase();
      const suggestions = new Set<string>();

      // Add domain suggestions
      const domains = [
        "Platform Fundamentals",
        "Endpoint Management",
        "Content Management",
        "Advanced Features",
        "Troubleshooting",
      ];
      domains.forEach((domain) => {
        if (domain.toLowerCase().includes(queryLower)) {
          suggestions.add(domain);
        }
      });

      // Add common search terms from questions
      const commonTerms = [
        "console",
        "sensor",
        "package",
        "action",
        "question",
        "endpoint",
        "compliance",
        "patch",
        "deployment",
      ];
      commonTerms.forEach((term) => {
        if (term.includes(queryLower)) {
          suggestions.add(term);
        }
      });

      // Add from search history
      state.searchHistory.forEach((historyQuery) => {
        if (historyQuery.toLowerCase().includes(queryLower) && historyQuery !== query) {
          suggestions.add(historyQuery);
        }
      });

      dispatch({
        type: "SET_SUGGESTIONS",
        suggestions: Array.from(suggestions).slice(0, 5),
      });
    },
    [state.searchHistory]
  );

  const value: SearchContextValue = {
    state,
    setQuery,
    setFilters,
    performSearch,
    addToSelection,
    removeFromSelection,
    clearSelection,
    setPage,
    setItemsPerPage,
    resetSearch,
    generateSuggestions,
  };

  return <SearchContext.Provider value={value}>{children}</SearchContext.Provider>;
}

// Helper function to identify matched fields
function getMatchedFields(question: Question, query: string): string[] {
  if (!query.trim()) return [];

  const fields: string[] = [];
  const queryLower = query.toLowerCase();

  if (question.question.toLowerCase().includes(queryLower)) {
    fields.push("question");
  }
  if (question.domain.toLowerCase().includes(queryLower)) {
    fields.push("domain");
  }
  if (question.choices.some((c) => c.text.toLowerCase().includes(queryLower))) {
    fields.push("choices");
  }
  if (question.explanation?.toLowerCase().includes(queryLower)) {
    fields.push("explanation");
  }

  return fields;
}

export function useSearch() {
  const context = useContext(SearchContext);
  if (!context) {
    throw new Error("useSearch must be used within a SearchProvider");
  }
  return context;
}

