// Helper functions for video management
export const getVideosByModule = (moduleId: string): TCOVideo[] => {
  return tcoVideos.filter(video => video.moduleId === moduleId);
};

export const getVideosByDomain = (domain: string): TCOVideo[] => {
  return tcoVideos.filter(video => video.domain === domain);
};

export const getVideoById = (videoId: string): TCOVideo | undefined => {
  return tcoVideos.find(video => video.id === videoId);
};

export const getPrimaryVideoForModule = (moduleId: string): TCOVideo | undefined => {
  const moduleVideos = getVideosByModule(moduleId);
  return moduleVideos[0]; // Return first video as primary
};

export const getTotalVideoWatchTime = (): number => {
  return tcoVideos.reduce((total, video) => total + video.duration, 0);
};

export const getVideosByTag = (tag: string): TCOVideo[] => {
  return tcoVideos.filter(video => video.tags.includes(tag));
};

// Export default for convenience
export default tcoVideos;

"use client";

import { useEffect, useRef } from "react";

interface UseScreenReaderOptions {
  politeness?: "polite" | "assertive";
  atomic?: boolean;
}

export function useScreenReader() {
  const liveRegionRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    // Create live region if it doesn't exist
    if (!liveRegionRef.current) {
      const liveRegion = document.createElement("div");
      liveRegion.setAttribute("aria-live", "polite");
      liveRegion.setAttribute("aria-atomic", "true");
      liveRegion.setAttribute("aria-relevant", "additions text");
      liveRegion.style.position = "absolute";
      liveRegion.style.left = "-10000px";
      liveRegion.style.width = "1px";
      liveRegion.style.height = "1px";
      liveRegion.style.overflow = "hidden";
      liveRegion.id = "screen-reader-announcements";

      document.body.appendChild(liveRegion);
      liveRegionRef.current = liveRegion;
    }

    return () => {
      if (liveRegionRef.current) {
        document.body.removeChild(liveRegionRef.current);
        liveRegionRef.current = null;
      }
    };
  }, []);

  const announce = (message: string, options: UseScreenReaderOptions = {}) => {
    const { politeness = "polite", atomic = true } = options;

    if (!liveRegionRef.current) return;

    // Update live region attributes
    liveRegionRef.current.setAttribute("aria-live", politeness);
    liveRegionRef.current.setAttribute("aria-atomic", atomic.toString());

    // Clear existing content and add new message
    liveRegionRef.current.innerHTML = "";
    setTimeout(() => {
      if (liveRegionRef.current) {
        liveRegionRef.current.textContent = message;
      }
    }, 100);

    // Clear message after announcement
    setTimeout(() => {
      if (liveRegionRef.current) {
        liveRegionRef.current.textContent = "";
      }
    }, 5000);
  };

  const announceImmediate = (message: string) => {
    announce(message, { politeness: "assertive" });
  };

  const announcePolite = (message: string) => {
    announce(message, { politeness: "polite" });
  };

  return {
    announce,
    announceImmediate,
    announcePolite,
  };
}

// Hook for managing focus announcements
export function useFocusAnnouncement() {
  const { announce } = useScreenReader();

  const announceFocus = (element: HTMLElement) => {
    const role = element.getAttribute("role");
    const label =
      element.getAttribute("aria-label") ||
      element.getAttribute("title") ||
      element.textContent?.trim();

    if (label) {
      const announcement = role ? `${role}, ${label}` : label;
      announce(announcement, { politeness: "polite" });
    }
  };

  const announceNavigation = (current: string, total?: number, index?: number) => {
    let message = current;
    if (total && index !== undefined) {
      message += `, ${index + 1} of ${total}`;
    }
    announce(message, { politeness: "polite" });
  };

  const announceStatus = (status: string) => {
    announce(status, { politeness: "assertive" });
  };

  return {
    announceFocus,
    announceNavigation,
    announceStatus,
  };
}

// Hook for managing exam-specific screen reader announcements
export function useExamAnnouncements() {
  const { announce, announceImmediate } = useScreenReader();

  const announceQuestion = (questionNumber: number, totalQuestions: number, question: string) => {
    const message = `Question ${questionNumber} of ${totalQuestions}: ${question}`;
    announce(message, { politeness: "polite" });
  };

  const announceAnswer = (isCorrect: boolean, explanation?: string) => {
    const result = isCorrect ? "Correct answer" : "Incorrect answer";
    let message = result;
    if (explanation) {
      message += `. ${explanation}`;
    }
    announceImmediate(message);
  };

  const announceProgress = (current: number, total: number, percentage: number) => {
    const message = `Progress: ${current} of ${total} questions completed, ${percentage}% complete`;
    announce(message, { politeness: "polite" });
  };

  const announceExamStart = (mode: string, questionCount: number, timeLimit?: number) => {
    let message = `Starting ${mode} mode with ${questionCount} questions`;
    if (timeLimit) {
      message += ` and ${Math.floor(timeLimit / 60)} minute time limit`;
    }
    announceImmediate(message);
  };

  const announceExamEnd = (score: number, passed: boolean) => {
    const result = passed ? "passed" : "did not pass";
    const message = `Exam completed. You ${result} with a score of ${score}%`;
    announceImmediate(message);
  };

  const announceTimeWarning = (minutesRemaining: number) => {
    const message = `Time warning: ${minutesRemaining} minutes remaining`;
    announceImmediate(message);
  };

  return {
    announceQuestion,
    announceAnswer,
    announceProgress,
    announceExamStart,
    announceExamEnd,
    announceTimeWarning,
  };
}

"use client";

// Inspired by react-hot-toast library
import * as React from "react";

import type { ToastActionElement, ToastProps } from "@/components/ui/toast";

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
};

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType["ADD_TOAST"];
      toast: ToasterToast;
    }
  | {
      type: ActionType["UPDATE_TOAST"];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType["DISMISS_TOAST"];
      toastId?: ToasterToast["id"];
    }
  | {
      type: ActionType["REMOVE_TOAST"];
      toastId?: ToasterToast["id"];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: "REMOVE_TOAST",
      toastId,
    });
  }, TOAST_REMOVE_DELAY);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      };

    case "DISMISS_TOAST": {
      const { toastId } = action;

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      };
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, "id">;

function toast({ ...props }: Toast) {
  const id = genId();

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id });

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  return {
    id,
    dismiss,
    update,
  };
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState);

  React.useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, [state]);

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  };
}

export { useToast, toast };

import { useState, useCallback, useEffect } from "react";
import { AssessmentEngine } from "../lib/assessment/assessment-engine";
import { ProgressService } from "../lib/services/progress-service";
import { AnalyticsService } from "../lib/services/analytics-service";
import type {
  AssessmentConfig,
  AssessmentSession,
  AssessmentResult,
  QuestionAnswer,
  AnalyticsEvent,
} from "../types/assessment";

export interface UseAssessmentReturn {
  currentSession: AssessmentSession | null;
  currentResult: AssessmentResult | null;
  isLoading: boolean;
  error: string | null;

  // Assessment lifecycle
  startAssessment: (config: AssessmentConfig) => Promise<void>;
  submitAnswer: (questionId: string, answer: QuestionAnswer) => Promise<void>;
  submitAssessment: () => Promise<AssessmentResult>;
  cancelAssessment: () => void;

  // Progress tracking
  updateProgress: (progress: any) => Promise<void>;
  getProgress: (userId: string, moduleId?: string) => Promise<any>;

  // Analytics
  trackEvent: (event: AnalyticsEvent) => Promise<void>;
  getAnalytics: (userId: string, timeRange?: string) => Promise<any>;
}

export function useAssessment(): UseAssessmentReturn {
  const [currentSession, setCurrentSession] = useState<AssessmentSession | null>(null);
  const [currentResult, setCurrentResult] = useState<AssessmentResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Assessment lifecycle methods
  const startAssessment = useCallback(async (config: AssessmentConfig) => {
    try {
      setIsLoading(true);
      setError(null);

      // Initialize assessment session
      const sessionData = await AssessmentEngine.initializeSession(config);

      const session: AssessmentSession = {
        id: sessionData.sessionId,
        assessmentId: config.assessmentId,
        userId: config.userId,
        moduleId: config.moduleId,
        type: config.assessmentType,
        status: "in_progress",
        startTime: new Date(),
        timeLimit: config.timeLimit,
        questions: sessionData.questions,
        answers: [],
        currentQuestionIndex: 0,
        score: null,
        passed: null,
        completedAt: null,
      };

      setCurrentSession(session);

      // Track assessment start
      await AnalyticsService.track({
        type: "assessment_started",
        userId: config.userId ?? "",
        data: {
          assessmentId: config.assessmentId,
          assessmentType: config.assessmentType,
          moduleId: config.moduleId,
          questionCount: sessionData.questions.length,
          timeLimit: config.timeLimit,
        },
        timestamp: new Date(),
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to start assessment");
      console.error("Error starting assessment:", err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const submitAnswer = useCallback(
    async (questionId: string, answer: QuestionAnswer) => {
      if (!currentSession) {
        throw new Error("No active assessment session");
      }

      try {
        setError(null);

        // Update session with answer
  const updatedAnswers = Array.isArray(currentSession.answers) ? [...currentSession.answers] : [];
        const existingAnswerIndex = updatedAnswers.findIndex((a) => a.questionId === questionId);

        if (existingAnswerIndex >= 0) {
          updatedAnswers[existingAnswerIndex] = answer;
        } else {
          updatedAnswers.push(answer);
        }

        const updatedSession = {
          ...currentSession,
          answers: updatedAnswers,
        };

        setCurrentSession(updatedSession);

        // Update assessment engine
        await AssessmentEngine.updateSession(currentSession.id, {
          answers: updatedAnswers,
        });

        // Track answer submission (provide normalized 'selectedAnswers' and keep 'answer' for compatibility)
        await AnalyticsService.track({
          type: "question_answered",
          userId: currentSession.userId ?? "",
          sessionId: currentSession.id,
          data: {
            sessionId: currentSession.id,
            questionId,
            selectedAnswers: ((answer as any).selectedAnswers ?? (
              Array.isArray((answer as any).selectedAnswer)
                ? (answer as any).selectedAnswer
                : [(answer as any).selectedAnswer]
            )).filter(Boolean),
            // Backward compatible alias
            answer: (answer as any).selectedAnswers ?? (answer as any).selectedAnswer,
            timeSpent: (answer as any).timeSpent ?? 0,
            attempts: (answer as any).attempts ?? 1,
            confidence: (answer as any).confidence ?? null,
          },
          timestamp: new Date(),
        });
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to submit answer");
        console.error("Error submitting answer:", err);
      }
    },
    [currentSession]
  );

  const submitAssessment = useCallback(async (): Promise<AssessmentResult> => {
    if (!currentSession) {
      throw new Error("No active assessment session");
    }

    try {
      setIsLoading(true);
      setError(null);

      // Calculate results using assessment engine
      const result = await AssessmentEngine.calculateResults(currentSession);

      // Update session status
      const completedSession = {
        ...currentSession,
        status: "completed" as const,
        completedAt: new Date(),
        score: result.overallScore,
        passed: result.passed,
      };

      setCurrentSession(completedSession);
      setCurrentResult(result);

      // Update progress tracking (keys aligned with tests)
      await ProgressService.updateAssessmentProgress({
        userId: (currentSession.userId ?? "") as any,
        moduleId: currentSession.moduleId as any,
        assessmentId: currentSession.assessmentId as any,
        score: (result as any).overallScore as any,
        passed: (result as any).passed as any,
        completedAt: (result as any).completedAt as any,
        timeSpent: (result as any).timeSpent ?? (result as any).totalTime ?? 0,
        correctAnswers: (result as any).correctAnswers ?? 0,
        incorrectAnswers: (result as any).incorrectAnswers ?? 0,
        totalQuestions: (result as any).totalQuestions ?? 0,
        domainBreakdown: (result as any).domainBreakdown,
      } as any);

      // Track assessment completion
      await AnalyticsService.track({
        type: "assessment_completed",
        userId: currentSession.userId ?? "",
        sessionId: currentSession.id,
        data: {
          sessionId: currentSession.id,
          score: result.overallScore,
          passed: result.passed,
          timeSpent: result.timeSpent,
          correctAnswers: result.correctAnswers,
          totalQuestions: result.totalQuestions,
          domainBreakdown: (result as any).domainBreakdown,
        },
        timestamp: new Date(),
      });

      return result;
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to submit assessment");
      console.error("Error submitting assessment:", err);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [currentSession]);

  const cancelAssessment = useCallback(() => {
    if (currentSession) {
      // Track assessment cancellation
      AnalyticsService.track({
        type: "assessment_cancelled",
        userId: currentSession.userId,
        sessionId: currentSession.id,
        data: {
          sessionId: currentSession.id,
          questionsAnswered: Array.isArray(currentSession.answers) ? currentSession.answers.length : 0,
          totalQuestions: currentSession.questions.length,
          timeSpent: Date.now() - currentSession.startTime.getTime(),
        },
        timestamp: new Date(),
      });

      // Clear session
      setCurrentSession(null);
      setCurrentResult(null);
    }
    setError(null);
  }, [currentSession]);

  const updateProgress = useCallback(async (progress: any) => {
    try {
      await ProgressService.updateQuestionProgress(progress);
    } catch (err) {
      console.error("Error updating progress:", err);
    }
  }, []);

  const getProgress = useCallback(async (userId: string, moduleId?: string) => {
    try {
      return await ProgressService.getUserProgress(userId, moduleId);
    } catch (err) {
      console.error("Error getting progress:", err);
      return null;
    }
  }, []);

  const trackEvent = useCallback(async (event: AnalyticsEvent) => {
    try {
      await AnalyticsService.track(event);
    } catch (err) {
      console.error("Error tracking event:", err);
    }
  }, []);

  const getAnalytics = useCallback(async (userId: string, timeRange?: string) => {
    try {
      return await AnalyticsService.getUserAnalytics(userId, timeRange);
    } catch (err) {
      console.error("Error getting analytics:", err);
      return null;
    }
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (currentSession && currentSession.status === "in_progress") {
        cancelAssessment();
      }
    };
  }, []);

  return {
    currentSession,
    currentResult,
    isLoading,
    error,
    startAssessment,
    submitAnswer,
    submitAssessment,
    cancelAssessment,
    updateProgress,
    getProgress,
    trackEvent,
    getAnalytics,
  };
}

import { useAuth } from "@/contexts/AuthContext";
import { studyModulesService } from "@/lib/study-modules";
import type { UserBookmarkWithDetails } from "@/types/supabase";
// Local alias used across UI code
type UserStudyBookmark = UserBookmarkWithDetails;
import { useEffect, useState } from "react";

export function useBookmarks() {
  const { user } = useAuth();
  const [bookmarks, setBookmarks] = useState<UserBookmarkWithDetails[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load user bookmarks
  useEffect(() => {
    if (!user) {
      setBookmarks([]);
      setLoading(false);
      return;
    }

    const loadBookmarks = async () => {
      try {
        setLoading(true);
        setError(null);
        const userBookmarks = await studyModulesService.getUserBookmarks(user.id);
        setBookmarks(userBookmarks);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load bookmarks");
        console.error("Error loading user bookmarks:", err);
      } finally {
        setLoading(false);
      }
    };

    loadBookmarks();
  }, [user]);

  // Add a bookmark
  const addBookmark = async (sectionId: string, moduleId: string, notes?: string) => {
    if (!user) return;

    try {
      const newBookmark = await studyModulesService.addBookmark(
        user.id,
        sectionId,
        moduleId,
        notes
      );

      // Update local state
      setBookmarks((prev) => [newBookmark, ...prev]);
      return newBookmark;
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to add bookmark";
      setError(message);
      throw new Error(message);
    }
  };

  // Remove a bookmark
  const removeBookmark = async (sectionId: string) => {
    if (!user) return;

    try {
      await studyModulesService.removeBookmark(user.id, sectionId);

      // Update local state
      setBookmarks((prev) => prev.filter((bookmark) => bookmark.section_id !== sectionId));
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to remove bookmark";
      setError(message);
      throw new Error(message);
    }
  };

  // Update bookmark notes
  const updateBookmarkNotes = async (sectionId: string, notes: string) => {
    if (!user) return;

    try {
      const updatedBookmark = await studyModulesService.updateBookmarkNotes(
        user.id,
        sectionId,
        notes
      );

      // Update local state
      setBookmarks((prev) =>
        prev.map((bookmark) => (bookmark.section_id === sectionId ? updatedBookmark : bookmark))
      );

      return updatedBookmark;
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to update bookmark notes";
      setError(message);
      throw new Error(message);
    }
  };

  // Check if a section is bookmarked
  const isBookmarked = (sectionId: string): boolean => {
    return bookmarks.some((bookmark) => bookmark.section_id === sectionId);
  };

  // Get bookmark for a specific section
  const getBookmark = (sectionId: string): UserStudyBookmark | null => {
    return bookmarks.find((bookmark) => bookmark.section_id === sectionId) || null;
  };

  // Toggle bookmark (add if not exists, remove if exists)
  const toggleBookmark = async (sectionId: string, moduleId: string, notes?: string) => {
    if (isBookmarked(sectionId)) {
      await removeBookmark(sectionId);
      return null;
    } else {
      return await addBookmark(sectionId, moduleId, notes);
    }
  };

  // Get bookmarks by module
  const getBookmarksByModule = (moduleId: string): UserStudyBookmark[] => {
    return bookmarks.filter((bookmark) => bookmark.module_id === moduleId);
  };

  // Get bookmarks count
  const getBookmarksCount = (): number => {
    return bookmarks.length;
  };

  // Get recent bookmarks (last 5)
  const getRecentBookmarks = (limit: number = 5): UserStudyBookmark[] => {
    return bookmarks.slice(0, limit);
  };

  return {
    bookmarks,
    loading,
    error,
    addBookmark,
    removeBookmark,
    updateBookmarkNotes,
    isBookmarked,
    getBookmark,
    toggleBookmark,
    getBookmarksByModule,
    getBookmarksCount,
    getRecentBookmarks,
  };
}

