  });

  test('pageview is callable', async () => {
    process.env.NEXT_PUBLIC_POSTHOG_KEY = '';
    const { analytics } = await import('@/lib/analytics');
    await expect(analytics.pageview('/x')).resolves.toBeUndefined();
  });
});

import { calculateExamResults } from '@/lib/examLogic';
import { ExamMode, type ExamSession, type Question, Difficulty, QuestionCategory, TCODomain } from '@/types/exam';

function q(id: string, domain: TCODomain): Question {
  return {
    id,
    question: `Q ${id}`,
    choices: [
      { id: 'a', text: 'A' },
      { id: 'b', text: 'B' },
      { id: 'c', text: 'C' },
      { id: 'd', text: 'D' },
    ],
    correctAnswerId: 'b',
    domain,
    difficulty: Difficulty.BEGINNER,
    category: QuestionCategory.PLATFORM_FUNDAMENTALS,
  };
}

describe('calculateExamResults', () => {
  it('computes score, domain breakdown, and pass flag', () => {
    const questions = [
      q('1', TCODomain.ASKING_QUESTIONS),
      q('2', TCODomain.REFINING_TARGETING),
      q('3', TCODomain.TAKING_ACTION),
    ];
    const session: ExamSession = {
      id: 's1',
      mode: ExamMode.PRACTICE,
      questions,
      currentIndex: 3,
      answers: { '1': 'b', '2': 'a', '3': 'b' },
      startTime: new Date(Date.now() - 60_000),
      endTime: new Date(),
      completed: true,
    };
    const result = calculateExamResults(session);
    expect(result.totalCount).toBe(3);
    expect(result.correctCount).toBe(2);
    expect(result.score).toBe(67);
    expect(typeof result.passed).toBe('boolean');
    // domain breakdown sums to total
    const sum = Object.values(result.domainBreakdown).reduce((a, b: any) => a + b.total, 0);
    expect(sum).toBe(3);
  });
});

import { createInitialState, schedule, isDue, getDueQueue } from "@/lib/sr";

describe("sr scheduling", () => {
  const now = new Date("2025-01-01T00:00:00Z");

  test("initial state is due now", () => {
    const s = createInitialState("n1", now);
    expect(isDue(s, now)).toBe(true);
    const q = getDueQueue([s], now);
    expect(q).toHaveLength(1);
    expect(q[0].id).toBe("n1");
  });

  test("good → sets reps and interval progression (1, then 6)", () => {
    let s = createInitialState("n2", now);
    s = schedule(s, "good", now); // first good → 1 day
    expect(s.reps).toBe(1);
    expect(s.interval).toBe(1);

    // After 1 day, good again → 6 days
    const day1 = new Date(now.getTime() + 24 * 60 * 60 * 1000);
    s = schedule(s, "good", day1);
    expect(s.reps).toBe(2);
    expect(s.interval).toBe(6);
  });

  test("easy increases ease and interval more aggressively", () => {
    let s = createInitialState("n3", now);
    const ease0 = s.ease;
    s = schedule(s, "easy", now);
    expect(s.reps).toBe(1);
    expect(s.interval).toBeGreaterThanOrEqual(3);
    expect(s.ease).toBeGreaterThan(ease0);
  });

  test("again resets reps and reduces ease, due next day", () => {
    let s = createInitialState("n4", now);
    s = schedule(s, "good", now);
    const before = s.ease;
    const later = new Date(now.getTime() + 1000);
    s = schedule(s, "again", later);
    expect(s.reps).toBe(0);
    expect(s.lapses).toBe(1);
    expect(s.ease).toBeLessThanOrEqual(before);
    expect(s.interval).toBe(1);
  });
});

// Lightweight PostHog-compatible analytics wrapper (no external deps)
// Sends events to PostHog ingestion API if NEXT_PUBLIC_POSTHOG_KEY is present.

export type AnalyticsProps = Record<string, any>;

const KEY = process.env.NEXT_PUBLIC_POSTHOG_KEY || "";
const DEBUG = (process.env.NEXT_PUBLIC_ANALYTICS_DEBUG || "").toLowerCase() === "true";
const HOST = (process.env.NEXT_PUBLIC_POSTHOG_HOST || "https://us.i.posthog.com").replace(/\/$/, "");
const STORAGE_ID = "ph_distinct_id";

let cachedId: string | null = null;

function uuid(): string {
  if (typeof crypto !== "undefined" && (crypto as any).randomUUID) {
    return (crypto as any).randomUUID();
  }
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

function getDistinctId(): string {
  if (typeof window === "undefined") return "server";
  if (cachedId) return cachedId;
  try {
    const existing = localStorage.getItem(STORAGE_ID);
    if (existing) return (cachedId = existing);
    const id = uuid();
    localStorage.setItem(STORAGE_ID, id);
    cachedId = id;
    return id;
  } catch {
    return (cachedId = uuid());
  }
}

function nowIso(): string {
  try { return new Date().toISOString(); } catch { return ""; }
}

function currentUrl(): string | undefined {
  if (typeof window === "undefined") return undefined;
  try { return window.location.href; } catch { return undefined; }
}

async function sendEvent(name: string, props?: AnalyticsProps) {
  if (!KEY || typeof window === "undefined") return; // disabled
  const distinct_id = getDistinctId();
  const payload: any = {
    api_key: KEY,
    event: name,
    properties: {
      distinct_id,
      $current_url: currentUrl(),
      ...props,
    },
    timestamp: nowIso(),
  };
  const url = `${HOST}/e/`;
  try {
    if (DEBUG) {
      // eslint-disable-next-line no-console
      console.debug("[analytics]", name, { ...payload.properties, timestamp: payload.timestamp });
    }
    if (navigator?.sendBeacon) {
      const blob = new Blob([JSON.stringify(payload)], { type: "application/json" });
      navigator.sendBeacon(url, blob);
    } else {
      await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        keepalive: true,
      });
    }
  } catch {
    // swallow
  }
}

export const analytics = {
  init() {
    // no-op for the lightweight sender; presence of KEY enables capture
    return Boolean(KEY);
  },
  capture(name: string, props?: AnalyticsProps) {
    return sendEvent(name, props);
  },
  pageview(path?: string) {
    return sendEvent("$pageview", path ? { path } : undefined);
  },
  identify(userId?: string | null, traits?: AnalyticsProps) {
    if (!userId) return;
    return sendEvent("$identify", { distinct_id: getDistinctId(), $user_id: userId, ...traits });
  },
};

import { NextResponse } from 'next/server';
import { analytics } from './analytics';

interface ApiError {
  message: string;
  status: number;
  code?: string;
  details?: any;
}

interface ErrorContext {
  endpoint: string;
  method: string;
  userId?: string;
  metadata?: Record<string, any>;
}

/**
 * Masks PII from error data
 */
function maskPII(data: any): any {
  if (!data) return data;

  if (typeof data === 'string') {
    // Mask email addresses
    data = data.replace(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/gi, '***@***.***');
    // Mask phone numbers
    data = data.replace(/(\+?[1-9]\d{1,14})/g, '***-***-****');
    // Mask credit card numbers
    data = data.replace(/\b(?:\d{4}[-\s]?){3}\d{4}\b/g, '****-****-****-****');
    // Mask SSN
    data = data.replace(/\b\d{3}-\d{2}-\d{4}\b/g, '***-**-****');
    // Mask API keys (common patterns)
    data = data.replace(/\b[A-Za-z0-9]{32,}\b/g, '***API_KEY***');
    return data;
  }

  if (Array.isArray(data)) {
    return data.map(maskPII);
  }

  if (typeof data === 'object') {
    const masked: any = {};
    const sensitiveKeys = ['password', 'token', 'secret', 'key', 'authorization', 'cookie', 'session', 'credit', 'ssn', 'phone', 'email'];

    for (const [key, value] of Object.entries(data)) {
      const lowerKey = key.toLowerCase();
      if (sensitiveKeys.some(sensitive => lowerKey.includes(sensitive))) {
        masked[key] = '***REDACTED***';
      } else {
        masked[key] = maskPII(value);
      }
    }
    return masked;
  }

  return data;
}

/**
 * Logs error to monitoring services
 */
async function logError(error: Error | ApiError, context: ErrorContext) {
  const maskedError = {
    message: maskPII(error.message),
    stack: error instanceof Error ? maskPII(error.stack) : undefined,
    details: 'details' in error ? maskPII(error.details) : undefined,
    context: maskPII(context),
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
  };

  // Log to console in development
  if (process.env.NODE_ENV === 'development') {
    console.error('[API Error]', maskedError);
  }

  // Track error in analytics
  if (analytics?.capture) {
    try {
      await analytics.capture('api_error', {
        endpoint: context.endpoint,
        method: context.method,
        status: 'status' in error ? error.status : 500,
        error_message: maskedError.message,
        ...context.metadata,
      });
    } catch (trackingError) {
      console.error('[Analytics Error]', trackingError);
    }
  }

  // If Sentry is configured, send error
  if (typeof window === 'undefined' && global.Sentry) {
    try {
      global.Sentry.captureException(error, {
        contexts: {
          api: maskedError.context,
        },
        tags: {
          endpoint: context.endpoint,
          method: context.method,
        },
        extra: maskedError.details,
      });
    } catch (sentryError) {
      console.error('[Sentry Error]', sentryError);
    }
  }

  // Could also send to external logging service like Datadog, LogDNA, etc.
  // Example: await sendToExternalLogger(maskedError);
}

/**
 * Standardized error response handler for API routes
 */
export async function handleApiError(
  error: Error | ApiError | unknown,
  context: ErrorContext
): Promise<NextResponse> {
  let apiError: ApiError;

  if (error instanceof Error) {
    apiError = {
      message: error.message,
      status: 500,
      details: error.stack,
    };
  } else if (typeof error === 'object' && error && 'status' in error) {
    apiError = error as ApiError;
  } else {
    apiError = {
      message: 'An unexpected error occurred',
      status: 500,
      details: error,
    };
  }

  // Log the error
  await logError(apiError, context);

  // Return sanitized error response
  const responseBody = {
    ok: false,
    error: maskPII(apiError.message),
    code: apiError.code,
    // Only include details in development
    ...(process.env.NODE_ENV === 'development' && { details: maskPII(apiError.details) }),
  };

  return NextResponse.json(responseBody, { status: apiError.status });
}

/**
 * Wrapper for API route handlers with automatic error tracking
 */
export function withErrorHandling<T extends (...args: any[]) => Promise<NextResponse>>(
  handler: T,
  endpoint: string
): T {
  return (async (...args: Parameters<T>) => {
    const request = args[0] as Request;
    const method = request.method;

    try {
      return await handler(...args);
    } catch (error) {
      // Extract user ID from request if available
      let userId: string | undefined;
      try {
        const authHeader = request.headers.get('authorization');
        // Parse JWT or session token to get user ID
        // This is a placeholder - implement based on your auth system
        userId = authHeader ? 'user_from_token' : undefined;
      } catch {}

      return handleApiError(error, {
        endpoint,
        method,
        userId,
        metadata: {
          url: request.url,
          // Add any other relevant metadata
        },
      });
    }
  }) as T;
}

