    if (typeof window === "undefined") return [];
    const local = lsGet();
    try {
      const { data, error } = await (supabase as any)
        .from("questions")
        .select("id,question,options,correct_answer,explanation,difficulty,category,tags,domain")
        .order("updated_at", { ascending: false })
        .limit(limit);
      if (error) throw error;
      const remote: AdminQuestion[] = (data || []).map((r: any) => ({
        id: r.id,
        question: r.question,
        options: Array.isArray(r.options) ? r.options : [],
        correctAnswer: r.correct_answer || "",
        explanation: r.explanation,
        difficulty: r.difficulty,
        category: r.category,
        tags: r.tags || [],
        domain: r.domain,
      }));
      if (remote.length) lsSet(remote);
      return remote.length ? remote : local;
    } catch {
      return local;
    }
  },

  async upsert(q: AdminQuestion, user?: User | null): Promise<AdminQuestion> {
    if (typeof window !== "undefined") {
      const cur = lsGet();
      const idx = cur.findIndex((x) => x.id === q.id);
      if (idx >= 0) cur[idx] = q; else cur.unshift(q);
      lsSet(cur);
    }
    try {
      await (supabase as any)
        .from("questions")
        .upsert({
          id: q.id,
          question: q.question,
          options: q.options,
          correct_answer: q.correctAnswer,
          explanation: q.explanation,
          difficulty: q.difficulty,
          category: q.category,
          tags: q.tags,
          domain: q.domain,
        }, { onConflict: "id" });
    } catch {}
    return q;
  },

  async remove(id: string): Promise<void> {
    if (typeof window !== "undefined") {
      const cur = lsGet().filter((x) => x.id !== id);
      lsSet(cur);
    }
    try { await (supabase as any).from("questions").delete().eq("id", id); } catch {}
  },
};

/**
 * Central Domain-Module Mapping Utility
 * Unified mapping system for cross-linking domains and modules
 */

import { TCODomain } from "@/types/exam";

// Domain slug to module slug mapping
export const DOMAIN_TO_MODULES: Record<string, string[]> = {
  "asking-questions": ["asking-questions"],
  "refining-questions-targeting": ["refining-questions-targeting"],
  "taking-action-packages-actions": ["taking-action-packages-actions"],
  "navigation-basic-modules": ["navigation-basic-modules"],
  "reporting-data-export": ["reporting-data-export"],
};

// Module slug to domain slug mapping (reverse lookup)
export const MODULE_TO_DOMAIN: Record<string, string> = {
  "asking-questions": "asking-questions",
  "refining-questions-targeting": "refining-questions-targeting",
  "taking-action-packages-actions": "taking-action-packages-actions",
  "navigation-basic-modules": "navigation-basic-modules",
  "reporting-data-export": "reporting-data-export",
};

// Domain enum to slug mapping
export const DOMAIN_ENUM_TO_SLUG: Record<string, string> = {
  ASKING_QUESTIONS: "asking-questions",
  REFINING_QUESTIONS: "refining-questions-targeting",
  TAKING_ACTION: "taking-action-packages-actions",
  NAVIGATION_MODULES: "navigation-basic-modules",
  REPORTING_EXPORT: "reporting-data-export",
};

// Domain slug to enum mapping (reverse)
export const DOMAIN_SLUG_TO_ENUM: Record<string, string> = {
  "asking-questions": "ASKING_QUESTIONS",
  "refining-questions-targeting": "REFINING_QUESTIONS",
  "taking-action-packages-actions": "TAKING_ACTION",
  "navigation-basic-modules": "NAVIGATION_MODULES",
  "reporting-data-export": "REPORTING_EXPORT",
};

// Domain display names
export const DOMAIN_DISPLAY_NAMES: Record<string, string> = {
  "asking-questions": "Asking Questions",
  "refining-questions-targeting": "Refining Questions & Targeting",
  "taking-action-packages-actions": "Taking Action",
  "navigation-basic-modules": "Navigation & Basic Modules",
  "reporting-data-export": "Reporting & Data Export",
};

// Domain route slugs (for existing domain pages)
export const DOMAIN_ROUTE_SLUGS: Record<string, string> = {
  "asking-questions": "domain1-asking-questions",
  "refining-questions-targeting": "domain2-refining-questions",
  "taking-action-packages-actions": "domain3-taking-action",
  "navigation-basic-modules": "domain4-navigation-modules",
  "reporting-data-export": "domain5-reporting-data-export",
};

// Utility functions
export function getModulesForDomain(domainSlug: string): string[] {
  return DOMAIN_TO_MODULES[domainSlug] || [];
}

export function getDomainForModule(moduleSlug: string): string | null {
  return MODULE_TO_DOMAIN[moduleSlug] || null;
}

export function getDomainDisplayName(domainSlug: string): string {
  return DOMAIN_DISPLAY_NAMES[domainSlug] || domainSlug;
}

export function getDomainRouteSlug(domainSlug: string): string {
  return DOMAIN_ROUTE_SLUGS[domainSlug] || domainSlug;
}

export function getDomainEnum(domainSlug: string): string | null {
  return DOMAIN_SLUG_TO_ENUM[domainSlug] || null;
}

export function getDomainSlugFromEnum(domainEnum: string): string | null {
  return DOMAIN_ENUM_TO_SLUG[domainEnum] || null;
}

// Validation functions
export function isValidDomainSlug(slug: string): boolean {
  return Object.keys(DOMAIN_TO_MODULES).includes(slug);
}

export function isValidModuleSlug(slug: string): boolean {
  return Object.keys(MODULE_TO_DOMAIN).includes(slug);
}

// Get all available domains
export function getAllDomains(): string[] {
  return Object.keys(DOMAIN_TO_MODULES);
}

// Get all available modules
export function getAllModules(): string[] {
  return Object.keys(MODULE_TO_DOMAIN);
}

// Cross-reference validation
export function validateDomainModuleMapping(): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  // Check that every domain has valid modules
  for (const [domain, modules] of Object.entries(DOMAIN_TO_MODULES)) {
    for (const module of modules) {
      if (!MODULE_TO_DOMAIN[module]) {
        errors.push(`Module '${module}' in domain '${domain}' not found in reverse mapping`);
      }
    }
  }

  // Check that every module maps back correctly
  for (const [module, domain] of Object.entries(MODULE_TO_DOMAIN)) {
    if (!DOMAIN_TO_MODULES[domain]?.includes(module)) {
      errors.push(
        `Module '${module}' maps to domain '${domain}' but domain doesn't include module`
      );
    }
  }

  // Check enum consistency
  for (const domainSlug of Object.keys(DOMAIN_TO_MODULES)) {
    const domainEnum = DOMAIN_SLUG_TO_ENUM[domainSlug];
    if (!domainEnum) {
      errors.push(`Domain slug '${domainSlug}' missing enum mapping`);
      continue;
    }

    if (DOMAIN_ENUM_TO_SLUG[domainEnum] !== domainSlug) {
      errors.push(`Enum mapping inconsistency for domain '${domainSlug}'`);
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

import type { Question } from "@/types/exam";
import { TCO_DOMAIN_WEIGHTS, TCODomain } from "@/types/exam";

// Static content fallback (5 items each)
import aq from "@/content/questions/asking-questions.json";
import rq from "@/content/questions/refining-questions.json";
import ta from "@/content/questions/taking-action.json";
import nb from "@/content/questions/navigation-modules.json";
import rd from "@/content/questions/reporting-export.json";

type DomainKey = keyof typeof TCO_DOMAIN_WEIGHTS;

const DOMAIN_TO_POOL: Record<string, Question[]> = {
  [TCODomain.ASKING_QUESTIONS]: aq as unknown as Question[],
  [TCODomain.REFINING_TARGETING]: rq as unknown as Question[],
  [TCODomain.TAKING_ACTION]: ta as unknown as Question[],
  [TCODomain.NAVIGATION_MODULES]: nb as unknown as Question[],
  [TCODomain.REPORTING_EXPORT]: rd as unknown as Question[],
};

/**
 * Compute per-domain counts for N questions using TCO weights for present domains.
 * Deterministic rounding: floor then allocate remainder by largest fractional part.
 */
export function computeWeightedCounts(total: number, domains: string[]): Record<string, number> {
  const weights = domains.map((d) => ({
    domain: d,
    weight: TCO_DOMAIN_WEIGHTS[d as DomainKey] ?? 1,
  }));
  const weightSum = weights.reduce((s, w) => s + w.weight, 0) || 1;
  const raws = weights.map((w) => ({
    domain: w.domain,
    raw: (total * w.weight) / weightSum,
  }));
  const base = raws.map((r) => ({ domain: r.domain, count: Math.floor(r.raw), frac: r.raw - Math.floor(r.raw) }));
  let remaining = total - base.reduce((s, b) => s + b.count, 0);
  // Sort by largest fractional part, tie-break by weight desc
  const order = [...base].sort((a, b) => {
    if (b.frac !== a.frac) return b.frac - a.frac;
    const wa = TCO_DOMAIN_WEIGHTS[a.domain as DomainKey] ?? 0;
    const wb = TCO_DOMAIN_WEIGHTS[b.domain as DomainKey] ?? 0;
    return wb - wa;
  });
  for (let i = 0; i < order.length && remaining > 0; i++) {
    base.find((x) => x.domain === order[i].domain)!.count += 1;
    remaining--;
  }
  const result: Record<string, number> = {};
  for (const b of base) result[b.domain] = b.count;
  return result;
}

/**
 * Return a deterministic Daily 10 drill set using local content and TCO weights.
 * Deterministic selection ensures stable tests.
 */
export async function getDailyDrill(total: number = 10): Promise<Question[]> {
  const availableDomains = Object.keys(DOMAIN_TO_POOL);
  const counts = computeWeightedCounts(total, availableDomains);
  const selected: Question[] = [];
  for (const d of availableDomains) {
    const pool = DOMAIN_TO_POOL[d] || [];
    const need = counts[d] ?? 0;
    for (let i = 0; i < Math.min(need, pool.length); i++) {
      selected.push(normalizeQuestion(pool[i]));
    }
  }
  // If we are short (pool too small), fill round-robin deterministically
  let i = 0;
  while (selected.length < total) {
    const d = availableDomains[i % availableDomains.length];
    const pool = DOMAIN_TO_POOL[d] || [];
    // pick next non-selected
    const next = pool.find((q) => !selected.some((s) => s.id === q.id));
    if (next) selected.push(normalizeQuestion(next));
    i++;
    if (i > 1000) break; // safety
  }
  return selected.slice(0, total);
}

function normalizeQuestion(q: Question): Question {
  // Ensure choices alias present for components that expect options
  return {
    ...q,
    options: (q as any).options ?? q.choices,
  };
}

