export class KnowledgeAssessment {
  private questions: KnowledgeQuestion[];
  private results: Map<string, number> = new Map();

  constructor(customQuestions?: KnowledgeQuestion[]) {
    this.questions = customQuestions || KNOWLEDGE_QUESTIONS;
  }

  /**
   * Get a subset of questions for assessment
   */
  getAssessmentQuestions(count: number = 10): KnowledgeQuestion[] {
    // Ensure representation from all categories
    const categoriesNeeded = ['basic-it', 'networking', 'security', 'systems', 'enterprise'];
    const questionsPerCategory = Math.ceil(count / categoriesNeeded.length);
    const selectedQuestions: KnowledgeQuestion[] = [];

    categoriesNeeded.forEach(category => {
      const categoryQuestions = this.questions
        .filter(q => q.category === category)
        .sort(() => Math.random() - 0.5) // Shuffle
        .slice(0, questionsPerCategory);

      selectedQuestions.push(...categoryQuestions);
    });

    return selectedQuestions.slice(0, count);
  }

  /**
   * Record an answer and return immediate feedback
   */
  recordAnswer(questionId: string, answerIndex: number): { correct: boolean; explanation: string } {
    const question = this.questions.find(q => q.id === questionId);
    if (!question) {
      throw new Error(`Question ${questionId} not found`);
    }

    const isCorrect = question.correctAnswer === answerIndex;
    const score = isCorrect ? question.weight : 0;
    this.results.set(questionId, score);

    return {
      correct: isCorrect,
      explanation: question.explanation
    };
  }

  /**
   * Calculate final assessment results and recommend learning path
   */
  calculateResults(questionsUsed: KnowledgeQuestion[]): AssessmentResult {
    const categoryScores: Record<string, { score: number; total: number; percentage: number }> = {};
    let totalScore = 0;
    let maxScore = 0;

    // Calculate category scores
    questionsUsed.forEach(question => {
      const category = question.category;
      const questionScore = this.results.get(question.id) || 0;
      const maxQuestionScore = question.weight;

      if (!categoryScores[category]) {
        categoryScores[category] = { score: 0, total: 0, percentage: 0 };
      }

      categoryScores[category].score += questionScore;
      categoryScores[category].total += maxQuestionScore;
      totalScore += questionScore;
      maxScore += maxQuestionScore;
    });

    // Calculate percentages
    Object.keys(categoryScores).forEach(category => {
      const categoryData = categoryScores[category];
      categoryData.percentage = categoryData.total > 0 
        ? Math.round((categoryData.score / categoryData.total) * 100)
        : 0;
    });

    const overallPercentage = maxScore > 0 ? Math.round((totalScore / maxScore) * 100) : 0;

    // Determine recommended path
    const recommendedPath = this.determineRecommendedPath(overallPercentage, categoryScores);

    // Identify strengths and weaknesses
    const { strengths, weaknesses } = this.analyzePerformance(categoryScores);

    // Generate next steps
    const nextSteps = this.generateNextSteps(recommendedPath, weaknesses);

    return {
      totalScore,
      maxScore,
      percentage: overallPercentage,
      categoryScores,
      recommendedPath,
      strengths,
      weaknesses,
      nextSteps
    };
  }

  private determineRecommendedPath(
    overallPercentage: number, 
    categoryScores: Record<string, { score: number; total: number; percentage: number }>
  ): LearningPath {
    const basicItScore = categoryScores['basic-it']?.percentage || 0;
    const networkingScore = categoryScores['networking']?.percentage || 0;
    const securityScore = categoryScores['security']?.percentage || 0;

    // Absolute beginner: Struggling with basic IT concepts
    if (basicItScore < 60 || overallPercentage < 40) {
      return LEARNING_PATHS.find(p => p.id === 'absolute-beginner')!;
    }

    // Beginner foundation: Decent basics but weak in specialized areas
    if (overallPercentage < 65 || networkingScore < 50 || securityScore < 50) {
      return LEARNING_PATHS.find(p => p.id === 'beginner-foundation')!;
    }

    // Intermediate: Good foundation, ready for direct TCO prep
    if (overallPercentage < 85) {
      return LEARNING_PATHS.find(p => p.id === 'intermediate-direct')!;
    }

    // Advanced: Strong performance, just needs exam practice
    return LEARNING_PATHS.find(p => p.id === 'advanced-review')!;
  }

  private analyzePerformance(categoryScores: Record<string, { score: number; total: number; percentage: number }>): 
    { strengths: string[]; weaknesses: string[] } {
    const strengths: string[] = [];
    const weaknesses: string[] = [];

    const categoryNames: Record<string, string> = {
      'basic-it': 'Basic IT Concepts',
      'networking': 'Networking Fundamentals',
      'security': 'Security Principles',
      'systems': 'Systems Administration',
      'enterprise': 'Enterprise Operations'
    };

    Object.entries(categoryScores).forEach(([category, scores]) => {
      const categoryName = categoryNames[category] || category;

      if (scores.percentage >= 70) {
        strengths.push(categoryName);
      } else if (scores.percentage < 50) {
        weaknesses.push(categoryName);
      }
    });

    return { strengths, weaknesses };
  }

  private generateNextSteps(recommendedPath: LearningPath, weaknesses: string[]): string[] {
    const nextSteps: string[] = [];

    // Add path-specific recommendations
    nextSteps.push(`Follow the "${recommendedPath.name}" learning path`);

    if (recommendedPath.id === 'absolute-beginner') {
      nextSteps.push('Start with the "What is Tanium?" foundation module');
      nextSteps.push('Complete basic IT terminology review');
      nextSteps.push('Practice with guided tutorials');
    } else if (recommendedPath.id === 'beginner-foundation') {
      nextSteps.push('Review endpoint management concepts');
      nextSteps.push('Complete hands-on lab exercises');
      nextSteps.push('Study Tanium platform overview');
    } else if (recommendedPath.id === 'intermediate-direct') {
      nextSteps.push('Begin TCO domain-specific study modules');
      nextSteps.push('Practice with mock exams');
      nextSteps.push('Focus on hands-on lab scenarios');
    } else {
      nextSteps.push('Take full-length practice exams');
      nextSteps.push('Review advanced scenarios');
      nextSteps.push('Schedule your TCO certification exam');
    }

    // Add weakness-specific recommendations
    if (weaknesses.includes('Basic IT Concepts')) {
      nextSteps.push('Review fundamental computing concepts');
    }
    if (weaknesses.includes('Networking Fundamentals')) {
      nextSteps.push('Study networking basics and protocols');
    }
    if (weaknesses.includes('Security Principles')) {
      nextSteps.push('Learn cybersecurity fundamentals');
    }

    return nextSteps;
  }

  /**
   * Reset assessment for retaking
   */
  reset(): void {
    this.results.clear();
  }
}

/**
 * Learn → Practice → Assess Flow State Machine Implementation
 * p5: Core state machine logic with gating rules and telemetry
 */

import {
  LearningFlowState,
  LearningFlowEvent,
  type LearningFlowContext,
  type FlowStateMachine,
  type GatingRules,
  DEFAULT_GATING_RULES,
  STATE_TRANSITIONS,
  type FlowTelemetry,
  type BoundaryNavigationGuard,
  type FlowProgressPersistence,
  type FlowValidation,
  type FlowValidationError,
  LearnPhaseProgress,
  PracticePhaseProgress,
  AssessPhaseProgress,
  LearningFlowMetadata,
} from "@/types/learning-flow";

/**
 * State Machine Implementation
 * Enforces Learn → Practice → Assess progression with safety checks
 */
export class LearningFlowStateMachine implements FlowStateMachine {
  constructor(
    public currentState: LearningFlowState,
    public context: LearningFlowContext,
    private gatingRules: GatingRules = DEFAULT_GATING_RULES,
    private navigationGuard?: BoundaryNavigationGuard,
    private persistence?: FlowProgressPersistence
  ) {}

  /**
   * Check if a state transition is allowed
   */
  canTransition(event: LearningFlowEvent): boolean {
    const allowedEvents = STATE_TRANSITIONS[this.currentState];
    if (!allowedEvents.includes(event)) {
      return false;
    }

    // Additional gating logic based on event
    switch (event) {
      case LearningFlowEvent.COMPLETE_LEARN:
        return this.canProceedToLearn();

      case LearningFlowEvent.START_PRACTICE:
      case LearningFlowEvent.COMPLETE_PRACTICE:
        return this.canProceedToPractice();

      case LearningFlowEvent.START_ASSESS:
      case LearningFlowEvent.COMPLETE_ASSESS:
        return this.canProceedToAssess();

      default:
        return true;
    }
  }

  /**
   * Perform state transition with validation and telemetry
   */
  transition(event: LearningFlowEvent): FlowStateMachine {
    if (!this.canTransition(event)) {
      throw new Error(`Invalid transition: ${event} from state ${this.currentState}`);
    }

    const previousState = this.currentState;
    const newState = this.getNextState(event);
    const timestamp = new Date();

    // Record telemetry
    this.recordEvent(event, {
      previousState,
      newState,
      timestamp: timestamp.toISOString(),
    });

    // Update context
    const updatedContext: LearningFlowContext = {
      ...this.context,
      currentState: newState,
      timeSpent: this.context.timeSpent + this.calculateSessionTime(),
      canProceed: this.evaluateCanProceed(newState),
    };

    // Handle state-specific logic
    switch (event) {
      case LearningFlowEvent.COMPLETE_LEARN:
        updatedContext.metadata.learnProgress.completedAt = timestamp;
        break;

      case LearningFlowEvent.COMPLETE_PRACTICE:
        updatedContext.metadata.practiceProgress.completedAt = timestamp;
        break;

      case LearningFlowEvent.COMPLETE_ASSESS:
        updatedContext.metadata.assessProgress.completedAt = timestamp;
        updatedContext.completedAt = timestamp;
        break;

      case LearningFlowEvent.FAIL_ASSESS:
        updatedContext.metadata.assessProgress.attempts++;
        // Reset to practice if under max attempts
        if (
          updatedContext.metadata.assessProgress.attempts <
          this.gatingRules.assessToComplete.maxAttempts
        ) {
          updatedContext.currentState = LearningFlowState.PRACTICE;
        }
        break;
    }

    return new LearningFlowStateMachine(
      updatedContext.currentState,
      updatedContext,
      this.gatingRules,
      this.navigationGuard,
      this.persistence
    );
  }

  /**
   * Gating Rules Implementation
   */
  canProceedToLearn(): boolean {
    // Learn phase is always accessible - entry point
    return true;
  }

  canProceedToPractice(): boolean {
    const { learnProgress } = this.context.metadata;
    const rules = this.gatingRules.learnTopractice;

    // Check minimum sections viewed
    if (learnProgress.sectionsViewed.length < rules.minSectionsViewed) {
      return false;
    }

    // Check minimum time spent
    if (learnProgress.timeSpent < rules.minTimeSpent) {
      return false;
    }

    // Check all checkpoints passed if required
    if (rules.requireAllCheckpoints && learnProgress.totalSections > 0) {
      const requiredCheckpoints = learnProgress.totalSections;
      return learnProgress.checkpointsPassed.length >= requiredCheckpoints;
    }

    return true;
  }

  canProceedToAssess(): boolean {
    const { practiceProgress } = this.context.metadata;
    const rules = this.gatingRules.practiceToAssess;

    // Check minimum questions attempted
    if (practiceProgress.questionsAttempted < rules.minQuestionsAttempted) {
      return false;
    }

    // Check minimum accuracy
    const accuracy =
      practiceProgress.questionsAttempted > 0
        ? practiceProgress.questionsCorrect / practiceProgress.questionsAttempted
        : 0;
    if (accuracy < rules.minAccuracy) {
      return false;
    }

    // Check minimum time spent
    if (practiceProgress.timeSpent < rules.minTimeSpent) {
      return false;
    }

    // Check required topics if specified
    if (rules.requiredTopics.length > 0) {
      const masteredTopics = practiceProgress.topics
        .filter((topic) => topic.masteryLevel === "proficient" || topic.masteryLevel === "advanced")
        .map((topic) => topic.topicId);

      return rules.requiredTopics.every((required) => masteredTopics.includes(required));
    }

    return true;
  }

  /**
   * Resume Functionality
   */
  async save(): Promise<void> {
    if (this.persistence) {
      await this.persistence.save(this.context);
    }
  }

  async resume(): Promise<FlowStateMachine> {
    if (this.persistence) {
      const savedContext = await this.persistence.load(this.context.moduleId, this.context.userId);
      if (savedContext) {
        this.recordEvent(LearningFlowEvent.RESUME_FLOW, {
          resumedAt: new Date().toISOString(),
          previousState: savedContext.currentState,
        });

        return new LearningFlowStateMachine(
          savedContext.currentState,
          savedContext,
          this.gatingRules,
          this.navigationGuard,
          this.persistence
        );
      }
    }
    return this;
  }

  /**
   * Telemetry Recording
   */
  recordEvent(event: LearningFlowEvent, metadata?: Record<string, any>): void {
    const telemetryEntry: FlowTelemetry = {
      event,
      timestamp: new Date(),
      state: this.currentState,
      metadata,
      duration: this.calculateSessionTime(),
    };

    this.context.metadata.telemetry.push(telemetryEntry);
  }

  /**
   * Private Helper Methods
   */
  private getNextState(event: LearningFlowEvent): LearningFlowState {
    switch (event) {
      case LearningFlowEvent.START_LEARN:
      case LearningFlowEvent.COMPLETE_LEARN:
        return event === LearningFlowEvent.COMPLETE_LEARN && this.canProceedToPractice()
          ? LearningFlowState.PRACTICE
          : LearningFlowState.LEARN;

      case LearningFlowEvent.START_PRACTICE:
      case LearningFlowEvent.COMPLETE_PRACTICE:
        return event === LearningFlowEvent.COMPLETE_PRACTICE && this.canProceedToAssess()
          ? LearningFlowState.ASSESS
          : LearningFlowState.PRACTICE;

      case LearningFlowEvent.START_ASSESS:
      case LearningFlowEvent.COMPLETE_ASSESS:
        return event === LearningFlowEvent.COMPLETE_ASSESS
          ? LearningFlowState.COMPLETED
          : LearningFlowState.ASSESS;

      case LearningFlowEvent.FAIL_ASSESS:
        // Return to practice unless max attempts exceeded
        return this.context.metadata.assessProgress.attempts <
          this.gatingRules.assessToComplete.maxAttempts
          ? LearningFlowState.PRACTICE
          : LearningFlowState.LEARN; // Restart from beginning

      case LearningFlowEvent.RESET_FLOW:
        return LearningFlowState.LEARN;

      case LearningFlowEvent.RESUME_FLOW:
        return this.currentState; // Stay in current state

      default:
        return this.currentState;
    }
  }

  private evaluateCanProceed(state: LearningFlowState): boolean {
    switch (state) {
      case LearningFlowState.LEARN:
        return true; // Can always start learning
      case LearningFlowState.PRACTICE:
        return this.canProceedToPractice();
      case LearningFlowState.ASSESS:
        return this.canProceedToAssess();
      case LearningFlowState.COMPLETED:
        return true; // Already completed
      default:
        return false;
    }
  }

  private calculateSessionTime(): number {
    // Simple session time calculation - can be enhanced with more sophisticated tracking
    return Date.now() - this.context.startedAt.getTime();
  }
}

/**
 * Boundary Navigation Guard Implementation
 * Prevents unsafe navigation between flow states
 */
export class DefaultBoundaryNavigationGuard implements BoundaryNavigationGuard {
  allowNavigation(
    currentState: LearningFlowState,
    targetState: LearningFlowState,
    context: LearningFlowContext
  ): boolean {
    // Allow backward navigation with warnings
    if (this.isBackwardNavigation(currentState, targetState)) {
      return true;
    }

    // Allow forward navigation only if gating rules are met
    const machine = new LearningFlowStateMachine(currentState, context);
    // Use public gating checks instead of private evaluateCanProceed
    switch (targetState) {
      case LearningFlowState.LEARN:
        return machine.canProceedToLearn();
      case LearningFlowState.PRACTICE:
        return machine.canProceedToPractice();
      case LearningFlowState.ASSESS:
        return machine.canProceedToAssess();
      case LearningFlowState.COMPLETED:
        return true;
      default:
        return false;
    }
  }

  getNavigationWarning(
    currentState: LearningFlowState,
    targetState: LearningFlowState
  ): string | null {
    if (this.isBackwardNavigation(currentState, targetState)) {
      return "Going back will reset your current progress. Are you sure?";
    }

    return null;
  }

  canForceNavigation(userId: string): boolean {
    // Implement admin/instructor override logic here
    return false;
  }

  private isBackwardNavigation(current: LearningFlowState, target: LearningFlowState): boolean {
    const stateOrder = [
      LearningFlowState.LEARN,
      LearningFlowState.PRACTICE,
      LearningFlowState.ASSESS,
      LearningFlowState.COMPLETED,
    ];

    const currentIndex = stateOrder.indexOf(current);
    const targetIndex = stateOrder.indexOf(target);

    return currentIndex > targetIndex;
  }
}

/**
 * Flow State Factory
 * Creates new learning flow instances with default configuration
 */
export class LearningFlowFactory {
  static createNewFlow(
    moduleId: string,
    userId: string,
    customGatingRules?: Partial<GatingRules>
  ): LearningFlowStateMachine {
    const gatingRules = customGatingRules
      ? { ...DEFAULT_GATING_RULES, ...customGatingRules }
      : DEFAULT_GATING_RULES;

    const context: LearningFlowContext = {
      moduleId,
      userId,
      currentState: LearningFlowState.LEARN,
      startedAt: new Date(),
      timeSpent: 0,
      attempts: 0,
      canProceed: true,
      metadata: {
        learnProgress: {
          sectionsViewed: [],
          totalSections: 0,
          timeSpent: 0,
          checkpointsPassed: [],
          keyPointsReviewed: [],
        },
        practiceProgress: {
          questionsAttempted: 0,
          questionsCorrect: 0,
          timeSpent: 0,
          topics: [],
          hintsUsed: 0,
        },
        assessProgress: {
          attempts: 0,
          bestScore: 0,
          lastScore: 0,
          timeSpent: 0,
          passed: false,
        },
        telemetry: [],
      },
    };

    const navigationGuard = new DefaultBoundaryNavigationGuard();

    return new LearningFlowStateMachine(
      LearningFlowState.LEARN,
      context,
      gatingRules,
      navigationGuard
    );
  }

  static validateFlowContext(context: LearningFlowContext): FlowValidation {
    const errors: FlowValidationError[] = [];
    const warnings: FlowValidationError[] = [];

    // Validate required fields
    if (!context.moduleId) {
      errors.push({
        code: "MISSING_MODULE_ID",
        message: "Module ID is required",
        severity: "error",
        field: "moduleId",
      });
    }

    if (!context.userId) {
      errors.push({
        code: "MISSING_USER_ID",
        message: "User ID is required",
        severity: "error",
        field: "userId",
      });
    }

    // Validate state
    if (!Object.values(LearningFlowState).includes(context.currentState)) {
      errors.push({
        code: "INVALID_STATE",
        message: "Invalid learning flow state",
        severity: "error",
        field: "currentState",
      });
    }

    // Validate timestamps
    if (context.completedAt && context.completedAt < context.startedAt) {
      errors.push({
        code: "INVALID_TIMESTAMPS",
        message: "Completed date cannot be before start date",
        severity: "error",
        field: "completedAt",
      });
    }

    // Check for potential issues
    if (context.timeSpent < 0) {
      warnings.push({
        code: "NEGATIVE_TIME",
        message: "Time spent cannot be negative",
        severity: "warning",
        field: "timeSpent",
      });
    }

    if (context.attempts > 10) {
      warnings.push({
        code: "HIGH_ATTEMPTS",
        message: "High number of attempts detected",
        severity: "warning",
        field: "attempts",
      });
    }

    return {
      isValid: errors.length === 0,
      errors,
      warnings,
    };
  }
}

export default {
  LearningFlowStateMachine,
  DefaultBoundaryNavigationGuard,
  LearningFlowFactory,
};

/**
 * MDX Content Loader - Dynamic import system for study modules
 * Maps domain slugs to MDX file imports with metadata extraction
 */

// Older versions of @mdx-js/react exported MDXProps; to avoid cross-version issues
// use a flexible component type for MDX modules.

export interface MDXModule {
  default: React.ComponentType<any>;
  metadata?: {
    id: string;
    title: string;
    domainSlug: string;
    difficulty: string;
    estimatedTime: string;
    objectives: string[];
    tags: string[];
    blueprintWeight: number;
    version: number;
    status: string;
    lastUpdated: string;
    assessment?: {
      passThreshold: number;
    };
  };
}

// Domain slug to MDX file mapping
const domainToMDXMap: Record<string, () => Promise<MDXModule>> = {
  "platform-foundation": () => import("@/content/modules/00-tanium-platform-foundation.mdx"),
  "tanium-platform-foundation": () => import("@/content/modules/00-tanium-platform-foundation.mdx"),
  "asking-questions": () => import("@/content/modules/01-asking-questions.mdx"),
  "refining-questions-targeting": () =>
    import("@/content/modules/02-refining-questions-targeting.mdx"),
  "taking-action-packages-actions": () =>
    import("@/content/modules/03-taking-action-packages-actions.mdx"),
  "navigation-basic-modules": () => import("@/content/modules/04-navigation-basic-modules.mdx"),
  "reporting-data-export": () => import("@/content/modules/05-reporting-data-export.mdx"),
};

export async function loadMDXContent(domainSlug: string): Promise<MDXModule | null> {
  const loader = domainToMDXMap[domainSlug];

  if (!loader) {
    console.error(`No MDX loader found for domain: ${domainSlug}`);
    return null;
  }

  try {
    const module = await loader();
    return module;
  } catch (error) {
    console.error(`Failed to load MDX content for ${domainSlug}:`, error);
    return null;
  }
}

export function getMDXMetadata(module: MDXModule) {
  return (
    module.metadata || {
      id: "unknown",
      title: "Unknown Module",
      domainSlug: "unknown",
      difficulty: "Intermediate",
      estimatedTime: "45 min",
      objectives: [],
      tags: [],
      blueprintWeight: 0,
      version: 1,
      status: "draft",
      lastUpdated: new Date().toISOString().split("T")[0],
    }
  );
}

// Available domain slugs for validation
export const AVAILABLE_DOMAINS = Object.keys(domainToMDXMap);

/**
 * MDX Frontmatter Schema Validation
 * Zod schemas for validating MDX module frontmatter
 */

import { z } from "zod";

export const MDXFrontmatterSchema = z.object({
  id: z.string().min(1, "ID is required"),
  title: z.string().min(1, "Title is required"),
  domainSlug: z.enum([
    "platform-foundation",
    "asking-questions",
    "refining-questions-targeting",
    "taking-action-packages-actions",
    "navigation-basic-modules",
    "reporting-data-export",
  ]),
  domainEnum: z.enum([
    "PLATFORM_FOUNDATION",
    "ASKING_QUESTIONS",
    "REFINING_QUESTIONS",
    "TAKING_ACTION",
    "NAVIGATION_MODULES",
    "REPORTING_EXPORT",
  ]),
  difficulty: z.enum(["Beginner", "Intermediate", "Advanced", "Expert"]),
  estimatedTime: z.string().regex(/^\d+\s+(min|mins|minutes?)$/i, 'Format: "45 min"'),
  prerequisites: z.array(z.string()).optional().default([]),
  objectives: z.array(z.string()).min(1, "At least one objective required"),
  tags: z.array(z.string()).min(1, "At least one tag required"),
  blueprintWeight: z.number().min(0).max(1, "Blueprint weight must be 0-1"),
  version: z.number().int().positive("Version must be positive integer"),
  status: z.enum(["draft", "review", "published", "archived"]),
  lastUpdated: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "Format: YYYY-MM-DD"),
  assessment: z
    .object({
      passThreshold: z.number().min(0).max(1, "Pass threshold must be 0-1"),
    })
    .optional(),
});

export type MDXFrontmatter = z.infer<typeof MDXFrontmatterSchema>;

export const ModuleSlugSchema = z
  .string()
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, "Slug must be lowercase with hyphens only");

export function validateFrontmatter(frontmatter: unknown): MDXFrontmatter {
  try {
    return MDXFrontmatterSchema.parse(frontmatter);
  } catch (error) {
    if (error instanceof z.ZodError) {
      const zError = error as z.ZodError<any>;
      const errorMessages = zError.issues
        .map((err: z.ZodIssue) => `${err.path.join(".")}: ${err.message}`)
        .join(", ");
      throw new Error(`Invalid frontmatter: ${errorMessages}`);
    }
    throw error;
  }
}

export function validateSlug(slug: string): string {
  try {
    return ModuleSlugSchema.parse(slug);
  } catch (error) {
    throw new Error(`Invalid module slug: ${slug}`);
  }
}

// Schema validation errors with context
export class MDXValidationError extends Error {
  constructor(
    public module: string,
    public validationError: string,
    public suggestion?: string
  ) {
    super(`MDX validation failed for ${module}: ${validationError}`);
    this.name = "MDXValidationError";
  }
}

