import fs from "fs";
import { glob } from "glob";
import matter from "gray-matter";
import type { MDXRemoteSerializeResult } from "next-mdx-remote";
import { serialize } from "next-mdx-remote/serialize";
import path from "path";
import {
  SLUG_TO_DOMAIN_ENUM,
  validateModuleFrontmatter,
  type ModuleFrontmatter,
  type ModuleValidationResult,
} from "./module-schema";

/**
 * Complete module data structure
 */
export interface ModuleData {
  frontmatter: ModuleFrontmatter;
  content: MDXRemoteSerializeResult;
  slug: string;
  filePath: string;
}

/**
 * Module discovery and loading errors
 */
export class ModuleLoadError extends Error {
  constructor(
    message: string,
    public filePath?: string,
    public validationErrors?: ModuleValidationResult["errors"]
  ) {
    super(message);
    this.name = "ModuleLoadError";
  }
}

/**
 * Content discovery configuration
 */
const MODULES_DIR = path.join(process.cwd(), "src", "content", "modules");
// Use POSIX-style glob so it works cross-platform (Windows/macOS/Linux)
const MODULES_GLOB = "src/content/modules/*.mdx";

/**
 * Discover all module files using glob patterns
 */
export async function discoverModuleFiles(): Promise<string[]> {
  try {
    const files = await glob(MODULES_GLOB, { windowsPathsNoEscape: true });
    return files.sort(); // Ensure consistent ordering
  } catch (error) {
    throw new ModuleLoadError(
      `Failed to discover module files: ${error instanceof Error ? error.message : "Unknown error"}`
    );
  }
}

/**
 * Generate slug from filename
 */
export function generateSlugFromFilename(filePath: string): string {
  const filename = path.basename(filePath, ".mdx");
  // Remove leading numbers and hyphens (e.g., "01-asking-questions" -> "asking-questions")
  return filename.replace(/^\d+-/, "");
}

/**
 * Load and parse a single module file
 */
export async function loadModuleFile(filePath: string): Promise<ModuleData> {
  try {
    // Check if file exists
    if (!fs.existsSync(filePath)) {
      throw new ModuleLoadError(`Module file not found: ${filePath}`, filePath);
    }

    // Read and parse the file
    const fileContents = fs.readFileSync(filePath, "utf8");
    const { data: frontmatter, content: rawContent } = matter(fileContents);

    // Validate frontmatter
    const validation = validateModuleFrontmatter(frontmatter, filePath);
    if (!validation.success) {
      throw new ModuleLoadError(`Invalid frontmatter in ${filePath}`, filePath, validation.errors);
    }

    // Generate slug from filename
    const slug = generateSlugFromFilename(filePath);

    // Verify slug matches domain
    const expectedDomainEnum = SLUG_TO_DOMAIN_ENUM[slug];
    if (expectedDomainEnum && validation.data!.domainEnum !== expectedDomainEnum) {
      throw new ModuleLoadError(
        `Slug "${slug}" doesn't match domainEnum "${validation.data!.domainEnum}" in ${filePath}`,
        filePath
      );
    }

    // Serialize MDX content
    const mdxContent = await serialize(rawContent, {
      mdxOptions: {
        remarkPlugins: [],
        rehypePlugins: [],
      },
    });

    return {
      frontmatter: validation.data!,
      content: mdxContent,
      slug,
      filePath,
    };
  } catch (error) {
    if (error instanceof ModuleLoadError) {
      throw error;
    }

    throw new ModuleLoadError(
      `Failed to load module ${filePath}: ${error instanceof Error ? error.message : "Unknown error"}`,
      filePath
    );
  }
}

/**
 * Load all modules with error handling and duplicate detection
 */
export async function loadAllModules(): Promise<{
  modules: ModuleData[];
  errors: ModuleLoadError[];
}> {
  let files: string[] = [];
  try {
    files = await discoverModuleFiles();
  } catch (error) {
    return { modules: [], errors: [new ModuleLoadError(String(error))] };
  }
  const modules: ModuleData[] = [];
  const errors: ModuleLoadError[] = [];
  const seenSlugs = new Set<string>();
  const seenIds = new Set<string>();

  for (const filePath of files) {
    try {
      const moduleData = await loadModuleFile(filePath);

      // Check for duplicate slugs
      if (seenSlugs.has(moduleData.slug)) {
        errors.push(
          new ModuleLoadError(`Duplicate slug "${moduleData.slug}" found in ${filePath}`, filePath)
        );
        continue;
      }

      // Check for duplicate IDs
      if (seenIds.has(moduleData.frontmatter.id)) {
        errors.push(
          new ModuleLoadError(
            `Duplicate ID "${moduleData.frontmatter.id}" found in ${filePath}`,
            filePath
          )
        );
        continue;
      }

      seenSlugs.add(moduleData.slug);
      seenIds.add(moduleData.frontmatter.id);
      modules.push(moduleData);
    } catch (error) {
      if (error instanceof ModuleLoadError) {
        errors.push(error);
      } else {
        errors.push(
          new ModuleLoadError(
            `Unexpected error loading ${filePath}: ${error instanceof Error ? error.message : "Unknown error"}`,
            filePath
          )
        );
      }
    }
  }

  return { modules, errors };
}

/**
 * Load a specific module by slug
 */
export async function loadModuleBySlug(slug: string): Promise<ModuleData | null> {
  let files: string[] = [];
  try {
    files = await discoverModuleFiles();
  } catch (error) {
    console.warn("Module discovery failed:", error);
    return null;
  }

  for (const filePath of files) {
    try {
      // Get metadata to check domainSlug without full parsing
      const metadata = await getModuleMetadata(filePath);
      if (metadata && metadata.frontmatter.domainSlug === slug) {
        return await loadModuleFile(filePath);
      }
    } catch (error) {
      console.error(`Failed to check module metadata for ${filePath}:`, error);
      continue;
    }
  }

  console.warn(`Module not found for slug: ${slug}`);
  return null;
}

/**
 * Get module metadata only (without parsing MDX content)
 */
export async function getModuleMetadata(filePath: string): Promise<{
  frontmatter: ModuleFrontmatter;
  slug: string;
  filePath: string;
} | null> {
  try {
    if (!fs.existsSync(filePath)) {
      return null;
    }

    const fileContents = fs.readFileSync(filePath, "utf8");
    const { data: frontmatter } = matter(fileContents);

    const validation = validateModuleFrontmatter(frontmatter, filePath);
    if (!validation.success) {
      console.error(`Invalid frontmatter in ${filePath}:`, validation.errors);
      return null;
    }

    const slug = generateSlugFromFilename(filePath);

    return {
      frontmatter: validation.data!,
      slug,
      filePath,
    };
  } catch (error) {
    console.error(`Failed to get metadata for ${filePath}:`, error);
    return null;
  }
}

/**
 * Get all module metadata without parsing MDX content (faster for lists)
 */
export async function getAllModuleMetadata(): Promise<
  {
    frontmatter: ModuleFrontmatter;
    slug: string;
    filePath: string;
  }[]
> {
  let files: string[] = [];
  try {
    files = await discoverModuleFiles();
  } catch (error) {
    console.warn("Module discovery failed:", error);
    return [];
  }
  const metadata = [];

  for (const filePath of files) {
    const meta = await getModuleMetadata(filePath);
    if (meta) {
      metadata.push(meta);
    }
  }

  return metadata;
}

/**
 * Server-side MDX rendering with RSC support
 * Properly handles MDX content rendering in React Server Components
 */

import { compileMDX } from "next-mdx-remote/rsc";
import type { MDXRemoteProps } from "next-mdx-remote/rsc";

// Re-export types for convenience
export type { MDXRemoteProps };

/**
 * Compile MDX content for server-side rendering
 * This properly handles MDX in React Server Components without client-side hydration issues
 */
export async function compileMDXContent(
  source: string,
  options?: {
    components?: Record<string, React.ComponentType>;
    scope?: Record<string, any>;
  }
) {
  const { content, frontmatter } = await compileMDX({
    source,
    options: {
      parseFrontmatter: true,
      mdxOptions: {
        remarkPlugins: [],
        rehypePlugins: [],
      },
    },
    components: options?.components,
  });

  return { content, frontmatter };
}

/**
 * Server Component wrapper for MDX content
 * This ensures proper RSC boundaries
 */
export function ServerMDXContent({
  content,
  components
}: {
  content: React.ReactElement;
  components?: Record<string, React.ComponentType>;
}) {
  // The content is already compiled, just return it
  return content;
}

/**
 * Module 3 Assessment Engine
 * Enhanced assessment system for the expanded 9-section structure
 */

import {
  Module3Section,
  MODULE_3_SECTIONS,
  getSectionCoverage
} from "@/lib/module3-section-definitions";
import { type Question, type TCODomain } from "@/types/exam";

/**
 * Module 3 specific assessment configuration
 */
export interface Module3AssessmentConfig {
  sectionWeights?: Partial<Record<Module3Section, number>>;
  passingThreshold?: number;
  requireAllSections?: boolean;
  adaptiveScoring?: boolean;
  penalizeGaps?: boolean;
}

/**
 * Assessment result for a specific section
 */
export interface SectionAssessmentResult {
  sectionId: Module3Section;
  questionsAttempted: number;
  questionsCorrect: number;
  accuracy: number;
  timeSpent: number;
  score: number;
  passed: boolean;
  objectivesMet: string[];
  objectivesMissed: string[];
  recommendations: string[];
}

/**
 * Complete Module 3 assessment result
 */
export interface Module3AssessmentResult {
  overallScore: number;
  overallAccuracy: number;
  totalTimeSpent: number;
  passed: boolean;
  sectionResults: Record<Module3Section, SectionAssessmentResult>;
  strengths: Module3Section[];
  weaknesses: Module3Section[];
  gapsIdentified: Module3Section[];
  recommendations: {
    priorityAreas: Module3Section[];
    suggestedStudyTime: number;
    nextSteps: string[];
  };
  certificationReadiness: {
    score: number;
    areas: Record<Module3Section, "strong" | "adequate" | "needs_improvement">;
    overallReadiness: "ready" | "almost_ready" | "needs_work";
  };
}

/**
 * Enhanced Module 3 Assessment Engine
 */
export class Module3AssessmentEngine {
  private static readonly DEFAULT_SECTION_WEIGHTS: Record<Module3Section, number> = {
    [Module3Section.PACKAGE_VALIDATION]: 0.12,
    [Module3Section.DEPLOYMENT_STRATEGIES]: 0.18,
    [Module3Section.ERROR_HANDLING]: 0.15,
    [Module3Section.ROLLBACK_PROCEDURES]: 0.10,
    [Module3Section.PERFORMANCE_MONITORING]: 0.15,
    [Module3Section.SECURITY_CONSIDERATIONS]: 0.12,
    [Module3Section.BATCH_OPERATIONS]: 0.08,
    [Module3Section.SCHEDULING_AUTOMATION]: 0.08,
    [Module3Section.DEPENDENCY_MANAGEMENT]: 0.02
  };

  private static readonly PASSING_THRESHOLDS: Record<Module3Section, number> = {
    [Module3Section.PACKAGE_VALIDATION]: 0.75,
    [Module3Section.DEPLOYMENT_STRATEGIES]: 0.80,
    [Module3Section.ERROR_HANDLING]: 0.85,
    [Module3Section.ROLLBACK_PROCEDURES]: 0.80,
    [Module3Section.PERFORMANCE_MONITORING]: 0.75,
    [Module3Section.SECURITY_CONSIDERATIONS]: 0.85,
    [Module3Section.BATCH_OPERATIONS]: 0.70,
    [Module3Section.SCHEDULING_AUTOMATION]: 0.75,
    [Module3Section.DEPENDENCY_MANAGEMENT]: 0.75
  };

  /**
   * Assess a complete Module 3 session
   */
  static assessModule3Session(
    sessionData: {
      responses: Array<{
        questionId: string;
        sectionId: Module3Section;
        correct: boolean;
        timeSpent: number;
        objectiveIds: string[];
      }>;
      totalTimeSpent: number;
    },
    config: Module3AssessmentConfig = {}
  ): Module3AssessmentResult {
    const {
      sectionWeights = this.DEFAULT_SECTION_WEIGHTS,
      passingThreshold = 0.75,
      requireAllSections = false,
      adaptiveScoring = true,
      penalizeGaps = true
    } = config;

    // Group responses by section
    const responsesBySection = this.groupResponsesBySection(sessionData.responses);

    // Calculate section results
    const sectionResults: Partial<Record<Module3Section, SectionAssessmentResult>> = {};
    let totalWeightedScore = 0;
    let totalWeight = 0;

    Object.entries(responsesBySection).forEach(([sectionId, responses]) => {
      const section = sectionId as Module3Section;
      const result = this.assessSection(section, responses, config);
      sectionResults[section] = result;

      const weight = sectionWeights[section] || this.DEFAULT_SECTION_WEIGHTS[section];
      totalWeightedScore += result.score * weight;
      totalWeight += weight;
    });

    // Handle sections with no responses (gaps)
    const attemptedSections = new Set(Object.keys(responsesBySection) as Module3Section[]);
    const gapsIdentified = Object.keys(MODULE_3_SECTIONS)
      .filter(sectionId => !attemptedSections.has(sectionId as Module3Section))
      .map(sectionId => sectionId as Module3Section);

    // Apply gap penalty if enabled
    if (penalizeGaps && gapsIdentified.length > 0) {
      const gapPenalty = gapsIdentified.length * 0.05; // 5% penalty per missing section
      totalWeightedScore = Math.max(0, totalWeightedScore - gapPenalty);
    }

    // Calculate overall metrics
    const overallScore = totalWeight > 0 ? totalWeightedScore / totalWeight : 0;
    const totalQuestions = sessionData.responses.length;
    const correctAnswers = sessionData.responses.filter(r => r.correct).length;
    const overallAccuracy = totalQuestions > 0 ? correctAnswers / totalQuestions : 0;

    // Determine pass/fail
    const passed = this.determineOverallPass(
      sectionResults as Record<Module3Section, SectionAssessmentResult>,
      overallScore,
      passingThreshold,
      requireAllSections
    );

    // Identify strengths and weaknesses
    const { strengths, weaknesses } = this.analyzeStrengthsAndWeaknesses(
      sectionResults as Record<Module3Section, SectionAssessmentResult>
    );

    // Generate recommendations
    const recommendations = this.generateRecommendations(
      sectionResults as Record<Module3Section, SectionAssessmentResult>,
      gapsIdentified,
      overallScore
    );

    // Assess certification readiness
    const certificationReadiness = this.assessCertificationReadiness(
      sectionResults as Record<Module3Section, SectionAssessmentResult>,
      overallScore
    );

    return {
      overallScore,
      overallAccuracy,
      totalTimeSpent: sessionData.totalTimeSpent,
      passed,
      sectionResults: sectionResults as Record<Module3Section, SectionAssessmentResult>,
      strengths,
      weaknesses,
      gapsIdentified,
      recommendations,
      certificationReadiness
    };
  }

  /**
   * Assess performance in a specific section
   */
  private static assessSection(
    sectionId: Module3Section,
    responses: Array<{
      questionId: string;
      correct: boolean;
      timeSpent: number;
      objectiveIds: string[];
    }>,
    config: Module3AssessmentConfig
  ): SectionAssessmentResult {
    const section = MODULE_3_SECTIONS[sectionId];
    const questionsAttempted = responses.length;
    const questionsCorrect = responses.filter(r => r.correct).length;
    const accuracy = questionsAttempted > 0 ? questionsCorrect / questionsAttempted : 0;
    const timeSpent = responses.reduce((sum, r) => sum + r.timeSpent, 0);

    // Calculate adaptive score
    let score = accuracy;
    if (config.adaptiveScoring) {
      score = this.calculateAdaptiveScore(accuracy, timeSpent, questionsAttempted, section);
    }

    // Determine pass/fail for section
    const threshold = this.PASSING_THRESHOLDS[sectionId];
    const passed = score >= threshold;

    // Analyze learning objectives
    const allObjectiveIds = responses.flatMap(r => r.objectiveIds);
    const correctObjectiveIds = responses
      .filter(r => r.correct)
      .flatMap(r => r.objectiveIds);

    const objectivesMet = [...new Set(correctObjectiveIds)];
    const objectivesMissed = section.learningObjectives
      .map(obj => obj.split(":")[0])
      .filter(objId => !objectivesMet.includes(objId));

    // Generate section-specific recommendations
    const recommendations = this.generateSectionRecommendations(
      sectionId,
      accuracy,
      objectivesMissed,
      timeSpent,
      questionsAttempted
    );

    return {
      sectionId,
      questionsAttempted,
      questionsCorrect,
      accuracy,
      timeSpent,
      score,
      passed,
      objectivesMet,
      objectivesMissed,
      recommendations
    };
  }

  /**
   * Calculate adaptive score based on performance and context
   */
  private static calculateAdaptiveScore(
    accuracy: number,
    timeSpent: number,
    questionCount: number,
    section: any
  ): number {
    let adaptiveScore = accuracy;

    // Time efficiency bonus/penalty
    const expectedTimePerQuestion = 90; // 1.5 minutes
    const actualTimePerQuestion = questionCount > 0 ? timeSpent / questionCount : 0;
    const timeRatio = expectedTimePerQuestion / Math.max(actualTimePerQuestion, 30);

    if (timeRatio > 1.2) {
      // Completed faster than expected with good accuracy
      adaptiveScore += 0.05;
    } else if (timeRatio < 0.8) {
      // Took longer than expected
      adaptiveScore -= 0.02;
    }

    // Difficulty adjustment
    if (section.difficulty === "Advanced") {
      adaptiveScore += 0.03; // Bonus for advanced sections
    } else if (section.difficulty === "Beginner") {
      adaptiveScore -= 0.01; // Slight penalty for beginner sections
    }

    // Question coverage bonus
    const targetQuestions = section.questionTargetCount;
    if (questionCount >= targetQuestions * 0.8) {
      adaptiveScore += 0.02; // Bonus for comprehensive coverage
    }

    return Math.min(1.0, Math.max(0.0, adaptiveScore));
  }

  /**
   * Group responses by section
   */
  private static groupResponsesBySection(
    responses: Array<{
      questionId: string;
      sectionId: Module3Section;
      correct: boolean;
      timeSpent: number;
      objectiveIds: string[];
    }>
  ): Record<string, Array<{
    questionId: string;
    correct: boolean;
    timeSpent: number;
    objectiveIds: string[];
  }>> {
    const grouped: Record<string, any[]> = {};

    responses.forEach(response => {
      const { sectionId, ...responseData } = response;
      if (!grouped[sectionId]) {
        grouped[sectionId] = [];
      }
      grouped[sectionId].push(responseData);
    });

    return grouped;
  }

  /**
   * Determine overall pass/fail status
   */
  private static determineOverallPass(
    sectionResults: Record<Module3Section, SectionAssessmentResult>,
    overallScore: number,
    passingThreshold: number,
    requireAllSections: boolean
  ): boolean {
    if (overallScore < passingThreshold) {
      return false;
    }

    if (requireAllSections) {
      return Object.values(sectionResults).every(result => result.passed);
    }

    // At least 70% of attempted sections must pass
    const attemptedSections = Object.values(sectionResults);
    const passedSections = attemptedSections.filter(result => result.passed);
    return passedSections.length >= attemptedSections.length * 0.7;
  }

  /**
   * Analyze strengths and weaknesses
   */
  private static analyzeStrengthsAndWeaknesses(
    sectionResults: Record<Module3Section, SectionAssessmentResult>
  ): { strengths: Module3Section[]; weaknesses: Module3Section[] } {
    const sections = Object.entries(sectionResults);

    const strengths = sections
      .filter(([_, result]) => result.score >= 0.85)
      .map(([sectionId]) => sectionId as Module3Section);

    const weaknesses = sections
      .filter(([_, result]) => result.score < 0.65)
      .map(([sectionId]) => sectionId as Module3Section);

    return { strengths, weaknesses };
  }

  /**
   * Generate comprehensive recommendations
   */
  private static generateRecommendations(
    sectionResults: Record<Module3Section, SectionAssessmentResult>,
    gapsIdentified: Module3Section[],
    overallScore: number
  ): Module3AssessmentResult["recommendations"] {
    const priorityAreas: Module3Section[] = [];
    const nextSteps: string[] = [];

    // Add gaps as highest priority
    priorityAreas.push(...gapsIdentified);

    // Add weak sections
    Object.entries(sectionResults).forEach(([sectionId, result]) => {
      if (result.score < 0.65) {
        priorityAreas.push(sectionId as Module3Section);
      }
    });

    // Calculate suggested study time
    let suggestedStudyTime = 0;
    priorityAreas.forEach(sectionId => {
      const section = MODULE_3_SECTIONS[sectionId];
      suggestedStudyTime += section.estimatedTime * 2; // Double the base time for review
    });

    // Generate next steps
    if (overallScore >= 0.85) {
      nextSteps.push("Focus on maintaining strong performance");
      nextSteps.push("Consider advanced practice scenarios");
    } else if (overallScore >= 0.75) {
      nextSteps.push("Review weak areas identified above");
      nextSteps.push("Practice with similar questions");
    } else {
      nextSteps.push("Comprehensive review of fundamentals needed");
      nextSteps.push("Focus on understanding core concepts");
      nextSteps.push("Seek additional study resources");
    }

    return {
      priorityAreas: priorityAreas.slice(0, 3), // Top 3 priorities
      suggestedStudyTime,
      nextSteps
    };
  }

  /**
   * Generate section-specific recommendations
   */
  private static generateSectionRecommendations(
    sectionId: Module3Section,
    accuracy: number,
    objectivesMissed: string[],
    timeSpent: number,
    questionCount: number
  ): string[] {
    const recommendations: string[] = [];
    const section = MODULE_3_SECTIONS[sectionId];

    if (accuracy < 0.6) {
      recommendations.push(`Review fundamental concepts in ${section.title}`);
      recommendations.push("Practice with easier questions first");
    } else if (accuracy < 0.8) {
      recommendations.push(`Focus on specific learning objectives: ${objectivesMissed.join(", ")}`);
      recommendations.push("Practice with similar question types");
    }

    if (timeSpent / questionCount > 120) { // More than 2 minutes per question
      recommendations.push("Work on improving response time");
      recommendations.push("Practice time management strategies");
    }

    if (objectivesMissed.length > 0) {
      recommendations.push(`Study these specific objectives: ${objectivesMissed.join(", ")}`);
    }

    return recommendations;
  }

  /**
   * Assess certification readiness
   */
  private static assessCertificationReadiness(
    sectionResults: Record<Module3Section, SectionAssessmentResult>,
    overallScore: number
  ): Module3AssessmentResult["certificationReadiness"] {
    const areas: Record<Module3Section, "strong" | "adequate" | "needs_improvement"> =
      {} as Record<Module3Section, "strong" | "adequate" | "needs_improvement">;

    Object.entries(sectionResults).forEach(([sectionId, result]) => {
      if (result.score >= 0.85) {
        areas[sectionId as Module3Section] = "strong";
      } else if (result.score >= 0.70) {
        areas[sectionId as Module3Section] = "adequate";
      } else {
        areas[sectionId as Module3Section] = "needs_improvement";
      }
    });

    let overallReadiness: "ready" | "almost_ready" | "needs_work";
    if (overallScore >= 0.85) {
      overallReadiness = "ready";
    } else if (overallScore >= 0.75) {
      overallReadiness = "almost_ready";
    } else {
      overallReadiness = "needs_work";
    }

    return {
      score: Math.round(overallScore * 100),
      areas,
      overallReadiness
    };
  }
}

/**
 * Module 3 Practice Integration
 * Extends practice question targeting for the expanded 9-section structure
 */

import {
  Module3Section,
  MODULE_3_SECTIONS,
  createSectionPracticeTargeting,
  type SectionMetadata
} from "@/lib/module3-section-definitions";
import { PracticeQuestionTargeting } from "@/lib/practice-question-targeting";
import { TCODomain, type Question, type PracticeTargeting } from "@/types/exam";

/**
 * Enhanced practice targeting for Module 3 sections
 */
export interface Module3PracticeConfig {
  sectionId: Module3Section;
  includePrerequisites?: boolean;
  includeRelatedSections?: boolean;
  adaptiveDifficulty?: boolean;
  focusOnGaps?: boolean;
}

/**
 * Get targeted questions for a specific Module 3 section
 */
export function getModule3SectionQuestions(
  allQuestions: Question[],
  sectionId: Module3Section,
  config?: Module3PracticeConfig
): Question[] {
  const section = MODULE_3_SECTIONS[sectionId];
  if (!section) {
    console.warn(`Invalid section ID: ${sectionId}`);
    return [];
  }

  // Start with base targeting for the section
  const targeting = createSectionPracticeTargeting(sectionId);

  // Include prerequisites if requested
  if (config?.includePrerequisites && section.prerequisites) {
    const prereqTags = section.prerequisites.map(
      prereqId => MODULE_3_SECTIONS[prereqId].primaryTag
    );
    targeting.optionalTags = [...targeting.optionalTags, ...prereqTags];
  }

  // Include related sections if requested
  if (config?.includeRelatedSections) {
    const relatedSections = getRelatedSections(sectionId);
    const relatedTags = relatedSections.map(s => s.primaryTag);
    targeting.optionalTags = [...targeting.optionalTags, ...relatedTags];
  }

  // Get questions using the targeting system
  const pool = PracticeQuestionTargeting.getTargetedQuestions(allQuestions, targeting);

  // Apply adaptive difficulty if requested
  if (config?.adaptiveDifficulty) {
    return applyAdaptiveDifficulty(pool.questions, section.difficulty);
  }

  return pool.questions;
}

/**
 * Get related sections based on content similarity
 */
function getRelatedSections(sectionId: Module3Section): SectionMetadata[] {
  const relatedMap: Record<Module3Section, Module3Section[]> = {
    [Module3Section.PACKAGE_VALIDATION]: [
      Module3Section.DEPENDENCY_MANAGEMENT,
      Module3Section.ERROR_HANDLING
    ],
    [Module3Section.DEPLOYMENT_STRATEGIES]: [
      Module3Section.SCHEDULING_AUTOMATION,
      Module3Section.BATCH_OPERATIONS
    ],
    [Module3Section.ERROR_HANDLING]: [
      Module3Section.ROLLBACK_PROCEDURES,
      Module3Section.PACKAGE_VALIDATION
    ],
    [Module3Section.ROLLBACK_PROCEDURES]: [
      Module3Section.ERROR_HANDLING,
      Module3Section.PERFORMANCE_MONITORING
    ],
    [Module3Section.PERFORMANCE_MONITORING]: [
      Module3Section.BATCH_OPERATIONS,
      Module3Section.ROLLBACK_PROCEDURES
    ],
    [Module3Section.SECURITY_CONSIDERATIONS]: [
      Module3Section.DEPLOYMENT_STRATEGIES,
      Module3Section.DEPENDENCY_MANAGEMENT
    ],
    [Module3Section.BATCH_OPERATIONS]: [
      Module3Section.PERFORMANCE_MONITORING,
      Module3Section.DEPLOYMENT_STRATEGIES
    ],
    [Module3Section.SCHEDULING_AUTOMATION]: [
      Module3Section.DEPLOYMENT_STRATEGIES,
      Module3Section.BATCH_OPERATIONS
    ],
    [Module3Section.DEPENDENCY_MANAGEMENT]: [
      Module3Section.PACKAGE_VALIDATION,
      Module3Section.SECURITY_CONSIDERATIONS
    ]
  };

  const relatedIds = relatedMap[sectionId] || [];
  return relatedIds.map(id => MODULE_3_SECTIONS[id]);
}

/**
 * Apply adaptive difficulty based on section level
 */
function applyAdaptiveDifficulty(
  questions: Question[],
  baseDifficulty: "Beginner" | "Intermediate" | "Advanced"
): Question[] {
  const difficultyDistribution = {
    Beginner: { beginner: 0.6, intermediate: 0.3, advanced: 0.1 },
    Intermediate: { beginner: 0.2, intermediate: 0.6, advanced: 0.2 },
    Advanced: { beginner: 0.1, intermediate: 0.3, advanced: 0.6 }
  };

  const distribution = difficultyDistribution[baseDifficulty];
  const totalQuestions = questions.length;

  // Group questions by difficulty
  const byDifficulty = {
    beginner: questions.filter(q => q.difficulty === "Beginner"),
    intermediate: questions.filter(q => q.difficulty === "Intermediate"),
    advanced: questions.filter(q => q.difficulty === "Advanced")
  };

  // Calculate target counts
  const targets = {
    beginner: Math.floor(totalQuestions * distribution.beginner),
    intermediate: Math.floor(totalQuestions * distribution.intermediate),
    advanced: Math.ceil(totalQuestions * distribution.advanced)
  };

  // Select questions based on targets
  const selected: Question[] = [];

  Object.entries(targets).forEach(([difficulty, count]) => {
    const available = byDifficulty[difficulty as keyof typeof byDifficulty];
    const toSelect = Math.min(count, available.length);
    const shuffled = [...available].sort(() => Math.random() - 0.5);
    selected.push(...shuffled.slice(0, toSelect));
  });

  // Fill remaining slots if needed
  while (selected.length < totalQuestions && selected.length < questions.length) {
    const remaining = questions.filter(q => !selected.includes(q));
    if (remaining.length === 0) break;
    selected.push(remaining[Math.floor(Math.random() * remaining.length)]);
  }

  return selected.sort(() => Math.random() - 0.5); // Final shuffle
}

/**
 * Create a comprehensive Module 3 practice session
 */
export interface Module3PracticeSession {
  sections: Module3Section[];
  questionsPerSection: number;
  randomizeOrder: boolean;
  focusOnWeakAreas: boolean;
  timeLimit?: number; // in minutes
}

/**
 * Build a complete Module 3 practice session
 */
export function buildModule3PracticeSession(
  allQuestions: Question[],
  config: Module3PracticeSession
): {
  questions: Question[];
  sectionBreakdown: Record<Module3Section, number>;
  estimatedTime: number;
} {
  const sessionQuestions: Question[] = [];
  const sectionBreakdown: Partial<Record<Module3Section, number>> = {};

  // Process each requested section
  config.sections.forEach(sectionId => {
    const section = MODULE_3_SECTIONS[sectionId];
    if (!section) return;

    // Adjust question count based on gaps if focusing on weak areas
    let targetCount = config.questionsPerSection;
    if (config.focusOnWeakAreas) {
      const gapRatio = 1 - (section.currentQuestionCount / section.questionTargetCount);
      targetCount = Math.ceil(config.questionsPerSection * (1 + gapRatio * 0.5));
    }

    // Get questions for this section
    const sectionQuestions = getModule3SectionQuestions(allQuestions, sectionId, {
      sectionId,
      includeRelatedSections: config.sections.length === 1, // Include related if single section
      adaptiveDifficulty: true
    });

    // Limit to target count
    const selected = sectionQuestions.slice(0, targetCount);
    sessionQuestions.push(...selected);
    sectionBreakdown[sectionId] = selected.length;
  });

  // Randomize order if requested
  if (config.randomizeOrder) {
    sessionQuestions.sort(() => Math.random() - 0.5);
  }

  // Calculate estimated time (1.5 minutes per question average)
  const estimatedTime = Math.ceil(sessionQuestions.length * 1.5);

  return {
    questions: sessionQuestions,
    sectionBreakdown: sectionBreakdown as Record<Module3Section, number>,
    estimatedTime
  };
}

/**
 * Get practice recommendations based on current progress
 */
export function getModule3PracticeRecommendations(
  userProgress: Record<Module3Section, { completed: number; accuracy: number }>
): {
  prioritySections: Module3Section[];
  recommendedSessionType: "focused" | "comprehensive" | "review";
  suggestedDuration: number;
} {
  // Identify weak sections (accuracy < 70% or completion < 50%)
  const weakSections = Object.entries(userProgress)
    .filter(([_, progress]) => progress.accuracy < 0.7 || progress.completed < 0.5)
    .map(([sectionId]) => sectionId as Module3Section);

  // Identify sections with no attempts
  const unattemptedSections = Object.entries(MODULE_3_SECTIONS)
    .filter(([sectionId]) => !userProgress[sectionId as Module3Section])
    .map(([sectionId]) => sectionId as Module3Section);

  let prioritySections: Module3Section[];
  let recommendedSessionType: "focused" | "comprehensive" | "review";
  let suggestedDuration: number;

  if (unattemptedSections.length > 3) {
    // Many unattempted sections - comprehensive learning needed
    prioritySections = unattemptedSections.slice(0, 3);
    recommendedSessionType = "comprehensive";
    suggestedDuration = 45;
  } else if (weakSections.length > 0) {
    // Focus on weak areas
    prioritySections = weakSections.slice(0, 2);
    recommendedSessionType = "focused";
    suggestedDuration = 30;
  } else {
    // General review
    prioritySections = Object.keys(MODULE_3_SECTIONS).slice(0, 3) as Module3Section[];
    recommendedSessionType = "review";
    suggestedDuration = 20;
  }

  return {
    prioritySections,
    recommendedSessionType,
    suggestedDuration
  };
}

/**
 * Create section-aware practice targeting
 */
export function createModule3PracticeTargeting(
  sections: Module3Section[],
  options?: {
    minQuestionsPerSection?: number;
    maxQuestionsPerSection?: number;
    includeCrossSectionQuestions?: boolean;
  }
): PracticeTargeting {
  const allTags: string[] = [];
  const allObjectives: string[] = [];

  sections.forEach(sectionId => {
    const section = MODULE_3_SECTIONS[sectionId];
    if (section) {
      allTags.push(section.primaryTag, ...section.tags);
      allObjectives.push(...section.learningObjectives.map(obj => obj.split(":")[0]));
    }
  });

  // Remove duplicates
  const uniqueTags = [...new Set(allTags)];
  const uniqueObjectives = [...new Set(allObjectives)];

  return {
    moduleId: "module-taking-action",
    primaryDomain: TCODomain.TAKING_ACTION,
    targetObjectives: uniqueObjectives,
    requiredTags: sections.map(s => MODULE_3_SECTIONS[s].primaryTag),
    optionalTags: uniqueTags,
    minQuestions: (options?.minQuestionsPerSection || 5) * sections.length,
    idealQuestions: (options?.maxQuestionsPerSection || 10) * sections.length,
    fallbackStrategy: options?.includeCrossSectionQuestions ? "mixed-content" : "expand-domain"
  };
}

