 * Get sections by difficulty level
 */
export function getSectionsByDifficulty(difficulty: "Beginner" | "Intermediate" | "Advanced"): SectionMetadata[] {
  return Object.values(MODULE_3_SECTIONS).filter(section => section.difficulty === difficulty);
}

/**
 * Get sections with missing questions (gaps)
 */
export function getSectionsWithGaps(): SectionMetadata[] {
  return Object.values(MODULE_3_SECTIONS).filter(
    section => section.currentQuestionCount < section.questionTargetCount
  );
}

/**
 * Get section coverage percentage
 */
export function getSectionCoverage(sectionId: Module3Section): number {
  const section = MODULE_3_SECTIONS[sectionId];
  if (!section || section.questionTargetCount === 0) return 0;
  return Math.round((section.currentQuestionCount / section.questionTargetCount) * 100);
}

/**
 * Get overall Module 3 coverage
 */
export function getOverallModule3Coverage(): {
  totalSections: number;
  completeSections: number;
  partialSections: number;
  emptySections: number;
  overallCoverage: number;
} {
  const sections = Object.values(MODULE_3_SECTIONS);
  const completeSections = sections.filter(s => s.currentQuestionCount >= s.questionTargetCount).length;
  const partialSections = sections.filter(s => s.currentQuestionCount > 0 && s.currentQuestionCount < s.questionTargetCount).length;
  const emptySections = sections.filter(s => s.currentQuestionCount === 0).length;

  const totalTarget = sections.reduce((sum, s) => sum + s.questionTargetCount, 0);
  const totalCurrent = sections.reduce((sum, s) => sum + s.currentQuestionCount, 0);
  const overallCoverage = totalTarget > 0 ? Math.round((totalCurrent / totalTarget) * 100) : 0;

  return {
    totalSections: sections.length,
    completeSections,
    partialSections,
    emptySections,
    overallCoverage
  };
}

/**
 * Create practice targeting for a specific section
 */
export function createSectionPracticeTargeting(sectionId: Module3Section) {
  const section = MODULE_3_SECTIONS[sectionId];

  return {
    moduleId: "module-taking-action",
    primaryDomain: TCODomain.TAKING_ACTION,
    targetObjectives: section.learningObjectives.map(obj => obj.split(":")[0]), // Extract objective IDs
    requiredTags: [section.primaryTag],
    optionalTags: section.tags,
    minQuestions: 5,
    idealQuestions: 15,
    fallbackStrategy: "expand-domain" as const
  };
}

/**
 * Get learning path for Module 3 (section order based on prerequisites)
 */
export function getModule3LearningPath(): Module3Section[] {
  // Topological sort based on prerequisites
  const path: Module3Section[] = [];
  const visited = new Set<Module3Section>();

  function visit(sectionId: Module3Section) {
    if (visited.has(sectionId)) return;

    const section = MODULE_3_SECTIONS[sectionId];
    if (section.prerequisites) {
      section.prerequisites.forEach(prereq => visit(prereq));
    }

    visited.add(sectionId);
    path.push(sectionId);
  }

  Object.keys(MODULE_3_SECTIONS).forEach(sectionId => {
    visit(sectionId as Module3Section);
  });

  return path;
}

/**
 * Estimate total study time for Module 3
 */
export function getModule3TotalTime(): {
  totalMinutes: number;
  formattedTime: string;
} {
  const totalMinutes = Object.values(MODULE_3_SECTIONS).reduce(
    (sum, section) => sum + section.estimatedTime,
    0
  );

  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  const formattedTime = hours > 0 ? `${hours}h ${minutes}min` : `${minutes}min`;

  return { totalMinutes, formattedTime };
}

"use client";

import { supabase } from "@/lib/supabase";

export type MonitoringEvent = {
  type:
    | "client_error"
    | "unhandled_rejection"
    | "page_view"
    | "api_error"
    | "performance"
    | "custom";
  data?: Record<string, unknown>;
  sessionId?: string;
};

export async function trackEvent(evt: MonitoringEvent) {
  try {
    const payload = {
      event_id: crypto?.randomUUID?.() || undefined,
      user_id: undefined,
      session_id: evt.sessionId,
      event_type: evt.type,
      event_timestamp: new Date().toISOString(),
      event_data: evt.data ?? {},
    } as any;

    // Insert is best-effort; do not throw in UI flows
    await (supabase as any).from("analytics_events").insert(payload);
  } catch (_) {
    // Swallow monitoring errors to avoid feedback loops
  }
}

export function initClientMonitoring() {
  if (typeof window === "undefined") return;
  // Avoid double-binding in Fast Refresh
  const key = "__tco_monitoring_bound__";
  if ((window as any)[key]) return;
  (window as any)[key] = true;

  window.addEventListener("error", (e) => {
    trackEvent({
      type: "client_error",
      data: {
        message: e?.error?.message || e?.message || "Unknown error",
        stack: e?.error?.stack,
        source: e?.filename,
        lineno: e?.lineno,
        colno: e?.colno,
      },
    });
  });

  window.addEventListener("unhandledrejection", (e) => {
    trackEvent({
      type: "unhandled_rejection",
      data: {
        reason: (e?.reason as any)?.message || String(e?.reason),
        stack: (e?.reason as any)?.stack,
      },
    });
  });
}

/**
 * Practice Question Targeting System (Phase 6.1)
 * Handles targeted question filtering, safe fallbacks, and domain distribution
 */

import {
  Difficulty,
  TCODomain,
  TCO_DOMAIN_WEIGHTS,
  type PracticeTargeting,
  type Question,
  type QuestionFilter,
  type QuestionPool,
} from "@/types/exam";
import { defaultDifficultyRecord } from './difficulty';

/**
 * Core question targeting and filtering utilities
 */
export class PracticeQuestionTargeting {
  /**
   * Get targeted questions for a specific module with safe fallbacks
   */
  static getTargetedQuestions(
    allQuestions: Question[],
    targeting: PracticeTargeting
  ): QuestionPool {
    // Stage 1: Exact targeting (ideal case)
    let pool = this.applyExactTargeting(allQuestions, targeting);

    // Stage 2: Check if we have minimum questions
    if (pool.questions.length >= targeting.minQuestions) {
      return this.buildQuestionPool(pool.questions, "exact-match");
    }

    // Stage 3: Apply fallback strategies
    switch (targeting.fallbackStrategy) {
      case "expand-domain":
        pool = this.expandToDomain(allQuestions, targeting);
        break;

      case "reduce-specificity":
        pool = this.reduceSpecificity(allQuestions, targeting);
        break;

      case "mixed-content":
        pool = this.getMixedContent(allQuestions, targeting);
        break;
    }

    // Stage 4: Final validation and pool construction
    const finalPool = this.buildQuestionPool(pool.questions, pool.fallbackUsed);

    return finalPool;
  }

  /**
   * Apply exact targeting criteria (Stage 1)
   */
  private static applyExactTargeting(
    questions: Question[],
    targeting: PracticeTargeting
  ): { questions: Question[]; fallbackUsed?: string } {
    let filtered = questions.filter((question) => {
      // Primary domain match
      if (question.domain !== targeting.primaryDomain) {
        return false;
      }

      // Module ID match (if available)
      if (targeting.moduleId && question.moduleId && question.moduleId !== targeting.moduleId) {
        return false;
      }

      // Required tags match
      if (targeting.requiredTags.length > 0) {
        const questionTags = question.tags || [];
        const hasRequiredTags = targeting.requiredTags.every((tag) => questionTags.includes(tag));
        if (!hasRequiredTags) {
          return false;
        }
      }

      // Objective match (if available)
      if (targeting.targetObjectives.length > 0 && question.objectiveIds) {
        const hasTargetObjective = targeting.targetObjectives.some((objective) =>
          question.objectiveIds!.includes(objective)
        );
        if (!hasTargetObjective) {
          return false;
        }
      }

      return true;
    });

    // Shuffle for variety
    filtered = this.shuffleArray([...filtered]);

    // Limit to ideal count if we have enough
    if (filtered.length > targeting.idealQuestions) {
      filtered = filtered.slice(0, targeting.idealQuestions);
    }

    return { questions: filtered };
  }

  /**
   * Expand to domain-level questions (Fallback Strategy 1)
   */
  private static expandToDomain(
    questions: Question[],
    targeting: PracticeTargeting
  ): { questions: Question[]; fallbackUsed: string } {
    let domainQuestions = questions.filter((q) => q.domain === targeting.primaryDomain);

    // Prefer questions with optional tags
    if (targeting.optionalTags.length > 0) {
      const withOptionalTags = domainQuestions.filter((q) => {
        const questionTags = q.tags || [];
        return targeting.optionalTags.some((tag) => questionTags.includes(tag));
      });

      if (withOptionalTags.length > 0) {
        domainQuestions = withOptionalTags;
      }
    }

    domainQuestions = this.shuffleArray(domainQuestions);

    return {
      questions: domainQuestions.slice(0, targeting.idealQuestions),
      fallbackUsed: "expand-domain",
    };
  }

  /**
   * Reduce specificity gradually (Fallback Strategy 2)
   */
  private static reduceSpecificity(
    questions: Question[],
    targeting: PracticeTargeting
  ): { questions: Question[]; fallbackUsed: string } {
    // Step 1: Drop objective requirements but keep domain + required tags
    let filtered = questions.filter((question) => {
      if (question.domain !== targeting.primaryDomain) return false;

      if (targeting.requiredTags.length > 0) {
        const questionTags = question.tags || [];
        return targeting.requiredTags.every((tag) => questionTags.includes(tag));
      }

      return true;
    });

    if (filtered.length >= targeting.minQuestions) {
      return {
        questions: this.shuffleArray(filtered).slice(0, targeting.idealQuestions),
        fallbackUsed: "reduced-specificity-objectives",
      };
    }

    // Step 2: Keep domain, drop some required tags
    if (targeting.requiredTags.length > 1) {
      const partialTags = targeting.requiredTags.slice(
        0,
        Math.ceil(targeting.requiredTags.length / 2)
      );

      filtered = questions.filter((question) => {
        if (question.domain !== targeting.primaryDomain) return false;

        const questionTags = question.tags || [];
        return partialTags.some((tag) => questionTags.includes(tag));
      });

      if (filtered.length >= targeting.minQuestions) {
        return {
          questions: this.shuffleArray(filtered).slice(0, targeting.idealQuestions),
          fallbackUsed: "reduced-specificity-tags",
        };
      }
    }

    // Step 3: Domain only
    filtered = questions.filter((q) => q.domain === targeting.primaryDomain);

    return {
      questions: this.shuffleArray(filtered).slice(0, targeting.idealQuestions),
      fallbackUsed: "reduced-specificity-domain-only",
    };
  }

  /**
   * Get mixed content from multiple domains (Fallback Strategy 3)
   */
  private static getMixedContent(
    questions: Question[],
    targeting: PracticeTargeting
  ): { questions: Question[]; fallbackUsed: string } {
    const primaryDomainQuestions = questions.filter((q) => q.domain === targeting.primaryDomain);

    // Get questions from related domains based on TCO weights
    const relatedDomains = Object.entries(TCO_DOMAIN_WEIGHTS)
      .filter(([domain]) => domain !== targeting.primaryDomain)
      .sort(([, weightA], [, weightB]) => weightB - weightA) // Sort by weight descending
      .slice(0, 2) // Top 2 related domains
      .map(([domain]) => domain as TCODomain);

    const relatedQuestions = questions.filter((q) => relatedDomains.includes(q.domain));

    // Distribute questions: 70% primary domain, 30% related
    const primaryCount = Math.ceil(targeting.idealQuestions * 0.7);
    const relatedCount = targeting.idealQuestions - primaryCount;

    const selectedPrimary = this.shuffleArray(primaryDomainQuestions).slice(0, primaryCount);
    const selectedRelated = this.shuffleArray(relatedQuestions).slice(0, relatedCount);

    const mixedQuestions = this.shuffleArray([...selectedPrimary, ...selectedRelated]);

    return {
      questions: mixedQuestions,
      fallbackUsed: "mixed-content",
    };
  }

  /**
   * Build comprehensive question pool with metadata
   */
  private static buildQuestionPool(questions: Question[], fallbackUsed?: string): QuestionPool {
    const domainValues = Object.values(TCODomain) as TCODomain[];
    const domainDistribution: Record<TCODomain, number> = domainValues.reduce(
      (acc, d) => {
        acc[d] = 0;
        return acc;
      },
      {} as Record<TCODomain, number>
    );

    const difficultyDistribution: Record<Difficulty, number> =
      defaultDifficultyRecord(() => 0);

    questions.forEach((question) => {
      domainDistribution[question.domain]++;
      difficultyDistribution[question.difficulty]++;
    });

    const isEmpty = questions.length === 0;
    const hasMinimumQuestions = questions.length >= 5; // Configurable minimum

    // Determine fallback recommendation
    let recommendedFallback: QuestionPool["recommendedFallback"];
    if (isEmpty) {
      recommendedFallback = "mixed-content";
    } else if (!hasMinimumQuestions) {
      recommendedFallback = "expand-criteria";
    } else if (fallbackUsed && fallbackUsed !== "exact-match") {
      recommendedFallback = "use-similar-modules";
    }

    return {
      questions,
      totalCount: questions.length,
      domainDistribution,
      difficultyDistribution,
      isEmpty,
      hasMinimumQuestions,
      recommendedFallback,
    };
  }

  /**
   * Apply general question filters (for QuestionsContext integration)
   */
  static applyQuestionFilter(questions: Question[], filter: QuestionFilter): Question[] {
    let filtered = [...questions];

    // Domain filtering
    if (filter.domains && filter.domains.length > 0) {
      filtered = filtered.filter((q) => filter.domains!.includes(q.domain));
    }

    // Difficulty filtering
    if (filter.difficulties && filter.difficulties.length > 0) {
      filtered = filtered.filter((q) => filter.difficulties!.includes(q.difficulty));
    }

    // Category filtering
    if (filter.categories && filter.categories.length > 0) {
      filtered = filtered.filter((q) => filter.categories!.includes(q.category));
    }

    // Tag filtering
    if (filter.tags && filter.tags.length > 0) {
      filtered = filtered.filter((q) => {
        const questionTags = q.tags || [];
        return filter.tags!.some((tag) => questionTags.includes(tag));
      });
    }

    // Module filtering
    if (filter.moduleIds && filter.moduleIds.length > 0) {
      filtered = filtered.filter((q) => q.moduleId && filter.moduleIds!.includes(q.moduleId));
    }

    // Objective filtering
    if (filter.objectiveIds && filter.objectiveIds.length > 0) {
      filtered = filtered.filter((q) => {
        if (!q.objectiveIds) return false;
        return filter.objectiveIds!.some((objective) => q.objectiveIds!.includes(objective));
      });
    }

    // Concept level filtering
    if (filter.conceptLevels && filter.conceptLevels.length > 0) {
      filtered = filtered.filter(
        (q) => q.conceptLevel && filter.conceptLevels!.includes(q.conceptLevel)
      );
    }

    // Maintain domain distribution if requested
    if (filter.maintainDistribution && filter.limit) {
      filtered = this.maintainDomainDistribution(filtered, filter.limit);
    }

    // Apply limit
    if (filter.limit && !filter.maintainDistribution) {
      filtered = this.shuffleArray(filtered).slice(0, filter.limit);
    }

    return filtered;
  }

  /**
   * Maintain proportional domain distribution when limiting questions
   */
  private static maintainDomainDistribution(
    questions: Question[],
    targetCount: number
  ): Question[] {
    if (questions.length <= targetCount) {
      return this.shuffleArray(questions);
    }

    const domainValues = Object.values(TCODomain) as TCODomain[];
    const domainGroups: Record<TCODomain, Question[]> = domainValues.reduce((acc, d) => {
      acc[d] = [];
      return acc;
    }, {} as Record<TCODomain, Question[]>);

    // Group questions by domain
    questions.forEach((q) => {
      domainGroups[q.domain].push(q);
    });

    const result: Question[] = [];
    const domains = Object.keys(domainGroups) as TCODomain[];

    // Calculate questions per domain based on TCO weights
    domains.forEach((domain) => {
      const domainQuestions = domainGroups[domain];
      if (domainQuestions.length === 0) return;

      const weight = TCO_DOMAIN_WEIGHTS[domain] / 100;
      const targetForDomain = Math.round(targetCount * weight);
      const availableForDomain = Math.min(targetForDomain, domainQuestions.length);

      const selectedFromDomain = this.shuffleArray(domainQuestions).slice(0, availableForDomain);

      result.push(...selectedFromDomain);
    });

    // If we're short, fill from largest available pools
    while (result.length < targetCount) {
      const remainingNeeded = targetCount - result.length;
      const availableQuestions = questions.filter((q) => !result.includes(q));

      if (availableQuestions.length === 0) break;

      const shuffled = this.shuffleArray(availableQuestions);
      result.push(...shuffled.slice(0, remainingNeeded));
    }

    return this.shuffleArray(result).slice(0, targetCount);
  }

  /**
   * Utility: Shuffle array using Fisher-Yates algorithm
   */
  private static shuffleArray<T>(array: T[]): T[] {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
  }
}

/**
 * Create practice targeting configuration for a module
 */
export function createPracticeTargeting(
  moduleId: string,
  domain: TCODomain,
  objectives: string[],
  options?: {
    requiredTags?: string[];
    optionalTags?: string[];
    minQuestions?: number;
    idealQuestions?: number;
    fallbackStrategy?: PracticeTargeting["fallbackStrategy"];
  }
): PracticeTargeting {
  return {
    moduleId,
    primaryDomain: domain,
    targetObjectives: objectives,
    requiredTags: options?.requiredTags || [],
    optionalTags: options?.optionalTags || [],
    minQuestions: options?.minQuestions || 5,
    idealQuestions: options?.idealQuestions || 15,
    fallbackStrategy: options?.fallbackStrategy || "expand-domain",
  };
}

// Bind static method to preserve `this` context when imported as a standalone function
export const getTargetedQuestions = PracticeQuestionTargeting.getTargetedQuestions.bind(
  PracticeQuestionTargeting
);
export default PracticeQuestionTargeting;

import {
  type PracticeSession,
  type PracticeSessionConfig,
  PracticeSessionState,
  type PracticeSessionSummary,
  type PracticeProgress,
  type PracticeQuestion,
} from "@/types/practice-session";
import { type Question, TCODomain, Difficulty } from "@/types/exam";
import { createId } from "@paralleldrive/cuid2";
import { defaultDifficultyRecord } from '@/lib/difficulty';

export class PracticeSessionManager {
  private session: PracticeSession | null = null;
  private onProgressUpdate?: any;
  private onSessionComplete?: any;

  constructor(onProgressUpdate?: any, onSessionComplete?: any) {
    this.onProgressUpdate = onProgressUpdate;
    this.onSessionComplete = onSessionComplete;
  }

  public setProgressCallback(cb: any) {
    this.onProgressUpdate = cb;
  }

  public setCompleteCallback(cb: any) {
    this.onSessionComplete = cb;
  }

  async startSession(
    config: PracticeSessionConfig,
    userId: string,
    questions: Question[]
  ): Promise<PracticeSession> {
    if (this.session && this.session.currentQuestionIndex < this.session.questions.length - 1) {
      throw new Error("Another practice session is already in progress");
    }

    // Shuffle questions for variety
    const shuffledQuestions = [...questions].sort(() => Math.random() - 0.5);
    const selectedQuestions = shuffledQuestions.slice(0, config.questionCount);

    // Convert to practice questions
    const practiceQuestions: PracticeQuestion[] = selectedQuestions.map((q, index) => ({
      ...q,
      sessionId: createId(),
      questionIndex: index,
    }));

    this.session = {
      id: createId(),
      moduleId: config.moduleId,
      userId,
      config,
      questions: practiceQuestions,
      currentQuestionIndex: 0,
      answers: {},
      startedAt: new Date(),
      score: 0,
      correctCount: 0,
      totalQuestions: practiceQuestions.length,
      timeSpent: 0,
      passed: false,
      attempts: 1,
    };

    return this.session;
  }

  getCurrentSession(): PracticeSession | null {
    return this.session;
  }

  getCurrentQuestion(): PracticeQuestion | null {
    if (!this.session || this.session.currentQuestionIndex >= this.session.questions.length) {
      return null;
    }
    return this.session.questions[this.session.currentQuestionIndex];
  }

  answerQuestion(questionId: string, choiceId: string): boolean {
    if (!this.session) {
      throw new Error("No active practice session");
    }

    const question = this.session.questions.find((q) => q.id === questionId);
    if (!question) {
      throw new Error("Question not found in current session");
    }

    // Record the answer
    const answeredAt = new Date();
    question.userAnswer = choiceId;
    question.answeredAt = answeredAt;
    question.isCorrect = choiceId === question.correctAnswerId;

    // Calculate time spent on this question
    const questionStartTime = this.session.startedAt.getTime() + this.session.timeSpent * 1000;
    question.timeSpent = Math.floor((answeredAt.getTime() - questionStartTime) / 1000);

    // Update session answers
    this.session.answers[questionId] = choiceId;

    // Update session statistics
    if (question.isCorrect) {
      this.session.correctCount++;
    }

    this.session.score = Math.round(
      (this.session.correctCount / this.session.totalQuestions) * 100
    );
    this.session.timeSpent += question.timeSpent;

    return question.isCorrect;
  }

  nextQuestion(): PracticeQuestion | null {
    if (!this.session) {
      throw new Error("No active practice session");
    }

    if (this.session.currentQuestionIndex < this.session.questions.length - 1) {
      this.session.currentQuestionIndex++;
      return this.getCurrentQuestion();
    }

    // Session completed
    this.completeSession();
    return null;
  }

  previousQuestion(): PracticeQuestion | null {
    if (!this.session) {
      throw new Error("No active practice session");
    }

    if (this.session.currentQuestionIndex > 0) {
      this.session.currentQuestionIndex--;
      return this.getCurrentQuestion();
    }

    return null;
  }

  canGoToPrevious(): boolean {
    return this.session !== null && this.session.currentQuestionIndex > 0;
  }

  canGoToNext(): boolean {
    if (!this.session) return false;

    const currentQuestion = this.getCurrentQuestion();
    return currentQuestion?.userAnswer !== undefined;
  }

  jumpToQuestion(index: number): PracticeQuestion | null {
    if (!this.session || index < 0 || index >= this.session.questions.length) {
      return null;
    }

    this.session.currentQuestionIndex = index;
    return this.getCurrentQuestion();
  }

  private completeSession(): void {
    if (!this.session) return;

    this.session.completedAt = new Date();
    this.session.passed = this.session.score >= this.session.config.passingScore;

    // Generate session summary
    const summary = this.generateSessionSummary();

    // Notify completion
    if (this.onSessionComplete) {
      this.onSessionComplete(summary);
    }
  }

  private generateSessionSummary(): PracticeSessionSummary {
    if (!this.session) {
      throw new Error("No active session to summarize");
    }

    // Calculate domain breakdown
    const domainValues = Object.values(TCODomain) as TCODomain[];
    const domainBreakdown: Record<
      TCODomain,
      { correct: number; total: number; percentage: number }
    > = domainValues.reduce((acc, d) => {
      acc[d] = { correct: 0, total: 0, percentage: 0 };
      return acc;
    }, {} as Record<TCODomain, { correct: number; total: number; percentage: number }>);

    // Calculate difficulty breakdown
    const difficultyBreakdown: Record<
      Difficulty,
      { correct: number; total: number; percentage: number }
    > = defaultDifficultyRecord(() => ({ correct: 0, total: 0, percentage: 0 }));

    // Process questions
    this.session.questions.forEach((question) => {
      // Domain stats
      domainBreakdown[question.domain].total++;
      if (question.isCorrect) {
        domainBreakdown[question.domain].correct++;
      }

      // Difficulty stats
      difficultyBreakdown[question.difficulty].total++;
      if (question.isCorrect) {
        difficultyBreakdown[question.difficulty].correct++;
      }
    });

    // Calculate percentages
    Object.values(domainBreakdown).forEach((domain) => {
      domain.percentage = domain.total > 0 ? Math.round((domain.correct / domain.total) * 100) : 0;
    });

    Object.values(difficultyBreakdown).forEach((difficulty) => {
      difficulty.percentage =
        difficulty.total > 0 ? Math.round((difficulty.correct / difficulty.total) * 100) : 0;
    });

    // Identify improvement and strong areas
    const improvementAreas: string[] = [];
    const strongAreas: string[] = [];

    Object.entries(domainBreakdown).forEach(([domain, stats]) => {
      if (stats.total > 0) {
        if (stats.percentage < 70) {
          improvementAreas.push(domain);
        } else if (stats.percentage >= 85) {
          strongAreas.push(domain);
        }
      }
    });

    return {
      sessionId: this.session.id,
      score: this.session.score,
      correctCount: this.session.correctCount,
      totalQuestions: this.session.totalQuestions,
      timeSpent: this.session.timeSpent,
      passed: this.session.passed,
      domainBreakdown,
      difficultyBreakdown,
      improvementAreas,
      strongAreas,
    };
  }

  getSessionProgress(): { current: number; total: number; percentage: number } {
    if (!this.session) {
      return { current: 0, total: 0, percentage: 0 };
    }

    const answeredQuestions = this.session.questions.filter(
      (q) => q.userAnswer !== undefined
    ).length;
    return {
      current: answeredQuestions,
      total: this.session.totalQuestions,
      percentage: Math.round((answeredQuestions / this.session.totalQuestions) * 100),
    };
  }

  getSessionState(): PracticeSessionState {
    if (!this.session) {
      return PracticeSessionState.NOT_STARTED;
    }

    if (this.session.completedAt) {
      return PracticeSessionState.COMPLETED;
    }

    return PracticeSessionState.IN_PROGRESS;
  }

  abandonSession(): void {
    if (this.session && !this.session.completedAt) {
      this.session.completedAt = new Date();
      // Don't mark as passed for abandoned sessions
      this.session = null;
    }
  }

  resetSession(): void {
    this.session = null;
  }
}

import { ProgressService } from "@/lib/services/progress-service";
import { supabase } from "@/lib/supabase";
