import { spawn, spawnSync } from 'child_process';
import path from 'path';

const envCandidates = [process.env.PYTHON_PATH, process.env.SIM_PYTHON];
const platformDefaults = process.platform === 'win32' ? ['python3', 'python', 'py'] : ['python3', 'python'];
const pythonCandidates = Array.from(
  new Set(
    [...envCandidates, ...platformDefaults]
      .filter((candidate): candidate is string => Boolean(candidate && candidate.trim()))
      .map((candidate) => candidate.trim()),
  ),
);

const SIM_DIR = path.join(process.cwd(), 'sim');
const SIM_SCRIPT = path.join(SIM_DIR, 'tanium_simulator_v2.py');
let resolvedPythonBin: string | null = null;

function resolvePythonBinary(): string {
  if (resolvedPythonBin) {
    return resolvedPythonBin;
  }

  for (const candidate of pythonCandidates) {
    const check = spawnSync(candidate, ['--version'], { stdio: 'ignore' });
    if (!check.error && check.status === 0) {
      resolvedPythonBin = candidate;
      return candidate;
    }
  }

  throw new Error(
    'Unable to locate a Python interpreter. Install Python 3 or set the SIM_PYTHON/PYTHON_PATH environment variable.',
  );
}

function runProcess(args: string[], timeoutMs = 8000): Promise<string> {
  return new Promise((resolve, reject) => {
    let pythonBin: string;
    try {
      pythonBin = resolvePythonBinary();
    } catch (error) {
      reject(error instanceof Error ? error : new Error('Python interpreter not found.'));
      return;
    }

    const child = spawn(pythonBin, [SIM_SCRIPT, ...args], {
      cwd: SIM_DIR,
      env: { ...process.env },
    });

    let stdout = '';
    let stderr = '';
    let settled = false;
    const timer = setTimeout(() => {
      if (!settled) {
        settled = true;
        child.kill('SIGKILL');
        reject(new Error('Simulator timed out'));
      }
    }, timeoutMs);

    child.stdout.on('data', (chunk) => {
      stdout += chunk.toString();
    });

    child.stderr.on('data', (chunk) => {
      stderr += chunk.toString();
    });

    child.on('error', (error: NodeJS.ErrnoException) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (error?.code === 'ENOENT') {
        reject(
          new Error(
            `Python executable "${pythonBin}" could not be found. Install Python 3 or configure SIM_PYTHON/PYTHON_PATH.`,
          ),
        );
        return;
      }
      reject(error);
    });

    child.on('close', (code) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (code !== 0 && stderr) {
        reject(new Error(stderr.trim()));
        return;
      }
      resolve(stdout.trim());
    });
  });
}

export async function runSimulator(args: string[], timeoutMs?: number) {
  const output = await runProcess(args, timeoutMs);
  if (!output) {
    return { ok: false, error: 'Simulator returned no data.' };
  }
  try {
    return JSON.parse(output);
  } catch (error) {
    return { ok: false, error: 'Failed to parse simulator output.', detail: output };
  }
}

// Minimal spaced repetition utilities (SM-2 inspired)
// Used by Notes MVP to schedule reviews client-side

export type SRRating = 'again' | 'hard' | 'good' | 'easy';

export interface SRCardState {
  id: string;
  // next due time (epoch ms)
  due: number;
  // interval in days
  interval: number;
  // easiness factor
  ease: number;
  // successful repetitions
  reps: number;
  // number of lapses (failures)
  lapses: number;
}

const DAY_MS = 24 * 60 * 60 * 1000;
const MIN_EASE = 1.3;

export function createInitialState(id: string, now: Date = new Date()): SRCardState {
  return {
    id,
    due: now.getTime(),
    interval: 0,
    ease: 2.5,
    reps: 0,
    lapses: 0,
  };
}

export function isDue(state: SRCardState, now: Date = new Date()): boolean {
  return state.due <= now.getTime();
}

export function nextDue(state: SRCardState): Date {
  return new Date(state.due);
}

export function schedule(
  state: SRCardState,
  rating: SRRating,
  now: Date = new Date()
): SRCardState {
  let ease = state.ease;
  let interval = state.interval; // days
  let reps = state.reps;
  let lapses = state.lapses;

  switch (rating) {
    case 'again': {
      // Reset repetitions; short interval, decrease ease
      reps = 0;
      lapses += 1;
      ease = Math.max(MIN_EASE, ease - 0.2);
      interval = 1; // review tomorrow
      break;
    }
    case 'hard': {
      ease = Math.max(MIN_EASE, ease - 0.15);
      if (reps <= 0) interval = 1;
      else if (reps === 1) interval = Math.max(1, Math.round(interval * 1.2));
      else interval = Math.max(1, Math.round(interval * 1.2));
      reps = Math.max(1, reps);
      break;
    }
    case 'good': {
      if (reps === 0) interval = 1;
      else if (reps === 1) interval = 6;
      else interval = Math.max(1, Math.round(interval * ease));
      reps += 1;
      break;
    }
    case 'easy': {
      ease = Math.max(MIN_EASE, ease + 0.15);
      if (reps === 0) interval = 3;
      else if (reps === 1) interval = 7;
      else interval = Math.max(1, Math.round(interval * ease * 1.3));
      reps += 1;
      break;
    }
  }

  const due = now.getTime() + interval * DAY_MS;
  return { ...state, ease, interval, reps, lapses, due };
}

export function getDueQueue(states: SRCardState[], now: Date = new Date()): SRCardState[] {
  const ts = now.getTime();
  return states
    .filter((s) => s.due <= ts)
    .sort((a, b) => a.due - b.due);
}

