/**
 * Tanium Query Engine - Cache Layer
 * High-performance LRU cache with TTL support
 */

import { createHash } from 'crypto';
import { QueryResult, QueryNode, CacheEntry } from './types';

interface CacheStats {
  hits: number;
  misses: number;
  evictions: number;
  size: number;
  maxSize: number;
}

export class QueryCache {
  protected cache: Map<string, CacheEntry<any>>;
  private accessOrder: string[] = [];
  private stats: CacheStats;
  private maxSize: number;
  private defaultTTL: number;

  constructor(maxSize: number = 1000, defaultTTL: number = 300000) { // 5 minutes default
    this.cache = new Map();
    this.maxSize = maxSize;
    this.defaultTTL = defaultTTL;
    this.stats = {
      hits: 0,
      misses: 0,
      evictions: 0,
      size: 0,
      maxSize
    };
  }

  /**
   * Generate cache key from query
   */
  private generateKey(query: string | QueryNode, options?: Record<string, any>): string {
    const data = typeof query === 'string' ? query : JSON.stringify(query);
    const optionsStr = options ? JSON.stringify(options) : '';
    return createHash('sha256')
      .update(data + optionsStr)
      .digest('hex')
      .substring(0, 16); // Use first 16 chars for shorter keys
  }

  /**
   * Get item from cache
   */
  public get<T>(query: string | QueryNode, options?: Record<string, any>): T | null {
    const key = this.generateKey(query, options);
    const entry = this.cache.get(key);

    if (!entry) {
      this.stats.misses++;
      return null;
    }

    // Check if expired
    const now = Date.now();
    if (now > entry.timestamp + entry.ttl) {
      this.delete(key);
      this.stats.misses++;
      return null;
    }

    // Update access order (LRU)
    this.updateAccessOrder(key);
    entry.hits++;
    this.stats.hits++;

    return entry.value;
  }

  /**
   * Set item in cache
   */
  public set<T>(
    query: string | QueryNode,
    value: T,
    options?: {
      ttl?: number;
      size?: number;
      metadata?: Record<string, any>;
    }
  ): void {
    const key = this.generateKey(query);
    const ttl = options?.ttl || this.defaultTTL;
    const size = options?.size || this.estimateSize(value);

    // Check if we need to evict items
    if (this.cache.size >= this.maxSize) {
      this.evictLRU();
    }

    const entry: CacheEntry<T> = {
      value,
      timestamp: Date.now(),
      ttl,
      hits: 0,
      size
    };

    this.cache.set(key, entry);
    this.updateAccessOrder(key);
    this.stats.size = this.cache.size;
  }

  /**
   * Delete item from cache
   */
  public delete(key: string): boolean {
    const deleted = this.cache.delete(key);
    if (deleted) {
      const index = this.accessOrder.indexOf(key);
      if (index > -1) {
        this.accessOrder.splice(index, 1);
      }
      this.stats.size = this.cache.size;
    }
    return deleted;
  }

  /**
   * Clear entire cache
   */
  public clear(): void {
    this.cache.clear();
    this.accessOrder = [];
    this.stats.size = 0;
    this.stats.evictions = 0;
  }

  /**
   * Get cache statistics
   */
  public getStats(): CacheStats {
    return { ...this.stats };
  }

  /**
   * Get cache hit rate
   */
  public getHitRate(): number {
    const total = this.stats.hits + this.stats.misses;
    return total === 0 ? 0 : this.stats.hits / total;
  }

  /**
   * Evict least recently used item
   */
  private evictLRU(): void {
    if (this.accessOrder.length === 0) return;

    const lruKey = this.accessOrder[0];
    this.cache.delete(lruKey);
    this.accessOrder.shift();
    this.stats.evictions++;
    this.stats.size = this.cache.size;
  }

  /**
   * Update access order for LRU
   */
  private updateAccessOrder(key: string): void {
    const index = this.accessOrder.indexOf(key);
    if (index > -1) {
      this.accessOrder.splice(index, 1);
    }
    this.accessOrder.push(key);
  }

  /**
   * Estimate size of cached value
   */
  private estimateSize(value: any): number {
    if (value === null || value === undefined) return 0;
    if (typeof value === 'string') return value.length;
    if (typeof value === 'number') return 8;
    if (typeof value === 'boolean') return 1;
    if (value instanceof Date) return 8;
    if (Array.isArray(value)) {
      return value.reduce((sum, item) => sum + this.estimateSize(item), 0);
    }
    if (typeof value === 'object') {
      return Object.entries(value).reduce(
        (sum, [key, val]) => sum + key.length + this.estimateSize(val),
        0
      );
    }
    return 0;
  }

  /**
   * Prune expired entries
   */
  public pruneExpired(): number {
    const now = Date.now();
    let pruned = 0;

    for (const [key, entry] of this.cache.entries()) {
      if (now > entry.timestamp + entry.ttl) {
        this.delete(key);
        pruned++;
      }
    }

    return pruned;
  }

  /**
   * Get cache size in bytes (estimated)
   */
  public getSizeInBytes(): number {
    let totalSize = 0;
    for (const entry of this.cache.values()) {
      totalSize += entry.size;
    }
    return totalSize;
  }

  /**
   * Export cache for persistence
   */
  public export(): string {
    const data = {
      entries: Array.from(this.cache.entries()),
      stats: this.stats,
      accessOrder: this.accessOrder
    };
    return JSON.stringify(data);
  }

  /**
   * Import cache from persistence
   */
  public import(data: string): void {
    try {
      const parsed = JSON.parse(data);
      this.cache = new Map(parsed.entries);
      this.stats = parsed.stats;
      this.accessOrder = parsed.accessOrder || [];

      // Prune expired entries after import
      this.pruneExpired();
    } catch (error) {
      console.error('Failed to import cache:', error);
    }
  }
}

/**
 * Specialized cache for parsed queries (AST)
 */
export class ParsedQueryCache extends QueryCache {
  constructor(maxSize: number = 500) {
    super(maxSize, 3600000); // 1 hour TTL for parsed queries
  }

  /**
   * Get parsed query AST
   */
  public getAST(query: string): QueryNode | null {
    return this.get<QueryNode>(query);
  }

  /**
   * Set parsed query AST
   */
  public setAST(query: string, ast: QueryNode): void {
    this.set(query, ast, {
      size: JSON.stringify(ast).length
    });
  }
}

/**
 * Specialized cache for query results
 */
export class ResultCache extends QueryCache {
  constructor(maxSize: number = 100, defaultTTL: number = 60000) { // 1 minute default
    super(maxSize, defaultTTL);
  }

  /**
   * Get query result
   */
  public getResult(query: string, userId?: string): QueryResult | null {
    const options = userId ? { userId } : undefined;
    return this.get<QueryResult>(query, options);
  }

  /**
   * Set query result
   */
  public setResult(query: string, result: QueryResult, userId?: string): void {
    const options = userId ? { userId } : undefined;
    const size = this.estimateResultSize(result);

    this.set(query, result, {
      size,
      metadata: options
    });
  }

  /**
   * Estimate size of query result
   */
  private estimateResultSize(result: QueryResult): number {
    let size = 100; // Base overhead

    if (result.headers) {
      size += result.headers.join('').length;
    }

    if (result.rows) {
      size += result.rows.length * 50; // Estimate 50 bytes per row
    }

    if (result.csv) {
      size += result.csv.length;
    }

    return size;
  }

  /**
   * Invalidate all results for a user
   */
  public invalidateUser(userId: string): void {
    const keysToDelete: string[] = [];

    for (const [key, entry] of this.cache.entries()) {
      if (entry.value?.metadata?.userId === userId) {
        keysToDelete.push(key);
      }
    }

    keysToDelete.forEach(key => this.delete(key));
  }
}

/**
 * Cache manager combining all cache types
 */
export class CacheManager {
  private parsedCache: ParsedQueryCache;
  private resultCache: ResultCache;
  private globalEnabled: boolean = true;

  constructor(config?: {
    maxParsedQueries?: number;
    maxResults?: number;
    resultTTL?: number;
    enabled?: boolean;
  }) {
    this.parsedCache = new ParsedQueryCache(config?.maxParsedQueries || 500);
    this.resultCache = new ResultCache(config?.maxResults || 100, config?.resultTTL || 60000);
    this.globalEnabled = config?.enabled ?? true;
  }

  /**
   * Get parsed query from cache
   */
  public getParsedQuery(query: string): QueryNode | null {
    if (!this.globalEnabled) return null;
    return this.parsedCache.getAST(query);
  }

  /**
   * Cache parsed query
   */
  public setParsedQuery(query: string, ast: QueryNode): void {
    if (!this.globalEnabled) return;
    this.parsedCache.setAST(query, ast);
  }

  /**
   * Get query result from cache
   */
  public getQueryResult(query: string, userId?: string): QueryResult | null {
    if (!this.globalEnabled) return null;
    return this.resultCache.getResult(query, userId);
  }

  /**
   * Cache query result
   */
  public setQueryResult(query: string, result: QueryResult, userId?: string): void {
    if (!this.globalEnabled) return;

    // Mark result as cached
    result.cached = true;
    this.resultCache.setResult(query, result, userId);
  }

  /**
   * Clear all caches
   */
  public clearAll(): void {
    this.parsedCache.clear();
    this.resultCache.clear();
  }

  /**
   * Get combined statistics
   */
  public getStatistics(): {
    parsed: CacheStats;
    results: CacheStats;
    totalHitRate: number;
  } {
    const parsedStats = this.parsedCache.getStats();
    const resultStats = this.resultCache.getStats();

    const totalHits = parsedStats.hits + resultStats.hits;
    const totalMisses = parsedStats.misses + resultStats.misses;
    const totalHitRate = totalHits + totalMisses === 0 ? 0 : totalHits / (totalHits + totalMisses);

    return {
      parsed: parsedStats,
      results: resultStats,
      totalHitRate
    };
  }

  /**
   * Prune expired entries from all caches
   */
  public pruneExpired(): {
    parsed: number;
    results: number;
  } {
    return {
      parsed: this.parsedCache.pruneExpired(),
      results: this.resultCache.pruneExpired()
    };
  }

  /**
   * Enable/disable caching
   */
  public setEnabled(enabled: boolean): void {
    this.globalEnabled = enabled;
    if (!enabled) {
      this.clearAll();
    }
  }

  /**
   * Check if caching is enabled
   */
  public isEnabled(): boolean {
    return this.globalEnabled;
  }
}

// Export singleton instance
export const cacheManager = new CacheManager();

/**
 * Tanium Query Engine - Executor
 * High-performance query execution with optimization
 */

import {
  QueryNode,
  QueryResult,
  QueryPlan,
  ExecutionError,
  ExecutorOptions,
  MachineData,
  ExecutionMetrics,
  QueryWarning,
  FilterNode,
  AggregateNode
} from './types';
import { getFieldMapping, getDbColumn, validateFieldOperator, resolveGroupAlias } from './field-mappings';

export class QueryExecutor {
  private data: MachineData[] = [];
  private options: ExecutorOptions;
  private warnings: QueryWarning[] = [];
  private metrics: ExecutionMetrics;

  constructor(data: MachineData[] = [], options: ExecutorOptions = {}) {
    this.data = data;
    this.options = {
      timeout: 5000,
      maxRows: 10000,
      useCache: true,
      cacheTTL: 60000,
      explainOnly: false,
      format: 'json',
      ...options
    };
    this.metrics = this.initMetrics();
  }

  /**
   * Initialize execution metrics
   */
  private initMetrics(): ExecutionMetrics {
    return {
      parseTimeMs: 0,
      planTimeMs: 0,
      executeTimeMs: 0,
      totalTimeMs: 0,
      scoped: 0,
      filtered: 0,
      rowsExamined: 0,
      cacheHit: false
    };
  }

  /**
   * Execute a parsed query
   */
  public async execute(query: QueryNode): Promise<QueryResult> {
    const startTime = performance.now();
    this.warnings = [];
    this.metrics = this.initMetrics();

    try {
      // Generate query plan
      const planStart = performance.now();
      const plan = this.generateQueryPlan(query);
      this.metrics.planTimeMs = performance.now() - planStart;

      // If explain only, return plan
      if (this.options.explainOnly) {
        return this.createExplainResult(plan);
      }

      // Execute query plan
      const execStart = performance.now();
      const result = await this.executePlan(query, plan);
      this.metrics.executeTimeMs = performance.now() - execStart;

      // Update metrics
      this.metrics.totalTimeMs = performance.now() - startTime;
      result.execution = { ...this.metrics };
      result.warnings = this.warnings;

      return result;
    } catch (error) {
      if (error instanceof ExecutionError) {
        throw error;
      }
      throw new ExecutionError(`Query execution failed: ${error}`);
    }
  }

  /**
   * Generate optimized query plan
   */
  private generateQueryPlan(query: QueryNode): QueryPlan {
    const plan: QueryPlan = {
      type: 'scan',
      cost: this.data.length,
      rows: this.data.length,
      width: 100,
      children: []
    };

    // Add scope filtering
    if (query.from.scope.scopeType === 'group' && query.from.scope.value) {
      plan.children?.push({
        type: 'filter',
        cost: plan.rows * 0.1,
        rows: Math.floor(plan.rows * 0.3), // Estimate 30% match
        width: plan.width,
        details: { scope: query.from.scope.value }
      });
    }

    // Add WHERE filters
    if (query.where && query.where.filters.length > 0) {
      const selectivity = 0.5 ** query.where.filters.length; // Each filter reduces by half
      plan.children?.push({
        type: 'filter',
        cost: plan.rows * 0.2,
        rows: Math.floor(plan.rows * selectivity),
        width: plan.width,
        details: { filters: query.where.filters.length }
      });
    }

    // Add GROUP BY
    if (query.groupBy && query.groupBy.columns.length > 0) {
      plan.children?.push({
        type: 'aggregate',
        cost: plan.rows * 0.5,
        rows: Math.floor(plan.rows * 0.1), // Estimate 10% unique groups
        width: 50,
        details: { groupBy: query.groupBy.columns }
      });
    }

    // Add ORDER BY
    if (query.orderBy && query.orderBy.columns.length > 0) {
      const sortCost = plan.rows * Math.log2(plan.rows);
      plan.children?.push({
        type: 'sort',
        cost: sortCost,
        rows: plan.rows,
        width: plan.width,
        details: { orderBy: query.orderBy.columns }
      });
    }

    // Add LIMIT
    if (query.limit) {
      plan.children?.push({
        type: 'limit',
        cost: 1,
        rows: Math.min(query.limit.value, plan.rows),
        width: plan.width,
        details: { limit: query.limit.value }
      });
    }

    return plan;
  }

  /**
   * Execute the query plan
   */
  private async executePlan(query: QueryNode, plan: QueryPlan): Promise<QueryResult> {
    let workingSet = [...this.data];
    this.metrics.rowsExamined = workingSet.length;

    // Apply scope filter
    workingSet = this.applyScope(workingSet, query);
    this.metrics.scoped = workingSet.length;

    // Apply WHERE filters
    if (query.where) {
      workingSet = this.applyFilters(workingSet, query.where.filters);
      this.metrics.filtered = workingSet.length;
    } else {
      this.metrics.filtered = this.metrics.scoped;
    }

    // Build result based on query type
    let headers: string[] = [];
    let rows: Array<Array<string | number | null>> = [];

    if (query.groupBy || query.select.aggregates.length > 0) {
      // Aggregate query
      const aggregateResult = this.executeAggregates(workingSet, query);
      headers = aggregateResult.headers;
      rows = aggregateResult.rows;
    } else {
      // Regular select query
      const selectResult = this.executeSelect(workingSet, query);
      headers = selectResult.headers;
      rows = selectResult.rows;
    }

    // Apply ORDER BY
    if (query.orderBy) {
      rows = this.applyOrderBy(rows, headers, query.orderBy);
    }

    // Apply LIMIT
    if (query.limit) {
      rows = rows.slice(0, query.limit.value);
    }

    // Format result based on options
    const result: QueryResult = {
      ok: true,
      headers,
      rows,
      rowCount: rows.length,
      metadata: this.buildMetadata(query)
    };

    // Add CSV format if requested
    if (this.options.format === 'csv') {
      result.csv = this.formatAsCSV(headers, rows);
    }

    return result;
  }

  /**
   * Apply scope filtering
   */
  private applyScope(data: MachineData[], query: QueryNode): MachineData[] {
    const scope = query.from.scope;

    if (scope.scopeType === 'all') {
      return data;
    }

    if (scope.scopeType === 'group' && scope.value) {
      const resolvedGroup = resolveGroupAlias(scope.value);
      return data.filter(row => row.group_name === resolvedGroup);
    }

    return data;
  }

  /**
   * Apply WHERE filters
   */
  private applyFilters(data: MachineData[], filters: FilterNode[]): MachineData[] {
    let filtered = data;

    for (const filter of filters) {
      const dbColumn = getDbColumn(filter.field);
      if (!dbColumn) {
        this.warnings.push({
          message: `Unknown field: ${filter.field}`,
          severity: 'warning'
        });
        continue;
      }

      // Validate operator compatibility
      if (!validateFieldOperator(filter.field, filter.operator)) {
        this.warnings.push({
          message: `Operator '${filter.operator}' may not be compatible with field '${filter.field}'`,
          severity: 'warning'
        });
      }

      filtered = filtered.filter(row => this.evaluateFilter(row, filter, dbColumn));
    }

    return filtered;
  }

  /**
   * Evaluate a single filter
   */
  private evaluateFilter(row: MachineData, filter: FilterNode, dbColumn: string): boolean {
    const value = (row as any)[dbColumn];
    if (value === null || value === undefined) return false;

    const textValue = String(value).toLowerCase();
    const filterValue = String(filter.value).toLowerCase();

    switch (filter.operator) {
      case 'contains':
        return textValue.includes(filterValue);
      case 'does_not_contain':
        return !textValue.includes(filterValue);
      case 'equals':
        return textValue === filterValue;
      case 'not_equals':
        return textValue !== filterValue;
      case 'starts_with':
        return textValue.startsWith(filterValue);
      case 'ends_with':
        return textValue.endsWith(filterValue);
      case 'greater_than':
        return Number(value) > Number(filter.value);
      case 'less_than':
        return Number(value) < Number(filter.value);
      case 'greater_or_equal':
        return Number(value) >= Number(filter.value);
      case 'less_or_equal':
        return Number(value) <= Number(filter.value);
      default:
        return false;
    }
  }

  /**
   * Execute SELECT columns
   */
  private executeSelect(data: MachineData[], query: QueryNode): {
    headers: string[];
    rows: Array<Array<string | number | null>>;
  } {
    const columns = query.select.columns;
    const headers = columns.length > 0
      ? columns.map(col => col.name)
      : ['Computer Name']; // Default column

    const rows = data.map(row => {
      return headers.map(header => {
        const dbColumn = getDbColumn(header);
        if (!dbColumn) return null;
        const value = (row as any)[dbColumn];
        return this.formatValue(value);
      });
    });

    return { headers, rows };
  }

  /**
   * Execute aggregate functions
   */
  private executeAggregates(data: MachineData[], query: QueryNode): {
    headers: string[];
    rows: Array<Array<string | number | null>>;
  } {
    const headers: string[] = [];
    const aggregates = query.select.aggregates;
    const groupBy = query.groupBy?.columns[0]; // Support single group by for now

    // Add group by column to headers
    if (groupBy) {
      headers.push(groupBy);
    }

    // Add aggregate columns to headers
    if (aggregates.length > 0) {
      aggregates.forEach(agg => {
        headers.push(`${agg.function}(${agg.column || ''})`);
      });
    } else {
      headers.push('count()');
    }

    // Calculate aggregates
    if (groupBy) {
      // Grouped aggregates
      const groups = this.groupData(data, groupBy);
      const rows: Array<Array<string | number | null>> = [];

      for (const [groupValue, groupData] of groups.entries()) {
        const row: Array<string | number | null> = [groupValue];

        if (aggregates.length > 0) {
          aggregates.forEach(agg => {
            row.push(this.calculateAggregate(groupData, agg));
          });
        } else {
          row.push(groupData.length); // Default count
        }

        rows.push(row);
      }

      return { headers, rows };
    } else {
      // Simple aggregates
      const row: Array<string | number | null> = [];

      if (aggregates.length > 0) {
        aggregates.forEach(agg => {
          row.push(this.calculateAggregate(data, agg));
        });
      } else {
        row.push(data.length); // Default count
      }

      return { headers, rows: [row] };
    }
  }

  /**
   * Group data by column
   */
  private groupData(data: MachineData[], column: string): Map<string, MachineData[]> {
    const groups = new Map<string, MachineData[]>();
    const dbColumn = getDbColumn(column);

    if (!dbColumn) {
      this.warnings.push({
        message: `Unknown group by column: ${column}`,
        severity: 'error'
      });
      return groups;
    }

    for (const row of data) {
      const key = String((row as any)[dbColumn] || 'null');
      if (!groups.has(key)) {
        groups.set(key, []);
      }
      groups.get(key)!.push(row);
    }

    return groups;
  }

  /**
   * Calculate aggregate function
   */
  private calculateAggregate(data: MachineData[], aggregate: AggregateNode): string | number | null {
    if (aggregate.function === 'count') {
      if (!aggregate.column) {
        return data.length;
      }
      const dbColumn = getDbColumn(aggregate.column);
      if (!dbColumn) return 0;
      return data.filter(row => (row as any)[dbColumn] != null).length;
    }

    if (!aggregate.column) return null;
    const dbColumn = getDbColumn(aggregate.column);
    if (!dbColumn) return null;

    const values = data
      .map(row => (row as any)[dbColumn])
      .filter(v => v != null && !isNaN(Number(v)))
      .map(Number);

    if (values.length === 0) return null;

    switch (aggregate.function) {
      case 'min':
        return Math.min(...values);
      case 'max':
        return Math.max(...values);
      case 'avg':
        return Math.round((values.reduce((a, b) => a + b, 0) / values.length) * 100) / 100;
      case 'sum':
        return Math.round(values.reduce((a, b) => a + b, 0) * 100) / 100;
      default:
        return null;
    }
  }

  /**
   * Apply ORDER BY
   */
  private applyOrderBy(
    rows: Array<Array<string | number | null>>,
    headers: string[],
    orderBy: QueryNode['orderBy']
  ): Array<Array<string | number | null>> {
    if (!orderBy) return rows;

    const sorted = [...rows];
    const sortColumns = orderBy.columns;

    sorted.sort((a, b) => {
      for (const sortCol of sortColumns) {
        const index = headers.indexOf(sortCol.column);
        if (index === -1) continue;

        const aVal = a[index];
        const bVal = b[index];

        if (aVal === null && bVal === null) continue;
        if (aVal === null) return sortCol.direction === 'asc' ? -1 : 1;
        if (bVal === null) return sortCol.direction === 'asc' ? 1 : -1;

        let comparison = 0;
        if (typeof aVal === 'number' && typeof bVal === 'number') {
          comparison = aVal - bVal;
        } else {
          comparison = String(aVal).localeCompare(String(bVal));
        }

        if (comparison !== 0) {
          return sortCol.direction === 'asc' ? comparison : -comparison;
        }
      }
      return 0;
    });

    return sorted;
  }

  /**
   * Format value for output
   */
  private formatValue(value: any): string | number | null {
    if (value === null || value === undefined) return null;
    if (typeof value === 'number') {
      return Math.round(value * 1000) / 1000; // Round to 3 decimal places
    }
    if (value instanceof Date) {
      return value.toISOString();
    }
    return String(value);
  }

  /**
   * Format result as CSV
   */
  private formatAsCSV(headers: string[], rows: Array<Array<string | number | null>>): string {
    const lines: string[] = [];

    // Add headers
    lines.push(headers.map(h => this.escapeCSV(h)).join(','));

    // Add rows
    for (const row of rows) {
      lines.push(row.map(cell => this.escapeCSV(cell)).join(','));
    }

    return lines.join('\n');
  }

  /**
   * Escape CSV value
   */
  private escapeCSV(value: any): string {
    if (value === null || value === undefined) return '';
    const str = String(value);
    if (str.includes(',') || str.includes('"') || str.includes('\n')) {
      return `"${str.replace(/"/g, '""')}"`;
    }
    return str;
  }

  /**
   * Build query metadata
   */
  private buildMetadata(query: QueryNode): QueryResult['metadata'] {
    return {
      aggregations: query.select.aggregates.map(a => a.function),
      groupBy: query.groupBy?.columns[0] || null,
      orderBy: query.orderBy?.columns[0]?.column || null,
      orderDir: query.orderBy?.columns[0]?.direction || 'asc',
      limit: query.limit?.value || null,
      scope: query.from.scope.value || query.from.scope.scopeType,
      filters: query.where?.filters.length || 0
    };
  }

  /**
   * Create explain result
   */
  private createExplainResult(plan: QueryPlan): QueryResult {
    return {
      ok: true,
      headers: ['Operation', 'Cost', 'Rows', 'Details'],
      rows: this.planToRows(plan),
      rowCount: 1,
      metadata: {
        aggregations: [],
        groupBy: null,
        orderBy: null,
        orderDir: 'asc',
        limit: null,
        scope: 'all',
        filters: 0
      }
    };
  }

  /**
   * Convert query plan to rows for display
   */
  private planToRows(plan: QueryPlan, depth: number = 0): Array<Array<string | number | null>> {
    const rows: Array<Array<string | number | null>> = [];
    const indent = '  '.repeat(depth);

    rows.push([
      `${indent}${plan.type}`,
      plan.cost,
      plan.rows,
      plan.details ? JSON.stringify(plan.details) : null
    ]);

    if (plan.children) {
      for (const child of plan.children) {
        rows.push(...this.planToRows(child, depth + 1));
      }
    }

    return rows;
  }

  /**
   * Set data for executor
   */
  public setData(data: MachineData[]): void {
    this.data = data;
  }

  /**
   * Get current data
   */
  public getData(): MachineData[] {
    return this.data;
  }
}

// Export factory function
export function executeQuery(
  query: QueryNode,
  data: MachineData[],
  options?: ExecutorOptions
): Promise<QueryResult> {
  const executor = new QueryExecutor(data, options);
  return executor.execute(query);
}

