/**
 * Tanium Query Engine - Lexer/Tokenizer
 * High-performance lexical analyzer for TQL syntax
 */

import { Token, TokenType, QueryError } from './types';

export class Lexer {
  private input: string;
  private position: number = 0;
  private line: number = 1;
  private column: number = 1;
  private tokens: Token[] = [];

  // Keyword mappings (case-insensitive)
  private static readonly KEYWORDS: Map<string, TokenType> = new Map([
    ['get', TokenType.GET],
    ['from', TokenType.FROM],
    ['where', TokenType.WHERE],
    ['with', TokenType.WITH],
    ['group', TokenType.GROUP_BY],
    ['by', TokenType.GROUP_BY],
    ['order', TokenType.ORDER_BY],
    ['limit', TokenType.LIMIT],
    ['and', TokenType.AND],
    ['contains', TokenType.CONTAINS],
    ['does', TokenType.DOES_NOT_CONTAIN],
    ['not', TokenType.DOES_NOT_CONTAIN],
    ['contain', TokenType.DOES_NOT_CONTAIN],
    ['equals', TokenType.EQUALS],
    ['is', TokenType.IS_GREATER_THAN],
    ['greater', TokenType.IS_GREATER_THAN],
    ['less', TokenType.IS_LESS_THAN],
    ['than', TokenType.IS_GREATER_THAN],
    ['starts', TokenType.STARTS_WITH],
    ['ends', TokenType.ENDS_WITH],
    ['count', TokenType.COUNT],
    ['min', TokenType.MIN],
    ['max', TokenType.MAX],
    ['avg', TokenType.AVG],
    ['sum', TokenType.SUM],
  ]);

  // Operator patterns for multi-word operators
  private static readonly OPERATOR_PATTERNS = [
    { pattern: /^does\s+not\s+contain/i, type: TokenType.DOES_NOT_CONTAIN },
    { pattern: /^is\s+greater\s+than/i, type: TokenType.IS_GREATER_THAN },
    { pattern: /^is\s+less\s+than/i, type: TokenType.IS_LESS_THAN },
    { pattern: /^starts\s+with/i, type: TokenType.STARTS_WITH },
    { pattern: /^ends\s+with/i, type: TokenType.ENDS_WITH },
    { pattern: /^group\s+by/i, type: TokenType.GROUP_BY },
    { pattern: /^order\s+by/i, type: TokenType.ORDER_BY },
  ];

  constructor(input: string) {
    this.input = input;
  }

  /**
   * Tokenize the input string
   */
  public tokenize(): Token[] {
    this.tokens = [];
    this.position = 0;
    this.line = 1;
    this.column = 1;

    while (!this.isEOF()) {
      this.skipWhitespace();
      if (this.isEOF()) break;

      const token = this.nextToken();
      if (token.type !== TokenType.UNKNOWN) {
        this.tokens.push(token);
      }
    }

    this.tokens.push(this.createToken(TokenType.EOF, ''));
    return this.tokens;
  }

  /**
   * Get the next token
   */
  private nextToken(): Token {
    const startPos = this.position;
    const startLine = this.line;
    const startColumn = this.column;

    // Check for multi-word operators first
    for (const { pattern, type } of Lexer.OPERATOR_PATTERNS) {
      const remaining = this.input.slice(this.position);
      const match = remaining.match(pattern);
      if (match && match.index === 0) {
        const value = match[0];
        this.advance(value.length);
        return this.createTokenAt(type, value, startPos, startLine, startColumn);
      }
    }

    const char = this.peek();

    // String literals
    if (char === '"' || char === "'") {
      return this.readString();
    }

    // Numbers
    if (this.isDigit(char)) {
      return this.readNumber();
    }

    // Identifiers and keywords
    if (this.isAlpha(char)) {
      return this.readIdentifier();
    }

    // Punctuation
    switch (char) {
      case ',':
        this.advance();
        return this.createTokenAt(TokenType.COMMA, ',', startPos, startLine, startColumn);
      case '(':
        this.advance();
        return this.createTokenAt(TokenType.LPAREN, '(', startPos, startLine, startColumn);
      case ')':
        this.advance();
        return this.createTokenAt(TokenType.RPAREN, ')', startPos, startLine, startColumn);
      case '.':
        this.advance();
        return this.createTokenAt(TokenType.DOT, '.', startPos, startLine, startColumn);
      default:
        // Unknown character
        this.advance();
        return this.createTokenAt(TokenType.UNKNOWN, char, startPos, startLine, startColumn);
    }
  }

  /**
   * Read a string literal
   */
  private readString(): Token {
    const startPos = this.position;
    const startLine = this.line;
    const startColumn = this.column;
    const quote = this.peek();

    this.advance(); // Skip opening quote
    let value = '';
    let escaped = false;

    while (!this.isEOF() && (escaped || this.peek() !== quote)) {
      const char = this.peek();

      if (escaped) {
        // Handle escape sequences
        switch (char) {
          case 'n': value += '\n'; break;
          case 't': value += '\t'; break;
          case 'r': value += '\r'; break;
          case '\\': value += '\\'; break;
          case '"': value += '"'; break;
          case "'": value += "'"; break;
          default: value += char;
        }
        escaped = false;
      } else if (char === '\\') {
        escaped = true;
      } else {
        value += char;
      }

      this.advance();
    }

    if (this.isEOF()) {
      throw new QueryError(
        `Unterminated string literal`,
        startPos,
        startLine,
        startColumn
      );
    }

    this.advance(); // Skip closing quote
    return this.createTokenAt(TokenType.STRING, value, startPos, startLine, startColumn);
  }

  /**
   * Read a number literal
   */
  private readNumber(): Token {
    const startPos = this.position;
    const startLine = this.line;
    const startColumn = this.column;
    let value = '';

    // Read integer part
    while (!this.isEOF() && this.isDigit(this.peek())) {
      value += this.peek();
      this.advance();
    }

    // Read decimal part if present
    if (!this.isEOF() && this.peek() === '.' && this.isDigit(this.peek(1))) {
      value += this.peek();
      this.advance();

      while (!this.isEOF() && this.isDigit(this.peek())) {
        value += this.peek();
        this.advance();
      }
    }

    return this.createTokenAt(TokenType.NUMBER, value, startPos, startLine, startColumn);
  }

  /**
   * Read an identifier or keyword
   */
  private readIdentifier(): Token {
    const startPos = this.position;
    const startLine = this.line;
    const startColumn = this.column;
    let value = '';

    // Read identifier characters
    while (!this.isEOF() && (this.isAlphaNumeric(this.peek()) || this.peek() === '_' || this.peek() === ' ')) {
      const char = this.peek();

      // Check if space is part of a multi-word identifier (e.g., "Computer Name")
      if (char === ' ') {
        const nextChar = this.peek(1);
        if (!nextChar || !this.isAlpha(nextChar)) {
          break;
        }
        // Look ahead to see if this forms a known field name
        const remaining = this.input.slice(this.position);
        const fieldMatch = remaining.match(/^[A-Za-z\s]+/);
        if (fieldMatch && this.isKnownField(fieldMatch[0].trim())) {
          value += char;
          this.advance();
        } else {
          break;
        }
      } else {
        value += char;
        this.advance();
      }
    }

    // Trim and check if it's a keyword
    value = value.trim();
    const lowerValue = value.toLowerCase();
    const keywordType = Lexer.KEYWORDS.get(lowerValue);

    if (keywordType) {
      // Special handling for aggregate functions
      if ([TokenType.COUNT, TokenType.MIN, TokenType.MAX, TokenType.AVG, TokenType.SUM].includes(keywordType)) {
        // Look for parentheses
        this.skipWhitespace();
        if (this.peek() === '(') {
          return this.createTokenAt(keywordType, value, startPos, startLine, startColumn);
        }
      }
      return this.createTokenAt(keywordType, value, startPos, startLine, startColumn);
    }

    return this.createTokenAt(TokenType.IDENTIFIER, value, startPos, startLine, startColumn);
  }

  /**
   * Check if a string is a known field name
   */
  private isKnownField(name: string): boolean {
    const knownFields = [
      'computer name', 'computer role', 'operating system', 'os platform',
      'os version', 'disk free gb', 'memory gb', 'cpu percent',
      'compliance score', 'group name', 'group', 'location',
      'last reboot', 'last seen', 'service status', 'ip address',
      'mac address', 'serial number', 'manufacturer', 'model'
    ];

    return knownFields.includes(name.toLowerCase());
  }

  /**
   * Skip whitespace characters
   */
  private skipWhitespace(): void {
    while (!this.isEOF() && this.isWhitespace(this.peek())) {
      if (this.peek() === '\n') {
        this.line++;
        this.column = 1;
      } else {
        this.column++;
      }
      this.position++;
    }
  }

  /**
   * Character classification methods
   */
  private isWhitespace(char: string): boolean {
    return /\s/.test(char);
  }

  private isDigit(char: string): boolean {
    return /\d/.test(char);
  }

  private isAlpha(char: string): boolean {
    return /[a-zA-Z]/.test(char);
  }

  private isAlphaNumeric(char: string): boolean {
    return /[a-zA-Z0-9]/.test(char);
  }

  /**
   * Peek at character(s) without advancing
   */
  private peek(offset: number = 0): string {
    const pos = this.position + offset;
    if (pos >= this.input.length) {
      return '\0';
    }
    return this.input[pos];
  }

  /**
   * Advance position by n characters
   */
  private advance(count: number = 1): void {
    for (let i = 0; i < count; i++) {
      if (this.position < this.input.length) {
        if (this.input[this.position] === '\n') {
          this.line++;
          this.column = 1;
        } else {
          this.column++;
        }
        this.position++;
      }
    }
  }

  /**
   * Check if at end of input
   */
  private isEOF(): boolean {
    return this.position >= this.input.length;
  }

  /**
   * Create a token at current position
   */
  private createToken(type: TokenType, value: string): Token {
    return {
      type,
      value,
      position: this.position,
      line: this.line,
      column: this.column
    };
  }

  /**
   * Create a token at specific position
   */
  private createTokenAt(
    type: TokenType,
    value: string,
    position: number,
    line: number,
    column: number
  ): Token {
    return {
      type,
      value,
      position,
      line,
      column
    };
  }

  /**
   * Get all tokens (for debugging)
   */
  public getTokens(): Token[] {
    return this.tokens;
  }

  /**
   * Get formatted token list (for debugging)
   */
  public formatTokens(): string {
    return this.tokens
      .map(t => `${t.type}(${t.value}) @ ${t.line}:${t.column}`)
      .join('\n');
  }
}

// Export factory function for convenience
export function tokenize(input: string): Token[] {
  const lexer = new Lexer(input);
  return lexer.tokenize();
}

/**
 * Tanium Query Engine - Parser
 * Recursive descent parser with AST generation
 */

import {
  Token,
  TokenType,
  QueryNode,
  SelectNode,
  FromNode,
  WhereNode,
  GroupByNode,
  OrderByNode,
  LimitNode,
  ColumnNode,
  AggregateNode,
  FilterNode,
  ScopeNode,
  FilterOperator,
  ParseError,
  ParserOptions,
  SourceLocation
} from './types';
import { Lexer } from './lexer';

export class Parser {
  private tokens: Token[] = [];
  private current: number = 0;
  private options: ParserOptions;

  constructor(options: ParserOptions = {}) {
    this.options = {
      strictMode: false,
      allowPartialQueries: false,
      maxDepth: 100,
      validateSemantics: true,
      ...options
    };
  }

  /**
   * Parse a query string into an AST
   */
  public parse(input: string): QueryNode {
    // Tokenize input
    const lexer = new Lexer(input);
    this.tokens = lexer.tokenize();
    this.current = 0;

    // Parse query
    const query = this.parseQuery();

    // Validate semantics if enabled
    if (this.options.validateSemantics) {
      this.validateQuery(query);
    }

    return query;
  }

  /**
   * Parse main query structure
   * Query ::= GET SelectList FROM Scope [WHERE Filters] [GROUP BY Columns] [ORDER BY Columns] [LIMIT Number]
   */
  private parseQuery(): QueryNode {
    const startToken = this.peek();

    // Expect GET keyword
    if (!this.match(TokenType.GET)) {
      throw new ParseError('Query must start with "Get"', this.peek());
    }

    // Parse SELECT clause
    const select = this.parseSelect();

    // Expect FROM keyword
    if (!this.match(TokenType.FROM)) {
      throw new ParseError('Expected "from" after column list', this.peek());
    }

    // Parse FROM clause
    const from = this.parseFrom();

    // Parse optional clauses
    let where: WhereNode | undefined;
    let groupBy: GroupByNode | undefined;
    let orderBy: OrderByNode | undefined;
    let limit: LimitNode | undefined;

    // Parse WHERE/WITH clause
    if (this.match(TokenType.WHERE) || this.match(TokenType.WITH)) {
      where = this.parseWhere();
    }

    // Parse GROUP BY clause
    if (this.matchSequence([TokenType.GROUP_BY]) ||
        (this.check(TokenType.IDENTIFIER) && this.peekValue()?.toLowerCase() === 'group')) {
      groupBy = this.parseGroupBy();
    }

    // Parse ORDER BY clause
    if (this.matchSequence([TokenType.ORDER_BY]) ||
        (this.check(TokenType.IDENTIFIER) && this.peekValue()?.toLowerCase() === 'order')) {
      orderBy = this.parseOrderBy();
    }

    // Parse LIMIT clause
    if (this.match(TokenType.LIMIT)) {
      limit = this.parseLimit();
    }

    // Create query node
    return {
      type: 'Query',
      select,
      from,
      where,
      groupBy,
      orderBy,
      limit,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse SELECT clause
   */
  private parseSelect(): SelectNode {
    const startToken = this.peek();
    const columns: ColumnNode[] = [];
    const aggregates: AggregateNode[] = [];

    do {
      // Check for aggregate functions
      if (this.checkAggregate()) {
        aggregates.push(this.parseAggregate());
      } else {
        // Parse column name
        const column = this.parseColumn();
        if (column) {
          columns.push(column);
        }
      }
    } while (this.match(TokenType.COMMA) ||
             (this.check(TokenType.IDENTIFIER) &&
              this.peekValue()?.toLowerCase() === 'and' &&
              !this.checkAhead(TokenType.FROM)));

    // If only aggregates and no columns, that's valid
    if (columns.length === 0 && aggregates.length === 0) {
      throw new ParseError('Expected at least one column or aggregate', this.peek());
    }

    return {
      type: 'Select',
      columns,
      aggregates,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse column reference
   */
  private parseColumn(): ColumnNode | null {
    const startToken = this.peek();

    // Handle multi-word column names
    let columnName = '';
    while (this.check(TokenType.IDENTIFIER)) {
      if (columnName) columnName += ' ';
      columnName += this.advance().value;

      // Check if next token continues the column name
      if (!this.checkColumnContinuation()) {
        break;
      }
    }

    if (!columnName) {
      return null;
    }

    return {
      type: 'Column',
      name: columnName,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse aggregate function
   */
  private parseAggregate(): AggregateNode {
    const startToken = this.peek();
    let func: AggregateNode['function'];

    // Get aggregate function
    const token = this.advance();
    switch (token.type) {
      case TokenType.COUNT:
        func = 'count';
        break;
      case TokenType.MIN:
        func = 'min';
        break;
      case TokenType.MAX:
        func = 'max';
        break;
      case TokenType.AVG:
        func = 'avg';
        break;
      case TokenType.SUM:
        func = 'sum';
        break;
      default:
        throw new ParseError(`Unknown aggregate function: ${token.value}`, token);
    }

    // Parse optional column argument
    let column: string | undefined;
    if (this.match(TokenType.LPAREN)) {
      if (!this.check(TokenType.RPAREN)) {
        const col = this.parseColumn();
        if (col) {
          column = col.name;
        }
      }
      this.consume(TokenType.RPAREN, 'Expected closing parenthesis');
    }

    return {
      type: 'Aggregate',
      function: func,
      column,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse FROM clause
   */
  private parseFrom(): FromNode {
    const startToken = this.peek();
    const scope = this.parseScope();

    return {
      type: 'From',
      scope,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse scope (all machines, group, etc.)
   */
  private parseScope(): ScopeNode {
    const startToken = this.peek();

    // Check for "all machines"
    if (this.check(TokenType.IDENTIFIER)) {
      const value = this.peekValue()?.toLowerCase();
      if (value === 'all') {
        this.advance();
        if (this.check(TokenType.IDENTIFIER) &&
            this.peekValue()?.toLowerCase() === 'machines') {
          this.advance();
        }
        return {
          type: 'Scope',
          scopeType: 'all',
          location: this.createLocation(startToken, this.previous())
        };
      }

      // Check for "group <name>"
      if (value === 'group') {
        this.advance();
        let groupName = '';

        // Handle quoted group name
        if (this.check(TokenType.STRING)) {
          groupName = this.advance().value;
        } else {
          // Handle unquoted group name
          while (this.check(TokenType.IDENTIFIER)) {
            if (groupName) groupName += ' ';
            groupName += this.advance().value;
            if (!this.checkGroupNameContinuation()) {
              break;
            }
          }
        }

        return {
          type: 'Scope',
          scopeType: 'group',
          value: groupName,
          location: this.createLocation(startToken, this.previous())
        };
      }
    }

    // Default to "all"
    return {
      type: 'Scope',
      scopeType: 'all',
      location: this.createLocation(startToken, startToken)
    };
  }

  /**
   * Parse WHERE clause
   */
  private parseWhere(): WhereNode {
    const startToken = this.previous();
    const filters: FilterNode[] = [];

    do {
      filters.push(this.parseFilter());
    } while (this.match(TokenType.AND));

    return {
      type: 'Where',
      filters,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse filter expression
   */
  private parseFilter(): FilterNode {
    const startToken = this.peek();

    // Parse field name
    const field = this.parseColumn();
    if (!field) {
      throw new ParseError('Expected field name in filter', this.peek());
    }

    // Parse operator
    const operator = this.parseOperator();

    // Parse value
    let value: string | number;
    if (this.check(TokenType.STRING)) {
      value = this.advance().value;
    } else if (this.check(TokenType.NUMBER)) {
      value = parseFloat(this.advance().value);
    } else {
      // Try to read unquoted string
      let stringValue = '';
      while (this.check(TokenType.IDENTIFIER)) {
        if (stringValue) stringValue += ' ';
        stringValue += this.advance().value;
        if (!this.checkFilterValueContinuation()) {
          break;
        }
      }
      value = stringValue;
    }

    return {
      type: 'Filter',
      field: field.name,
      operator,
      value,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse filter operator
   */
  private parseOperator(): FilterOperator {
    if (this.match(TokenType.CONTAINS)) {
      return 'contains';
    }
    if (this.match(TokenType.DOES_NOT_CONTAIN)) {
      return 'does_not_contain';
    }
    if (this.match(TokenType.EQUALS)) {
      return 'equals';
    }
    if (this.match(TokenType.IS_GREATER_THAN)) {
      return 'greater_than';
    }
    if (this.match(TokenType.IS_LESS_THAN)) {
      return 'less_than';
    }
    if (this.match(TokenType.STARTS_WITH)) {
      return 'starts_with';
    }
    if (this.match(TokenType.ENDS_WITH)) {
      return 'ends_with';
    }

    throw new ParseError('Expected comparison operator', this.peek());
  }

  /**
   * Parse GROUP BY clause
   */
  private parseGroupBy(): GroupByNode {
    const startToken = this.peek();

    // Consume "group by"
    if (this.check(TokenType.IDENTIFIER) && this.peekValue()?.toLowerCase() === 'group') {
      this.advance();
      if (this.check(TokenType.IDENTIFIER) && this.peekValue()?.toLowerCase() === 'by') {
        this.advance();
      }
    } else if (this.check(TokenType.GROUP_BY)) {
      this.advance();
    }

    const columns: string[] = [];
    do {
      const col = this.parseColumn();
      if (col) {
        columns.push(col.name);
      }
    } while (this.match(TokenType.COMMA));

    return {
      type: 'GroupBy',
      columns,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse ORDER BY clause
   */
  private parseOrderBy(): OrderByNode {
    const startToken = this.peek();

    // Consume "order by"
    if (this.check(TokenType.IDENTIFIER) && this.peekValue()?.toLowerCase() === 'order') {
      this.advance();
      if (this.check(TokenType.IDENTIFIER) && this.peekValue()?.toLowerCase() === 'by') {
        this.advance();
      }
    } else if (this.check(TokenType.ORDER_BY)) {
      this.advance();
    }

    const columns: OrderByNode['columns'] = [];
    do {
      const col = this.parseColumn();
      if (col) {
        let direction: 'asc' | 'desc' = 'asc';

        // Check for ASC/DESC
        if (this.check(TokenType.IDENTIFIER)) {
          const dir = this.peekValue()?.toLowerCase();
          if (dir === 'asc' || dir === 'desc') {
            direction = dir as 'asc' | 'desc';
            this.advance();
          }
        }

        columns.push({
          column: col.name,
          direction
        });
      }
    } while (this.match(TokenType.COMMA));

    return {
      type: 'OrderBy',
      columns,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Parse LIMIT clause
   */
  private parseLimit(): LimitNode {
    const startToken = this.previous();

    if (!this.check(TokenType.NUMBER)) {
      throw new ParseError('Expected number after LIMIT', this.peek());
    }

    const value = parseInt(this.advance().value);

    return {
      type: 'Limit',
      value,
      location: this.createLocation(startToken, this.previous())
    };
  }

  /**
   * Validate query semantics
   */
  private validateQuery(query: QueryNode): void {
    // Validate GROUP BY columns are in SELECT
    if (query.groupBy) {
      for (const groupCol of query.groupBy.columns) {
        const inSelect = query.select.columns.some(c => c.name === groupCol);
        if (!inSelect && query.select.aggregates.length === 0) {
          throw new ParseError(`GROUP BY column "${groupCol}" must appear in SELECT clause`);
        }
      }
    }

    // Validate ORDER BY columns
    if (query.orderBy) {
      for (const orderCol of query.orderBy.columns) {
        const inSelect = query.select.columns.some(c => c.name === orderCol.column);
        const inGroup = query.groupBy?.columns.includes(orderCol.column);
        if (!inSelect && !inGroup) {
          throw new ParseError(`ORDER BY column "${orderCol.column}" must appear in SELECT or GROUP BY clause`);
        }
      }
    }
  }

  /**
   * Token matching helpers
   */
  private check(type: TokenType): boolean {
    if (this.isAtEnd()) return false;
    return this.peek().type === type;
  }

  private checkAggregate(): boolean {
    return [
      TokenType.COUNT,
      TokenType.MIN,
      TokenType.MAX,
      TokenType.AVG,
      TokenType.SUM
    ].includes(this.peek().type);
  }

  private checkAhead(type: TokenType, offset: number = 1): boolean {
    const pos = this.current + offset;
    if (pos >= this.tokens.length) return false;
    return this.tokens[pos].type === type;
  }

  private match(...types: TokenType[]): boolean {
    for (const type of types) {
      if (this.check(type)) {
        this.advance();
        return true;
      }
    }
    return false;
  }

  private matchSequence(types: TokenType[]): boolean {
    for (let i = 0; i < types.length; i++) {
      if (!this.checkAhead(types[i], i)) {
        return false;
      }
    }
    // Consume all tokens
    for (let i = 0; i < types.length; i++) {
      this.advance();
    }
    return true;
  }

  private consume(type: TokenType, message: string): Token {
    if (this.check(type)) {
      return this.advance();
    }
    throw new ParseError(message, this.peek());
  }

  private advance(): Token {
    if (!this.isAtEnd()) this.current++;
    return this.previous();
  }

  private isAtEnd(): boolean {
    return this.peek().type === TokenType.EOF;
  }

  private peek(): Token {
    return this.tokens[this.current];
  }

  private peekValue(): string | undefined {
    return this.tokens[this.current]?.value;
  }

  private previous(): Token {
    return this.tokens[this.current - 1];
  }

  /**
   * Continuation checks for multi-word tokens
   */
  private checkColumnContinuation(): boolean {
    // Don't continue if we hit keywords or operators
    const stopTokens = [
      TokenType.FROM, TokenType.WHERE, TokenType.WITH,
      TokenType.GROUP_BY, TokenType.ORDER_BY, TokenType.LIMIT,
      TokenType.AND, TokenType.COMMA
    ];
    return !stopTokens.includes(this.peek().type);
  }

  private checkGroupNameContinuation(): boolean {
    const stopTokens = [
      TokenType.WHERE, TokenType.WITH, TokenType.GROUP_BY,
      TokenType.ORDER_BY, TokenType.LIMIT
    ];
    return !stopTokens.includes(this.peek().type);
  }

  private checkFilterValueContinuation(): boolean {
    const stopTokens = [
      TokenType.AND, TokenType.GROUP_BY, TokenType.ORDER_BY,
      TokenType.LIMIT, TokenType.EOF
    ];
    return !stopTokens.includes(this.peek().type);
  }

  /**
   * Create source location from tokens
   */
  private createLocation(start: Token, end: Token): SourceLocation {
    return {
      start: start.position,
      end: end.position + end.value.length,
      line: start.line,
      column: start.column
    };
  }
}

// Export factory function
export function parse(input: string, options?: ParserOptions): QueryNode {
  const parser = new Parser(options);
  return parser.parse(input);
}

import { supabase } from "@/lib/supabase";
import type { User } from "@supabase/supabase-js";

export type TeamSeatStatus = "invited" | "active" | "revoked";

export interface TeamSeat {
  id: string;
  email: string;
  status: TeamSeatStatus;
  invitedAt: string; // ISO
  acceptedAt?: string | null;
}

const STORAGE_KEY = "tco_team_seats_v1";
const LIMIT = parseInt(process.env.NEXT_PUBLIC_TEAM_SEAT_LIMIT || "5", 10) || 5;

function uuid(): string {
  if (typeof crypto !== "undefined" && (crypto as any).randomUUID) {
    return (crypto as any).randomUUID();
  }
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

function lsGet(): TeamSeat[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function lsSet(seats: TeamSeat[]) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(seats)); } catch {}
}

export const teamService = {
  getLimit(): number {
    return LIMIT;
  },

  async list(user?: User | null): Promise<TeamSeat[]> {
    const local = typeof window !== "undefined" ? lsGet() : [];
    if (!user?.id) return local;
    try {
      const { data, error } = await (supabase as any)
        .from("team_seats")
        .select("id,email,status,invited_at,accepted_at")
        .eq("owner_id", user.id)
        .order("invited_at", { ascending: false });
      if (error) throw error;
      const remote: TeamSeat[] = (data || []).map((r: any) => ({
        id: r.id,
        email: r.email,
        status: r.status as TeamSeatStatus,
        invitedAt: r.invited_at,
        acceptedAt: r.accepted_at,
      }));
      if (remote.length && typeof window !== "undefined") lsSet(remote);
      return remote.length ? remote : local;
    } catch {
      return local;
    }
  },

  async invite(email: string, user?: User | null): Promise<TeamSeat> {
    const newSeat: TeamSeat = {
      id: uuid(),
      email: email.trim().toLowerCase(),
      status: "invited",
      invitedAt: new Date().toISOString(),
      acceptedAt: null,
    };
    const cur = typeof window !== "undefined" ? lsGet() : [];
    const updated = [newSeat, ...cur];
    if (typeof window !== "undefined") lsSet(updated);
    if (user?.id) {
      try {
        await (supabase as any)
          .from("team_seats")
          .upsert({
            id: newSeat.id,
            owner_id: user.id,
            email: newSeat.email,
            status: newSeat.status,
            invited_at: newSeat.invitedAt,
            accepted_at: newSeat.acceptedAt,
          }, { onConflict: "id" });
      } catch {}
    }
    return newSeat;
  },

  async revoke(id: string, user?: User | null): Promise<void> {
    const cur = typeof window !== "undefined" ? lsGet() : [];
    const updated = cur.map((s) => (s.id === id ? { ...s, status: "revoked" as TeamSeatStatus } : s));
    if (typeof window !== "undefined") lsSet(updated);
    if (user?.id) {
      try {
        await (supabase as any)
          .from("team_seats")
          .update({ status: "revoked" })
          .eq("id", id)
          .eq("owner_id", user.id);
      } catch {}
    }
  },

  async activate(id: string, user?: User | null): Promise<void> {
    const cur = typeof window !== "undefined" ? lsGet() : [];
    const now = new Date().toISOString();
    const updated = cur.map((s) => (s.id === id ? { ...s, status: "active" as TeamSeatStatus, acceptedAt: now } : s));
    if (typeof window !== "undefined") lsSet(updated);
    if (user?.id) {
      try {
        await (supabase as any)
          .from("team_seats")
          .update({ status: "active", accepted_at: now })
          .eq("id", id)
          .eq("owner_id", user.id);
      } catch {}
    }
  },
};

import {
  ActionHistory,
  ConsoleState,
  CriteriaResult,
  LabStep,
  ValidationCriteria,
  ValidationFeedback,
  ValidationResult,
} from "@/types/lab";

/**
 * Real-Time Validation Service
 *
 * Provides continuous validation of lab exercise steps with immediate feedback,
 * progress tracking, and adaptive assistance based on user performance.
 */

export interface ValidationContext {
  stepId: string;
  userId: string;
  sessionId: string;
  startTime: number;
  consoleState: ConsoleState;
  previousAttempts: number;
  hintsUsed: boolean;
}

export interface RealTimeValidationResult extends ValidationResult {
  confidence: number;
  suggestedActions: string[];
  nextStepRecommendation?: string;
  performanceMetrics: {
    accuracy: number;
    efficiency: number;
    timeSpent: number;
    errorCount: number;
  };
  adaptiveFeedback: AdaptiveFeedback;
  validationTime: number;
}

export interface AdaptiveFeedback {
  level: "beginner" | "intermediate" | "advanced";
  tone: "encouraging" | "instructional" | "corrective";
  content: {
    immediate: string;
    detailed: string;
    nextSteps: string[];
    resources?: string[];
  };
  visualCues: {
    color: "green" | "yellow" | "red";
    icon: string;
    animation?: string;
  };
}

class RealTimeValidationService {
  private validationCache: Map<string, ValidationResult> = new Map();
  private performanceTracking: Map<string, number[]> = new Map();
  private validationTimeouts: Map<string, NodeJS.Timeout> = new Map();

  /**
   * Continuously validate a lab step in real-time
   */
  async validateStepRealTime(
    step: LabStep,
    context: ValidationContext
  ): Promise<RealTimeValidationResult> {
    const startValidation = Date.now(); // Moved declaration here
    try {
      // Clear previous validation timeout
      this.clearValidationTimeout(context.stepId);

      // Perform comprehensive validation
      const baseResult = await this.performComprehensiveValidation(step, context);

      // Calculate performance metrics
      const performanceMetrics = this.calculatePerformanceMetrics(context, baseResult);

      // Generate adaptive feedback
      const adaptiveFeedback = this.generateAdaptiveFeedback(
        baseResult,
        context,
        performanceMetrics
      );

      // Determine confidence and suggestions
      const confidence = this.calculateValidationConfidence(baseResult, context);
      const suggestedActions = this.generateSuggestedActions(
        baseResult,
        context,
        performanceMetrics
      );

      // Create enhanced result
      const enhancedResult: RealTimeValidationResult = {
        ...baseResult,
        confidence,
        suggestedActions,
        nextStepRecommendation: this.determineNextStepRecommendation(baseResult, context),
        performanceMetrics,
        adaptiveFeedback,
        validationTime: Date.now() - startValidation,
      };

      // Cache result for performance
      this.cacheValidationResult(context.stepId, enhancedResult);

      // Track performance history
      this.trackPerformanceHistory(context.userId, performanceMetrics.accuracy);

      // Schedule next validation if step is incomplete
      if (!baseResult.passed) {
        this.scheduleNextValidation(step, context);
      }

      return enhancedResult;
    } catch (error) {
      console.error("Real-time validation failed:", error);

      const feedback: ValidationFeedback = {
        success: { title: "Success", content: "Validation complete", type: "success" },
        failure: {
          title: "Error",
          content: "Validation system temporarily unavailable. Please try again.",
          type: "error",
        },
        partial: { title: "Partial", content: "Partial validation result", type: "warning" },
        hints: [],
      };

      return {
        passed: false,
        score: 0,
        criteriaResults: [],
        feedback,
        confidence: 0,
        suggestedActions: ["Refresh the page and try again"],
        performanceMetrics: {
          accuracy: 0,
          efficiency: 0,
          timeSpent: Date.now() - context.startTime,
          errorCount: 1,
        },
        adaptiveFeedback: {
          level: "beginner",
          tone: "corrective",
          content: {
            immediate: (feedback.failure && feedback.failure.content) || "Validation system error",
            detailed: "Please check your connection or contact support.",
            nextSteps: [],
          },
          visualCues: { color: "red", icon: "XCircle" },
        },
        validationTime: Date.now() - startValidation,
      };
    }
  }

  /**
   * Perform comprehensive step validation
   */
  private async performComprehensiveValidation(
    step: LabStep,
    context: ValidationContext
  ): Promise<ValidationResult> {
    if (!step.validation) {
      const feedback: ValidationFeedback = {
        success: { title: "Success", content: "Step completed successfully", type: "success" },
        failure: { title: "Error", content: "", type: "error" },
        partial: { title: "Partial", content: "", type: "warning" },
        hints: [],
      };

      return {
        passed: true,
        score: 100,
        criteriaResults: [],
        feedback,
      };
    }

    const criteriaResults = await Promise.all(
      step.validation.criteria.map((criterion) => this.validateCriterion(criterion, context))
    );

    const totalWeight = step.validation.criteria.reduce((sum, c) => sum + c.weight, 0);
    const weightedScore = criteriaResults.reduce((sum, result, index) => {
      const criterion = step.validation.criteria[index];
      return sum + (result.score * criterion.weight) / totalWeight;
    }, 0);

    const passed = weightedScore >= step.validation.passingScore;
    const feedback = this.selectFeedback(
      step.validation.feedback,
      weightedScore,
      step.validation.passingScore
    );

    return {
      passed,
      score: Math.round(weightedScore),
      criteriaResults,
      feedback,
    };
  }

  /**
   * Validate individual criterion
   */
  private async validateCriterion(
    criterion: ValidationCriteria,
    context: ValidationContext
  ): Promise<CriteriaResult> {
    let result: { passed: boolean; score: number; details: string };

    switch (criterion.type) {
      case "console-state":
        result = this.validateConsoleState(criterion, context.consoleState);
        break;

      case "user-input":
        result = this.validateUserInput(criterion, context);
        break;

      case "result-data":
        result = this.validateResultData(criterion, context.consoleState);
        break;

      case "action-sequence":
        result = this.validateActionSequence(criterion, context.consoleState);
        break;

      case "time-based":
        result = this.validateTimeBased(criterion, context);
        break;

      default:
        console.warn(`Unknown validation criterion type: ${criterion.type}`);
        result = { passed: false, score: 0, details: "Unknown validation type" };
    }

    return {
      id: criterion.id,
      passed: result.passed,
      score: result.score,
      feedback: result.details, // Using details as feedback for CriteriaResult
      details: result.details,
    };
  }

  /**
   * Validate console state
   */
  private validateConsoleState(
    criterion: ValidationCriteria,
    consoleState: ConsoleState
  ): { passed: boolean; score: number; details: string } {
    const target = consoleState[criterion.target as keyof ConsoleState];

    switch (criterion.condition) {
      case "equals":
        const passed = target === criterion.value;
        return {
          passed,
          score: passed ? 100 : 0,
          details: passed
            ? "Console state matches expected value"
            : `Expected ${criterion.value}, got ${target}`,
        };

      case "contains":
        if (Array.isArray(target)) {
          const containsValue = target.some((item: any) =>
            typeof item === "object"
              ? this.objectContains(item, criterion.value)
              : item === criterion.value
          );
          return {
            passed: containsValue,
            score: containsValue ? 100 : 0,
            details: containsValue ? "Required item found" : "Required item not found",
          };
        }
        return { passed: false, score: 0, details: "Target is not an array" };

      default:
        return { passed: false, score: 0, details: "Unsupported condition" };
    }
  }

  /**
   * Validate user input
   */
  private validateUserInput(
    criterion: ValidationCriteria,
    context: ValidationContext
  ): { passed: boolean; score: number; details: string } {
    // This would validate specific user inputs based on the criterion
    // For now, return a basic implementation
    return {
      passed: true,
      score: 100,
      details: "User input validation passed",
    };
  }

  /**
   * Validate result data
   */
  private validateResultData(
    criterion: ValidationCriteria,
    consoleState: ConsoleState
  ): { passed: boolean; score: number; details: string } {
    // Validate query results, data exports, etc.
    const queries = Array.isArray(consoleState.queries) ? consoleState.queries : [];

    if (criterion.target === "columnCount") {
      const lastQuery = queries[queries.length - 1];
      if (!lastQuery?.results) {
        return { passed: false, score: 0, details: "No query results found" };
      }

      const columnCount = lastQuery.results[0]?.columns?.length || 0; // Access columns from the first QueryResult object
      const passed = columnCount === criterion.value;

      return {
        passed,
        score: passed ? 100 : 0,
        details: passed
          ? "Correct number of columns"
          : `Expected ${criterion.value} columns, got ${columnCount}`,
      };
    }

    return { passed: true, score: 100, details: "Result data validation passed" };
  }

  /**
   * Validate action sequence
   */
  private validateActionSequence(
    criterion: ValidationCriteria,
    consoleState: ConsoleState
  ): { passed: boolean; score: number; details: string } {
    const activityLog = Array.isArray(consoleState.activityLog) ? consoleState.activityLog : [];

    switch (criterion.condition) {
      case "performed":
        const actionFound = activityLog.some((entry: ActionHistory) =>
          entry.action === criterion.target || (typeof entry.details === 'string' && entry.details.includes(criterion.target as string))
        );

        return {
          passed: actionFound,
          score: actionFound ? 100 : 0,
          details: actionFound
            ? "Required action was performed"
            : `Action '${criterion.target}' not found`,
        };

      case "visited_all":
        const requiredModules = criterion.value as string[];
        const visitedModules = activityLog
          .filter((entry: ActionHistory) => entry.action === "module_navigation")
          .map((entry: ActionHistory) => entry.module)
          .filter(Boolean);

        const allVisited = requiredModules.every((module) => visitedModules.includes(module));

        return {
          passed: allVisited,
          score: allVisited ? 100 : (visitedModules.length / requiredModules.length) * 100,
          details: allVisited
            ? "All required modules visited"
            : `Visited ${visitedModules.length}/${requiredModules.length} required modules`,
        };

      default:
        return { passed: true, score: 100, details: "Action sequence validation passed" };
    }
  }

  /**
   * Validate time-based criteria
   */
  private validateTimeBased(
    criterion: ValidationCriteria,
    context: ValidationContext
  ): { passed: boolean; score: number; details: string } {
    const elapsedTime = Date.now() - context.startTime;
    const elapsedMinutes = elapsedTime / (1000 * 60);

    switch (criterion.condition) {
      case "within_time":
        const timeLimit = criterion.value as number; // minutes
        const passed = elapsedMinutes <= timeLimit;

        return {
          passed,
          score: passed ? 100 : Math.max(0, 100 - ((elapsedMinutes - timeLimit) / timeLimit) * 50),
          details: passed
            ? `Completed within ${timeLimit} minutes`
            : `Exceeded time limit by ${(elapsedMinutes - timeLimit).toFixed(1)} minutes`,
        };

      default:
        return { passed: true, score: 100, details: "Time validation passed" };
    }
  }

  /**
   * Calculate performance metrics
   */
  private calculatePerformanceMetrics(
    context: ValidationContext,
    result: ValidationResult
  ): RealTimeValidationResult["performanceMetrics"] {
    const timeSpent = Date.now() - context.startTime;
    const accuracy = result.score;

    // Calculate efficiency based on time and accuracy
    const efficiency = Math.max(0, 100 - (timeSpent / 1000 / 60 - 5) * 10); // Penalty after 5 minutes

    return {
      accuracy,
      efficiency: Math.min(100, efficiency),
      timeSpent,
      errorCount: context.previousAttempts,
    };
  }

  /**
   * Generate adaptive feedback based on user performance
   */
  private generateAdaptiveFeedback(
    result: ValidationResult,
    context: ValidationContext,
    metrics: RealTimeValidationResult["performanceMetrics"]
  ): AdaptiveFeedback {
    const userHistory = this.performanceTracking.get(context.userId) || [];
    const avgAccuracy =
      userHistory.length > 0 ? userHistory.reduce((a, b) => a + b, 0) / userHistory.length : 70;

    // Determine user level based on history
    let level: AdaptiveFeedback["level"] = "intermediate";
    if (avgAccuracy < 60) level = "beginner";
    else if (avgAccuracy > 85) level = "advanced";

    // Determine tone based on current performance
    let tone: AdaptiveFeedback["tone"] = "instructional";
    if (result.score >= 90) tone = "encouraging";
    else if (result.score < 50) tone = "corrective";

    // Generate content based on level and performance
    const content = this.generateFeedbackContent(result, level, tone, metrics);

    // Visual cues based on performance
    const visualCues = this.generateVisualCues(result.score);

    return {
      level,
      tone,
      content,
      visualCues,
    };
  }

  /**
   * Generate feedback content
   */
  private generateFeedbackContent(
    result: ValidationResult,
    level: AdaptiveFeedback["level"],
    tone: AdaptiveFeedback["tone"],
    metrics: RealTimeValidationResult["performanceMetrics"]
  ): AdaptiveFeedback["content"] {
    const baseContent = result.feedback;

    let immediate =
      this.feedbackMessageContent(baseContent, 'success') ||
      this.feedbackMessageContent(baseContent, 'failure') ||
      this.feedbackMessageContent(baseContent, 'partial');
    let detailed = "";
    let nextSteps: string[] = [];
    let resources: string[] = [];

    if (result.passed) {
      immediate = tone === "encouraging" ? `🎉 Excellent work! ${immediate}` : immediate;

      detailed =
        level === "beginner"
          ? "Great job completing this step! You're building solid foundational skills."
          : level === "advanced"
            ? "Perfect execution. You demonstrated mastery of this concept."
            : "Well done! You're progressing nicely through the material.";

      nextSteps = ["Continue to the next step", "Review your work if needed"];
    } else {
      immediate =
        tone === "corrective" ? `Let's work through this together. ${immediate}` : immediate;

      detailed =
        level === "beginner"
          ? "Don't worry - learning takes practice. Let's break this down into smaller steps."
          : level === "advanced"
            ? "This is a challenging step. Review the requirements carefully."
            : "You're close to the solution. Check your work against the instructions.";

      nextSteps = [
        "Review the step instructions carefully",
        "Check your console state",
        "Try the suggested actions below",
      ];

      if (level === "beginner") {
        resources = [
          "Review the hints for this step",
          "Check the Tanium documentation",
          "Ask for help if you're stuck",
        ];
      }
    }

    return {
      immediate,
      detailed,
      nextSteps,
      resources: resources.length > 0 ? resources : undefined,
    };
  }

  /**
   * Generate visual cues for feedback
   */
  private generateVisualCues(score: number): AdaptiveFeedback["visualCues"] {
    if (score >= 80) {
      return {
        color: "green",
        icon: "CheckCircle",
        animation: "bounce",
      };
    } else if (score >= 50) {
      return {
        color: "yellow",
        icon: "AlertTriangle",
        animation: "pulse",
      };
    } else {
      return {
        color: "red",
        icon: "XCircle",
        animation: "shake",
      };
    }
  }

  /**
   * Calculate validation confidence
   */
  private calculateValidationConfidence(
    result: ValidationResult,
    context: ValidationContext
  ): number {
    let confidence = 100;

    // Reduce confidence based on factors
    if (context.previousAttempts > 0) {
      confidence -= context.previousAttempts * 10;
    }

    if (context.hintsUsed) {
      confidence -= 15;
    }

    // Adjust based on score distribution
    const scores = result.criteriaResults?.map((r: CriteriaResult) => r.score) || [result.score];
    const variance = this.calculateVariance(scores);
    confidence -= variance * 0.5;

    return Math.max(0, Math.min(100, confidence));
  }

  /**
   * Generate suggested actions
   */
  private generateSuggestedActions(
    result: ValidationResult,
    context: ValidationContext,
    metrics: RealTimeValidationResult["performanceMetrics"]
  ): string[] {
    const suggestions: string[] = [];

    if (!result.passed) {
      // Add specific suggestions based on failed criteria
      result.criteriaResults?.forEach((criterionResult: CriteriaResult, index: number) => {
        if (!criterionResult.passed) {
          suggestions.push(`Check: ${criterionResult.details}`);
        }
      });

      // Add general suggestions
      if (metrics.timeSpent > 300000) {
        // 5 minutes
        suggestions.push("Consider using hints to speed up progress");
      }

      if (context.previousAttempts > 2) {
        suggestions.push("Review the step instructions and try a different approach");
      }

      suggestions.push("Verify your console state matches the requirements");
    } else {
      suggestions.push("Great work! Continue to the next step");

      if (metrics.timeSpent < 60000) {
        // Under 1 minute
        suggestions.push("Excellent speed! Consider helping others or reviewing advanced concepts");
      }
    }

    return suggestions;
  }

  /**
   * Determine next step recommendation
   */
  private determineNextStepRecommendation(
    result: ValidationResult,
    context: ValidationContext
  ): string | undefined {
    if (result.passed) {
      return "Ready for the next step";
    }

    if (context.previousAttempts > 3) {
      return "Consider reviewing the prerequisites for this step";
    }

    return "Continue working on the current step";
  }

  /**
   * Helper methods
   */
  private objectContains(obj: any, target: any): boolean {
    if (typeof target !== "object") return false;

    return Object.keys(target).every(
      (key) =>
        obj[key] !== undefined &&
        (typeof obj[key] === "object"
          ? this.objectContains(obj[key], target[key])
          : obj[key] === target[key])
    );
  }

  private feedbackToObject(feedback: any): { success?: any; failure?: any; partial?: any; hints?: any[] } {
    if (!feedback) return {};
    const t = typeof feedback;
    if (t === 'string' || t === 'number' || t === 'boolean') {
      return { failure: { title: '', content: String(feedback), type: 'error' } };
    }

    if (typeof feedback === 'object') {
      // If it already looks like a feedback object, return as-is
      if ('success' in feedback || 'failure' in feedback || 'partial' in feedback || 'hints' in feedback) {
        return feedback as any;
      }

      // Unknown object shape - serialize into failure message
      try {
        return { failure: { title: '', content: JSON.stringify(feedback), type: 'error' } };
      } catch (e) {
        return { failure: { title: '', content: String(feedback), type: 'error' } };
      }
    }

    return { failure: { title: '', content: String(feedback), type: 'error' } };
  }

  private feedbackMessageContent(feedback: any, key: 'success' | 'failure' | 'partial'): string {
    const obj = this.feedbackToObject(feedback);
    return (obj && obj[key] && obj[key].content) || '';
  }

  private selectFeedback(
    feedback: ValidationFeedback,
    score: number,
    passingScore: number
  ): ValidationFeedback {
    const fb = this.feedbackToObject(feedback);

    if (score >= passingScore) {
      return {
        success: fb.success || undefined,
        failure: { ...(fb.failure || {}), content: "" },
        partial: { ...(fb.partial || {}), content: "" },
        hints: fb.hints || [],
      } as ValidationFeedback;
    } else if (score >= passingScore * 0.5) {
      return {
        success: { ...(fb.success || {}), content: "" },
        failure: { ...(fb.failure || {}), content: "" },
        partial: fb.partial || undefined,
        hints: fb.hints || [],
      } as ValidationFeedback;
    } else {
      return {
        success: { ...(fb.success || {}), content: "" },
        failure: fb.failure || undefined,
        partial: { ...(fb.partial || {}), content: "" },
        hints: fb.hints || [],
      } as ValidationFeedback;
    }
  }

  private calculateVariance(numbers: number[]): number {
    if (numbers.length <= 1) return 0;

    const mean = numbers.reduce((a, b) => a + b, 0) / numbers.length;
    const variance =
      numbers.reduce((sum, num) => sum + Math.pow(num - mean, 2), 0) / numbers.length;

    return Math.sqrt(variance);
  }

  private cacheValidationResult(stepId: string, result: ValidationResult): void {
    this.validationCache.set(stepId, result);

    // Clean old cache entries after 5 minutes
    setTimeout(
      () => {
        this.validationCache.delete(stepId);
      },
      5 * 60 * 1000
    );
  }

  private trackPerformanceHistory(userId: string, accuracy: number): void {
    const history = this.performanceTracking.get(userId) || [];
    history.push(accuracy);

    // Keep only last 20 results
    if (history.length > 20) {
      history.shift();
    }

    this.performanceTracking.set(userId, history);
  }

  private scheduleNextValidation(step: LabStep, context: ValidationContext): void {
    const timeoutId = setTimeout(() => {
      // This would trigger another validation cycle
      console.log(`Scheduled validation for step ${step.id}`);
    }, 30000); // 30 seconds

    this.validationTimeouts.set(context.stepId, timeoutId);
  }

  private clearValidationTimeout(stepId: string): void {
    const timeoutId = this.validationTimeouts.get(stepId);
    if (timeoutId) {
      clearTimeout(timeoutId);
      this.validationTimeouts.delete(stepId);
    }
  }

  /**
   * Public API methods
   */

  /**
   * Start continuous validation for a step
   */
  async startContinuousValidation(
    step: LabStep,
    context: ValidationContext,
    onUpdate: (result: RealTimeValidationResult) => void
  ): Promise<void> {
    const validationLoop = async () => {
      const result = await this.validateStepRealTime(step, context);
      onUpdate(result);

      if (!result.passed) {
        // Schedule next validation
        setTimeout(validationLoop, 15000); // Every 15 seconds
      }
    };

    await validationLoop();
  }

  /**
   * Stop continuous validation
   */
  stopContinuousValidation(stepId: string): void {
    this.clearValidationTimeout(stepId);
  }

  /**
   * Get cached validation result
   */
  getCachedResult(stepId: string): ValidationResult | undefined {
    return this.validationCache.get(stepId);
  }

  /**
   * Clear all caches and timeouts
   */
  cleanup(): void {
    this.validationCache.clear();
    this.validationTimeouts.forEach((timeout) => clearTimeout(timeout));
    this.validationTimeouts.clear();
  }
}

