    score: number,
    questions: number
  ): LearningAnalytics["masteryLevel"] {
    if (score >= 90 && questions >= 50) return "expert";
    if (score >= 80 && questions >= 30) return "proficient";
    if (score >= 70 && questions >= 20) return "developing";
